// CHEMISTRY — BATCH 2: MATTER AND PARTICLE THEORY
// ============================================================


// ------------------------------------------------------------
// 1. MEANING OF MATTER
// ------------------------------------------------------------

add(
  "chemistry",
  "matter_separation",
  "Meaning of Matter",
  `
  <h2>Meaning of Matter</h2>

  <p><strong>Matter</strong> is anything that has mass and occupies space.</p>

  <p>Examples of matter include water, air, wood, iron, oxygen and plastic.</p>

  <h3>Two Important Features of Matter</h3>

  <p><strong>1. Matter has mass</strong></p>

  <p>Mass is the amount of matter in a substance.</p>

  <p><strong>2. Matter occupies space</strong></p>

  <p>This means matter has volume.</p>

  <h3>Particles of Matter</h3>

  <p>Matter is made up of very small particles. These particles may be atoms,
  molecules or ions depending on the substance.</p>

  <p>The particles are too small to be seen directly with the naked eye.</p>

  <h3>Examples</h3>

  <p>Water is matter because it has mass and occupies space.</p>

  <p>Air is also matter even though it cannot normally be seen because it has
  mass and occupies space.</p>
  `,
  [
    {
      q: "What is matter?",
      steps: [
        "Step 1: Identify the two properties used to define matter.",
        "Step 2: Matter has mass.",
        "Step 3: Matter occupies space.",
        "Step 4: Combine the two properties into the definition."
      ],
      ans: "Matter is anything that has mass and occupies space.",
      why: "Having mass and occupying space are the two basic properties used to identify matter."
    },
    {
      q: "Why is air considered to be matter?",
      steps: [
        "Step 1: Matter must have mass.",
        "Step 2: Air has mass.",
        "Step 3: Matter must also occupy space.",
        "Step 4: Air occupies space."
      ],
      ans: "Air is matter because it has mass and occupies space.",
      why: "Being invisible does not mean that something is not matter."
    },
    {
      q: "A stone is placed on a balance and then put into a measuring cylinder containing water. What two properties of matter are demonstrated?",
      steps: [
        "Step 1: The balance demonstrates that the stone has mass.",
        "Step 2: The measuring cylinder demonstrates that the stone occupies space because it displaces water."
      ],
      ans: "The stone has mass and occupies space.",
      why: "These are the two defining properties of matter."
    }
  ],
  [
    {
      q: "A student says that air is not matter because it cannot be seen. Correct the statement.",
      hint: "Use the definition of matter.",
      steps: [
        "Step 1: Matter does not have to be visible.",
        "Step 2: Check whether air has mass.",
        "Step 3: Check whether air occupies space.",
        "Step 4: Air satisfies both conditions."
      ],
      ans: "Air is matter because it has mass and occupies space even though it cannot normally be seen.",
      why: "Visibility is not a requirement for something to be matter."
    }
  ]
);


// ------------------------------------------------------------
// 2. PHYSICAL PROPERTIES
// ------------------------------------------------------------

add(
  "chemistry",
  "matter_separation",
  "Physical Properties",
  `
  <h2>Physical Properties</h2>

  <p>A <strong>physical property</strong> is a characteristic of a substance
  that can be observed or measured without changing the substance into a
  different substance.</p>

  <h3>Examples</h3>

  <ul>
    <li>Colour</li>
    <li>Density</li>
    <li>Melting point</li>
    <li>Boiling point</li>
    <li>Electrical conductivity</li>
    <li>Solubility</li>
    <li>Hardness</li>
    <li>State of matter</li>
  </ul>

  <h3>Example</h3>

  <p>Water has a boiling point of about 100°C at standard atmospheric
  pressure. Measuring its boiling point does not change water into a new
  chemical substance.</p>

  <p>Therefore boiling point is a physical property.</p>

  <h3>Physical Property vs Chemical Property</h3>

  <p>A physical property can be determined without changing the chemical
  identity of the substance.</p>
  `,
  [
    {
      q: "What is a physical property?",
      steps: [
        "Step 1: Identify what is being observed or measured.",
        "Step 2: Check whether the substance's chemical identity changes.",
        "Step 3: If it does not change, the characteristic is a physical property."
      ],
      ans: "A physical property is a characteristic of a substance that can be observed or measured without changing it into a different substance.",
      why: "The key feature is that the chemical identity of the substance remains unchanged."
    },
    {
      q: "Is density a physical property? Explain.",
      steps: [
        "Step 1: Density can be measured from mass and volume.",
        "Step 2: Measuring density does not require changing the substance into another substance.",
        "Step 3: Therefore density is a physical property."
      ],
      ans: "Yes. Density is a physical property because it can be measured without changing the substance into another substance.",
      why: "The substance retains its chemical identity while its density is measured."
    },
    {
      q: "Classify colour, boiling point and electrical conductivity as physical or chemical properties.",
      steps: [
        "Step 1: Colour can be observed without changing the substance.",
        "Step 2: Boiling point can be measured without changing its chemical identity.",
        "Step 3: Electrical conductivity can be measured without converting it into a new substance."
      ],
      ans: "All three—colour, boiling point and electrical conductivity—are physical properties.",
      why: "None of these measurements requires the substance to become a different chemical substance."
    }
  ],
  [
    {
      q: "A learner says that boiling point is a chemical property because boiling involves a change. Is the learner correct?",
      hint: "Ask whether a new chemical substance is formed.",
      steps: [
        "Step 1: Boiling changes a liquid into a gas.",
        "Step 2: The substance itself remains chemically the same.",
        "Step 3: Therefore boiling point is a physical property."
      ],
      ans: "No. Boiling point is a physical property because boiling does not change the substance into a new chemical substance.",
      why: "A change in physical state does not necessarily mean a chemical change."
    }
  ]
);


// ------------------------------------------------------------
// 3. CHEMICAL PROPERTIES
// ------------------------------------------------------------

add(
  "chemistry",
  "matter_separation",
  "Chemical Properties",
  `
  <h2>Chemical Properties</h2>

  <p>A <strong>chemical property</strong> describes the ability of a substance
  to undergo a chemical change and form new substances.</p>

  <h3>Examples</h3>

  <ul>
    <li>Flammability</li>
    <li>Ability to react with oxygen</li>
    <li>Ability to react with acids</li>
    <li>Ability to react with water</li>
    <li>Ability to corrode</li>
  </ul>

  <h3>Example: Iron</h3>

  <p>Iron can react with oxygen and water to form rust.</p>

  <p>The ability of iron to undergo this reaction is a chemical property.</p>

  <h3>Example: Magnesium</h3>

  <p>Magnesium reacts with oxygen when heated to form magnesium oxide.</p>

  <p>Its ability to react with oxygen is therefore a chemical property.</p>

  <h3>Key Difference</h3>

  <p>A physical property can be observed without forming a new substance.
  A chemical property describes how a substance behaves when it undergoes a
  chemical change.</p>
  `,
  [
    {
      q: "What is a chemical property?",
      steps: [
        "Step 1: Consider how the substance behaves during a chemical change.",
        "Step 2: A chemical property describes the substance's ability to undergo such a change.",
        "Step 3: New substances are formed during the chemical change."
      ],
      ans: "A chemical property describes the ability of a substance to undergo a chemical change and form new substances.",
      why: "Chemical properties concern how substances react chemically."
    },
    {
      q: "Why is flammability a chemical property?",
      steps: [
        "Step 1: Flammability describes whether a substance can burn.",
        "Step 2: Burning is a chemical reaction.",
        "Step 3: New substances are produced during combustion."
      ],
      ans: "Flammability is a chemical property because burning is a chemical reaction that forms new substances.",
      why: "The property describes the substance's ability to undergo a chemical change."
    },
    {
      q: "Why is the ability of iron to rust a chemical property?",
      steps: [
        "Step 1: Rusting involves iron reacting with oxygen and water.",
        "Step 2: New substances are formed.",
        "Step 3: Therefore the ability of iron to rust is a chemical property."
      ],
      ans: "It is a chemical property because iron can react with oxygen and water to form new substances called rust.",
      why: "The property involves the chemical reactivity of iron."
    }
  ],
  [
    {
      q: "A student says that the melting point of iron is a chemical property. Correct the statement.",
      hint: "Ask whether melting produces a new chemical substance.",
      steps: [
        "Step 1: Melting changes iron from solid to liquid.",
        "Step 2: The substance remains iron.",
        "Step 3: No new chemical substance is formed.",
        "Step 4: Therefore melting point is a physical property."
      ],
      ans: "The statement is incorrect. The melting point of iron is a physical property because melting changes its physical state without forming a new substance.",
      why: "Chemical properties involve chemical reactions and formation of new substances."
    }
  ]
);


// ------------------------------------------------------------
// 4. SOLIDS
// ------------------------------------------------------------

add(
  "chemistry",
  "matter_separation",
  "Solids",
  `
  <h2>Solids</h2>

  <p>A solid is a state of matter in which particles are closely packed and
  held in relatively fixed positions.</p>

  <h3>Particle Arrangement</h3>

  <p>The particles in a solid are arranged very close together. There is
  little empty space between neighbouring particles.</p>

  <h3>Particle Movement</h3>

  <p>Particles in a solid cannot move freely from place to place. They
  vibrate about fixed positions.</p>

  <h3>Properties of Solids</h3>

  <ul>
    <li>They have a fixed shape.</li>
    <li>They have a fixed volume.</li>
    <li>They are difficult to compress.</li>
    <li>They usually have relatively high density compared with gases.</li>
  </ul>

  <h3>Examples</h3>

  <p>Iron, copper, salt, ice and wood are examples of solids.</p>
  `,
  [
    {
      q: "Why do solids have a fixed shape?",
      steps: [
        "Step 1: Particles in a solid are closely packed.",
        "Step 2: They are held in relatively fixed positions.",
        "Step 3: Therefore the bulk solid retains a fixed shape."
      ],
      ans: "Solids have a fixed shape because their particles are closely packed and held in relatively fixed positions.",
      why: "The particles cannot move freely past one another."
    },
    {
      q: "Describe the movement of particles in a solid.",
      steps: [
        "Step 1: Solid particles are held in fixed positions.",
        "Step 2: They cannot move freely from place to place.",
        "Step 3: They vibrate about their fixed positions."
      ],
      ans: "Particles in a solid vibrate about fixed positions.",
      why: "The strong attraction and close arrangement restrict their movement."
    },
    {
      q: "Why are solids difficult to compress?",
      steps: [
        "Step 1: Particles in solids are already very close together.",
        "Step 2: There is little empty space between them.",
        "Step 3: There is therefore little room to reduce the volume."
      ],
      ans: "Solids are difficult to compress because their particles are already closely packed with very little empty space between them.",
      why: "Compression requires particles to be pushed closer together."
    }
  ],
  [
    {
      q: "A student says that particles in a solid do not move. Correct the statement.",
      hint: "Think about what particles do even when the solid remains in one place.",
      steps: [
        "Step 1: Solid particles are restricted to fixed positions.",
        "Step 2: They still possess kinetic energy.",
        "Step 3: They vibrate about their fixed positions."
      ],
      ans: "Particles in a solid do move. They vibrate about their fixed positions.",
      why: "Particles in matter are continuously moving; their movement is simply restricted in a solid."
    }
  ]
);


// ------------------------------------------------------------
// 5. LIQUIDS
// ------------------------------------------------------------

add(
  "chemistry",
  "matter_separation",
  "Liquids",
  `
  <h2>Liquids</h2>

  <p>A liquid is a state of matter whose particles are close together but
  are able to move past one another.</p>

  <h3>Particle Arrangement</h3>

  <p>Liquid particles are relatively close together, but their arrangement
  is less ordered than that of particles in a solid.</p>

  <h3>Particle Movement</h3>

  <p>The particles can move and slide past one another.</p>

  <h3>Properties of Liquids</h3>

  <ul>
    <li>They have a fixed volume.</li>
    <li>They do not have a fixed shape.</li>
    <li>They take the shape of their container.</li>
    <li>They are difficult to compress.</li>
    <li>They can flow.</li>
  </ul>

  <h3>Examples</h3>

  <p>Water, ethanol, cooking oil and mercury are liquids at suitable
  temperatures.</p>
  `,
  [
    {
      q: "Why do liquids take the shape of their containers?",
      steps: [
        "Step 1: Liquid particles are close together.",
        "Step 2: Unlike solid particles, they are not fixed in position.",
        "Step 3: They can move past one another.",
        "Step 4: This allows the liquid to flow and take the container's shape."
      ],
      ans: "Liquids take the shape of their containers because their particles can move past one another.",
      why: "The particles are not held in fixed positions as they are in solids."
    },
    {
      q: "Why does a liquid have a fixed volume but no fixed shape?",
      steps: [
        "Step 1: Liquid particles remain relatively close together, maintaining a definite amount of space.",
        "Step 2: The particles can move past one another.",
        "Step 3: Therefore the volume remains approximately fixed while the shape changes."
      ],
      ans: "A liquid has a fixed volume because its particles remain close together, but it has no fixed shape because the particles can move past one another.",
      why: "The arrangement allows flow without allowing easy compression."
    },
    {
      q: "Why are liquids difficult to compress?",
      steps: [
        "Step 1: Liquid particles are already relatively close together.",
        "Step 2: There is little empty space between them.",
        "Step 3: Therefore their volume cannot be reduced easily."
      ],
      ans: "Liquids are difficult to compress because their particles are already relatively close together with little empty space between them.",
      why: "There is not enough empty space for the particles to be pushed significantly closer together."
    }
  ],
  [
    {
      q: "A learner says that a liquid has no volume because it has no fixed shape. Explain why this is wrong.",
      hint: "Separate the ideas of shape and volume.",
      steps: [
        "Step 1: Shape describes the form of an object.",
        "Step 2: Volume describes the amount of space occupied.",
        "Step 3: Liquid particles remain close together, so the liquid has a definite volume.",
        "Step 4: The particles can rearrange, so the liquid does not have a fixed shape."
      ],
      ans: "The statement is wrong. A liquid has a definite volume but no fixed shape. Its particles can rearrange to fit the container.",
      why: "Having no fixed shape does not mean having no volume."
    }
  ]
);


// ------------------------------------------------------------
// 6. GASES
// ------------------------------------------------------------

add(
  "chemistry",
  "matter_separation",
  "Gases",
  `
  <h2>Gases</h2>

  <p>A gas is a state of matter in which particles are far apart and move
  freely in all directions.</p>

  <h3>Particle Arrangement</h3>

  <p>Gas particles are widely separated with large amounts of empty space
  between them.</p>

  <h3>Particle Movement</h3>

  <p>The particles move rapidly and randomly in all directions.</p>

  <h3>Properties of Gases</h3>

  <ul>
    <li>They have no fixed shape.</li>
    <li>They have no fixed volume.</li>
    <li>They fill their containers.</li>
    <li>They are easily compressed.</li>
    <li>They can flow.</li>
    <li>They exert pressure on the walls of their containers.</li>
  </ul>

  <h3>Examples</h3>

  <p>Oxygen, nitrogen, carbon dioxide and water vapour are examples of gases
  under suitable conditions.</p>
  `,
  [
    {
      q: "Why can gases be compressed easily?",
      steps: [
        "Step 1: Gas particles are far apart.",
        "Step 2: There are large spaces between the particles.",
        "Step 3: Applying pressure can reduce these spaces."
      ],
      ans: "Gases can be compressed easily because there are large spaces between their particles.",
      why: "Compression mainly reduces the empty spaces between gas particles."
    },
    {
      q: "Why does a gas fill its container?",
      steps: [
        "Step 1: Gas particles are not fixed in position.",
        "Step 2: They move freely and randomly in all directions.",
        "Step 3: They spread throughout the available space."
      ],
      ans: "A gas fills its container because its particles move freely in all directions and spread throughout the available space.",
      why: "Gas particles are not restricted to fixed positions."
    },
    {
      q: "Why do gases exert pressure on the walls of their containers?",
      steps: [
        "Step 1: Gas particles move continuously.",
        "Step 2: They collide with the walls of the container.",
        "Step 3: These collisions exert forces on the walls."
      ],
      ans: "Gases exert pressure because their moving particles continually collide with the walls of the container.",
      why: "The combined effect of many particle collisions produces gas pressure."
    }
  ],
  [
    {
      q: "A gas is transferred from a 1 L container into a 5 L container. What happens to the gas volume if temperature and pressure conditions allow the gas to occupy the available space?",
      hint: "Think about whether gas particles have fixed positions.",
      steps: [
        "Step 1: Gas particles move freely.",
        "Step 2: They spread through the available space.",
        "Step 3: The gas therefore expands to occupy the larger container."
      ],
      ans: "The gas expands to occupy the available space in the 5 L container.",
      why: "A gas has no fixed volume and spreads throughout the space available to it."
    }
  ]
);


// ------------------------------------------------------------
// 7. PARTICLE ARRANGEMENT
// ------------------------------------------------------------

add(
  "chemistry",
  "matter_separation",
  "Particle Arrangement",
  `
  <h2>Particle Arrangement</h2>

  <p>The particle model explains the different states of matter by considering
  how closely particles are packed and how they are arranged.</p>

  <h3>Solid</h3>

  <p>Particles are very close together and arranged in relatively fixed
  positions.</p>

  <h3>Liquid</h3>

  <p>Particles remain close together but are less ordered and can move past
  one another.</p>

  <h3>Gas</h3>

  <p>Particles are far apart and arranged randomly.</p>

  <h3>Comparison</h3>

  <p><strong>Solid →</strong> closest and most ordered.</p>
  <p><strong>Liquid →</strong> close but less ordered.</p>
  <p><strong>Gas →</strong> far apart and random.</p>

  <p>The arrangement of particles helps explain properties such as shape,
  volume and compressibility.</p>
  `,
  [
    {
      q: "Describe the arrangement of particles in a solid.",
      steps: [
        "Step 1: Consider the distance between particles.",
        "Step 2: Consider their order.",
        "Step 3: Solid particles are closely packed and relatively ordered."
      ],
      ans: "Particles in a solid are closely packed and arranged in relatively fixed positions.",
      why: "Their close, fixed arrangement gives solids a definite shape and volume."
    },
    {
      q: "Describe the arrangement of particles in a liquid.",
      steps: [
        "Step 1: Liquid particles remain relatively close together.",
        "Step 2: They are not held in fixed positions.",
        "Step 3: Their arrangement is less ordered than in a solid."
      ],
      ans: "Liquid particles are relatively close together but are less ordered and can move past one another.",
      why: "This arrangement allows liquids to flow while retaining a nearly fixed volume."
    },
    {
      q: "State the main difference between the particle arrangement in a liquid and a gas.",
      steps: [
        "Step 1: Liquid particles are relatively close together.",
        "Step 2: Gas particles are widely separated.",
        "Step 3: Gas particles therefore have much more empty space between them."
      ],
      ans: "Liquid particles are relatively close together, whereas gas particles are far apart with large spaces between them.",
      why: "The greater separation of gas particles explains their high compressibility and ability to fill a container."
    }
  ],
  [
    {
      q: "Arrange the states solid, liquid and gas in order from particles closest together to particles furthest apart.",
      hint: "Compare the spaces between neighbouring particles.",
      steps: [
        "Step 1: Solid particles are closest together.",
        "Step 2: Liquid particles are slightly more separated.",
        "Step 3: Gas particles are furthest apart."
      ],
      ans: "Solid → Liquid → Gas.",
      why: "The average separation between particles increases from solids to liquids to gases."
    }
  ]
);


// ------------------------------------------------------------
// 8. PARTICLE MOVEMENT
// ------------------------------------------------------------

add(
  "chemistry",
  "matter_separation",
  "Particle Movement",
  `
  <h2>Particle Movement</h2>

  <p>Particles in matter are continuously moving. The type and freedom of
  movement depend on the state of matter.</p>

  <h3>Solids</h3>

  <p>Particles vibrate about fixed positions.</p>

  <h3>Liquids</h3>

  <p>Particles move around and slide past one another.</p>

  <h3>Gases</h3>

  <p>Particles move rapidly and randomly in all directions.</p>

  <h3>Diffusion</h3>

  <p><strong>Diffusion</strong> is the net movement of particles from a region
  of higher concentration to a region of lower concentration due to random
  particle motion.</p>

  <p>Diffusion is fastest in gases because gas particles move rapidly and
  have large spaces between them.</p>

  <h3>Example</h3>

  <p>If a small amount of perfume is released in one part of a room, its
  particles gradually spread throughout the room.</p>
  `,
  [
    {
      q: "How do particles move in a solid?",
      steps: [
        "Step 1: Solid particles are held in fixed positions.",
        "Step 2: They cannot move freely from place to place.",
        "Step 3: They vibrate about their fixed positions."
      ],
      ans: "They vibrate about their fixed positions.",
      why: "The particles have kinetic energy but are strongly restricted by neighbouring particles."
    },
    {
      q: "How do particles move in a gas?",
      steps: [
        "Step 1: Gas particles are not fixed in position.",
        "Step 2: They have considerable freedom of movement.",
        "Step 3: They move rapidly and randomly in all directions."
      ],
      ans: "Gas particles move rapidly and randomly in all directions.",
      why: "Large spaces between particles and relatively weak intermolecular attractions allow considerable freedom of movement."
    },
    {
      q: "What is diffusion?",
      steps: [
        "Step 1: Particles are always moving randomly.",
        "Step 2: This random movement causes particles to spread.",
        "Step 3: The net movement is from higher concentration to lower concentration."
      ],
      ans: "Diffusion is the net movement of particles from a region of higher concentration to a region of lower concentration due to random particle motion.",
      why: "Random motion causes particles to spread until they become more evenly distributed."
    }
  ],
  [
    {
      q: "A smell released at one end of a room is eventually detected at the other end. Explain this using particle movement.",
      hint: "Think about gas particles and diffusion.",
      steps: [
        "Step 1: The smell-producing substance releases particles into the air.",
        "Step 2: Gas particles move randomly in all directions.",
        "Step 3: The particles diffuse from the region of higher concentration.",
        "Step 4: Eventually some particles reach the other side of the room."
      ],
      ans: "The particles move randomly through the air and diffuse from the region of higher concentration to lower concentration until they spread through the room.",
      why: "Diffusion is caused by continuous random particle motion."
    }
  ]
);


// ------------------------------------------------------------
// 9. EFFECT OF TEMPERATURE ON PARTICLES
// ------------------------------------------------------------

add(
  "chemistry",
  "matter_separation",
  "Effect of Temperature on Particles",
  `
  <h2>Effect of Temperature on Particles</h2>

  <p>Temperature affects the kinetic energy and movement of particles.</p>

  <h3>Increasing Temperature</h3>

  <p>When a substance is heated, its particles gain kinetic energy.</p>

  <p>As a result:</p>

  <ul>
    <li>Particles move faster.</li>
    <li>Collisions may become more frequent and energetic.</li>
    <li>Diffusion generally becomes faster.</li>
  </ul>

  <h3>Cooling</h3>

  <p>When a substance is cooled, its particles lose kinetic energy and move
  more slowly.</p>

  <h3>Example: Diffusion</h3>

  <p>Food colouring spreads through warm water faster than through cold water
  because the particles have greater kinetic energy at the higher
  temperature.</p>

  <h3>Important Point</h3>

  <p>Increasing temperature does not create new particles. It increases the
  average kinetic energy of the particles already present.</p>
  `,
  [
    {
      q: "What happens to particle movement when the temperature of a substance increases?",
      steps: [
        "Step 1: Heating transfers energy to the particles.",
        "Step 2: The particles gain kinetic energy.",
        "Step 3: Their average movement becomes faster."
      ],
      ans: "The particles gain kinetic energy and move faster on average.",
      why: "Temperature is related to the average kinetic energy of particles."
    },
    {
      q: "Why does diffusion generally occur faster at higher temperatures?",
      steps: [
        "Step 1: Increasing temperature gives particles more kinetic energy.",
        "Step 2: The particles move faster.",
        "Step 3: Faster random movement causes particles to spread more quickly."
      ],
      ans: "Diffusion is generally faster at higher temperatures because particles have more kinetic energy and move faster.",
      why: "Faster particle movement increases the rate at which particles spread."
    },
    {
      q: "What happens to particle movement when a substance is cooled?",
      steps: [
        "Step 1: Cooling removes thermal energy from the substance.",
        "Step 2: The average kinetic energy of the particles decreases.",
        "Step 3: The particles move more slowly on average."
      ],
      ans: "Particles lose kinetic energy and move more slowly on average.",
      why: "Lower temperature corresponds to lower average kinetic energy."
    }
  ],
  [
    {
      q: "Two identical beakers contain equal volumes of water. Food colouring is added to both. The colouring spreads faster in the warm water than in the cold water. Explain why.",
      hint: "Compare the kinetic energy of the particles.",
      steps: [
        "Step 1: The warm water has a higher temperature.",
        "Step 2: Its particles have greater average kinetic energy.",
        "Step 3: They move faster.",
        "Step 4: Faster particle movement increases the rate of diffusion."
      ],
      ans: "The particles in the warm water have greater average kinetic energy and move faster, so the food colouring diffuses more quickly.",
      why: "Higher temperature increases the average kinetic energy of particles."
    }
  ]
);
// ============================================================
// CHEMISTRY — BATCH 3: CHANGES OF STATE
// One concept per screen
// ============================================================


// ------------------------------------------------------------
// 1. MELTING
// ------------------------------------------------------------

add(
  "chemistry",
  "matter_separation",
  "Melting",
  `
  <h2>Melting</h2>

  <p><strong>Melting</strong> is the change of state in which a substance
  changes from a <strong>solid to a liquid</strong>.</p>

  <p><strong>Solid → Liquid</strong></p>

  <h3>What Happens to the Particles?</h3>

  <p>When a solid is heated, its particles gain kinetic energy and vibrate
  more strongly about their fixed positions.</p>

  <p>At the melting point, the particles have enough energy to overcome
  enough of the forces holding them in their fixed arrangement. They can
  then move past one another as a liquid.</p>

  <h3>Melting Point</h3>

  <p>The <strong>melting point</strong> is the temperature at which a pure
  substance changes from solid to liquid at a stated pressure.</p>

  <p>For example, pure ice melts at approximately <strong>0°C</strong> at
  standard atmospheric pressure.</p>

  <h3>Important Point</h3>

  <p>Melting is a <strong>physical change</strong>. The substance itself
  remains chemically the same.</p>

  <p>For example:</p>

  <p><strong>Ice → liquid water</strong></p>

  <p>Both are H₂O.</p>
  `,
  [
    {
      q: "What is melting?",
      steps: [
        "Step 1: Identify the initial state.",
        "Step 2: Identify the final state.",
        "Step 3: A solid changes into a liquid."
      ],
      ans: "Melting is the change of state from a solid to a liquid.",
      why: "Heating gives the particles enough energy to leave their fixed positions and move past one another."
    },
    {
      q: "What happens to the particles of a solid as it is heated towards its melting point?",
      steps: [
        "Step 1: Heating transfers energy to the particles.",
        "Step 2: Their kinetic energy increases.",
        "Step 3: They vibrate more strongly about their fixed positions.",
        "Step 4: At the melting point, they can begin moving past one another."
      ],
      ans: "The particles gain kinetic energy and vibrate more strongly until they have enough energy to leave their fixed positions and move past one another.",
      why: "The change from solid to liquid requires particles to become less restricted in their movement."
    },
    {
      q: "Ice melts at 0°C at standard atmospheric pressure. What is the melting point of pure ice under these conditions?",
      steps: [
        "Step 1: Identify the stated temperature.",
        "Step 2: The temperature at which the solid changes to liquid is the melting point."
      ],
      ans: "0°C.",
      why: "The melting point is the temperature at which a pure substance changes from solid to liquid under stated conditions."
    }
  ],
  [
    {
      q: "A learner says that melting ice produces a new substance. Is this correct?",
      hint: "Compare the chemical identity of ice and liquid water.",
      steps: [
        "Step 1: Ice is solid H₂O.",
        "Step 2: Liquid water is also H₂O.",
        "Step 3: The physical state changes, but the chemical substance does not."
      ],
      ans: "No. Melting ice is a physical change because both ice and liquid water are H₂O.",
      why: "A change of state does not create a different chemical substance."
    }
  ]
);


// ------------------------------------------------------------
// 2. FREEZING
// ------------------------------------------------------------

add(
  "chemistry",
  "matter_separation",
  "Freezing",
  `
  <h2>Freezing</h2>

  <p><strong>Freezing</strong> is the change of state in which a substance
  changes from a <strong>liquid to a solid</strong>.</p>

  <p><strong>Liquid → Solid</strong></p>

  <h3>What Happens to the Particles?</h3>

  <p>When a liquid is cooled, its particles lose kinetic energy and move
  more slowly.</p>

  <p>As cooling continues, the particles become increasingly restricted
  until they become arranged in fixed positions in the solid.</p>

  <h3>Freezing Point</h3>

  <p>The <strong>freezing point</strong> is the temperature at which a pure
  substance changes from liquid to solid at a stated pressure.</p>

  <p>Pure water freezes at approximately <strong>0°C</strong> at standard
  atmospheric pressure.</p>

  <h3>Freezing Is a Physical Change</h3>

  <p>Freezing does not produce a new chemical substance.</p>

  <p>For example:</p>

  <p><strong>Liquid water → ice</strong></p>

  <p>Both are H₂O.</p>
  `,
  [
    {
      q: "What is freezing?",
      steps: [
        "Step 1: Identify the initial state: liquid.",
        "Step 2: Identify the final state: solid.",
        "Step 3: State the name of the change."
      ],
      ans: "Freezing is the change of state from a liquid to a solid.",
      why: "Cooling removes energy from the particles, causing them to move less and become fixed in a solid arrangement."
    },
    {
      q: "What happens to particles when a liquid freezes?",
      steps: [
        "Step 1: Cooling removes thermal energy.",
        "Step 2: The particles lose kinetic energy.",
        "Step 3: Their movement becomes slower.",
        "Step 4: They become arranged in relatively fixed positions."
      ],
      ans: "The particles lose kinetic energy, move more slowly and become arranged in fixed positions.",
      why: "Reduced particle movement allows the solid structure to form."
    },
    {
      q: "Water freezes at approximately 0°C at standard atmospheric pressure. What happens to water when it reaches its freezing point and continues to lose heat?",
      steps: [
        "Step 1: Water is initially liquid.",
        "Step 2: At its freezing point, the liquid begins changing to solid.",
        "Step 3: Continued heat removal allows more liquid to become ice."
      ],
      ans: "The liquid water changes into solid ice.",
      why: "Freezing is the liquid-to-solid change of state."
    }
  ],
  [
    {
      q: "A student says that freezing is a chemical change because the water becomes hard ice. Correct the statement.",
      hint: "Check whether the chemical substance has changed.",
      steps: [
        "Step 1: Liquid water consists of H₂O.",
        "Step 2: Ice also consists of H₂O.",
        "Step 3: Only the physical state has changed."
      ],
      ans: "Freezing is a physical change because liquid water and ice are both H₂O.",
      why: "No new chemical substance is formed during freezing."
    }
  ]
);


// ------------------------------------------------------------
// 3. EVAPORATION
// ------------------------------------------------------------

add(
  "chemistry",
  "matter_separation",
  "Evaporation",
  `
  <h2>Evaporation</h2>

  <p><strong>Evaporation</strong> is the change of state in which particles
  escape from the <strong>surface of a liquid</strong> and enter the gas
  state.</p>

  <p><strong>Liquid → Gas</strong></p>

  <h3>How Evaporation Happens</h3>

  <p>Particles in a liquid have different amounts of kinetic energy.</p>

  <p>Some particles at the surface have enough energy to overcome the
  attractive forces holding them in the liquid. These particles escape into
  the gas state.</p>

  <h3>Important Features</h3>

  <ul>
    <li>Evaporation occurs at the surface.</li>
    <li>It can occur below the boiling point.</li>
    <li>It can occur at different temperatures.</li>
    <li>It becomes faster when temperature increases.</li>
    <li>It becomes faster when surface area increases.</li>
    <li>Moving air can increase the rate of evaporation.</li>
  </ul>

  <h3>Cooling by Evaporation</h3>

  <p>The particles that escape tend to be the faster-moving, higher-energy
  particles. The particles remaining in the liquid therefore have a lower
  average kinetic energy, causing cooling.</p>
  `,
  [
    {
      q: "What is evaporation?",
      steps: [
        "Step 1: Identify the initial state: liquid.",
        "Step 2: Particles escape from the liquid surface.",
        "Step 3: They enter the gas state."
      ],
      ans: "Evaporation is the change from liquid to gas that occurs at the surface of a liquid.",
      why: "Only particles at or near the surface can escape directly into the gas state."
    },
    {
      q: "Why can evaporation occur below the boiling point?",
      steps: [
        "Step 1: Liquid particles have different kinetic energies.",
        "Step 2: Some surface particles have enough energy to escape.",
        "Step 3: Therefore particles can leave the surface even when the whole liquid has not reached its boiling point."
      ],
      ans: "Evaporation can occur below the boiling point because some surface particles have enough kinetic energy to escape from the liquid.",
      why: "Not all particles have the same kinetic energy."
    },
    {
      q: "Why does evaporation generally become faster when the temperature of a liquid increases?",
      steps: [
        "Step 1: Increasing temperature increases the average kinetic energy of the particles.",
        "Step 2: More surface particles have enough energy to escape.",
        "Step 3: More particles escape per unit time.",
        "Step 4: The rate of evaporation therefore increases."
      ],
      ans: "Evaporation becomes faster because more surface particles have sufficient kinetic energy to escape from the liquid.",
      why: "Higher temperature increases the number of particles capable of escaping from the surface."
    }
  ],
  [
    {
      q: "Wet clothes dry faster on a windy day than on a still day. Explain why.",
      hint: "Think about what moving air does to water vapour near the clothes.",
      steps: [
        "Step 1: Water evaporates from the surface of the clothes.",
        "Step 2: Moving air removes water vapour from near the surface.",
        "Step 3: This allows more water particles to escape.",
        "Step 4: The rate of evaporation increases."
      ],
      ans: "Wind removes water vapour from around the clothes, allowing more water particles to escape from the surface, so evaporation occurs faster.",
      why: "Removing vapour near the surface helps maintain a concentration gradient that favours further evaporation."
    }
  ]
);


// ------------------------------------------------------------
// 4. BOILING
// ------------------------------------------------------------

add(
  "chemistry",
  "matter_separation",
  "Boiling",
  `
  <h2>Boiling</h2>

  <p><strong>Boiling</strong> is the rapid change of a liquid to a gas that
  occurs throughout the liquid at its boiling point.</p>

  <p><strong>Liquid → Gas</strong></p>

  <h3>What Happens During Boiling?</h3>

  <p>When a liquid reaches its boiling point, vapour bubbles form throughout
  the liquid and rise to the surface.</p>

  <p>The liquid continues changing into gas as long as energy is supplied
  under the same pressure conditions.</p>

  <h3>Boiling Point</h3>

  <p>The <strong>boiling point</strong> is the temperature at which a liquid
  boils at a stated pressure.</p>

  <p>Pure water boils at approximately <strong>100°C</strong> at standard
  atmospheric pressure.</p>

  <h3>Boiling vs Evaporation</h3>

  <p><strong>Boiling:</strong></p>

  <ul>
    <li>Occurs throughout the liquid.</li>
    <li>Occurs at the boiling point for a given pressure.</li>
    <li>Vapour bubbles form throughout the liquid.</li>
  </ul>

  <p><strong>Evaporation:</strong></p>

  <ul>
    <li>Occurs at the surface.</li>
    <li>Can occur below the boiling point.</li>
    <li>Does not require bubbles throughout the liquid.</li>
  </ul>
  `,
  [
    {
      q: "What is boiling?",
      steps: [
        "Step 1: Identify the initial state: liquid.",
        "Step 2: The liquid reaches its boiling point.",
        "Step 3: Vapour bubbles form throughout the liquid.",
        "Step 4: The liquid changes to gas."
      ],
      ans: "Boiling is the change of a liquid to a gas throughout the liquid at its boiling point.",
      why: "Boiling differs from evaporation because vapour formation occurs throughout the liquid."
    },
    {
      q: "What happens inside a liquid when it boils?",
      steps: [
        "Step 1: The liquid reaches its boiling point.",
        "Step 2: Vapour forms within the liquid.",
        "Step 3: Bubbles of vapour rise through the liquid.",
        "Step 4: The vapour escapes at the surface."
      ],
      ans: "Vapour bubbles form throughout the liquid and rise to the surface.",
      why: "Boiling is a bulk process rather than only a surface process."
    },
    {
      q: "Water boils at approximately 100°C at standard atmospheric pressure. What does this temperature represent?",
      steps: [
        "Step 1: Identify the process occurring.",
        "Step 2: The temperature at which a liquid boils is its boiling point."
      ],
      ans: "It represents the boiling point of water under standard atmospheric pressure.",
      why: "Boiling point depends on pressure, so the pressure condition must be stated."
    }
  ],
  [
    {
      q: "A learner says that a puddle evaporating in the sun is boiling. Explain the mistake.",
      hint: "Compare where the change occurs and the temperature required.",
      steps: [
        "Step 1: A puddle can evaporate without reaching its boiling point.",
        "Step 2: Evaporation occurs only at the surface.",
        "Step 3: Boiling occurs throughout the liquid at its boiling point."
      ],
      ans: "The learner is incorrect. A puddle normally evaporates from its surface and does not need to reach its boiling point.",
      why: "Evaporation and boiling are both liquid-to-gas changes but occur differently."
    }
  ]
);


// ------------------------------------------------------------
// 5. CONDENSATION
// ------------------------------------------------------------

add(
  "chemistry",
  "matter_separation",
  "Condensation",
  `
  <h2>Condensation</h2>

  <p><strong>Condensation</strong> is the change of state in which a gas
  changes into a liquid.</p>

  <p><strong>Gas → Liquid</strong></p>

  <h3>What Happens to the Particles?</h3>

  <p>When a gas is cooled, its particles lose kinetic energy and move more
  slowly.</p>

  <p>As the particles lose energy, attractive forces between them become
  more effective at bringing them closer together. The gas changes into a
  liquid.</p>

  <h3>Examples</h3>

  <ul>
    <li>Water vapour forming droplets on a cold surface.</li>
    <li>Steam forming liquid water on a cooler surface.</li>
    <li>Water vapour in the atmosphere forming cloud droplets.</li>
  </ul>

  <h3>Condensation in Distillation</h3>

  <p>During distillation, vapour passes into a condenser where it is cooled
  and changed back into a liquid.</p>

  <p>Condensation is the reverse of vaporisation.</p>
  `,
  [
    {
      q: "What is condensation?",
      steps: [
        "Step 1: Identify the initial state: gas.",
        "Step 2: Identify the final state: liquid.",
        "Step 3: State the name of the change."
      ],
      ans: "Condensation is the change of state from gas to liquid.",
      why: "Cooling removes energy from gas particles, allowing them to come closer together."
    },
    {
      q: "What happens to gas particles when condensation occurs?",
      steps: [
        "Step 1: The gas is cooled.",
        "Step 2: Particles lose kinetic energy.",
        "Step 3: They move more slowly.",
        "Step 4: They come closer together and form a liquid."
      ],
      ans: "The particles lose kinetic energy, move more slowly and come closer together to form a liquid.",
      why: "Reduced kinetic energy allows attractive forces between particles to become more effective."
    },
    {
      q: "Why do water droplets form on the outside of a cold glass containing a cold drink?",
      steps: [
        "Step 1: The air around the glass contains water vapour.",
        "Step 2: The cold glass cools the nearby air and water vapour.",
        "Step 3: The water vapour loses energy.",
        "Step 4: It condenses into liquid water droplets."
      ],
      ans: "Water vapour in the surrounding air cools and condenses into liquid droplets on the cold glass.",
      why: "The droplets come from water vapour in the air, not from water passing through the glass."
    }
  ],
  [
    {
      q: "A student claims that water droplets on a cold bottle have leaked through the bottle. Explain why this is not normally the case.",
      hint: "Think about the water vapour in the surrounding air.",
      steps: [
        "Step 1: Air contains water vapour.",
        "Step 2: The bottle surface is cold.",
        "Step 3: Water vapour touching the cold surface loses energy.",
        "Step 4: It condenses into liquid droplets."
      ],
      ans: "The droplets normally form by condensation of water vapour from the surrounding air on the cold bottle surface.",
      why: "The gas-to-liquid change occurs when the water vapour is cooled."
    }
  ]
);


// ------------------------------------------------------------
// 6. SUBLIMATION
// ------------------------------------------------------------

add(
  "chemistry",
  "matter_separation",
  "Sublimation",
  `
  <h2>Sublimation</h2>

  <p><strong>Sublimation</strong> is the change of state in which a solid
  changes directly into a gas without passing through the liquid state.</p>

  <p><strong>Solid → Gas</strong></p>

  <h3>What Happens to the Particles?</h3>

  <p>The particles in the solid gain enough energy to escape directly into
  the gas state.</p>

  <p>The liquid state is skipped.</p>

  <h3>Examples</h3>

  <ul>
    <li>Solid carbon dioxide (dry ice) changes directly into carbon dioxide gas.</li>
    <li>Iodine can form iodine vapour when heated.</li>
  </ul>

  <h3>Important Point</h3>

  <p>Sublimation is a physical change. The chemical identity of the substance
  remains the same.</p>

  <p>For example:</p>

  <p><strong>Solid CO₂ → CO₂ gas</strong></p>

  <p>The substance remains carbon dioxide.</p>
  `,
  [
    {
      q: "What is sublimation?",
      steps: [
        "Step 1: Identify the starting state: solid.",
        "Step 2: Identify the final state: gas.",
        "Step 3: Check whether the liquid state is passed through.",
        "Step 4: The liquid state is skipped."
      ],
      ans: "Sublimation is the direct change of a solid into a gas without passing through the liquid state.",
      why: "Sublimation is a direct solid-to-gas change."
    },
    {
      q: "What happens to the particles during sublimation?",
      steps: [
        "Step 1: Energy is supplied to the solid.",
        "Step 2: The particles gain kinetic energy.",
        "Step 3: Some particles gain enough energy to escape the solid.",
        "Step 4: They enter the gas state directly."
      ],
      ans: "The particles gain enough energy to escape directly from the solid into the gas state.",
      why: "The particles do not need to form a liquid first."
    },
    {
      q: "Dry ice is solid carbon dioxide. What happens when dry ice changes directly into carbon dioxide gas?",
      steps: [
        "Step 1: The starting state is solid.",
        "Step 2: The final state is gas.",
        "Step 3: No liquid state is involved.",
        "Step 4: Therefore the process is sublimation."
      ],
      ans: "Sublimation occurs.",
      why: "A direct solid-to-gas change is sublimation."
    }
  ],
  [
    {
      q: "A learner says that dry ice melts into a liquid before becoming gas. Correct the statement.",
      hint: "Consider the meaning of sublimation.",
      steps: [
        "Step 1: Dry ice is solid CO₂.",
        "Step 2: Under ordinary atmospheric conditions, it changes directly to CO₂ gas.",
        "Step 3: It does not pass through the liquid state under these conditions."
      ],
      ans: "Dry ice changes directly from solid CO₂ to gaseous CO₂ by sublimation; it does not first become liquid under ordinary atmospheric conditions.",
      why: "Sublimation is the direct solid-to-gas change."
    }
  ]
);


// ------------------------------------------------------------
// 7. DEPOSITION
// ------------------------------------------------------------

add(
  "chemistry",
  "matter_separation",
  "Deposition",
  `
  <h2>Deposition</h2>

  <p><strong>Deposition</strong> is the change of state in which a gas changes
  directly into a solid without passing through the liquid state.</p>

  <p><strong>Gas → Solid</strong></p>

  <h3>What Happens to the Particles?</h3>

  <p>Gas particles lose kinetic energy as they are cooled.</p>

  <p>They move more slowly and become held in a fixed arrangement, forming
  a solid directly.</p>

  <h3>Example: Frost</h3>

  <p>Water vapour in cold air can change directly into solid ice on a very
  cold surface. This forms frost.</p>

  <h3>Relationship with Sublimation</h3>

  <p>Deposition is the reverse of sublimation.</p>

  <p><strong>Sublimation:</strong> Solid → Gas</p>

  <p><strong>Deposition:</strong> Gas → Solid</p>

  <h3>Important Point</h3>

  <p>The chemical identity of the substance remains unchanged. Therefore
  deposition is a physical change.</p>
  `,
  [
    {
      q: "What is deposition?",
      steps: [
        "Step 1: Identify the starting state: gas.",
        "Step 2: Identify the final state: solid.",
        "Step 3: Check whether the liquid state is skipped.",
        "Step 4: The liquid state is skipped."
      ],
      ans: "Deposition is the direct change of a gas into a solid without passing through the liquid state.",
      why: "Deposition is a direct gas-to-solid change."
    },
    {
      q: "What happens to particles during deposition?",
      steps: [
        "Step 1: The gas is cooled.",
        "Step 2: Particles lose kinetic energy.",
        "Step 3: Their movement becomes slower.",
        "Step 4: They become arranged in a solid structure."
      ],
      ans: "The particles lose kinetic energy, move more slowly and become arranged directly into a solid.",
      why: "Cooling reduces particle motion enough for the particles to form a fixed solid arrangement."
    },
    {
      q: "How is deposition related to sublimation?",
      steps: [
        "Step 1: Sublimation is solid → gas.",
        "Step 2: Deposition is gas → solid.",
        "Step 3: The two processes move in opposite directions."
      ],
      ans: "Deposition is the reverse of sublimation.",
      why: "Sublimation changes a solid directly to a gas, while deposition changes a gas directly to a solid."
    }
  ],
  [
    {
      q: "Frost forms directly from water vapour on a very cold surface. Which change of state has occurred?",
      hint: "Water vapour is a gas and frost is solid ice.",
      steps: [
        "Step 1: Water vapour is a gas.",
        "Step 2: Frost is solid water.",
        "Step 3: The change is gas → solid.",
        "Step 4: Gas → solid directly is deposition."
      ],
      ans: "Deposition.",
      why: "Deposition is the direct change from gas to solid."
    }
  ]
);
// ============================================================
// BATCH 4 — PURE SUBSTANCES AND MIXTURES
// Chapter: matter_separation
// ============================================================


// ============================================================
// 1. ELEMENTS
// ============================================================

add(
  "chemistry",
  "matter_separation",
  "Elements",
  `<h2>Elements</h2>

  <p>An <strong>element</strong> is a pure substance made of only one type of atom.</p>

  <p>Each element is identified by its <strong>atomic number</strong>, which is the number of protons in its atoms.</p>

  <h3>Examples</h3>
  <ul>
    <li>Iron — Fe</li>
    <li>Copper — Cu</li>
    <li>Oxygen — O₂</li>
    <li>Hydrogen — H₂</li>
    <li>Carbon — C</li>
  </ul>

  <p>O₂ is still an element because every atom present is oxygen. The fact that two oxygen atoms are joined does not make it a compound.</p>

  <h3>Key idea</h3>
  <p><strong>One type of atom → element.</strong></p>

  <p>Elements cannot be broken down into simpler substances by ordinary chemical reactions.</p>`,

  [
    {
      q: "What is an element?",
      steps: [
        "Step 1: An element is a pure substance.",
        "Step 2: It contains only one type of atom.",
        "Step 3: Therefore, an element is a pure substance made of one type of atom."
      ],
      ans: "An element is a pure substance made of only one type of atom.",
      why: "The defining feature of an element is that all its atoms have the same proton number."
    },
    {
      q: "Is O₂ an element or a compound?",
      steps: [
        "Step 1: O₂ contains two atoms.",
        "Step 2: Both atoms are oxygen atoms.",
        "Step 3: Only one type of atom is present.",
        "Step 4: Therefore, O₂ is an element."
      ],
      ans: "O₂ is an element.",
      why: "An element can exist as molecules such as O₂. It remains an element because it contains only oxygen atoms."
    },
    {
      q: "Classify Fe, H₂O and Cu as elements or compounds.",
      steps: [
        "Step 1: Fe contains only iron atoms → element.",
        "Step 2: H₂O contains hydrogen and oxygen chemically combined → compound.",
        "Step 3: Cu contains only copper atoms → element."
      ],
      ans: "Fe = element; H₂O = compound; Cu = element.",
      why: "Elements contain one type of atom, while compounds contain two or more different elements chemically combined."
    }
  ],

  [
    {
      q: "A substance contains only chlorine atoms. Classify it.",
      hint: "Ask how many types of atoms are present.",
      steps: [
        "Step 1: Only chlorine atoms are present.",
        "Step 2: Therefore, only one type of atom is present.",
        "Step 3: The substance is an element."
      ],
      ans: "Element",
      why: "A substance containing only one type of atom is an element."
    }
  ]
);


// ============================================================
// 2. COMPOUNDS
// ============================================================

add(
  "chemistry",
  "matter_separation",
  "Compounds",
  `<h2>Compounds</h2>

  <p>A <strong>compound</strong> is a pure substance formed when two or more different elements are chemically combined in a fixed ratio.</p>

  <h3>Examples</h3>
  <ul>
    <li>Water — H₂O</li>
    <li>Carbon dioxide — CO₂</li>
    <li>Sodium chloride — NaCl</li>
    <li>Magnesium oxide — MgO</li>
  </ul>

  <p>The elements in a compound are chemically bonded. The compound has properties different from those of the elements that formed it.</p>

  <h3>Example</h3>
  <p>Sodium is a reactive metal and chlorine is a poisonous gas. When chemically combined, they form sodium chloride, NaCl.</p>

  <h3>Key idea</h3>
  <p><strong>Different elements + chemical combination in a fixed ratio → compound.</strong></p>

  <p>Compounds can be broken down into simpler substances by chemical methods, not ordinary physical separation.</p>`,

  [
    {
      q: "What is a compound?",
      steps: [
        "Step 1: A compound is a pure substance.",
        "Step 2: It contains two or more different elements.",
        "Step 3: The elements are chemically combined.",
        "Step 4: They occur in a fixed ratio."
      ],
      ans: "A compound is a pure substance formed when two or more different elements are chemically combined in a fixed ratio.",
      why: "Chemical combination and fixed composition distinguish compounds from mixtures."
    },
    {
      q: "Why is water, H₂O, a compound?",
      steps: [
        "Step 1: Water contains hydrogen and oxygen.",
        "Step 2: Hydrogen and oxygen are different elements.",
        "Step 3: They are chemically bonded.",
        "Step 4: They occur in a fixed 2:1 ratio.",
        "Step 5: Therefore, water is a compound."
      ],
      ans: "Water is a compound because hydrogen and oxygen are chemically combined in a fixed 2:1 ratio.",
      why: "A compound contains different elements chemically joined in a fixed composition."
    },
    {
      q: "Is sodium chloride, NaCl, an element or a compound? Explain.",
      steps: [
        "Step 1: NaCl contains sodium and chlorine.",
        "Step 2: Sodium and chlorine are different elements.",
        "Step 3: They are chemically combined.",
        "Step 4: Therefore, NaCl is a compound."
      ],
      ans: "NaCl is a compound.",
      why: "It contains two different elements chemically combined in a fixed ratio."
    }
  ],

  [
    {
      q: "A substance contains carbon and oxygen chemically combined in a fixed ratio. What type of substance is it?",
      hint: "Look for different elements that are chemically combined.",
      steps: [
        "Step 1: Carbon and oxygen are different elements.",
        "Step 2: They are chemically combined.",
        "Step 3: Therefore, the substance is a compound."
      ],
      ans: "Compound",
      why: "Different elements chemically combined in a fixed ratio form a compound."
    }
  ]
);


// ============================================================
// 3. MIXTURES
// ============================================================

add(
  "chemistry",
  "matter_separation",
  "Mixtures",
  `<h2>Mixtures</h2>

  <p>A <strong>mixture</strong> contains two or more substances that are physically combined but not chemically bonded to form a new substance.</p>

  <h3>Examples</h3>
  <ul>
    <li>Air</li>
    <li>Salt water</li>
    <li>Sand and water</li>
    <li>Iron filings and sulfur powder</li>
    <li>Brass</li>
  </ul>

  <h3>Important properties</h3>
  <ul>
    <li>The substances in a mixture retain many of their own properties.</li>
    <li>The composition can vary.</li>
    <li>The components can be separated by physical methods.</li>
    <li>No new substance is formed simply by mixing.</li>
  </ul>

  <h3>Example</h3>
  <p>If 5 g of salt is mixed with 100 g of water, more salt can be added without changing the identity of the water or salt. This variable composition is a feature of mixtures.</p>

  <p><strong>Mixture = substances physically combined, not chemically combined.</strong></p>`,

  [
    {
      q: "What is a mixture?",
      steps: [
        "Step 1: A mixture contains two or more substances.",
        "Step 2: The substances are physically combined.",
        "Step 3: They are not chemically bonded to form a new substance.",
        "Step 4: Therefore, the result is a mixture."
      ],
      ans: "A mixture is a physical combination of two or more substances that are not chemically combined.",
      why: "The components of a mixture retain their identities and can generally be separated using physical methods."
    },
    {
      q: "Why is air a mixture?",
      steps: [
        "Step 1: Air contains several gases, including nitrogen and oxygen.",
        "Step 2: These gases are not chemically combined into one fixed compound.",
        "Step 3: Their proportions can vary.",
        "Step 4: Therefore, air is a mixture."
      ],
      ans: "Air is a mixture because it contains several gases that are physically mixed.",
      why: "The gases in air retain their individual identities and are not chemically combined in a fixed ratio."
    },
    {
      q: "A student mixes iron filings with sulfur powder without heating them. Is the result a mixture or compound?",
      steps: [
        "Step 1: Iron and sulfur are placed together.",
        "Step 2: They have not chemically reacted.",
        "Step 3: Each substance retains its own properties.",
        "Step 4: Therefore, the result is a mixture."
      ],
      ans: "Mixture.",
      why: "Iron and sulfur are only physically mixed. A compound would require chemical combination."
    }
  ],

  [
    {
      q: "A sample contains water and sand. Classify it.",
      hint: "Ask whether the substances are chemically combined.",
      steps: [
        "Step 1: Water and sand are two different substances.",
        "Step 2: They are not chemically combined.",
        "Step 3: Therefore, the sample is a mixture."
      ],
      ans: "Mixture",
      why: "Water and sand are physically combined and can be separated by physical methods."
    }
  ]
);


// ============================================================
// 4. HOMOGENEOUS MIXTURES
// ============================================================

add(
  "chemistry",
  "matter_separation",
  "Homogeneous Mixtures",
  `<h2>Homogeneous Mixtures</h2>

  <p>A <strong>homogeneous mixture</strong> is a mixture whose composition is uniform throughout.</p>

  <p>Every part of the mixture has essentially the same composition and properties.</p>

  <h3>Examples</h3>
  <ul>
    <li>Salt solution</li>
    <li>Sugar solution</li>
    <li>Air</li>
    <li>Brass</li>
  </ul>

  <h3>Key features</h3>
  <ul>
    <li>Uniform composition throughout.</li>
    <li>Components are not normally visibly distinguishable.</li>
    <li>It is still a mixture.</li>
    <li>Its components can be separated by suitable physical methods.</li>
  </ul>

  <h3>Example</h3>
  <p>When salt dissolves completely in water, the salt particles become evenly distributed throughout the water. A sample taken from the top has the same composition as a sample taken from the bottom, assuming the solution is properly mixed.</p>

  <p><strong>Homogeneous = uniform throughout.</strong></p>`,

  [
    {
      q: "What is a homogeneous mixture?",
      steps: [
        "Step 1: It contains two or more substances.",
        "Step 2: The substances are physically combined.",
        "Step 3: They are distributed uniformly throughout the mixture.",
        "Step 4: Therefore, it is a homogeneous mixture."
      ],
      ans: "A homogeneous mixture is a mixture with uniform composition throughout.",
      why: "Uniform distribution is the defining feature of a homogeneous mixture."
    },
    {
      q: "Classify salt water as homogeneous or heterogeneous when all the salt has dissolved.",
      steps: [
        "Step 1: Salt and water are different substances.",
        "Step 2: They are physically mixed.",
        "Step 3: The dissolved salt is uniformly distributed throughout the water.",
        "Step 4: Therefore, the mixture is homogeneous."
      ],
      ans: "Homogeneous mixture.",
      why: "The dissolved salt is evenly distributed throughout the solution."
    },
    {
      q: "Why is air classified as a homogeneous mixture?",
      steps: [
        "Step 1: Air contains several gases.",
        "Step 2: These gases are physically mixed.",
        "Step 3: The gases are distributed fairly uniformly throughout a sample of air.",
        "Step 4: Therefore, air is a homogeneous mixture."
      ],
      ans: "Air is a homogeneous mixture because its component gases are uniformly distributed.",
      why: "A homogeneous mixture has a uniform composition throughout."
    }
  ],

  [
    {
      q: "A solution has the same composition at the top, middle and bottom. What type of mixture is it?",
      hint: "Uniform composition is the key.",
      steps: [
        "Step 1: The composition is the same throughout.",
        "Step 2: Uniform composition means homogeneous.",
        "Step 3: Therefore, it is a homogeneous mixture."
      ],
      ans: "Homogeneous mixture",
      why: "Homogeneous mixtures have uniform composition throughout."
    }
  ]
);


// ============================================================
// 5. HETEROGENEOUS MIXTURES
// ============================================================

add(
  "chemistry",
  "matter_separation",
  "Heterogeneous Mixtures",
  `<h2>Heterogeneous Mixtures</h2>

  <p>A <strong>heterogeneous mixture</strong> is a mixture whose composition is not uniform throughout.</p>

  <p>Different parts of the mixture may contain different amounts or types of components.</p>

  <h3>Examples</h3>
  <ul>
    <li>Sand and water</li>
    <li>Oil and water</li>
    <li>Iron filings and sulfur</li>
    <li>Sand and gravel</li>
  </ul>

  <h3>Key features</h3>
  <ul>
    <li>Composition is not uniform.</li>
    <li>Different components may be visibly distinguishable.</li>
    <li>Different portions can have different compositions.</li>
    <li>Components can usually be separated using physical methods.</li>
  </ul>

  <h3>Example</h3>
  <p>In a mixture of sand and water, the sand settles at the bottom while water remains above it. The composition is therefore not uniform throughout the sample.</p>

  <p><strong>Heterogeneous = non-uniform throughout.</strong></p>`,

  [
    {
      q: "What is a heterogeneous mixture?",
      steps: [
        "Step 1: It contains two or more substances.",
        "Step 2: The substances are physically combined.",
        "Step 3: They are not distributed uniformly.",
        "Step 4: Therefore, it is a heterogeneous mixture."
      ],
      ans: "A heterogeneous mixture is a mixture whose composition is not uniform throughout.",
      why: "Uneven distribution of components distinguishes heterogeneous mixtures from homogeneous mixtures."
    },
    {
      q: "Classify a mixture of oil and water.",
      steps: [
        "Step 1: Oil and water are different substances.",
        "Step 2: They do not mix uniformly.",
        "Step 3: Separate layers are formed.",
        "Step 4: Therefore, the mixture is heterogeneous."
      ],
      ans: "Heterogeneous mixture.",
      why: "The oil and water form separate regions, so the composition is not uniform."
    },
    {
      q: "Why is sand and water a heterogeneous mixture?",
      steps: [
        "Step 1: Sand and water are physically combined.",
        "Step 2: Sand does not dissolve uniformly in the water.",
        "Step 3: Different parts of the sample contain different amounts of sand and water.",
        "Step 4: Therefore, it is heterogeneous."
      ],
      ans: "Sand and water form a heterogeneous mixture because their composition is not uniform throughout.",
      why: "The components remain physically distinct and are unevenly distributed."
    }
  ],

  [
    {
      q: "A mixture contains visible particles of two different substances. Classify it.",
      hint: "Visible separate components usually indicate non-uniform composition.",
      steps: [
        "Step 1: The components can be distinguished.",
        "Step 2: The composition is therefore not uniform.",
        "Step 3: The mixture is heterogeneous."
      ],
      ans: "Heterogeneous mixture",
      why: "Heterogeneous mixtures have non-uniform composition and may have visibly distinct components."
    }
  ]
);


// ============================================================
// 6. IDENTIFYING PURE SUBSTANCES
// ============================================================

add(
  "chemistry",
  "matter_separation",
  "Identifying Pure Substances",
  `<h2>Identifying Pure Substances</h2>

  <p>A <strong>pure substance</strong> contains only one type of substance and has a fixed composition.</p>

  <p>Pure substances are divided into two groups:</p>

  <ul>
    <li><strong>Elements</strong> — contain one type of atom.</li>
    <li><strong>Compounds</strong> — contain two or more different elements chemically combined in a fixed ratio.</li>
  </ul>

  <h3>How to identify a pure substance</h3>

  <p>Ask:</p>

  <ol>
    <li>Does it contain only one substance?</li>
    <li>Does it have a fixed composition?</li>
    <li>Does it have characteristic physical properties such as a definite melting point or boiling point?</li>
  </ol>

  <p>If the sample is a pure substance, determine whether it is an <strong>element</strong> or a <strong>compound</strong>.</p>

  <h3>Examples</h3>
  <ul>
    <li>Cu → pure substance → element</li>
    <li>O₂ → pure substance → element</li>
    <li>H₂O → pure substance → compound</li>
    <li>NaCl → pure substance → compound</li>
  </ul>

  <p><strong>Pure substance → element or compound.</strong></p>`,

  [
    {
      q: "What are the two types of pure substances?",
      steps: [
        "Step 1: Pure substances have fixed composition.",
        "Step 2: A pure substance can contain one type of atom → element.",
        "Step 3: It can also contain different elements chemically combined → compound."
      ],
      ans: "Elements and compounds.",
      why: "Elements and compounds are the two main classes of pure substances."
    },
    {
      q: "Classify pure water, H₂O, as an element or compound.",
      steps: [
        "Step 1: H₂O contains hydrogen and oxygen.",
        "Step 2: These are two different elements.",
        "Step 3: They are chemically combined in a fixed ratio.",
        "Step 4: Therefore, H₂O is a compound."
      ],
      ans: "Compound.",
      why: "Pure water contains hydrogen and oxygen chemically combined in a fixed ratio."
    },
    {
      q: "Classify pure copper, Cu.",
      steps: [
        "Step 1: Cu represents copper.",
        "Step 2: Only copper atoms are present.",
        "Step 3: Therefore, it is an element.",
        "Step 4: Since it contains only one type of substance, pure copper is a pure substance."
      ],
      ans: "Cu is a pure substance and an element.",
      why: "Copper contains only one type of atom."
    }
  ],

  [
    {
      q: "A sample contains only NaCl particles. Is it a pure substance?",
      hint: "Ask whether only one substance is present.",
      steps: [
        "Step 1: Only NaCl is present.",
        "Step 2: Therefore, only one substance is present.",
        "Step 3: The sample is a pure substance.",
        "Step 4: NaCl contains sodium and chlorine chemically combined, so it is a compound."
      ],
      ans: "Yes. It is a pure substance and a compound.",
      why: "Pure NaCl contains only one compound."
    }
  ]
);


// ============================================================
// 7. IDENTIFYING MIXTURES
// ============================================================

add(
  "chemistry",
  "matter_separation",
  "Identifying Mixtures",
  `<h2>Identifying Mixtures</h2>

  <p>A mixture contains two or more substances that are physically combined.</p>

  <h3>Classification process</h3>

  <p>When given a sample, use this sequence:</p>

  <ol>
    <li>Ask whether more than one substance is present.</li>
    <li>If yes, it is a mixture.</li>
    <li>Ask whether the composition is uniform.</li>
    <li>If uniform → homogeneous mixture.</li>
    <li>If non-uniform → heterogeneous mixture.</li>
  </ol>

  <h3>Examples</h3>

  <p><strong>Salt water:</strong> mixture → uniform → homogeneous.</p>

  <p><strong>Oil and water:</strong> mixture → non-uniform → heterogeneous.</p>

  <p><strong>Air:</strong> mixture → generally uniform → homogeneous.</p>

  <p><strong>Sand and water:</strong> mixture → non-uniform → heterogeneous.</p>

  <h3>Fast classification rule</h3>

  <p><strong>More than one substance?</strong></p>
  <p>Yes → mixture.</p>

  <p><strong>Uniform throughout?</strong></p>
  <p>Yes → homogeneous.</p>

  <p>No → heterogeneous.</p>`,

  [
    {
      q: "Classify salt water as pure substance, homogeneous mixture or heterogeneous mixture.",
      steps: [
        "Step 1: Salt and water are two different substances.",
        "Step 2: Therefore, it is a mixture.",
        "Step 3: If the salt is completely dissolved, it is uniformly distributed.",
        "Step 4: Therefore, it is a homogeneous mixture."
      ],
      ans: "Homogeneous mixture.",
      why: "Salt water contains more than one substance, but the dissolved salt is uniformly distributed."
    },
    {
      q: "Classify oil and water.",
      steps: [
        "Step 1: Oil and water are different substances.",
        "Step 2: Therefore, the sample is a mixture.",
        "Step 3: Oil and water form separate layers.",
        "Step 4: The composition is not uniform.",
        "Step 5: Therefore, it is a heterogeneous mixture."
      ],
      ans: "Heterogeneous mixture.",
      why: "The components are not uniformly distributed and form separate layers."
    },
    {
      q: "Classify each substance: O₂, H₂O, air and sand mixed with water.",
      steps: [
        "Step 1: O₂ contains only oxygen atoms → element → pure substance.",
        "Step 2: H₂O contains hydrogen and oxygen chemically combined → compound → pure substance.",
        "Step 3: Air contains several gases physically mixed and is generally uniform → homogeneous mixture.",
        "Step 4: Sand and water are physically mixed and non-uniform → heterogeneous mixture."
      ],
      ans: "O₂ = element; H₂O = compound; air = homogeneous mixture; sand and water = heterogeneous mixture.",
      why: "Classification depends on the number of substances present, whether they are chemically combined, and whether a mixture is uniform."
    }
  ],

  [
    {
      q: "Classify a sample containing Fe, S and Cu particles that have not reacted chemically.",
      hint: "Determine whether the substances are chemically combined.",
      steps: [
        "Step 1: Iron, sulfur and copper are separate substances.",
        "Step 2: They have not chemically reacted.",
        "Step 3: Therefore, they form a mixture.",
        "Step 4: If the particles are distributed unevenly, it is heterogeneous."
      ],
      ans: "A heterogeneous mixture.",
      why: "Several substances are physically combined without chemical bonding, and the separate particles make the composition non-uniform."
    }
  ]
);
