// ============================================================


// ============================================================
// 1. FILTRATION
// ============================================================

add(
  "chemistry",
  "matter_separation",
  "Filtration",
  `<h2>Filtration</h2>

  <p><strong>Filtration</strong> is used to separate an <strong>insoluble solid from a liquid</strong>.</p>

  <h3>Principle</h3>
  <p>The method depends on the difference in particle size and the fact that the solid does not dissolve in the liquid.</p>

  <h3>Apparatus</h3>
  <ul>
    <li>Filter funnel</li>
    <li>Filter paper</li>
    <li>Beaker or conical flask</li>
    <li>Glass rod</li>
  </ul>

  <h3>Procedure</h3>
  <ol>
    <li>Place folded filter paper inside the funnel.</li>
    <li>Place the funnel over a clean container.</li>
    <li>Pour the mixture through the filter paper.</li>
    <li>The liquid passes through the paper.</li>
    <li>The insoluble solid remains on the paper.</li>
  </ol>

  <h3>Important terms</h3>
  <p><strong>Residue:</strong> solid left on the filter paper.</p>
  <p><strong>Filtrate:</strong> liquid that passes through the filter paper.</p>

  <h3>Example</h3>
  <p>Sand and water can be separated by filtration because sand is insoluble in water.</p>`,

  [
    {
      q: "What type of mixture can be separated by filtration?",
      steps: [
        "Step 1: Identify the phases present.",
        "Step 2: Filtration separates a solid from a liquid.",
        "Step 3: The solid must be insoluble in the liquid."
      ],
      ans: "An insoluble solid mixed with a liquid.",
      why: "The insoluble solid is trapped by the filter paper while the liquid passes through."
    },
    {
      q: "Describe how to separate sand from water by filtration.",
      steps: [
        "Step 1: Place filter paper in a filter funnel.",
        "Step 2: Place the funnel over a clean container.",
        "Step 3: Pour the sand-water mixture through the filter paper.",
        "Step 4: Sand remains on the filter paper as the residue.",
        "Step 5: Water passes through as the filtrate."
      ],
      ans: "Filter the mixture using filter paper; sand remains as residue and water passes through as filtrate.",
      why: "Sand is insoluble and its particles are retained by the filter paper."
    },
    {
      q: "In filtration, what is the difference between residue and filtrate?",
      steps: [
        "Step 1: The residue is the material retained by the filter.",
        "Step 2: The filtrate is the material that passes through the filter.",
        "Step 3: In sand and water, sand is retained while water passes through."
      ],
      ans: "Residue is the solid retained on the filter paper; filtrate is the liquid that passes through.",
      why: "These terms describe the two products obtained during filtration."
    }
  ],

  [
    {
      q: "A mixture contains chalk powder and water. Which method should be used?",
      hint: "Ask whether the solid dissolves in water.",
      steps: [
        "Step 1: Chalk is an insoluble solid.",
        "Step 2: The other component is a liquid.",
        "Step 3: Therefore, filtration is appropriate."
      ],
      ans: "Filtration",
      why: "Filtration separates an insoluble solid from a liquid."
    }
  ]
);


// ============================================================
// 2. EVAPORATION
// ============================================================

add(
  "chemistry",
  "matter_separation",
  "Evaporation",
  `<h2>Evaporation</h2>

  <p><strong>Evaporation</strong> is used to separate a dissolved solid from a solution by removing the solvent as vapour.</p>

  <h3>Principle</h3>
  <p>The solvent is volatile and changes from liquid to gas, leaving the dissolved solid behind.</p>

  <h3>Procedure</h3>
  <ol>
    <li>Place the solution in an evaporating basin.</li>
    <li>Heat the solution gently.</li>
    <li>The solvent changes into vapour.</li>
    <li>The dissolved solid remains behind.</li>
  </ol>

  <h3>Example</h3>
  <p>Common salt can be obtained from salt solution by evaporating the water.</p>

  <h3>Important limitation</h3>
  <p>Evaporation is suitable when the <strong>solid is required</strong>. If the liquid solvent is also required, distillation is more appropriate.</p>`,

  [
    {
      q: "What is evaporation used for in separation of mixtures?",
      steps: [
        "Step 1: Start with a solution containing a dissolved solid.",
        "Step 2: Heat or allow the solvent to evaporate.",
        "Step 3: The solvent becomes vapour.",
        "Step 4: The dissolved solid remains."
      ],
      ans: "Evaporation is used to obtain a dissolved solid from a solution.",
      why: "The solvent is removed as vapour while the non-volatile solute remains."
    },
    {
      q: "Describe how salt can be obtained from salt solution by evaporation.",
      steps: [
        "Step 1: Pour the salt solution into an evaporating basin.",
        "Step 2: Heat the solution gently.",
        "Step 3: Water evaporates.",
        "Step 4: Salt remains in the evaporating basin."
      ],
      ans: "Heat the salt solution in an evaporating basin until the water evaporates, leaving salt behind.",
      why: "Water is removed as vapour while the salt remains."
    },
    {
      q: "Why is evaporation not the best method if both salt and water are required?",
      steps: [
        "Step 1: During evaporation, water changes into vapour.",
        "Step 2: The vapour is normally allowed to escape.",
        "Step 3: Therefore, the water is not recovered.",
        "Step 4: If both products are required, distillation should be used."
      ],
      ans: "Because the water is lost as vapour; distillation should be used to recover it.",
      why: "Distillation condenses the vapour and collects the solvent."
    }
  ],

  [
    {
      q: "Which method can be used to obtain sodium chloride from salt solution when only the salt is required?",
      hint: "The water does not need to be collected.",
      steps: [
        "Step 1: Salt is dissolved in water.",
        "Step 2: The desired product is the solid salt.",
        "Step 3: Remove the water by evaporation."
      ],
      ans: "Evaporation",
      why: "Evaporation removes the solvent and leaves the dissolved salt."
    }
  ]
);


// ============================================================
// 3. CRYSTALLISATION
// ============================================================

add(
  "chemistry",
  "matter_separation",
  "Crystallisation",
  `<h2>Crystallisation</h2>

  <p><strong>Crystallisation</strong> is used to obtain a solid in the form of crystals from a solution.</p>

  <h3>Principle</h3>
  <p>The solubility of many solids changes with temperature. A hot, concentrated solution can be cooled so that crystals form as the solubility decreases.</p>

  <h3>Procedure</h3>
  <ol>
    <li>Prepare a solution containing the dissolved solid.</li>
    <li>Heat the solution to concentrate it.</li>
    <li>Stop heating before all the solvent evaporates.</li>
    <li>Allow the concentrated solution to cool.</li>
    <li>Crystals form as the solubility decreases.</li>
    <li>Filter the crystals.</li>
    <li>Wash and dry the crystals.</li>
  </ol>

  <h3>Why crystallisation instead of complete evaporation?</h3>
  <p>Crystallisation can produce purer, well-formed crystals and avoids unnecessary strong heating of the solid.</p>`,

  [
    {
      q: "What is crystallisation used for?",
      steps: [
        "Step 1: Start with a solution containing a dissolved solid.",
        "Step 2: Concentrate the solution.",
        "Step 3: Allow it to cool.",
        "Step 4: Crystals form from the solution."
      ],
      ans: "Crystallisation is used to obtain a dissolved solid as crystals from a solution.",
      why: "Cooling a concentrated solution can cause the dissolved substance to crystallise."
    },
    {
      q: "Describe the main steps used to obtain crystals from a solution.",
      steps: [
        "Step 1: Heat the solution to concentrate it.",
        "Step 2: Stop heating before the solvent is completely removed.",
        "Step 3: Allow the concentrated solution to cool.",
        "Step 4: Crystals form.",
        "Step 5: Filter the crystals.",
        "Step 6: Wash and dry them."
      ],
      ans: "Concentrate the solution, cool it to form crystals, then filter, wash and dry the crystals.",
      why: "Cooling reduces the amount of solute that can remain dissolved, causing crystals to form."
    },
    {
      q: "Why should a crystallisation solution not normally be evaporated completely?",
      steps: [
        "Step 1: Crystallisation requires some solvent to remain.",
        "Step 2: Cooling the concentrated solution allows crystals to form.",
        "Step 3: Complete evaporation removes the solvent before controlled crystal formation occurs.",
        "Step 4: Therefore, the solution is normally concentrated rather than completely evaporated."
      ],
      ans: "Because crystals are formed by cooling a concentrated solution; complete evaporation can prevent controlled crystal formation.",
      why: "Crystallisation is a controlled method of obtaining solid crystals from a concentrated solution."
    }
  ],

  [
    {
      q: "A student wants to obtain pure crystals of a soluble solid from its solution. Which method is suitable?",
      hint: "The desired product is crystals, not simply a dry solid.",
      steps: [
        "Step 1: The solid is dissolved in a solution.",
        "Step 2: The desired product is crystals.",
        "Step 3: Concentrate the solution and cool it.",
        "Step 4: Therefore, crystallisation is suitable."
      ],
      ans: "Crystallisation",
      why: "Crystallisation is specifically used to obtain a dissolved solid as crystals."
    }
  ]
);


// ============================================================
// 4. SIMPLE DISTILLATION
// ============================================================

add(
  "chemistry",
  "matter_separation",
  "Simple Distillation",
  `<h2>Simple Distillation</h2>

  <p><strong>Simple distillation</strong> separates a liquid from a solution by evaporation followed by condensation.</p>

  <h3>Principle</h3>
  <p>The components have different boiling points. The component with the lower boiling point vaporises more readily.</p>

  <h3>Apparatus</h3>
  <ul>
    <li>Distillation flask</li>
    <li>Thermometer</li>
    <li>Condenser</li>
    <li>Receiving flask</li>
    <li>Heat source</li>
  </ul>

  <h3>Procedure</h3>
  <ol>
    <li>Heat the mixture.</li>
    <li>The more volatile component vaporises.</li>
    <li>The vapour enters the condenser.</li>
    <li>Cold water around the condenser cools the vapour.</li>
    <li>The vapour condenses into liquid.</li>
    <li>The liquid is collected as the distillate.</li>
  </ol>

  <h3>Example</h3>
  <p>Pure water can be obtained from salt solution by simple distillation.</p>`,

  [
    {
      q: "What is the principle of simple distillation?",
      steps: [
        "Step 1: Components of the mixture have different boiling points.",
        "Step 2: Heating causes the more volatile liquid to vaporise.",
        "Step 3: The vapour is cooled.",
        "Step 4: It condenses and is collected."
      ],
      ans: "Simple distillation separates components using differences in boiling point, followed by condensation of the vapour.",
      why: "The component that vaporises is separated and then recovered as a liquid."
    },
    {
      q: "Describe how pure water can be obtained from salt solution by simple distillation.",
      steps: [
        "Step 1: Heat the salt solution.",
        "Step 2: Water vaporises while the salt remains behind.",
        "Step 3: The water vapour enters the condenser.",
        "Step 4: Cold water around the condenser cools the vapour.",
        "Step 5: The water vapour condenses.",
        "Step 6: Collect the liquid water as the distillate."
      ],
      ans: "Heat the salt solution, condense the water vapour and collect the condensed water.",
      why: "Water is volatile and can be vaporised and then condensed, while salt remains in the flask."
    },
    {
      q: "What is the function of the condenser during distillation?",
      steps: [
        "Step 1: The liquid is heated and forms vapour.",
        "Step 2: The vapour enters the condenser.",
        "Step 3: Cooling water removes heat from the vapour.",
        "Step 4: The vapour changes back into liquid."
      ],
      ans: "The condenser cools vapour so that it condenses into a liquid.",
      why: "Condensation converts the separated vapour back into a liquid that can be collected."
    }
  ],

  [
    {
      q: "Which method should be used to obtain water from salt solution if the water must be collected?",
      hint: "The solvent is the desired product.",
      steps: [
        "Step 1: Water is the desired product.",
        "Step 2: Evaporation would lose the water as vapour.",
        "Step 3: Distillation vaporises and then condenses the water.",
        "Step 4: Therefore, simple distillation is suitable."
      ],
      ans: "Simple distillation",
      why: "The water vapour is condensed and collected."
    }
  ]
);


// ============================================================
// 5. FRACTIONAL DISTILLATION
// ============================================================

add(
  "chemistry",
  "matter_separation",
  "Fractional Distillation",
  `<h2>Fractional Distillation</h2>

  <p><strong>Fractional distillation</strong> is used to separate two or more <strong>miscible liquids</strong> with different boiling points, especially when their boiling points are relatively close.</p>

  <h3>Principle</h3>
  <p>The liquids have different boiling points. The liquid with the lower boiling point vaporises more readily.</p>

  <h3>Fractionating column</h3>
  <p>A fractionating column provides repeated vaporisation and condensation. This improves separation of liquids with relatively close boiling points.</p>

  <h3>Procedure</h3>
  <ol>
    <li>Heat the mixture of miscible liquids.</li>
    <li>Vapours rise through the fractionating column.</li>
    <li>Repeated condensation and vaporisation occur in the column.</li>
    <li>The component with the lower boiling point reaches the condenser more readily.</li>
    <li>It condenses and is collected.</li>
    <li>The temperature is monitored as different fractions are collected.</li>
  </ol>

  <h3>Example</h3>
  <p>Crude oil is separated into useful fractions using fractional distillation because it contains several hydrocarbons with different boiling ranges.</p>`,

  [
    {
      q: "What type of mixture is separated by fractional distillation?",
      steps: [
        "Step 1: The mixture contains liquids.",
        "Step 2: The liquids must be miscible.",
        "Step 3: They have different boiling points.",
        "Step 4: Therefore, fractional distillation can separate them."
      ],
      ans: "A mixture of miscible liquids with different boiling points.",
      why: "Fractional distillation separates liquids according to differences in boiling points."
    },
    {
      q: "Why is a fractionating column used?",
      steps: [
        "Step 1: Liquids with close boiling points are difficult to separate in one vaporisation step.",
        "Step 2: The column allows repeated vaporisation and condensation.",
        "Step 3: This enriches the vapour in the more volatile component.",
        "Step 4: Therefore, separation becomes more effective."
      ],
      ans: "It allows repeated vaporisation and condensation, improving separation of liquids with close boiling points.",
      why: "Repeated equilibrium between liquid and vapour phases gives better separation."
    },
    {
      q: "State one important difference between simple and fractional distillation.",
      steps: [
        "Step 1: Simple distillation is commonly used to recover a solvent from a solution or separate liquids with sufficiently different boiling points.",
        "Step 2: Fractional distillation uses a fractionating column.",
        "Step 3: It is especially useful for separating miscible liquids with relatively close boiling points."
      ],
      ans: "Fractional distillation uses a fractionating column and is used when miscible liquids have relatively close boiling points.",
      why: "The column improves separation by repeated vaporisation and condensation."
    }
  ],

  [
    {
      q: "Which method is used to separate different hydrocarbon fractions in crude oil?",
      hint: "Crude oil contains many miscible hydrocarbons with different boiling ranges.",
      steps: [
        "Step 1: Crude oil contains several hydrocarbons.",
        "Step 2: These hydrocarbons have different boiling ranges.",
        "Step 3: Fractional distillation separates them into fractions."
      ],
      ans: "Fractional distillation",
      why: "The different hydrocarbons have different boiling ranges."
    }
  ]
);


// ============================================================
// 6. CHROMATOGRAPHY
// ============================================================

add(
  "chemistry",
  "matter_separation",
  "Chromatography",
  `<h2>Chromatography</h2>

  <p><strong>Chromatography</strong> is used to separate and identify components of a mixture, especially coloured substances such as dyes and pigments.</p>

  <h3>Principle</h3>
  <p>Different substances have different attractions to the <strong>stationary phase</strong> and the <strong>mobile phase</strong>. They therefore travel at different rates.</p>

  <h3>Paper chromatography</h3>
  <ol>
    <li>Draw a pencil baseline near the bottom of chromatography paper.</li>
    <li>Place a small spot of the mixture on the baseline.</li>
    <li>Place the paper in a suitable solvent.</li>
    <li>Keep the solvent level below the sample spot.</li>
    <li>Allow the solvent to move up the paper.</li>
    <li>Different components travel different distances.</li>
    <li>Remove the paper and mark the solvent front.</li>
  </ol>

  <h3>Important rule</h3>
  <p>The starting line is drawn using <strong>pencil</strong>, not ink, because pencil does not dissolve and interfere with the chromatogram.</p>

  <h3>Interpreting results</h3>
  <p>One spot suggests one component under those conditions. Several spots indicate several components.</p>`,

  [
    {
      q: "What is chromatography used for?",
      steps: [
        "Step 1: A mixture is placed on a stationary material.",
        "Step 2: A mobile solvent moves through the material.",
        "Step 3: Different components move at different rates.",
        "Step 4: The components become separated."
      ],
      ans: "Chromatography is used to separate and identify components of a mixture.",
      why: "Different components have different attractions to the stationary and mobile phases."
    },
    {
      q: "Why is pencil used to draw the baseline in paper chromatography?",
      steps: [
        "Step 1: The baseline must remain in position during the experiment.",
        "Step 2: Ink contains dyes.",
        "Step 3: The solvent could dissolve the ink and produce extra spots.",
        "Step 4: Pencil graphite does not dissolve in the solvent under normal conditions.",
        "Step 5: Therefore, pencil is used."
      ],
      ans: "Pencil is used because graphite does not dissolve and interfere with the chromatogram.",
      why: "Ink can dissolve and produce additional spots, making the results unreliable."
    },
    {
      q: "A chromatogram shows four separate spots from one ink sample. What does this indicate?",
      steps: [
        "Step 1: Each separated spot represents a component under the conditions used.",
        "Step 2: Four distinct spots are present.",
        "Step 3: Therefore, the ink contains at least four separable components."
      ],
      ans: "The ink contains at least four separable components.",
      why: "Different components travel different distances and appear as separate spots."
    }
  ],

  [
    {
      q: "A black ink separates into three spots during paper chromatography. What can you conclude?",
      hint: "Each spot represents a separated component.",
      steps: [
        "Step 1: Observe the number of spots.",
        "Step 2: There are three distinct spots.",
        "Step 3: Therefore, the ink contains at least three components that separated under those conditions."
      ],
      ans: "The ink contains at least three separable components.",
      why: "Chromatography separates different components into different positions."
    }
  ]
);


// ============================================================
// 7. DECANTATION
// ============================================================

add(
  "chemistry",
  "matter_separation",
  "Decantation",
  `<h2>Decantation</h2>

  <p><strong>Decantation</strong> separates a liquid from a settled solid or separates immiscible liquids by carefully pouring off one component.</p>

  <h3>Separating a solid from a liquid</h3>
  <ol>
    <li>Allow the insoluble solid to settle at the bottom.</li>
    <li>The solid forms a sediment.</li>
    <li>Carefully pour the liquid into another container.</li>
    <li>Leave the sediment behind.</li>
  </ol>

  <h3>Example</h3>
  <p>Sand and water can be separated by allowing the sand to settle and carefully pouring off the water.</p>

  <h3>Limitation</h3>
  <p>Decantation is generally less effective than filtration when very fine solid particles remain suspended.</p>

  <p><strong>Key idea: settle → carefully pour off.</strong></p>`,

  [
    {
      q: "What is decantation?",
      steps: [
        "Step 1: Allow a denser insoluble solid to settle.",
        "Step 2: The solid forms sediment at the bottom.",
        "Step 3: Carefully pour the liquid into another container."
      ],
      ans: "Decantation is the separation of a liquid from a settled solid by carefully pouring off the liquid.",
      why: "The method relies on the components separating into different layers or the solid settling due to density differences."
    },
    {
      q: "Describe how sand and water can be separated by decantation.",
      steps: [
        "Step 1: Leave the mixture undisturbed.",
        "Step 2: Sand settles at the bottom.",
        "Step 3: Carefully pour the water into another container.",
        "Step 4: Leave the settled sand behind."
      ],
      ans: "Allow the sand to settle, then carefully pour off the water.",
      why: "The sand settles because it is denser than water."
    },
    {
      q: "Why is filtration usually better than decantation for very fine suspended particles?",
      steps: [
        "Step 1: Very fine particles may remain suspended in the liquid.",
        "Step 2: If they do not settle completely, they can be poured out during decantation.",
        "Step 3: Filter paper can retain these insoluble particles.",
        "Step 4: Therefore, filtration gives a more effective separation."
      ],
      ans: "Filtration is better because the filter paper can retain fine insoluble particles that may remain suspended.",
      why: "Decantation depends on settling, while filtration physically traps insoluble particles."
    }
  ],

  [
    {
      q: "A mixture contains muddy water and the mud has settled at the bottom. Which simple method can be used to remove most of the water?",
      hint: "The solid has already settled.",
      steps: [
        "Step 1: The mud has settled at the bottom.",
        "Step 2: The water is above the sediment.",
        "Step 3: Carefully pour off the water."
      ],
      ans: "Decantation",
      why: "Decantation separates a liquid from a settled solid by carefully pouring off the liquid."
    }
  ]
);


// ============================================================
// 8. MAGNETIC SEPARATION
// ============================================================

add(
  "chemistry",
  "matter_separation",
  "Magnetic Separation",
  `<h2>Magnetic Separation</h2>

  <p><strong>Magnetic separation</strong> is used when one component of a mixture is attracted to a magnet while the other component is not.</p>

  <h3>Principle</h3>
  <p>The method depends on a difference in <strong>magnetic properties</strong>.</p>

  <h3>Procedure</h3>
  <ol>
    <li>Bring a magnet close to the mixture.</li>
    <li>The magnetic component is attracted to the magnet.</li>
    <li>The non-magnetic component remains behind.</li>
    <li>Remove the magnetic material from the magnet.</li>
  </ol>

  <h3>Example</h3>
  <p>Iron filings can be separated from sulfur powder using a magnet.</p>

  <h3>Important point</h3>
  <p>The method only works when the components have sufficiently different magnetic properties.</p>`,

  [
    {
      q: "What property is used in magnetic separation?",
      steps: [
        "Step 1: Identify the physical property being exploited.",
        "Step 2: One component must be attracted to a magnet.",
        "Step 3: The other component should not be attracted.",
        "Step 4: Therefore, magnetic properties allow separation."
      ],
      ans: "Difference in magnetic properties.",
      why: "A magnet attracts the magnetic component while leaving the non-magnetic component behind."
    },
    {
      q: "How can iron filings be separated from sulfur powder?",
      steps: [
        "Step 1: Place the mixture on a suitable surface.",
        "Step 2: Bring a magnet close to the mixture.",
        "Step 3: Iron filings are attracted to the magnet.",
        "Step 4: Sulfur remains behind.",
        "Step 5: Remove the iron filings from the magnet."
      ],
      ans: "Use a magnet to attract and remove the iron filings.",
      why: "Iron is attracted to a magnet whereas sulfur is not."
    },
    {
      q: "Why can a magnet separate iron from sulfur without causing a chemical reaction?",
      steps: [
        "Step 1: The iron and sulfur are physically mixed.",
        "Step 2: A magnet acts on the magnetic property of iron.",
        "Step 3: No new substance is produced.",
        "Step 4: Therefore, the separation is a physical process."
      ],
      ans: "Because the magnet separates the components using their physical magnetic properties without forming a new substance.",
      why: "Magnetic separation changes only the arrangement of the components, not their chemical identities."
    }
  ],

  [
    {
      q: "Which method should be used to separate iron filings from copper powder?",
      hint: "One of the metals is strongly attracted to a magnet.",
      steps: [
        "Step 1: Iron is attracted to a magnet.",
        "Step 2: Copper is not attracted in the same way.",
        "Step 3: Use a magnet to remove the iron."
      ],
      ans: "Magnetic separation",
      why: "The method exploits the difference in magnetic properties."
    }
  ]
);
// ============================================================
// BATCH 6 — ATOMIC STRUCTURE
// Chapter: atomic_structure
// ============================================================


// ============================================================
// 1. STRUCTURE OF THE ATOM
// ============================================================

add(
  "chemistry",
  "atomic_structure",
  "Structure of the Atom",
  `<h2>Structure of the Atom</h2>

  <p>An <strong>atom</strong> is the smallest particle of an element that retains the chemical identity of that element.</p>

  <p>An atom has two main regions:</p>

  <ul>
    <li><strong>Nucleus</strong> — the small, dense central region.</li>
    <li><strong>Electron region</strong> — the region around the nucleus where electrons are found.</li>
  </ul>

  <h3>The three main subatomic particles</h3>

  <ul>
    <li><strong>Proton</strong> — positive charge.</li>
    <li><strong>Neutron</strong> — no charge.</li>
    <li><strong>Electron</strong> — negative charge.</li>
  </ul>

  <p>Protons and neutrons are found in the nucleus. Electrons occupy energy levels around the nucleus.</p>

  <h3>Electrical neutrality</h3>

  <p>A normal atom has equal numbers of protons and electrons, so the positive and negative charges cancel.</p>

  <p><strong>Atom = nucleus + electrons around the nucleus.</strong></p>`,

  [
    {
      q: "Name the three main subatomic particles and state their charges.",
      steps: [
        "Step 1: The positively charged particle is the proton.",
        "Step 2: The particle with no charge is the neutron.",
        "Step 3: The negatively charged particle is the electron."
      ],
      ans: "Proton = +1; neutron = 0; electron = −1.",
      why: "These are the three main subatomic particles and their relative electrical charges."
    },
    {
      q: "Where are protons, neutrons and electrons found in an atom?",
      steps: [
        "Step 1: Protons are located in the nucleus.",
        "Step 2: Neutrons are located in the nucleus.",
        "Step 3: Electrons occupy energy levels around the nucleus."
      ],
      ans: "Protons and neutrons are in the nucleus; electrons occupy energy levels around the nucleus.",
      why: "The nucleus contains almost all of the atom's mass, while electrons occupy the surrounding region."
    },
    {
      q: "Why is a normal atom electrically neutral?",
      steps: [
        "Step 1: Each proton contributes +1 charge.",
        "Step 2: Each electron contributes −1 charge.",
        "Step 3: A normal atom has equal numbers of protons and electrons.",
        "Step 4: The positive and negative charges cancel."
      ],
      ans: "A normal atom is neutral because it has equal numbers of positively charged protons and negatively charged electrons.",
      why: "Equal positive and negative charges give a net charge of zero."
    }
  ],

  [
    {
      q: "An atom contains 11 protons and 11 electrons. What is its overall charge?",
      hint: "Add the positive and negative charges.",
      steps: [
        "Step 1: 11 protons give +11.",
        "Step 2: 11 electrons give −11.",
        "Step 3: +11 + (−11) = 0."
      ],
      ans: "0; the atom is electrically neutral.",
      why: "The positive and negative charges are equal and cancel."
    }
  ]
);


// ============================================================
// 2. PROTONS
// ============================================================

add(
  "chemistry",
  "atomic_structure",
  "Protons",
  `<h2>Protons</h2>

  <p>A <strong>proton</strong> is a positively charged subatomic particle found in the nucleus of an atom.</p>

  <ul>
    <li>Relative charge = <strong>+1</strong></li>
    <li>Relative mass ≈ <strong>1</strong></li>
    <li>Location = <strong>nucleus</strong></li>
  </ul>

  <p>The number of protons determines the identity of an element.</p>

  <p>For example:</p>

  <ul>
    <li>Hydrogen has 1 proton.</li>
    <li>Carbon has 6 protons.</li>
    <li>Oxygen has 8 protons.</li>
    <li>Sodium has 11 protons.</li>
  </ul>

  <p><strong>Change the number of protons → change the element.</strong></p>`,

  [
    {
      q: "What is the relative charge of a proton?",
      steps: [
        "Step 1: A proton is the positively charged subatomic particle.",
        "Step 2: Its relative charge is assigned as +1."
      ],
      ans: "+1",
      why: "The proton carries one unit of positive relative charge."
    },
    {
      q: "Where is a proton found in an atom?",
      steps: [
        "Step 1: Protons are subatomic particles.",
        "Step 2: They are located in the central nucleus."
      ],
      ans: "In the nucleus.",
      why: "The nucleus contains protons and neutrons."
    },
    {
      q: "An atom has 17 protons. Which element is it?",
      steps: [
        "Step 1: The number of protons is the atomic number.",
        "Step 2: Atomic number 17 corresponds to chlorine.",
        "Step 3: Therefore, the atom is chlorine."
      ],
      ans: "Chlorine.",
      why: "Every chlorine atom has 17 protons."
    }
  ],

  [
    {
      q: "An atom contains 12 protons. Identify the element.",
      hint: "The proton number is the atomic number.",
      steps: [
        "Step 1: Atomic number = number of protons = 12.",
        "Step 2: Atomic number 12 is magnesium."
      ],
      ans: "Magnesium.",
      why: "Magnesium has atomic number 12."
    }
  ]
);


// ============================================================
// 3. NEUTRONS
// ============================================================

add(
  "chemistry",
  "atomic_structure",
  "Neutrons",
  `<h2>Neutrons</h2>

  <p>A <strong>neutron</strong> is a subatomic particle found in the nucleus of an atom.</p>

  <ul>
    <li>Relative charge = <strong>0</strong></li>
    <li>Relative mass ≈ <strong>1</strong></li>
    <li>Location = <strong>nucleus</strong></li>
  </ul>

  <p>Neutrons contribute to the mass of an atom but do not affect its electrical charge.</p>

  <h3>Finding the number of neutrons</h3>

  <p>The mass number is the total number of protons and neutrons.</p>

  <p><strong>Mass number = protons + neutrons</strong></p>

  <p>Therefore:</p>

  <p><strong>Neutrons = mass number − atomic number</strong></p>`,

  [
    {
      q: "What is the relative charge of a neutron?",
      steps: [
        "Step 1: A neutron is electrically neutral.",
        "Step 2: Therefore, its relative charge is zero."
      ],
      ans: "0",
      why: "A neutron has no electrical charge."
    },
    {
      q: "An atom has a mass number of 23 and an atomic number of 11. Calculate the number of neutrons.",
      steps: [
        "Step 1: Use neutrons = mass number − atomic number.",
        "Step 2: Neutrons = 23 − 11.",
        "Step 3: Neutrons = 12."
      ],
      ans: "12 neutrons.",
      why: "The mass number contains protons and neutrons, while the atomic number gives the number of protons."
    },
    {
      q: "An atom has 19 protons and 20 neutrons. Calculate its mass number.",
      steps: [
        "Step 1: Mass number = protons + neutrons.",
        "Step 2: Mass number = 19 + 20.",
        "Step 3: Mass number = 39."
      ],
      ans: "39.",
      why: "Mass number is the total number of protons and neutrons."
    }
  ],

  [
    {
      q: "An atom has mass number 40 and atomic number 20. How many neutrons does it contain?",
      hint: "Neutrons = mass number − atomic number.",
      steps: [
        "Step 1: 40 − 20 = 20."
      ],
      ans: "20 neutrons.",
      why: "The atom contains 20 protons and 20 neutrons."
    }
  ]
);


// ============================================================
// 4. ELECTRONS
// ============================================================

add(
  "chemistry",
  "atomic_structure",
  "Electrons",
  `<h2>Electrons</h2>

  <p>An <strong>electron</strong> is a negatively charged subatomic particle found in energy levels around the nucleus.</p>

  <ul>
    <li>Relative charge = <strong>−1</strong></li>
    <li>Relative mass ≈ <strong>1/1840</strong></li>
    <li>Location = <strong>energy levels around the nucleus</strong></li>
  </ul>

  <p>In a neutral atom:</p>

  <p><strong>Number of electrons = number of protons</strong></p>

  <p>When an atom gains or loses electrons, it becomes an ion.</p>`,

  [
    {
      q: "What is the relative charge of an electron?",
      steps: [
        "Step 1: An electron carries negative charge.",
        "Step 2: Its relative charge is −1."
      ],
      ans: "−1",
      why: "The electron is the negatively charged subatomic particle."
    },
    {
      q: "A neutral atom has 8 protons. How many electrons does it have?",
      steps: [
        "Step 1: A neutral atom has equal numbers of protons and electrons.",
        "Step 2: The atom has 8 protons.",
        "Step 3: Therefore, it has 8 electrons."
      ],
      ans: "8 electrons.",
      why: "Equal numbers of protons and electrons make the atom neutral."
    },
    {
      q: "An atom loses two electrons. What happens to its charge?",
      steps: [
        "Step 1: Electrons have negative charge.",
        "Step 2: Losing negative charge leaves more positive charge.",
        "Step 3: The atom becomes a positively charged ion.",
        "Step 4: Losing two electrons gives a charge of +2."
      ],
      ans: "It becomes a +2 ion.",
      why: "Removing two negatively charged electrons produces a net positive charge of +2."
    }
  ],

  [
    {
      q: "A neutral atom has 15 protons. How many electrons are present?",
      hint: "A neutral atom has equal numbers of protons and electrons.",
      steps: [
        "Step 1: Number of electrons = number of protons.",
        "Step 2: Therefore, electrons = 15."
      ],
      ans: "15 electrons.",
      why: "The positive charge from 15 protons is balanced by 15 electrons."
    }
  ]
);


// ============================================================
// 5. ATOMIC NUMBER
// ============================================================

add(
  "chemistry",
  "atomic_structure",
  "Atomic Number",
  `<h2>Atomic Number</h2>

  <p>The <strong>atomic number</strong> of an element is the number of protons in the nucleus of its atoms.</p>

  <p>It is represented by <strong>Z</strong>.</p>

  <p><strong>Atomic number = number of protons</strong></p>

  <p>For a neutral atom:</p>

  <p><strong>Atomic number = number of protons = number of electrons</strong></p>

  <h3>Examples</h3>

  <ul>
    <li>Hydrogen: Z = 1</li>
    <li>Carbon: Z = 6</li>
    <li>Oxygen: Z = 8</li>
    <li>Sodium: Z = 11</li>
    <li>Chlorine: Z = 17</li>
  </ul>

  <p>The atomic number identifies the element.</p>`,

  [
    {
      q: "What is atomic number?",
      steps: [
        "Step 1: Atomic number identifies an element.",
        "Step 2: It is defined as the number of protons in the nucleus."
      ],
      ans: "Atomic number is the number of protons in the nucleus of an atom.",
      why: "Each element has a unique number of protons."
    },
    {
      q: "An element has atomic number 8. How many protons does it have?",
      steps: [
        "Step 1: Atomic number = number of protons.",
        "Step 2: Atomic number = 8.",
        "Step 3: Therefore, protons = 8."
      ],
      ans: "8 protons.",
      why: "Atomic number directly gives the number of protons."
    },
    {
      q: "A neutral atom has atomic number 12. How many electrons does it have?",
      steps: [
        "Step 1: Atomic number = number of protons = 12.",
        "Step 2: A neutral atom has equal protons and electrons.",
        "Step 3: Therefore, electrons = 12."
      ],
      ans: "12 electrons.",
      why: "Neutrality requires equal numbers of protons and electrons."
    }
  ],

  [
    {
      q: "An atom has 13 protons. What is its atomic number?",
      hint: "Atomic number equals the number of protons.",
      steps: [
        "Step 1: Count the protons.",
        "Step 2: There are 13 protons.",
        "Step 3: Atomic number = 13."
      ],
      ans: "13",
      why: "The atomic number is defined by the number of protons."
    }
  ]
);


// ============================================================
// 6. MASS NUMBER
// ============================================================

add(
  "chemistry",
  "atomic_structure",
  "Mass Number",
  `<h2>Mass Number</h2>

  <p>The <strong>mass number</strong> is the total number of protons and neutrons in the nucleus of an atom.</p>

  <p>It is represented by <strong>A</strong>.</p>

  <p><strong>Mass number = protons + neutrons</strong></p>

  <p>Therefore:</p>

  <p><strong>Neutrons = mass number − protons</strong></p>

  <h3>Example</h3>

  <p>An atom has 11 protons and 12 neutrons:</p>

  <p>Mass number = 11 + 12 = <strong>23</strong></p>

  <p>Electrons are not included in the mass number because their mass is extremely small compared with that of protons and neutrons.</p>`,

  [
    {
      q: "What is mass number?",
      steps: [
        "Step 1: Identify the particles that contribute almost all of the atom's mass.",
        "Step 2: These are protons and neutrons.",
        "Step 3: Add their numbers."
      ],
      ans: "Mass number is the total number of protons and neutrons in the nucleus.",
      why: "Protons and neutrons make up almost all of the atom's mass."
    },
    {
      q: "An atom has 8 protons and 8 neutrons. Calculate its mass number.",
      steps: [
        "Step 1: Mass number = protons + neutrons.",
        "Step 2: Mass number = 8 + 8.",
        "Step 3: Mass number = 16."
      ],
      ans: "16.",
      why: "The mass number is the total number of protons and neutrons."
    },
    {
      q: "An atom has mass number 27 and 13 protons. Calculate the number of neutrons.",
      steps: [
        "Step 1: Neutrons = mass number − protons.",
        "Step 2: Neutrons = 27 − 13.",
        "Step 3: Neutrons = 14."
      ],
      ans: "14 neutrons.",
      why: "Mass number equals protons plus neutrons."
    }
  ],

  [
    {
      q: "An atom has 17 protons and 18 neutrons. What is its mass number?",
      hint: "Add protons and neutrons.",
      steps: [
        "Step 1: Mass number = 17 + 18.",
        "Step 2: Mass number = 35."
      ],
      ans: "35",
      why: "Mass number is the total number of protons and neutrons."
    }
  ]
);


// ============================================================
// 7. ELECTRON ARRANGEMENT
// ============================================================

add(
  "chemistry",
  "atomic_structure",
  "Electron Arrangement",
  `<h2>Electron Arrangement</h2>

  <p>Electrons occupy <strong>energy levels</strong> around the nucleus.</p>

  <p>For the first 20 elements, the electron arrangement can be written using the shell pattern:</p>

  <ul>
    <li>First energy level: maximum 2 electrons</li>
    <li>Second energy level: maximum 8 electrons</li>
    <li>Third energy level: up to 8 electrons for the first 20 elements</li>
    <li>Fourth energy level: begins to fill for elements such as potassium and calcium</li>
  </ul>

  <h3>Examples</h3>

  <ul>
    <li>H = 1</li>
    <li>He = 2</li>
    <li>Li = 2,1</li>
    <li>C = 2,4</li>
    <li>O = 2,6</li>
    <li>Na = 2,8,1</li>
    <li>Cl = 2,8,7</li>
    <li>Ca = 2,8,8,2</li>
  </ul>

  <p>For a neutral atom, the total number of electrons in all energy levels equals the atomic number.</p>`,

  [
    {
      q: "Write the electron arrangement of sodium, atomic number 11.",
      steps: [
        "Step 1: Sodium has 11 electrons because it is neutral.",
        "Step 2: Put 2 electrons in the first energy level.",
        "Step 3: Put 8 electrons in the second energy level.",
        "Step 4: The remaining electron goes into the third energy level.",
        "Step 5: Arrangement = 2,8,1."
      ],
      ans: "2,8,1",
      why: "The 11 electrons are distributed as 2 in the first level, 8 in the second and 1 in the third."
    },
    {
      q: "Write the electron arrangement of chlorine, atomic number 17.",
      steps: [
        "Step 1: Chlorine has 17 electrons.",
        "Step 2: Put 2 in the first level.",
        "Step 3: Put 8 in the second level.",
        "Step 4: The remaining 7 go into the third level.",
        "Step 5: Arrangement = 2,8,7."
      ],
      ans: "2,8,7",
      why: "The 17 electrons fill the first three energy levels as 2, 8 and 7."
    },
    {
      q: "An atom has electron arrangement 2,8,8,2. How many electrons does it have?",
      steps: [
        "Step 1: Add the electrons in all energy levels.",
        "Step 2: 2 + 8 + 8 + 2 = 20.",
        "Step 3: Therefore, the atom has 20 electrons."
      ],
      ans: "20 electrons.",
      why: "The total electron arrangement gives the total number of electrons."
    }
  ],

  [
    {
      q: "Write the electron arrangement of magnesium, atomic number 12.",
      hint: "Distribute 12 electrons as 2, then 8, then the remainder.",
      steps: [
        "Step 1: First level = 2.",
        "Step 2: Second level = 8.",
        "Step 3: Remaining electrons = 12 − 10 = 2.",
        "Step 4: Arrangement = 2,8,2."
      ],
      ans: "2,8,2",
      why: "Magnesium has 12 electrons arranged as 2,8,2."
    }
  ]
);


// ============================================================
// 8. ISOTOPES
// ============================================================

add(
  "chemistry",
  "atomic_structure",
  "Isotopes",
  `<h2>Isotopes</h2>

  <p><strong>Isotopes</strong> are atoms of the same element that have the same number of protons but different numbers of neutrons.</p>

  <h3>What remains the same?</h3>

  <p>Isotopes of an element have the same:</p>
  <ul>
    <li>Number of protons</li>
    <li>Atomic number</li>
    <li>Element identity</li>
  </ul>

  <h3>What changes?</h3>

  <p>They have different:</p>
  <ul>
    <li>Numbers of neutrons</li>
    <li>Mass numbers</li>
  </ul>

  <h3>Example: carbon</h3>

  <p>Carbon-12:</p>
  <p>6 protons + 6 neutrons = 12</p>

  <p>Carbon-14:</p>
  <p>6 protons + 8 neutrons = 14</p>

  <p>Both are carbon because both contain 6 protons.</p>`,

  [
    {
      q: "What are isotopes?",
      steps: [
        "Step 1: Isotopes belong to the same element.",
        "Step 2: Therefore, they must have the same number of protons.",
        "Step 3: They differ in their number of neutrons.",
        "Step 4: This gives them different mass numbers."
      ],
      ans: "Isotopes are atoms of the same element with the same number of protons but different numbers of neutrons.",
      why: "The proton number determines the element, while changing the neutron number changes the mass number."
    },
    {
      q: "How many neutrons are present in carbon-14 if carbon has atomic number 6?",
      steps: [
        "Step 1: Mass number = 14.",
        "Step 2: Atomic number = protons = 6.",
        "Step 3: Neutrons = 14 − 6.",
        "Step 4: Neutrons = 8."
      ],
      ans: "8 neutrons.",
      why: "Mass number is the sum of protons and neutrons."
    },
    {
      q: "Why are carbon-12 and carbon-14 both carbon?",
      steps: [
        "Step 1: Carbon has atomic number 6.",
        "Step 2: Both carbon-12 and carbon-14 contain 6 protons.",
        "Step 3: Therefore, both have the identity of carbon.",
        "Step 4: They differ only in their numbers of neutrons."
      ],
      ans: "They are both carbon because they each contain 6 protons.",
      why: "The number of protons determines the identity of an element."
    }
  ],

  [
    {
      q: "Two atoms each contain 17 protons, but one has 18 neutrons and the other has 20 neutrons. What are they?",
      hint: "Same protons but different neutrons.",
      steps: [
        "Step 1: Both atoms have 17 protons.",
        "Step 2: Therefore, both are chlorine atoms.",
        "Step 3: Their neutron numbers are different.",
        "Step 4: Therefore, they are isotopes of chlorine."
      ],
      ans: "Isotopes of chlorine.",
      why: "They have the same proton number but different neutron numbers."
    }
  ]
);


// ============================================================
// 9. IDENTIFYING ISOTOPES
// ============================================================

add(
  "chemistry",
  "atomic_structure",
  "Identifying Isotopes",
  `<h2>Identifying Isotopes</h2>

  <p>To determine whether two atoms are isotopes, compare their <strong>proton numbers</strong> and <strong>neutron numbers</strong>.</p>

  <h3>Rule</h3>

  <p><strong>Same protons + different neutrons = isotopes.</strong></p>

  <p>If the proton numbers are different, the atoms are different elements and therefore cannot be isotopes of one another.</p>

  <h3>Example 1</h3>

  <p>Atom A: 6 protons, 6 neutrons</p>
  <p>Atom B: 6 protons, 8 neutrons</p>

  <p>Same protons + different neutrons → isotopes.</p>

  <h3>Example 2</h3>

  <p>Atom A: 6 protons</p>
  <p>Atom B: 7 protons</p>

  <p>Different proton numbers → different elements → not isotopes.</p>`,

  [
    {
      q: "Atom X has 8 protons and 8 neutrons. Atom Y has 8 protons and 10 neutrons. Are they isotopes?",
      steps: [
        "Step 1: Compare proton numbers: 8 and 8.",
        "Step 2: The proton numbers are the same.",
        "Step 3: Compare neutron numbers: 8 and 10.",
        "Step 4: The neutron numbers are different.",
        "Step 5: Therefore, they are isotopes."
      ],
      ans: "Yes, they are isotopes.",
      why: "They have the same number of protons but different numbers of neutrons."
    },
    {
      q: "Atom A has 11 protons and 12 neutrons. Atom B has 12 protons and 12 neutrons. Are they isotopes?",
      steps: [
        "Step 1: Compare proton numbers.",
        "Step 2: Atom A has 11 protons while Atom B has 12.",
        "Step 3: Their proton numbers are different.",
        "Step 4: Therefore, they are different elements and are not isotopes."
      ],
      ans: "No, they are not isotopes.",
      why: "Isotopes must have the same proton number."
    },
    {
      q: "Determine whether chlorine-35 and chlorine-37 are isotopes. Chlorine has atomic number 17.",
      steps: [
        "Step 1: Both have atomic number 17.",
        "Step 2: Therefore, both have 17 protons.",
        "Step 3: Chlorine-35 has 35 − 17 = 18 neutrons.",
        "Step 4: Chlorine-37 has 37 − 17 = 20 neutrons.",
        "Step 5: Same protons but different neutrons means isotopes."
      ],
      ans: "Yes. Chlorine-35 and chlorine-37 are isotopes.",
      why: "They have the same proton number but different neutron numbers."
    }
  ],

  [
    {
      q: "Are atoms with proton numbers 12 and 12 but neutron numbers 12 and 13 isotopes?",
      hint: "Compare the proton numbers first.",
      steps: [
        "Step 1: Both have 12 protons.",
        "Step 2: Their neutron numbers are different.",
        "Step 3: Therefore, they are isotopes."
      ],
      ans: "Yes.",
      why: "Same proton number and different neutron number is the definition of isotopes."
    }
  ]
);


// ============================================================
// 10. USES OF ISOTOPES
// ============================================================

add(
  "chemistry",
  "atomic_structure",
  "Uses of Isotopes",
  `<h2>Uses of Isotopes</h2>

  <p>Some isotopes are useful because their nuclei are unstable and emit radiation. These are called <strong>radioisotopes</strong>.</p>

  <h3>Medical uses</h3>

  <p>Radioisotopes can be used in medicine for diagnosis and treatment.</p>

  <ul>
    <li>Some are used as tracers to follow processes inside the body.</li>
    <li>Some are used to destroy abnormal cells during treatment.</li>
  </ul>

  <h3>Industrial uses</h3>

  <ul>
    <li>Checking the thickness of materials.</li>
    <li>Tracing leaks or movement of substances.</li>
  </ul>

  <h3>Scientific and environmental uses</h3>

  <ul>
    <li>Studying biological and chemical processes.</li>
    <li>Determining the age of some materials using radioactive dating techniques.</li>
  </ul>

  <p>Radioisotopes must be handled carefully because ionising radiation can damage living tissue.</p>`,

  [
    {
      q: "What is a radioisotope?",
      steps: [
        "Step 1: Isotopes are atoms of the same element with different neutron numbers.",
        "Step 2: Some isotopes have unstable nuclei.",
        "Step 3: Unstable nuclei emit radiation.",
        "Step 4: Such isotopes are called radioisotopes."
      ],
      ans: "A radioisotope is an isotope with an unstable nucleus that emits radiation.",
      why: "Radioisotopes undergo radioactive decay because their nuclei are unstable."
    },
    {
      q: "Give one medical use of radioisotopes.",
      steps: [
        "Step 1: Radioisotopes can emit detectable radiation.",
        "Step 2: This radiation can be monitored when a radioisotope is used as a tracer.",
        "Step 3: Therefore, radioisotopes can help doctors study processes inside the body."
      ],
      ans: "They can be used as radioactive tracers for medical diagnosis.",
      why: "Radiation from a tracer can be detected and used to follow biological processes."
    },
    {
      q: "Why must radioisotopes be handled carefully?",
      steps: [
        "Step 1: Radioisotopes can emit ionising radiation.",
        "Step 2: Ionising radiation can damage living cells.",
        "Step 3: Therefore, exposure must be controlled."
      ],
      ans: "They must be handled carefully because their radiation can damage living tissue.",
      why: "Ionising radiation can cause biological damage."
    }
  ],

  [
    {
      q: "State one use of radioactive isotopes in industry.",
      hint: "Think about checking materials or tracing substances.",
      steps: [
        "Step 1: Radiation can be detected through or from materials.",
        "Step 2: This allows radioactive sources to be used for industrial measurements.",
        "Step 3: One example is checking material thickness."
      ],
      ans: "They can be used to measure or monitor the thickness of materials.",
      why: "Radiation intensity can be used to monitor material thickness in industrial processes."
    }
  ]
);


// ============================================================
// 11. ION FORMATION
// ============================================================

add(
  "chemistry",
  "atomic_structure",
  "Ion Formation",
  `<h2>Ion Formation</h2>

  <p>An <strong>ion</strong> is a charged particle formed when an atom gains or loses electrons.</p>

  <h3>Cation formation</h3>

  <p>When an atom <strong>loses electrons</strong>, it becomes positively charged.</p>

  <p>Example:</p>

  <p>Na → Na⁺ + e⁻</p>

  <p>Sodium loses one electron and forms a +1 ion.</p>

  <h3>Anion formation</h3>

  <p>When an atom <strong>gains electrons</strong>, it becomes negatively charged.</p>

  <p>Example:</p>

  <p>Cl + e⁻ → Cl⁻</p>

  <p>Chlorine gains one electron and forms a −1 ion.</p>

  <h3>Key rule</h3>

  <p><strong>Lose electrons → positive ion.</strong></p>
  <p><strong>Gain electrons → negative ion.</strong></p>`,

  [
    {
      q: "What is an ion?",
      steps: [
        "Step 1: A neutral atom has equal numbers of protons and electrons.",
        "Step 2: If electrons are gained or lost, this balance changes.",
        "Step 3: The particle now has a net charge.",
        "Step 4: Therefore, it is an ion."
      ],
      ans: "An ion is a charged particle formed when an atom gains or loses electrons.",
      why: "Changing the number of electrons changes the balance between positive and negative charge."
    },
    {
      q: "What happens when a sodium atom loses one electron?",
      steps: [
        "Step 1: Sodium initially has equal numbers of protons and electrons.",
        "Step 2: It loses one negatively charged electron.",
        "Step 3: There is now one more positive charge than negative charge.",
        "Step 4: Sodium forms Na⁺."
      ],
      ans: "It forms a Na⁺ ion.",
      why: "Loss of one electron produces a net charge of +1."
    },
    {
      q: "What happens when a chlorine atom gains one electron?",
      steps: [
        "Step 1: Chlorine gains one negatively charged electron.",
        "Step 2: There is now one more electron than the number of protons.",
        "Step 3: The particle has a net charge of −1.",
        "Step 4: It forms Cl⁻."
      ],
      ans: "It forms a Cl⁻ ion.",
      why: "Gaining one electron gives chlorine one extra unit of negative charge."
    }
  ],

  [
    {
      q: "An atom gains two electrons. What charge will its ion have?",
      hint: "Electrons carry negative charge.",
      steps: [
        "Step 1: Each gained electron contributes −1.",
        "Step 2: Two electrons contribute −2.",
        "Step 3: Therefore, the ion has a charge of −2."
      ],
      ans: "−2",
      why: "Gaining two electrons gives a net charge of −2."
    }
  ]
);


// ============================================================
// 12. WRITING ION CHARGES
// ============================================================

add(
  "chemistry",
  "atomic_structure",
  "Writing Ion Charges",
  `<h2>Writing Ion Charges</h2>

  <p>The charge of an ion tells us how many electrons an atom has gained or lost.</p>

  <h3>Positive ions</h3>

  <p>Positive ions form when electrons are lost.</p>

  <ul>
    <li>Na → Na⁺</li>
    <li>Mg → Mg²⁺</li>
    <li>Al → Al³⁺</li>
  </ul>

  <h3>Negative ions</h3>

  <p>Negative ions form when electrons are gained.</p>

  <ul>
    <li>Cl → Cl⁻</li>
    <li>O → O²⁻</li>
    <li>N → N³⁻</li>
  </ul>

  <h3>Finding the charge from proton and electron numbers</h3>

  <p><strong>Ion charge = number of protons − number of electrons</strong></p>

  <p>Example:</p>

  <p>12 protons and 10 electrons:</p>

  <p>Charge = 12 − 10 = +2</p>

  <p>Therefore, the ion is 2+.</p>

  <p>Example:</p>

  <p>17 protons and 18 electrons:</p>

  <p>Charge = 17 − 18 = −1</p>

  <p>Therefore, the ion is 1−.</p>`,

  [
    {
      q: "An ion has 12 protons and 10 electrons. Calculate its charge.",
      steps: [
        "Step 1: Use charge = protons − electrons.",
        "Step 2: Charge = 12 − 10.",
        "Step 3: Charge = +2."
      ],
      ans: "+2",
      why: "There are two more positive charges than negative charges."
    },
    {
      q: "An ion has 17 protons and 18 electrons. Calculate its charge.",
      steps: [
        "Step 1: Charge = protons − electrons.",
        "Step 2: Charge = 17 − 18.",
        "Step 3: Charge = −1."
      ],
      ans: "−1",
      why: "There is one more electron than proton, giving a net −1 charge."
    },
    {
      q: "An aluminium atom has atomic number 13. It loses three electrons. What ion does it form?",
      steps: [
        "Step 1: Atomic number 13 means aluminium has 13 protons.",
        "Step 2: Losing three electrons gives it 10 electrons.",
        "Step 3: Charge = 13 − 10.",
        "Step 4: Charge = +3.",
        "Step 5: Therefore, the ion is Al³⁺."
      ],
      ans: "Al³⁺",
      why: "Aluminium loses three negatively charged electrons, leaving a net +3 charge."
    }
  ],

  [
    {
      q: "An oxygen atom gains two electrons. Write the charge of the ion formed.",
      hint: "Each gained electron adds one negative charge.",
      steps: [
        "Step 1: Oxygen gains 2 electrons.",
        "Step 2: Each electron has charge −1.",
        "Step 3: Total charge gained = −2.",
        "Step 4: The ion is O²⁻."
      ],
      ans: "O²⁻",
      why: "Gaining two electrons produces a 2− ion."
    }
  ]
);
