// ============================================================
// 1. ARRANGEMENT OF THE PERIODIC TABLE
// ============================================================

add(
  "chemistry",
  "periodic_table",
  "Arrangement of the Periodic Table",
  `<h2>Arrangement of the Periodic Table</h2>

  <p>The <strong>Periodic Table</strong> is a systematic arrangement of elements according to their atomic numbers and repeating patterns in their properties.</p>

  <h3>Important features</h3>

  <ul>
    <li>Elements are arranged in order of increasing atomic number.</li>
    <li>Horizontal rows are called <strong>periods</strong>.</li>
    <li>Vertical columns are called <strong>groups</strong>.</li>
    <li>Elements in the same group have similar chemical properties because they have related outer-electron arrangements.</li>
  </ul>

  <h3>First 20 elements</h3>

  <p>The first 20 elements are:</p>

  <p>
  H, He, Li, Be, B, C, N, O, F, Ne,
  Na, Mg, Al, Si, P, S, Cl, Ar, K, Ca
  </p>

  <h3>Why the table is useful</h3>

  <p>The position of an element helps us predict its electron arrangement, valency and chemical behaviour.</p>`,

  [
    {
      q: "How are elements arranged in the modern periodic table?",
      steps: [
        "Step 1: Elements are identified by their atomic numbers.",
        "Step 2: The atomic numbers increase across the table.",
        "Step 3: Therefore, elements are arranged in order of increasing atomic number."
      ],
      ans: "Elements are arranged in order of increasing atomic number.",
      why: "Atomic number gives the number of protons and uniquely identifies each element."
    },
    {
      q: "What are the horizontal rows in the periodic table called?",
      steps: [
        "Step 1: Look at the horizontal arrangement of elements.",
        "Step 2: Horizontal rows are called periods."
      ],
      ans: "Periods.",
      why: "A period is a horizontal row in the periodic table."
    },
    {
      q: "What are the vertical columns in the periodic table called?",
      steps: [
        "Step 1: Look at the vertical arrangement of elements.",
        "Step 2: Vertical columns are called groups."
      ],
      ans: "Groups.",
      why: "A group is a vertical column in the periodic table."
    }
  ],

  [
    {
      q: "Which element has atomic number 17?",
      hint: "Use the atomic number to identify the element.",
      steps: [
        "Step 1: Find atomic number 17.",
        "Step 2: Atomic number 17 corresponds to chlorine."
      ],
      ans: "Chlorine.",
      why: "Chlorine has 17 protons and therefore atomic number 17."
    }
  ]
);


// ============================================================
// 2. GROUPS
// ============================================================

add(
  "chemistry",
  "periodic_table",
  "Groups",
  `<h2>Groups</h2>

  <p>A <strong>group</strong> is a vertical column in the periodic table.</p>

  <p>Elements in the same group generally have similar chemical properties because they have similar numbers of electrons in their outermost energy level.</p>

  <h3>Important groups</h3>

  <ul>
    <li><strong>Group 1</strong> — alkali metals</li>
    <li><strong>Group 2</strong> — alkaline earth metals</li>
    <li><strong>Group 7</strong> — halogens</li>
    <li><strong>Group 0</strong> — noble gases</li>
  </ul>

  <h3>Example</h3>

  <p>Sodium has electron arrangement 2,8,1.</p>

  <p>Potassium has electron arrangement 2,8,8,1.</p>

  <p>Both have one electron in the outermost energy level, so they belong to the same group: Group 1.</p>

  <p><strong>Same group → similar outer-electron pattern → similar chemical behaviour.</strong></p>`,

  [
    {
      q: "What is a group in the periodic table?",
      steps: [
        "Step 1: Identify the direction of the column.",
        "Step 2: A vertical column is called a group."
      ],
      ans: "A group is a vertical column in the periodic table.",
      why: "Groups contain elements with related outer-electron arrangements and similar chemical properties."
    },
    {
      q: "Why do elements in the same group often have similar chemical properties?",
      steps: [
        "Step 1: Chemical reactions involve electrons, especially outer electrons.",
        "Step 2: Elements in the same group have similar outer-electron arrangements.",
        "Step 3: Therefore, they tend to react in similar ways."
      ],
      ans: "They have similar outer-electron arrangements, giving them similar chemical behaviour.",
      why: "The outer electrons strongly influence how an element reacts."
    },
    {
      q: "Sodium has electron arrangement 2,8,1. Which group does it belong to?",
      steps: [
        "Step 1: Count the electrons in the outermost energy level.",
        "Step 2: Sodium has 1 outer electron.",
        "Step 3: It belongs to Group 1."
      ],
      ans: "Group 1.",
      why: "For the first 20 elements, the number of outer electrons helps identify the group."
    }
  ],

  [
    {
      q: "An element has electron arrangement 2,8,7. Which group does it belong to?",
      hint: "Count the electrons in the outermost energy level.",
      steps: [
        "Step 1: The outermost level contains 7 electrons.",
        "Step 2: An element with 7 outer electrons belongs to Group 7.",
        "Step 3: Therefore, the element is in Group 7."
      ],
      ans: "Group 7.",
      why: "The first 20 elements with seven outer electrons are placed in Group 7."
    }
  ]
);


// ============================================================
// 3. PERIODS
// ============================================================

add(
  "chemistry",
  "periodic_table",
  "Periods",
  `<h2>Periods</h2>

  <p>A <strong>period</strong> is a horizontal row in the periodic table.</p>

  <p>For the first 20 elements, the period number corresponds to the number of occupied electron energy levels.</p>

  <h3>Examples</h3>

  <p>Hydrogen: 1 → one occupied energy level → Period 1.</p>

  <p>Carbon: 2,4 → two occupied energy levels → Period 2.</p>

  <p>Sodium: 2,8,1 → three occupied energy levels → Period 3.</p>

  <p>Calcium: 2,8,8,2 → four occupied energy levels → Period 4.</p>

  <p><strong>Number of occupied energy levels = period number.</strong></p>`,

  [
    {
      q: "What is a period in the periodic table?",
      steps: [
        "Step 1: Identify the horizontal rows.",
        "Step 2: A horizontal row is called a period."
      ],
      ans: "A period is a horizontal row in the periodic table.",
      why: "Elements in the same period have the same number of occupied principal energy levels."
    },
    {
      q: "An element has electron arrangement 2,8,1. Which period is it in?",
      steps: [
        "Step 1: Count the occupied energy levels.",
        "Step 2: There are three energy levels: 2, 8 and 1.",
        "Step 3: Therefore, the element is in Period 3."
      ],
      ans: "Period 3.",
      why: "Three occupied energy levels correspond to Period 3."
    },
    {
      q: "An element has electron arrangement 2,8,8,2. Which period is it in?",
      steps: [
        "Step 1: Count the energy levels.",
        "Step 2: There are four occupied energy levels.",
        "Step 3: Therefore, the element is in Period 4."
      ],
      ans: "Period 4.",
      why: "The number of occupied energy levels gives the period for the first 20 elements."
    }
  ],

  [
    {
      q: "An element has electron arrangement 2,6. Which period is it in?",
      hint: "Count the occupied energy levels.",
      steps: [
        "Step 1: There are two occupied energy levels.",
        "Step 2: Therefore, the element is in Period 2."
      ],
      ans: "Period 2.",
      why: "Two occupied energy levels indicate Period 2."
    }
  ]
);


// ============================================================
// 4. ELECTRONIC STRUCTURE AND PERIODIC POSITION
// ============================================================

add(
  "chemistry",
  "periodic_table",
  "Electronic Structure and Periodic Position",
  `<h2>Electronic Structure and Periodic Position</h2>

  <p>The electron arrangement of an element can be used to determine its position in the periodic table.</p>

  <h3>Finding the period</h3>

  <p>Count the number of occupied energy levels.</p>

  <p><strong>Occupied energy levels → period</strong></p>

  <h3>Finding the group</h3>

  <p>For the first 20 elements, examine the number of electrons in the outermost energy level.</p>

  <p><strong>Outer electrons → group</strong></p>

  <h3>Example</h3>

  <p>Magnesium = 2,8,2</p>

  <ul>
    <li>Three occupied energy levels → Period 3.</li>
    <li>Two outer electrons → Group 2.</li>
  </ul>

  <p>Therefore, magnesium is in <strong>Period 3, Group 2</strong>.</p>`,

  [
    {
      q: "Determine the group and period of an element with electron arrangement 2,8,1.",
      steps: [
        "Step 1: Count occupied energy levels: 3.",
        "Step 2: Therefore, period = 3.",
        "Step 3: Count outer electrons: 1.",
        "Step 4: Therefore, group = 1."
      ],
      ans: "Group 1, Period 3.",
      why: "The three energy levels determine the period and the one outer electron determines the group."
    },
    {
      q: "Determine the group and period of an element with electron arrangement 2,8,6.",
      steps: [
        "Step 1: There are three occupied energy levels.",
        "Step 2: Period = 3.",
        "Step 3: There are six outer electrons.",
        "Step 4: Group = 6."
      ],
      ans: "Group 6, Period 3.",
      why: "The number of occupied levels gives the period while the outer-electron number gives the group for these elements."
    },
    {
      q: "An element is in Group 2 and Period 3. Write its electron arrangement.",
      steps: [
        "Step 1: Period 3 means three occupied energy levels.",
        "Step 2: Group 2 means two outer electrons.",
        "Step 3: Fill the first level with 2 electrons.",
        "Step 4: Fill the second level with 8 electrons.",
        "Step 5: Put 2 electrons in the third level.",
        "Step 6: Arrangement = 2,8,2."
      ],
      ans: "2,8,2.",
      why: "The group gives the outer-electron number and the period gives the number of occupied energy levels."
    }
  ],

  [
    {
      q: "An element has electron arrangement 2,8,7. State its group and period.",
      hint: "Use outer electrons for the group and occupied levels for the period.",
      steps: [
        "Step 1: Seven outer electrons → Group 7.",
        "Step 2: Three occupied energy levels → Period 3."
      ],
      ans: "Group 7, Period 3.",
      why: "The electron arrangement directly gives both its group and period."
    }
  ]
);


// ============================================================
// 5. GROUP 1 ELEMENTS
// ============================================================

add(
  "chemistry",
  "periodic_table",
  "Group 1 Elements",
  `<h2>Group 1 Elements</h2>

  <p>Group 1 elements are called the <strong>alkali metals</strong>.</p>

  <h3>Examples</h3>

  <ul>
    <li>Lithium — Li</li>
    <li>Sodium — Na</li>
    <li>Potassium — K</li>
  </ul>

  <h3>Electron arrangement</h3>

  <p>Group 1 elements have <strong>one electron in their outermost energy level</strong>.</p>

  <p>Examples:</p>

  <ul>
    <li>Li = 2,1</li>
    <li>Na = 2,8,1</li>
    <li>K = 2,8,8,1</li>
  </ul>

  <h3>Reaction with water</h3>

  <p>Group 1 metals react with water to form a metal hydroxide and hydrogen gas.</p>

  <p><strong>metal + water → metal hydroxide + hydrogen</strong></p>

  <p>The metals generally become more reactive down the group.</p>`,

  [
    {
      q: "Why are lithium, sodium and potassium placed in the same group?",
      steps: [
        "Step 1: Lithium has one outer electron.",
        "Step 2: Sodium has one outer electron.",
        "Step 3: Potassium has one outer electron.",
        "Step 4: Therefore, they belong to the same group."
      ],
      ans: "They all have one electron in their outermost energy level.",
      why: "Similar outer-electron arrangements give Group 1 elements similar chemical behaviour."
    },
    {
      q: "Write the general word equation for the reaction of a Group 1 metal with water.",
      steps: [
        "Step 1: The metal reacts with water.",
        "Step 2: A metal hydroxide is formed.",
        "Step 3: Hydrogen gas is also produced."
      ],
      ans: "Group 1 metal + water → metal hydroxide + hydrogen.",
      why: "This is the characteristic reaction of Group 1 metals with water."
    },
    {
      q: "Which is more reactive, lithium or potassium?",
      steps: [
        "Step 1: Lithium and potassium are both Group 1 metals.",
        "Step 2: Potassium is lower down the group.",
        "Step 3: Reactivity of Group 1 metals increases down the group.",
        "Step 4: Therefore, potassium is more reactive."
      ],
      ans: "Potassium.",
      why: "Group 1 metals generally become more reactive down the group."
    }
  ],

  [
    {
      q: "Which Group 1 metal is more reactive: sodium or potassium?",
      hint: "Reactivity increases down Group 1.",
      steps: [
        "Step 1: Potassium is below sodium in Group 1.",
        "Step 2: Reactivity increases down the group.",
        "Step 3: Therefore, potassium is more reactive."
      ],
      ans: "Potassium.",
      why: "Potassium is lower in Group 1 than sodium."
    }
  ]
);


// ============================================================
// 6. GROUP 2 ELEMENTS
// ============================================================

add(
  "chemistry",
  "periodic_table",
  "Group 2 Elements",
  `<h2>Group 2 Elements</h2>

  <p>Group 2 elements are called the <strong>alkaline earth metals</strong>.</p>

  <h3>Examples</h3>

  <ul>
    <li>Beryllium — Be</li>
    <li>Magnesium — Mg</li>
    <li>Calcium — Ca</li>
  </ul>

  <h3>Electron arrangement</h3>

  <p>Group 2 elements have <strong>two electrons in their outermost energy level</strong>.</p>

  <p>Examples:</p>

  <ul>
    <li>Be = 2,2</li>
    <li>Mg = 2,8,2</li>
    <li>Ca = 2,8,8,2</li>
  </ul>

  <p>They commonly lose two electrons to form <strong>2+</strong> ions.</p>

  <h3>Reaction with water</h3>

  <p>Some Group 2 metals react with water to form metal hydroxides and hydrogen. Reactivity generally increases down the group.</p>`,

  [
    {
      q: "How many outer electrons does a Group 2 element have?",
      steps: [
        "Step 1: Group 2 elements have two electrons in their outermost energy level.",
        "Step 2: Therefore, the number of outer electrons is 2."
      ],
      ans: "2 outer electrons.",
      why: "The outer-electron arrangement is characteristic of Group 2."
    },
    {
      q: "What ion is commonly formed when a Group 2 atom loses its outer electrons?",
      steps: [
        "Step 1: A Group 2 atom has two outer electrons.",
        "Step 2: It can lose both electrons.",
        "Step 3: Losing two negative electrons leaves a +2 charge."
      ],
      ans: "A 2+ ion.",
      why: "Loss of two electrons produces a net charge of +2."
    },
    {
      q: "Write the electron arrangement of calcium, atomic number 20.",
      steps: [
        "Step 1: Calcium has 20 electrons.",
        "Step 2: First energy level = 2.",
        "Step 3: Second = 8.",
        "Step 4: Third = 8.",
        "Step 5: Remaining electrons = 2.",
        "Step 6: Arrangement = 2,8,8,2."
      ],
      ans: "2,8,8,2.",
      why: "Calcium has 20 electrons distributed among four occupied energy levels."
    }
  ],

  [
    {
      q: "An element has electron arrangement 2,8,2. Which group does it belong to?",
      hint: "Look at the outermost energy level.",
      steps: [
        "Step 1: The outermost level contains 2 electrons.",
        "Step 2: Therefore, the element belongs to Group 2."
      ],
      ans: "Group 2.",
      why: "Group 2 elements have two outer electrons."
    }
  ]
);


// ============================================================
// 7. GROUP 7 ELEMENTS
// ============================================================

add(
  "chemistry",
  "periodic_table",
  "Group 7 Elements",
  `<h2>Group 7 Elements</h2>

  <p>Group 7 elements are called the <strong>halogens</strong>.</p>

  <h3>Examples</h3>

  <ul>
    <li>Fluorine — F</li>
    <li>Chlorine — Cl</li>
    <li>Bromine — Br</li>
    <li>Iodine — I</li>
  </ul>

  <p>For the first 20 elements, fluorine and chlorine are important examples.</p>

  <h3>Electron arrangement</h3>

  <p>Group 7 elements have <strong>seven outer electrons</strong>.</p>

  <p>Example:</p>

  <p>Chlorine = 2,8,7</p>

  <p>They tend to gain one electron to obtain a stable outer shell, forming <strong>1− ions</strong>.</p>

  <h3>Reactivity</h3>

  <p>Halogen reactivity generally decreases down the group.</p>`,

  [
    {
      q: "How many outer electrons does a Group 7 element have?",
      steps: [
        "Step 1: Group 7 elements are characterised by seven outer electrons.",
        "Step 2: Therefore, the number is 7."
      ],
      ans: "7 outer electrons.",
      why: "The seven outer electrons are characteristic of the halogens."
    },
    {
      q: "Why does chlorine tend to gain one electron?",
      steps: [
        "Step 1: Chlorine has electron arrangement 2,8,7.",
        "Step 2: Its outer level contains 7 electrons.",
        "Step 3: Gaining one electron gives 8 outer electrons.",
        "Step 4: Therefore, chlorine tends to gain one electron."
      ],
      ans: "Chlorine gains one electron to achieve a full outer energy level.",
      why: "A full outer energy level gives the atom a more stable electron arrangement."
    },
    {
      q: "Which is more reactive: fluorine or chlorine?",
      steps: [
        "Step 1: Fluorine and chlorine are both Group 7 elements.",
        "Step 2: Fluorine is above chlorine.",
        "Step 3: Halogen reactivity generally decreases down the group.",
        "Step 4: Therefore, fluorine is more reactive."
      ],
      ans: "Fluorine.",
      why: "Halogens generally become less reactive down Group 7."
    }
  ],

  [
    {
      q: "An atom has electron arrangement 2,8,7. Which type of element is it likely to be?",
      hint: "Seven outer electrons identify a particular chemical family.",
      steps: [
        "Step 1: The atom has seven outer electrons.",
        "Step 2: Seven outer electrons correspond to Group 7.",
        "Step 3: Group 7 elements are halogens."
      ],
      ans: "A Group 7 halogen.",
      why: "The electron arrangement identifies the halogen family."
    }
  ]
);


// ============================================================
// 8. GROUP 0 ELEMENTS
// ============================================================

add(
  "chemistry",
  "periodic_table",
  "Group 0 Elements",
  `<h2>Group 0 Elements</h2>

  <p>Group 0 elements are called the <strong>noble gases</strong>.</p>

  <h3>Examples</h3>

  <ul>
    <li>Helium — He</li>
    <li>Neon — Ne</li>
    <li>Argon — Ar</li>
  </ul>

  <h3>Electron arrangement</h3>

  <p>Noble gases have full outer energy levels.</p>

  <ul>
    <li>Helium = 2</li>
    <li>Neon = 2,8</li>
    <li>Argon = 2,8,8</li>
  </ul>

  <p>Because their outer energy levels are full, noble gases are generally very unreactive.</p>

  <h3>Physical state</h3>

  <p>At room temperature, noble gases are gases.</p>`,

  [
    {
      q: "Why are Group 0 elements generally unreactive?",
      steps: [
        "Step 1: Their outer energy levels are full.",
        "Step 2: They do not normally need to gain, lose or share electrons.",
        "Step 3: Therefore, they have low chemical reactivity."
      ],
      ans: "They have full outer energy levels, making them very stable.",
      why: "A full outer energy level reduces the tendency to undergo chemical reactions."
    },
    {
      q: "Write the electron arrangement of neon, atomic number 10.",
      steps: [
        "Step 1: Neon has 10 electrons.",
        "Step 2: Put 2 in the first energy level.",
        "Step 3: The remaining 8 go into the second level.",
        "Step 4: Arrangement = 2,8."
      ],
      ans: "2,8.",
      why: "Neon has a complete first and second energy level."
    },
    {
      q: "Why does helium belong to Group 0 even though it has only two electrons?",
      steps: [
        "Step 1: The first energy level can hold a maximum of 2 electrons.",
        "Step 2: Helium has 2 electrons.",
        "Step 3: Its only energy level is therefore full.",
        "Step 4: A full outer energy level makes helium a noble gas."
      ],
      ans: "Because its first and only energy level is completely full with two electrons.",
      why: "Helium has a stable full outer energy level even though the first level holds only two electrons."
    }
  ],

  [
    {
      q: "An element has electron arrangement 2,8,8. Which group does it belong to?",
      hint: "The outermost energy level is completely full.",
      steps: [
        "Step 1: The outermost energy level contains 8 electrons.",
        "Step 2: This is a full outer level for the first 20 elements.",
        "Step 3: The element belongs to Group 0."
      ],
      ans: "Group 0.",
      why: "Group 0 elements have full outer energy levels."
    }
  ]
);


// ============================================================
// 9. METALS AND NON-METALS
// ============================================================

add(
  "chemistry",
  "periodic_table",
  "Metals and Non-metals",
  `<h2>Metals and Non-metals</h2>

  <p>Elements can broadly be classified as <strong>metals</strong> or <strong>non-metals</strong> based on their physical and chemical properties.</p>

  <h3>Typical properties of metals</h3>

  <ul>
    <li>Good conductors of heat.</li>
    <li>Good conductors of electricity.</li>
    <li>Generally shiny when freshly cut or polished.</li>
    <li>Malleable.</li>
    <li>Ductile.</li>
    <li>Generally solid at room temperature.</li>
  </ul>

  <h3>Typical properties of non-metals</h3>

  <ul>
    <li>Generally poor conductors of electricity.</li>
    <li>Many are dull in appearance.</li>
    <li>Solid non-metals are often brittle.</li>
    <li>Many have relatively low melting and boiling points.</li>
    <li>They may exist as solids, liquids or gases.</li>
  </ul>

  <h3>Position in the periodic table</h3>

  <p>Most metals are found on the left and centre of the periodic table, while most non-metals are found toward the right.</p>`,

  [
    {
      q: "State two typical physical properties of metals.",
      steps: [
        "Step 1: Metals generally conduct heat well.",
        "Step 2: Metals generally conduct electricity well.",
        "Step 3: Metals are also commonly malleable and ductile."
      ],
      ans: "Any two: good electrical conductivity, good thermal conductivity, malleability or ductility.",
      why: "These are characteristic physical properties of many metals."
    },
    {
      q: "State two typical properties of non-metals.",
      steps: [
        "Step 1: Most non-metals are poor electrical conductors.",
        "Step 2: Many solid non-metals are brittle.",
        "Step 3: Many also have relatively low melting and boiling points."
      ],
      ans: "Any two: poor electrical conductivity, brittleness when solid, or relatively low melting/boiling points.",
      why: "These properties distinguish many non-metals from metals."
    },
    {
      q: "Where are most metals found in the periodic table?",
      steps: [
        "Step 1: Examine the broad regions of the periodic table.",
        "Step 2: Most metals occur on the left and central regions.",
        "Step 3: Therefore, metals are mainly found on the left and centre."
      ],
      ans: "Mainly on the left and in the centre of the periodic table.",
      why: "The periodic table broadly separates metallic and non-metallic elements."
    }
  ],

  [
    {
      q: "An element is a good conductor of electricity and is malleable. Is it more likely to be a metal or non-metal?",
      hint: "Think about the typical properties of metals.",
      steps: [
        "Step 1: Good electrical conductivity is characteristic of metals.",
        "Step 2: Malleability is also characteristic of metals.",
        "Step 3: Therefore, the element is likely to be a metal."
      ],
      ans: "Metal.",
      why: "Electrical conductivity and malleability are typical metallic properties."
    }
  ]
);


// ============================================================
// 10. PERIODIC TRENDS
// ============================================================

add(
  "chemistry",
  "periodic_table",
  "Periodic Trends",
  `<h2>Periodic Trends</h2>

  <p>A <strong>periodic trend</strong> is a pattern in the properties of elements as their position changes across a period or down a group.</p>

  <h3>Across a period</h3>

  <p>As atomic number increases across a period:</p>

  <ul>
    <li>The number of outer electrons generally increases.</li>
    <li>Elements gradually change from metallic to non-metallic behaviour.</li>
  </ul>

  <h3>Down a group</h3>

  <p>Elements have more occupied energy levels as we move down a group.</p>

  <p>This affects atomic size and the attraction between the nucleus and outer electrons.</p>

  <h3>Reactivity</h3>

  <p>Different groups show different reactivity patterns:</p>

  <ul>
    <li>Group 1 metals generally become more reactive down the group.</li>
    <li>Group 7 halogens generally become less reactive down the group.</li>
    <li>Group 0 elements remain very unreactive.</li>
  </ul>`,

  [
    {
      q: "What is meant by a periodic trend?",
      steps: [
        "Step 1: Elements are arranged systematically in the periodic table.",
        "Step 2: Their properties show repeating patterns.",
        "Step 3: These patterns are called periodic trends."
      ],
      ans: "A periodic trend is a repeating pattern in the properties of elements across periods or down groups.",
      why: "The repeating electron arrangements produce repeating chemical and physical behaviour."
    },
    {
      q: "How does the reactivity of Group 1 metals change down the group?",
      steps: [
        "Step 1: Compare Group 1 elements from top to bottom.",
        "Step 2: The outer electron is farther from the nucleus in larger atoms.",
        "Step 3: It becomes easier to lose the outer electron.",
        "Step 4: Therefore, reactivity increases down Group 1."
      ],
      ans: "Reactivity increases down Group 1.",
      why: "The outer electron becomes easier to remove as atomic size increases."
    },
    {
      q: "How does the reactivity of Group 7 elements change down the group?",
      steps: [
        "Step 1: Group 7 elements react by gaining an electron.",
        "Step 2: Down the group, atoms become larger.",
        "Step 3: The nucleus attracts an incoming electron less strongly.",
        "Step 4: Therefore, reactivity decreases down Group 7."
      ],
      ans: "Reactivity decreases down Group 7.",
      why: "The attraction for an incoming electron becomes weaker as the atomic size increases."
    }
  ],

  [
    {
      q: "Which is more reactive in Group 1: lithium or potassium?",
      hint: "Group 1 reactivity increases down the group.",
      steps: [
        "Step 1: Potassium is below lithium.",
        "Step 2: Reactivity increases down Group 1.",
        "Step 3: Therefore, potassium is more reactive."
      ],
      ans: "Potassium.",
      why: "Group 1 metals become more reactive down the group."
    }
  ]
);


// ============================================================
// 11. ATOMIC SIZE
// ============================================================

add(
  "chemistry",
  "periodic_table",
  "Atomic Size",
  `<h2>Atomic Size</h2>

  <p><strong>Atomic size</strong> refers to the relative size of an atom.</p>

  <h3>Down a group</h3>

  <p>Atomic size generally <strong>increases down a group</strong>.</p>

  <p>This happens because each step down adds another occupied energy level.</p>

  <p>The outer electrons are therefore farther from the nucleus.</p>

  <h3>Across a period</h3>

  <p>Atomic size generally <strong>decreases from left to right</strong> across a period.</p>

  <p>As proton number increases, the nucleus attracts the electrons more strongly while the electrons are being added to the same main energy level.</p>

  <h3>Simple rule</h3>

  <p><strong>Down a group → atomic size increases.</strong></p>

  <p><strong>Across a period → atomic size generally decreases.</strong></p>`,

  [
    {
      q: "Why does atomic size generally increase down a group?",
      steps: [
        "Step 1: Moving down a group adds another occupied energy level.",
        "Step 2: The outer electrons are therefore farther from the nucleus.",
        "Step 3: The atom becomes larger."
      ],
      ans: "Atomic size increases because additional occupied energy levels place the outer electrons farther from the nucleus.",
      why: "Each new energy level increases the distance between the nucleus and the outermost electrons."
    },
    {
      q: "Which atom is larger: sodium or potassium?",
      steps: [
        "Step 1: Sodium and potassium are in Group 1.",
        "Step 2: Potassium is below sodium.",
        "Step 3: Atomic size increases down a group.",
        "Step 4: Therefore, potassium is larger."
      ],
      ans: "Potassium.",
      why: "Potassium has an additional occupied energy level compared with sodium."
    },
    {
      q: "How does atomic size generally change from left to right across a period?",
      steps: [
        "Step 1: Proton number increases across the period.",
        "Step 2: Electrons are added to the same main energy level.",
        "Step 3: The increasing nuclear attraction pulls the electrons closer.",
        "Step 4: Therefore, atomic size generally decreases."
      ],
      ans: "Atomic size generally decreases from left to right across a period.",
      why: "Increasing nuclear charge attracts the electrons more strongly across the same main energy level."
    }
  ],

  [
    {
      q: "Which is larger, lithium or sodium?",
      hint: "Both are in Group 1. Look at their positions.",
      steps: [
        "Step 1: Lithium is above sodium in Group 1.",
        "Step 2: Atomic size increases down a group.",
        "Step 3: Therefore, sodium is larger."
      ],
      ans: "Sodium.",
      why: "Sodium has one more occupied energy level than lithium."
    }
  ]
);
