add(
  "chemistry",
  "chemical_formulae",
  "Valency and Chemical Formulae",
  `<h2>Valency and Chemical Formulae</h2>

  <p>The <strong>valency</strong> of an element helps determine the ratio in which its atoms combine with other elements.</p>

  <h3>Common valencies</h3>

  <ul>
    <li>Sodium (Na) → 1</li>
    <li>Magnesium (Mg) → 2</li>
    <li>Aluminium (Al) → 3</li>
    <li>Chlorine (Cl) → 1</li>
    <li>Oxygen (O) → 2</li>
    <li>Nitrogen (N) → 3</li>
  </ul>

  <h3>Using valency</h3>

  <p>When writing a formula, the total combining capacity of the positive part must balance the total combining capacity of the negative part.</p>

  <p>For example:</p>

  <p>Mg has valency 2 and Cl has valency 1.</p>

  <p>One Mg atom requires two Cl atoms.</p>

  <p>Therefore:</p>

  <p><strong>MgCl₂</strong></p>`,

  [
    {
      q: "Why is valency important when writing chemical formulae?",
      steps: [
        "Step 1: Valency indicates the combining capacity of an element.",
        "Step 2: The valencies of the combining elements determine their ratio.",
        "Step 3: The formula must represent a compound with the correct ratio of atoms or ions."
      ],
      ans: "Valency determines the ratio in which elements combine when forming a compound.",
      why: "The correct ratio ensures that the combining capacities are satisfied."
    },
    {
      q: "What is the valency of magnesium?",
      steps: [
        "Step 1: Magnesium is in Group 2.",
        "Step 2: It commonly loses two electrons.",
        "Step 3: Therefore, its common valency is 2."
      ],
      ans: "2.",
      why: "Magnesium has two outer electrons and commonly has valency 2."
    },
    {
      q: "What is the valency of oxygen?",
      steps: [
        "Step 1: Oxygen has six outer electrons.",
        "Step 2: It needs two more electrons to complete its outer energy level.",
        "Step 3: Therefore, its common valency is 2."
      ],
      ans: "2.",
      why: "Oxygen commonly gains or shares two electrons when forming compounds."
    }
  ],

  [
    {
      q: "A metal has valency 2 and chlorine has valency 1. What ratio of metal atoms to chlorine atoms is required?",
      hint: "The two chlorine atoms provide a total valency of 2.",
      steps: [
        "Step 1: The metal has valency 2.",
        "Step 2: Each chlorine atom has valency 1.",
        "Step 3: Two chlorine atoms provide a total valency of 2.",
        "Step 4: Therefore, the ratio is 1 metal atom : 2 chlorine atoms."
      ],
      ans: "1 : 2.",
      why: "Two chlorine atoms are required to balance the valency of one divalent metal atom."
    }
  ]
);

add(
  "chemistry",
  "chemical_formulae",
  "Writing Chemical Formulae",
  `<h2>Writing Chemical Formulae</h2>

  <p>A chemical formula shows the elements present in a compound and the ratio in which their atoms or ions occur.</p>

  <h3>Method</h3>

  <ol>
    <li>Write the symbols of the elements.</li>
    <li>Write their valencies.</li>
    <li>Find the simplest ratio that balances the valencies.</li>
    <li>Write the subscripts in the formula.</li>
    <li>Do not write subscript 1.</li>
    <li>Reduce the ratio to the simplest whole numbers if necessary.</li>
  </ol>

  <h3>Example: Aluminium oxide</h3>

  <p>Aluminium = 3</p>

  <p>Oxygen = 2</p>

  <p>Two Al atoms give:</p>

  <p>2 × 3 = 6</p>

  <p>Three O atoms give:</p>

  <p>3 × 2 = 6</p>

  <p>Therefore:</p>

  <p><strong>Al₂O₃</strong></p>`,

  [
    {
      q: "Write the formula of magnesium chloride. Magnesium has valency 2 and chlorine has valency 1.",
      steps: [
        "Step 1: Write the symbols: Mg and Cl.",
        "Step 2: Magnesium has valency 2.",
        "Step 3: Chlorine has valency 1.",
        "Step 4: One Mg atom gives a combining capacity of 2.",
        "Step 5: Two Cl atoms give a combining capacity of 2.",
        "Step 6: Therefore, the formula is MgCl₂."
      ],
      ans: "MgCl₂.",
      why: "One Mg atom combines with two Cl atoms to balance the valencies."
    },
    {
      q: "Write the formula of aluminium oxide. Aluminium has valency 3 and oxygen has valency 2.",
      steps: [
        "Step 1: Write Al and O.",
        "Step 2: Al has valency 3 and O has valency 2.",
        "Step 3: The lowest common total is 6.",
        "Step 4: Two Al atoms give 2 × 3 = 6.",
        "Step 5: Three O atoms give 3 × 2 = 6.",
        "Step 6: Therefore, the formula is Al₂O₃."
      ],
      ans: "Al₂O₃.",
      why: "Two Al atoms and three O atoms give equal total combining capacities."
    },
    {
      q: "Write the formula of calcium oxide. Calcium has valency 2 and oxygen has valency 2.",
      steps: [
        "Step 1: Write Ca and O.",
        "Step 2: Calcium has valency 2.",
        "Step 3: Oxygen has valency 2.",
        "Step 4: One Ca atom gives 2.",
        "Step 5: One O atom gives 2.",
        "Step 6: Therefore, the simplest formula is CaO."
      ],
      ans: "CaO.",
      why: "The two valencies are equal, so one calcium atom combines with one oxygen atom."
    }
  ],

  [
    {
      q: "Write the formula of sodium oxide. Sodium has valency 1 and oxygen has valency 2.",
      hint: "Two sodium atoms are needed to balance one oxygen atom.",
      steps: [
        "Step 1: Sodium has valency 1.",
        "Step 2: Oxygen has valency 2.",
        "Step 3: Two Na atoms give a total valency of 2.",
        "Step 4: One O atom gives a total valency of 2.",
        "Step 5: Therefore, the formula is Na₂O."
      ],
      ans: "Na₂O.",
      why: "Two sodium atoms balance the valency of one oxygen atom."
    }
  ]
);

add(
  "chemistry",
  "chemical_formulae",
  "Formulae of Ionic Compounds",
  `<h2>Formulae of Ionic Compounds</h2>

  <p>The formula of an ionic compound must have an overall charge of <strong>zero</strong>.</p>

  <h3>Using ion charges</h3>

  <p>Consider calcium chloride:</p>

  <p>Ca²⁺ and Cl⁻</p>

  <p>One Ca²⁺ gives +2.</p>

  <p>Two Cl⁻ ions give:</p>

  <p>2 × (−1) = −2</p>

  <p>Total charge:</p>

  <p>+2 + (−2) = 0</p>

  <p>Therefore:</p>

  <p><strong>CaCl₂</strong></p>

  <h3>Important rule</h3>

  <p>Always check the charges after writing an ionic formula.</p>`,

  [
    {
      q: "Write the formula of calcium chloride using Ca²⁺ and Cl⁻.",
      steps: [
        "Step 1: Ca²⁺ has charge +2.",
        "Step 2: Cl⁻ has charge −1.",
        "Step 3: Two Cl⁻ ions give −2.",
        "Step 4: +2 + (−2) = 0.",
        "Step 5: Therefore, the formula is CaCl₂."
      ],
      ans: "CaCl₂.",
      why: "Two chloride ions are needed to balance one calcium ion."
    },
    {
      q: "Write the formula of magnesium oxide using Mg²⁺ and O²⁻.",
      steps: [
        "Step 1: Mg²⁺ has charge +2.",
        "Step 2: O²⁻ has charge −2.",
        "Step 3: One Mg²⁺ balances one O²⁻.",
        "Step 4: The total charge is zero.",
        "Step 5: Therefore, the formula is MgO."
      ],
      ans: "MgO.",
      why: "The +2 and −2 charges balance in a 1:1 ratio."
    },
    {
      q: "Write the formula of aluminium oxide using Al³⁺ and O²⁻.",
      steps: [
        "Step 1: Al³⁺ has charge +3.",
        "Step 2: O²⁻ has charge −2.",
        "Step 3: Two Al³⁺ ions give +6.",
        "Step 4: Three O²⁻ ions give −6.",
        "Step 5: +6 + (−6) = 0.",
        "Step 6: Therefore, the formula is Al₂O₃."
      ],
      ans: "Al₂O₃.",
      why: "Two aluminium ions and three oxide ions produce a neutral compound."
    }
  ],

  [
    {
      q: "Write the formula of aluminium chloride using Al³⁺ and Cl⁻.",
      hint: "Find the smallest number of chloride ions needed to balance +3.",
      steps: [
        "Step 1: Al³⁺ contributes +3.",
        "Step 2: Each Cl⁻ contributes −1.",
        "Step 3: Three Cl⁻ ions contribute −3.",
        "Step 4: The total charge becomes zero.",
        "Step 5: Therefore, the formula is AlCl₃."
      ],
      ans: "AlCl₃.",
      why: "Three chloride ions balance the +3 charge of one aluminium ion."
    }
  ]
);

add(
  "chemistry",
  "chemical_formulae",
  "Formulae of Covalent Compounds",
  `<h2>Formulae of Covalent Compounds</h2>

  <p>Covalent compounds are formed when non-metal atoms share electrons.</p>

  <p>The formula shows the actual number or ratio of atoms in the molecule or substance.</p>

  <h3>Examples</h3>

  <p><strong>Water</strong> = H₂O</p>

  <p>One oxygen atom is combined with two hydrogen atoms.</p>

  <p><strong>Carbon dioxide</strong> = CO₂</p>

  <p>One carbon atom is combined with two oxygen atoms.</p>

  <p><strong>Ammonia</strong> = NH₃</p>

  <p>One nitrogen atom is combined with three hydrogen atoms.</p>

  <h3>Subscripts</h3>

  <p>A subscript shows how many atoms of that element are present.</p>

  <p>In CO₂, the subscript 2 applies to oxygen only.</p>

  <p>In H₂O, the subscript 2 applies to hydrogen only.</p>`,

  [
    {
      q: "What does the formula H₂O tell us about water?",
      steps: [
        "Step 1: The symbol H represents hydrogen.",
        "Step 2: The subscript 2 means there are two hydrogen atoms.",
        "Step 3: O represents oxygen with no subscript.",
        "Step 4: No subscript means one oxygen atom.",
        "Step 5: Therefore, H₂O contains two hydrogen atoms and one oxygen atom."
      ],
      ans: "Two hydrogen atoms and one oxygen atom.",
      why: "Subscripts show the number of atoms of each element in the formula."
    },
    {
      q: "What does the formula CO₂ tell us about carbon dioxide?",
      steps: [
        "Step 1: C represents carbon.",
        "Step 2: There is no subscript after C, so there is one carbon atom.",
        "Step 3: The subscript 2 after O means two oxygen atoms.",
        "Step 4: Therefore, one carbon atom combines with two oxygen atoms."
      ],
      ans: "One carbon atom and two oxygen atoms.",
      why: "The subscript 2 applies only to oxygen."
    },
    {
      q: "What does the formula NH₃ tell us about ammonia?",
      steps: [
        "Step 1: N represents nitrogen.",
        "Step 2: There is no subscript after N, so there is one nitrogen atom.",
        "Step 3: The subscript 3 after H means three hydrogen atoms.",
        "Step 4: Therefore, NH₃ contains one nitrogen atom and three hydrogen atoms."
      ],
      ans: "One nitrogen atom and three hydrogen atoms.",
      why: "The subscript 3 applies to hydrogen only."
    }
  ],

  [
    {
      q: "How many atoms are present in one molecule of CO₂?",
      hint: "Count the carbon atom and the two oxygen atoms.",
      steps: [
        "Step 1: CO₂ contains one carbon atom.",
        "Step 2: It contains two oxygen atoms.",
        "Step 3: Total atoms = 1 + 2.",
        "Step 4: Total atoms = 3."
      ],
      ans: "3 atoms.",
      why: "One carbon atom plus two oxygen atoms gives three atoms."
    }
  ]
);

add(
  "chemistry",
  "chemical_formulae",
  "Naming Compounds",
  `<h2>Naming Compounds</h2>

  <p>The name of a compound identifies the elements or ions present in it.</p>

  <h3>Ionic compounds</h3>

  <p>For a simple ionic compound, name the positive ion first, followed by the negative ion.</p>

  <p>Examples:</p>

  <ul>
    <li>NaCl → sodium chloride</li>
    <li>MgO → magnesium oxide</li>
    <li>CaCl₂ → calcium chloride</li>
    <li>Al₂O₃ → aluminium oxide</li>
  </ul>

  <h3>Common naming changes</h3>

  <p>Many simple non-metal ions end in <strong>-ide</strong>.</p>

  <ul>
    <li>chlorine → chloride</li>
    <li>oxygen → oxide</li>
    <li>nitrogen → nitride</li>
    <li>sulphur → sulphide</li>
  </ul>

  <h3>Covalent compounds</h3>

  <p>Simple covalent compounds can use prefixes to show the number of atoms present.</p>

  <ul>
    <li>mono- → 1</li>
    <li>di- → 2</li>
    <li>tri- → 3</li>
    <li>tetra- → 4</li>
  </ul>

  <p>Examples:</p>

  <ul>
    <li>CO → carbon monoxide</li>
    <li>CO₂ → carbon dioxide</li>
    <li>N₂O₃ → dinitrogen trioxide</li>
  </ul>`,

  [
    {
      q: "Name NaCl.",
      steps: [
        "Step 1: Na is sodium.",
        "Step 2: Cl forms chloride in the compound name.",
        "Step 3: Name the positive ion first.",
        "Step 4: Therefore, NaCl is sodium chloride."
      ],
      ans: "Sodium chloride.",
      why: "Ionic compounds are named by stating the positive ion followed by the negative ion."
    },
    {
      q: "Name MgO.",
      steps: [
        "Step 1: Mg is magnesium.",
        "Step 2: O forms oxide in the compound name.",
        "Step 3: Combine the names.",
        "Step 4: MgO is magnesium oxide."
      ],
      ans: "Magnesium oxide.",
      why: "The metal is named first and oxygen becomes oxide."
    },
    {
      q: "Name CO₂.",
      steps: [
        "Step 1: C is carbon.",
        "Step 2: There is one carbon atom, so mono- is normally omitted for the first element.",
        "Step 3: There are two oxygen atoms, so use di-.",
        "Step 4: Oxygen becomes oxide.",
        "Step 5: Therefore, CO₂ is carbon dioxide."
      ],
      ans: "Carbon dioxide.",
      why: "The prefix di- indicates two oxygen atoms."
    }
  ],

  [
    {
      q: "Name CaCl₂.",
      hint: "Identify calcium and the chloride ion.",
      steps: [
        "Step 1: Ca is calcium.",
        "Step 2: Cl is named chloride in the compound.",
        "Step 3: Therefore, CaCl₂ is calcium chloride."
      ],
      ans: "Calcium chloride.",
      why: "The compound contains calcium ions and chloride ions."
    }
  ]
);

add(
  "chemistry",
  "chemical_formulae",
  "State Symbols",
  `<h2>State Symbols</h2>

  <p><strong>State symbols</strong> show the physical state of a substance in a chemical equation.</p>

  <h3>The four state symbols</h3>

  <ul>
    <li><strong>(s)</strong> → solid</li>
    <li><strong>(l)</strong> → liquid</li>
    <li><strong>(g)</strong> → gas</li>
    <li><strong>(aq)</strong> → aqueous, meaning dissolved in water</li>
  </ul>

  <h3>Examples</h3>

  <p>NaCl(s) means solid sodium chloride.</p>

  <p>H₂O(l) means liquid water.</p>

  <p>CO₂(g) means gaseous carbon dioxide.</p>

  <p>NaCl(aq) means sodium chloride dissolved in water.</p>

  <h3>Why state symbols matter</h3>

  <p>State symbols provide information about the physical state of reactants and products during a chemical reaction.</p>`,

  [
    {
      q: "What does (s) mean in a chemical equation?",
      steps: [
        "Step 1: Identify the state symbol.",
        "Step 2: The symbol (s) represents a solid."
      ],
      ans: "Solid.",
      why: "(s) indicates that the substance is in the solid state."
    },
    {
      q: "What does (aq) mean in a chemical equation?",
      steps: [
        "Step 1: The letters aq stand for aqueous.",
        "Step 2: Aqueous means the substance is dissolved in water."
      ],
      ans: "Aqueous; the substance is dissolved in water.",
      why: "(aq) tells us that the substance is present as a solution in water."
    },
    {
      q: "State the meaning of each symbol: (s), (l), (g) and (aq).",
      steps: [
        "Step 1: (s) means solid.",
        "Step 2: (l) means liquid.",
        "Step 3: (g) means gas.",
        "Step 4: (aq) means aqueous, or dissolved in water."
      ],
      ans: "(s) = solid; (l) = liquid; (g) = gas; (aq) = aqueous.",
      why: "These four symbols identify the physical state or solution state of substances in chemical equations."
    }
  ],

  [
    {
      q: "What state symbol should be used for carbon dioxide gas?",
      hint: "Carbon dioxide is gaseous under ordinary conditions.",
      steps: [
        "Step 1: Carbon dioxide is a gas.",
        "Step 2: The state symbol for a gas is (g).",
        "Step 3: Therefore, carbon dioxide is written as CO₂(g)."
      ],
      ans: "(g).",
      why: "(g) represents the gaseous state."
    }
  ]
);
