// BATCH 10 — MOLES AND QUANTITATIVE CHEMISTRY
// Chapter: moles_quantitative_chemistry
// One concept per screen
// No multiple-choice questions
// ============================================================

add(
  "chemistry",
  "moles_quantitative_chemistry",
  "Meaning of Mole",
  `<h2>Meaning of Mole</h2>

  <p>A <strong>mole</strong> is a unit used to measure the amount of a substance.</p>

  <p>One mole contains a fixed number of particles:</p>

  <p><strong>1 mole = 6.02 × 10²³ particles</strong></p>

  <p>The particles may be atoms, molecules, ions or other specified particles.</p>

  <h3>Examples</h3>

  <p>1 mole of carbon atoms contains 6.02 × 10²³ carbon atoms.</p>

  <p>1 mole of water molecules contains 6.02 × 10²³ water molecules.</p>

  <p>1 mole of sodium ions contains 6.02 × 10²³ sodium ions.</p>

  <p>The number <strong>6.02 × 10²³</strong> is called the <strong>Avogadro constant</strong>.</p>`,

  [
    {
      q: "What is a mole?",
      steps: [
        "Step 1: A mole is a unit for measuring amount of substance.",
        "Step 2: One mole contains 6.02 × 10²³ specified particles.",
        "Step 3: Therefore, a mole represents a fixed number of particles."
      ],
      ans: "A mole is a unit for measuring amount of substance containing 6.02 × 10²³ specified particles.",
      why: "The mole provides a convenient way of counting extremely large numbers of particles."
    },
    {
      q: "How many particles are present in one mole of a substance?",
      steps: [
        "Step 1: Recall the Avogadro constant.",
        "Step 2: One mole contains 6.02 × 10²³ particles."
      ],
      ans: "6.02 × 10²³ particles.",
      why: "This is the number of particles defined as one mole."
    },
    {
      q: "How many molecules are present in 1 mole of water?",
      steps: [
        "Step 1: One mole always contains 6.02 × 10²³ specified particles.",
        "Step 2: For water, the particles are water molecules.",
        "Step 3: Therefore, 1 mole of water contains 6.02 × 10²³ molecules."
      ],
      ans: "6.02 × 10²³ water molecules.",
      why: "The particles being counted are molecules of water."
    }
  ],

  [
    {
      q: "How many atoms are present in 1 mole of sodium atoms?",
      hint: "One mole contains the Avogadro constant number of particles.",
      steps: [
        "Step 1: The specified particles are sodium atoms.",
        "Step 2: One mole contains 6.02 × 10²³ particles.",
        "Step 3: Therefore, there are 6.02 × 10²³ sodium atoms."
      ],
      ans: "6.02 × 10²³ sodium atoms.",
      why: "One mole of any specified particles contains the Avogadro constant number of particles."
    }
  ]
);

add(
  "chemistry",
  "moles_quantitative_chemistry",
  "Avogadro Constant",
  `<h2>Avogadro Constant</h2>

  <p>The <strong>Avogadro constant</strong> is the number of particles in one mole.</p>

  <p><strong>Nₐ = 6.02 × 10²³ mol⁻¹</strong></p>

  <h3>Particles from moles</h3>

  <p>Use:</p>

  <p><strong>Number of particles = moles × Avogadro constant</strong></p>

  <p>N = nNₐ</p>

  <h3>Moles from particles</h3>

  <p>Rearrange:</p>

  <p><strong>moles = number of particles ÷ Avogadro constant</strong></p>

  <p>n = N ÷ Nₐ</p>`,

  [
    {
      q: "Calculate the number of particles in 2 moles of a substance.",
      steps: [
        "Step 1: Use N = nNₐ.",
        "Step 2: n = 2 mol.",
        "Step 3: Nₐ = 6.02 × 10²³ mol⁻¹.",
        "Step 4: N = 2 × 6.02 × 10²³.",
        "Step 5: N = 12.04 × 10²³.",
        "Step 6: N = 1.204 × 10²⁴ particles."
      ],
      ans: "1.204 × 10²⁴ particles.",
      why: "The number of particles is proportional to the number of moles."
    },
    {
      q: "Calculate the number of particles in 0.5 mol of a substance.",
      steps: [
        "Step 1: Use N = nNₐ.",
        "Step 2: n = 0.5 mol.",
        "Step 3: N = 0.5 × 6.02 × 10²³.",
        "Step 4: N = 3.01 × 10²³ particles."
      ],
      ans: "3.01 × 10²³ particles.",
      why: "Half a mole contains half of the Avogadro constant number of particles."
    },
    {
      q: "Calculate the number of moles in 3.01 × 10²³ particles.",
      steps: [
        "Step 1: Use n = N ÷ Nₐ.",
        "Step 2: N = 3.01 × 10²³.",
        "Step 3: Nₐ = 6.02 × 10²³.",
        "Step 4: n = (3.01 × 10²³) ÷ (6.02 × 10²³).",
        "Step 5: n = 0.5 mol."
      ],
      ans: "0.5 mol.",
      why: "3.01 × 10²³ particles is half of 6.02 × 10²³ particles."
    }
  ],

  [
    {
      q: "How many molecules are present in 0.25 mol of water?",
      hint: "Use N = nNₐ.",
      steps: [
        "Step 1: N = nNₐ.",
        "Step 2: N = 0.25 × 6.02 × 10²³.",
        "Step 3: N = 1.505 × 10²³ molecules."
      ],
      ans: "1.505 × 10²³ molecules.",
      why: "The number of molecules equals the number of moles multiplied by the Avogadro constant."
    }
  ]
);

add(
  "chemistry",
  "moles_quantitative_chemistry",
  "Relative Atomic Mass",
  `<h2>Relative Atomic Mass</h2>

  <p><strong>Relative atomic mass (Aᵣ)</strong> is the average mass of an atom of an element compared with a standard reference.</p>

  <p>The relative atomic masses of elements are used when calculating formula masses and molar masses.</p>

  <h3>Common values</h3>

  <ul>
    <li>H = 1</li>
    <li>C = 12</li>
    <li>N = 14</li>
    <li>O = 16</li>
    <li>Na = 23</li>
    <li>Mg = 24</li>
    <li>Cl = 35.5</li>
    <li>Ca = 40</li>
  </ul>

  <p>These values are dimensionless because they are relative values.</p>`,

  [
    {
      q: "What is meant by relative atomic mass?",
      steps: [
        "Step 1: Atomic masses are compared using a standard reference.",
        "Step 2: The resulting value is called relative atomic mass.",
        "Step 3: It is represented by Aᵣ."
      ],
      ans: "Relative atomic mass is the average mass of an atom of an element compared with a standard reference.",
      why: "Relative atomic mass allows the masses of atoms to be compared."
    },
    {
      q: "State the relative atomic mass of oxygen.",
      steps: [
        "Step 1: Locate oxygen in the periodic table.",
        "Step 2: Its commonly used relative atomic mass is 16."
      ],
      ans: "16.",
      why: "Oxygen has a commonly used relative atomic mass of 16."
    },
    {
      q: "State the relative atomic mass of chlorine used in calculations.",
      steps: [
        "Step 1: Locate chlorine in the periodic table.",
        "Step 2: The commonly used value is 35.5."
      ],
      ans: "35.5.",
      why: "Chlorine has a relative atomic mass of approximately 35.5."
    }
  ],

  [
    {
      q: "What relative atomic mass would you use for sodium in a basic mole calculation?",
      hint: "Use the standard periodic-table value.",
      steps: [
        "Step 1: Locate sodium.",
        "Step 2: Sodium has relative atomic mass 23."
      ],
      ans: "23.",
      why: "The commonly used relative atomic mass of sodium is 23."
    }
  ]
);

add(
  "chemistry",
  "moles_quantitative_chemistry",
  "Relative Formula Mass",
  `<h2>Relative Formula Mass</h2>

  <p><strong>Relative formula mass (Mᵣ)</strong> is the sum of the relative atomic masses of all atoms shown in a chemical formula.</p>

  <h3>Example: H₂O</h3>

  <p>H = 1</p>

  <p>O = 16</p>

  <p>Mᵣ(H₂O) = (2 × 1) + 16</p>

  <p>Mᵣ(H₂O) = 18</p>

  <h3>Example: CO₂</h3>

  <p>Mᵣ(CO₂) = 12 + (2 × 16)</p>

  <p>Mᵣ(CO₂) = 44</p>`,

  [
    {
      q: "Calculate the relative formula mass of H₂O.",
      steps: [
        "Step 1: H has Aᵣ = 1.",
        "Step 2: O has Aᵣ = 16.",
        "Step 3: There are two H atoms.",
        "Step 4: Mᵣ = (2 × 1) + 16.",
        "Step 5: Mᵣ = 18."
      ],
      ans: "18.",
      why: "The formula mass is found by adding the masses of all atoms in the formula."
    },
    {
      q: "Calculate the relative formula mass of CO₂.",
      steps: [
        "Step 1: C has Aᵣ = 12.",
        "Step 2: O has Aᵣ = 16.",
        "Step 3: There are two O atoms.",
        "Step 4: Mᵣ = 12 + (2 × 16).",
        "Step 5: Mᵣ = 44."
      ],
      ans: "44.",
      why: "One carbon atom contributes 12 and two oxygen atoms contribute 32."
    },
    {
      q: "Calculate the relative formula mass of CaCl₂.",
      steps: [
        "Step 1: Ca has Aᵣ = 40.",
        "Step 2: Cl has Aᵣ = 35.5.",
        "Step 3: There are two Cl atoms.",
        "Step 4: Mᵣ = 40 + (2 × 35.5).",
        "Step 5: Mᵣ = 40 + 71.",
        "Step 6: Mᵣ = 111."
      ],
      ans: "111.",
      why: "The formula contains one calcium atom and two chlorine atoms."
    }
  ],

  [
    {
      q: "Calculate the relative formula mass of MgO. Mg = 24 and O = 16.",
      hint: "Add the relative atomic masses of Mg and O.",
      steps: [
        "Step 1: Mg = 24.",
        "Step 2: O = 16.",
        "Step 3: Mᵣ = 24 + 16.",
        "Step 4: Mᵣ = 40."
      ],
      ans: "40.",
      why: "MgO contains one magnesium atom and one oxygen atom."
    }
  ]
);

add(
  "chemistry",
  "moles_quantitative_chemistry",
  "Molar Mass",
  `<h2>Molar Mass</h2>

  <p><strong>Molar mass</strong> is the mass of one mole of a substance.</p>

  <p>It is measured in <strong>g mol⁻¹</strong>.</p>

  <p>The numerical value of molar mass corresponds to the relative atomic mass or relative formula mass.</p>

  <h3>Examples</h3>

  <p>H₂O:</p>

  <p>Mᵣ = 18</p>

  <p>Therefore molar mass = <strong>18 g mol⁻¹</strong>.</p>

  <p>CO₂:</p>

  <p>Mᵣ = 44</p>

  <p>Therefore molar mass = <strong>44 g mol⁻¹</strong>.</p>`,

  [
    {
      q: "What is the molar mass of water, H₂O?",
      steps: [
        "Step 1: Calculate Mᵣ of H₂O.",
        "Step 2: Mᵣ = (2 × 1) + 16 = 18.",
        "Step 3: Therefore, molar mass = 18 g mol⁻¹."
      ],
      ans: "18 g mol⁻¹.",
      why: "One mole of water has a mass of 18 grams."
    },
    {
      q: "What is the molar mass of carbon dioxide, CO₂?",
      steps: [
        "Step 1: Calculate Mᵣ.",
        "Step 2: Mᵣ = 12 + (2 × 16).",
        "Step 3: Mᵣ = 44.",
        "Step 4: Therefore, molar mass = 44 g mol⁻¹."
      ],
      ans: "44 g mol⁻¹.",
      why: "One mole of carbon dioxide has a mass of 44 grams."
    },
    {
      q: "What is the molar mass of calcium carbonate, CaCO₃? Ca = 40, C = 12, O = 16.",
      steps: [
        "Step 1: Ca = 40.",
        "Step 2: C = 12.",
        "Step 3: Three O atoms contribute 3 × 16 = 48.",
        "Step 4: Mᵣ = 40 + 12 + 48.",
        "Step 5: Mᵣ = 100.",
        "Step 6: Molar mass = 100 g mol⁻¹."
      ],
      ans: "100 g mol⁻¹.",
      why: "The formula contains one Ca, one C and three O atoms."
    }
  ],

  [
    {
      q: "What is the unit of molar mass?",
      hint: "Molar mass is mass per mole.",
      steps: [
        "Step 1: Mass is measured in grams.",
        "Step 2: Amount of substance is measured in moles.",
        "Step 3: Therefore, molar mass is measured in grams per mole."
      ],
      ans: "g mol⁻¹.",
      why: "Molar mass expresses the mass of one mole of a substance."
    }
  ]
);

add(
  "chemistry",
  "moles_quantitative_chemistry",
  "Calculating Moles from Mass",
  `<h2>Calculating Moles from Mass</h2>

  <p>The number of moles can be calculated from mass using:</p>

  <p><strong>n = m ÷ M</strong></p>

  <ul>
    <li>n = number of moles</li>
    <li>m = mass in grams</li>
    <li>M = molar mass in g mol⁻¹</li>
  </ul>

  <h3>Example</h3>

  <p>Calculate the number of moles in 36 g of water.</p>

  <p>Molar mass of H₂O = 18 g mol⁻¹.</p>

  <p>n = 36 ÷ 18</p>

  <p>n = 2 mol</p>`,

  [
    {
      q: "Calculate the number of moles in 36 g of water. Molar mass of water = 18 g mol⁻¹.",
      steps: [
        "Step 1: Use n = m ÷ M.",
        "Step 2: m = 36 g.",
        "Step 3: M = 18 g mol⁻¹.",
        "Step 4: n = 36 ÷ 18.",
        "Step 5: n = 2 mol."
      ],
      ans: "2 mol.",
      why: "The mass is divided by the mass of one mole."
    },
    {
      q: "Calculate the number of moles in 44 g of CO₂. Molar mass = 44 g mol⁻¹.",
      steps: [
        "Step 1: n = m ÷ M.",
        "Step 2: n = 44 ÷ 44.",
        "Step 3: n = 1 mol."
      ],
      ans: "1 mol.",
      why: "A mass equal to the molar mass contains exactly one mole."
    },
    {
      q: "Calculate the number of moles in 20 g of calcium carbonate. Molar mass = 100 g mol⁻¹.",
      steps: [
        "Step 1: n = m ÷ M.",
        "Step 2: m = 20 g.",
        "Step 3: M = 100 g mol⁻¹.",
        "Step 4: n = 20 ÷ 100.",
        "Step 5: n = 0.20 mol."
      ],
      ans: "0.20 mol.",
      why: "The sample has one-fifth of the mass of one mole."
    }
  ],

  [
    {
      q: "Calculate the number of moles in 9 g of water. Molar mass = 18 g mol⁻¹.",
      hint: "Use n = m ÷ M.",
      steps: [
        "Step 1: n = 9 ÷ 18.",
        "Step 2: n = 0.5 mol."
      ],
      ans: "0.5 mol.",
      why: "9 g is half the mass of one mole of water."
    }
  ]
);

add(
  "chemistry",
  "moles_quantitative_chemistry",
  "Calculating Mass from Moles",
  `<h2>Calculating Mass from Moles</h2>

  <p>Mass can be calculated from the number of moles using:</p>

  <p><strong>m = n × M</strong></p>

  <ul>
    <li>m = mass in grams</li>
    <li>n = number of moles</li>
    <li>M = molar mass in g mol⁻¹</li>
  </ul>

  <h3>Example</h3>

  <p>Find the mass of 3 mol of water.</p>

  <p>M = 18 g mol⁻¹.</p>

  <p>m = 3 × 18</p>

  <p>m = 54 g</p>`,

  [
    {
      q: "Calculate the mass of 3 mol of water. Molar mass = 18 g mol⁻¹.",
      steps: [
        "Step 1: Use m = n × M.",
        "Step 2: n = 3 mol.",
        "Step 3: M = 18 g mol⁻¹.",
        "Step 4: m = 3 × 18.",
        "Step 5: m = 54 g."
      ],
      ans: "54 g.",
      why: "Three moles have three times the mass of one mole."
    },
    {
      q: "Calculate the mass of 0.5 mol of CO₂. Molar mass = 44 g mol⁻¹.",
      steps: [
        "Step 1: m = n × M.",
        "Step 2: m = 0.5 × 44.",
        "Step 3: m = 22 g."
      ],
      ans: "22 g.",
      why: "Half a mole has half the mass of one mole."
    },
    {
      q: "Calculate the mass of 2.5 mol of NaCl. Molar mass = 58.5 g mol⁻¹.",
      steps: [
        "Step 1: m = n × M.",
        "Step 2: n = 2.5 mol.",
        "Step 3: M = 58.5 g mol⁻¹.",
        "Step 4: m = 2.5 × 58.5.",
        "Step 5: m = 146.25 g."
      ],
      ans: "146.25 g.",
      why: "Mass equals amount in moles multiplied by molar mass."
    }
  ],

  [
    {
      q: "What is the mass of 0.25 mol of water? Molar mass = 18 g mol⁻¹.",
      hint: "Use m = n × M.",
      steps: [
        "Step 1: m = 0.25 × 18.",
        "Step 2: m = 4.5 g."
      ],
      ans: "4.5 g.",
      why: "A quarter of a mole has a quarter of the mass of one mole."
    }
  ]
);

add(
  "chemistry",
  "moles_quantitative_chemistry",
  "Moles and Particles",
  `<h2>Moles and Particles</h2>

  <p>Moles and number of particles are directly related through the Avogadro constant.</p>

  <p><strong>N = nNₐ</strong></p>

  <p>Therefore:</p>

  <p><strong>particles = moles × 6.02 × 10²³</strong></p>

  <p>And:</p>

  <p><strong>moles = particles ÷ 6.02 × 10²³</strong></p>

  <h3>Important</h3>

  <p>Always identify what type of particle is being counted: atoms, molecules or ions.</p>`,

  [
    {
      q: "How many molecules are present in 2 mol of CO₂?",
      steps: [
        "Step 1: Use N = nNₐ.",
        "Step 2: n = 2 mol.",
        "Step 3: N = 2 × 6.02 × 10²³.",
        "Step 4: N = 1.204 × 10²⁴ molecules."
      ],
      ans: "1.204 × 10²⁴ molecules.",
      why: "Each mole contains 6.02 × 10²³ molecules."
    },
    {
      q: "How many atoms are present in 0.1 mol of carbon atoms?",
      steps: [
        "Step 1: N = nNₐ.",
        "Step 2: N = 0.1 × 6.02 × 10²³.",
        "Step 3: N = 6.02 × 10²² atoms."
      ],
      ans: "6.02 × 10²² atoms.",
      why: "0.1 mole contains one-tenth of the Avogadro constant number of atoms."
    },
    {
      q: "How many moles are represented by 1.204 × 10²⁴ molecules?",
      steps: [
        "Step 1: Use n = N ÷ Nₐ.",
        "Step 2: n = (1.204 × 10²⁴) ÷ (6.02 × 10²³).",
        "Step 3: n = 2 mol."
      ],
      ans: "2 mol.",
      why: "1.204 × 10²⁴ is twice the Avogadro constant."
    }
  ],

  [
    {
      q: "How many molecules are present in 0.5 mol of oxygen molecules?",
      hint: "Multiply 0.5 by the Avogadro constant.",
      steps: [
        "Step 1: N = nNₐ.",
        "Step 2: N = 0.5 × 6.02 × 10²³.",
        "Step 3: N = 3.01 × 10²³ molecules."
      ],
      ans: "3.01 × 10²³ molecules.",
      why: "Half a mole contains half the Avogadro constant number of molecules."
    }
  ]
);

add(
  "chemistry",
  "moles_quantitative_chemistry",
  "Mole Ratios",
  `<h2>Mole Ratios</h2>

  <p>A balanced chemical equation gives the ratio in which substances react and are produced.</p>

  <h3>Example</h3>

  <p>2H₂ + O₂ → 2H₂O</p>

  <p>The coefficients give the mole ratio:</p>

  <p><strong>2 mol H₂ : 1 mol O₂ : 2 mol H₂O</strong></p>

  <h3>Using the ratio</h3>

  <p>If 2 mol of H₂ react, 1 mol of O₂ is required and 2 mol of H₂O are produced.</p>`,

  [
    {
      q: "What is the mole ratio of H₂ : O₂ : H₂O in 2H₂ + O₂ → 2H₂O?",
      steps: [
        "Step 1: Read the coefficient of H₂: 2.",
        "Step 2: Read the coefficient of O₂: 1.",
        "Step 3: Read the coefficient of H₂O: 2.",
        "Step 4: Therefore, the ratio is 2 : 1 : 2."
      ],
      ans: "2 : 1 : 2.",
      why: "The coefficients in a balanced equation represent the mole ratio."
    },
    {
      q: "How many moles of oxygen react with 4 mol of hydrogen in 2H₂ + O₂ → 2H₂O?",
      steps: [
        "Step 1: The equation gives H₂ : O₂ = 2 : 1.",
        "Step 2: 2 mol H₂ require 1 mol O₂.",
        "Step 3: 4 mol H₂ is twice 2 mol.",
        "Step 4: Therefore, oxygen required = 2 mol."
      ],
      ans: "2 mol O₂.",
      why: "The balanced equation requires half as many moles of O₂ as H₂."
    },
    {
      q: "How many moles of water are produced when 3 mol of O₂ react completely in 2H₂ + O₂ → 2H₂O?",
      steps: [
        "Step 1: The ratio O₂ : H₂O is 1 : 2.",
        "Step 2: 1 mol O₂ produces 2 mol H₂O.",
        "Step 3: 3 mol O₂ produces 3 × 2 mol H₂O.",
        "Step 4: Water produced = 6 mol."
      ],
      ans: "6 mol H₂O.",
      why: "The balanced equation shows that twice as many moles of water are produced as oxygen consumed."
    }
  ],

  [
    {
      q: "In N₂ + 3H₂ → 2NH₃, how many moles of NH₃ are produced from 2 mol of N₂?",
      hint: "Use the ratio N₂ : NH₃ = 1 : 2.",
      steps: [
        "Step 1: The equation gives 1 mol N₂ → 2 mol NH₃.",
        "Step 2: 2 mol N₂ → 2 × 2 mol NH₃.",
        "Step 3: NH₃ produced = 4 mol."
      ],
      ans: "4 mol NH₃.",
      why: "The mole ratio of nitrogen to ammonia is 1:2."
    }
  ]
);

add(
  "chemistry",
  "moles_quantitative_chemistry",
  "Calculating Reactant Amount",
  `<h2>Calculating Reactant Amount</h2>

  <p>A balanced equation can be used to calculate the amount of one reactant required when the amount of another reactant is known.</p>

  <h3>Example</h3>

  <p>2H₂ + O₂ → 2H₂O</p>

  <p>Suppose 6 mol H₂ are available.</p>

  <p>Ratio H₂ : O₂ = 2 : 1.</p>

  <p>Therefore:</p>

  <p>6 mol H₂ require 3 mol O₂.</p>

  <h3>Method</h3>

  <ol>
    <li>Write the balanced equation.</li>
    <li>Identify the two coefficients.</li>
    <li>Set up the mole ratio.</li>
    <li>Calculate the unknown amount.</li>
  </ol>`,

  [
    {
      q: "How many moles of O₂ are required to react with 6 mol H₂ in 2H₂ + O₂ → 2H₂O?",
      steps: [
        "Step 1: H₂ : O₂ = 2 : 1.",
        "Step 2: 2 mol H₂ require 1 mol O₂.",
        "Step 3: 6 mol H₂ is three times 2 mol.",
        "Step 4: O₂ required = 3 × 1.",
        "Step 5: O₂ required = 3 mol."
      ],
      ans: "3 mol O₂.",
      why: "The balanced equation requires one mole of oxygen for every two moles of hydrogen."
    },
    {
      q: "How many moles of H₂ are required to react with 5 mol N₂ in N₂ + 3H₂ → 2NH₃?",
      steps: [
        "Step 1: N₂ : H₂ = 1 : 3.",
        "Step 2: 1 mol N₂ requires 3 mol H₂.",
        "Step 3: 5 mol N₂ requires 5 × 3 mol H₂.",
        "Step 4: H₂ required = 15 mol."
      ],
      ans: "15 mol H₂.",
      why: "The balanced equation gives a 1:3 mole ratio between N₂ and H₂."
    },
    {
      q: "How many moles of oxygen are required to burn 4 mol CH₄ completely? CH₄ + 2O₂ → CO₂ + 2H₂O.",
      steps: [
        "Step 1: CH₄ : O₂ = 1 : 2.",
        "Step 2: 1 mol CH₄ requires 2 mol O₂.",
        "Step 3: 4 mol CH₄ requires 4 × 2 mol O₂.",
        "Step 4: O₂ required = 8 mol."
      ],
      ans: "8 mol O₂.",
      why: "Complete combustion of methane requires two moles of oxygen for every mole of methane."
    }
  ],

  [
    {
      q: "How many moles of oxygen are required to react with 2 mol of magnesium? 2Mg + O₂ → 2MgO.",
      hint: "Use the ratio Mg : O₂ = 2 : 1.",
      steps: [
        "Step 1: 2 mol Mg require 1 mol O₂.",
        "Step 2: The given amount is exactly 2 mol Mg.",
        "Step 3: Therefore, O₂ required = 1 mol."
      ],
      ans: "1 mol O₂.",
      why: "The balanced equation gives a 2:1 mole ratio."
    }
  ]
);

add(
  "chemistry",
  "moles_quantitative_chemistry",
  "Calculating Product Amount",
  `<h2>Calculating Product Amount</h2>

  <p>The coefficients in a balanced equation can be used to calculate the amount of product formed.</p>

  <h3>Example</h3>

  <p>N₂ + 3H₂ → 2NH₃</p>

  <p>The ratio is:</p>

  <p>1 mol N₂ → 2 mol NH₃</p>

  <p>Therefore, 4 mol N₂ produce:</p>

  <p>4 × 2 = 8 mol NH₃</p>`,

  [
    {
      q: "How many moles of NH₃ are produced from 4 mol N₂ in N₂ + 3H₂ → 2NH₃?",
      steps: [
        "Step 1: N₂ : NH₃ = 1 : 2.",
        "Step 2: 1 mol N₂ produces 2 mol NH₃.",
        "Step 3: 4 mol N₂ produces 4 × 2 mol NH₃.",
        "Step 4: NH₃ = 8 mol."
      ],
      ans: "8 mol NH₃.",
      why: "The balanced equation shows that two moles of ammonia are produced per mole of nitrogen."
    },
    {
      q: "How many moles of CO₂ are produced from 3 mol CH₄? CH₄ + 2O₂ → CO₂ + 2H₂O.",
      steps: [
        "Step 1: CH₄ : CO₂ = 1 : 1.",
        "Step 2: 1 mol CH₄ produces 1 mol CO₂.",
        "Step 3: 3 mol CH₄ produces 3 mol CO₂."
      ],
      ans: "3 mol CO₂.",
      why: "Methane and carbon dioxide have a 1:1 mole ratio in the balanced equation."
    },
    {
      q: "How many moles of H₂O are produced from 5 mol O₂ in 2H₂ + O₂ → 2H₂O?",
      steps: [
        "Step 1: O₂ : H₂O = 1 : 2.",
        "Step 2: 1 mol O₂ produces 2 mol H₂O.",
        "Step 3: 5 mol O₂ produces 5 × 2 mol H₂O.",
        "Step 4: H₂O = 10 mol."
      ],
      ans: "10 mol H₂O.",
      why: "The balanced equation gives a 1:2 ratio between oxygen and water."
    }
  ],

  [
    {
      q: "How many moles of MgO are formed from 3 mol Mg? 2Mg + O₂ → 2MgO.",
      hint: "Compare the coefficients of Mg and MgO.",
      steps: [
        "Step 1: Mg : MgO = 2 : 2.",
        "Step 2: This simplifies to 1 : 1.",
        "Step 3: Therefore, 3 mol Mg produce 3 mol MgO."
      ],
      ans: "3 mol MgO.",
      why: "The balanced equation gives a 1:1 mole ratio between Mg and MgO."
    }
  ]
);

add(
  "chemistry",
  "moles_quantitative_chemistry",
  "Empirical Formula",
  `<h2>Empirical Formula</h2>

  <p>The <strong>empirical formula</strong> shows the simplest whole-number ratio of atoms in a compound.</p>

  <h3>Method from masses</h3>

  <ol>
    <li>Write the mass of each element.</li>
    <li>Divide each mass by its relative atomic mass.</li>
    <li>Obtain the mole values.</li>
    <li>Divide all mole values by the smallest value.</li>
    <li>Convert the resulting ratio to the smallest whole numbers.</li>
    <li>Write the empirical formula.</li>
  </ol>

  <h3>Example</h3>

  <p>A compound contains 12 g carbon and 16 g oxygen.</p>

  <p>C: 12 ÷ 12 = 1 mol</p>

  <p>O: 16 ÷ 16 = 1 mol</p>

  <p>Ratio = 1 : 1</p>

  <p>Empirical formula = <strong>CO</strong></p>`,

  [
    {
      q: "Find the empirical formula of a compound containing 12 g of carbon and 16 g of oxygen. C = 12, O = 16.",
      steps: [
        "Step 1: Calculate moles of C: 12 ÷ 12 = 1 mol.",
        "Step 2: Calculate moles of O: 16 ÷ 16 = 1 mol.",
        "Step 3: Divide by the smallest value, 1.",
        "Step 4: C : O = 1 : 1.",
        "Step 5: Therefore, the empirical formula is CO."
      ],
      ans: "CO.",
      why: "The simplest mole ratio of carbon to oxygen is 1:1."
    },
    {
      q: "Find the empirical formula of a compound containing 24 g carbon and 8 g hydrogen. C = 12, H = 1.",
      steps: [
        "Step 1: Moles of C = 24 ÷ 12 = 2 mol.",
        "Step 2: Moles of H = 8 ÷ 1 = 8 mol.",
        "Step 3: Divide by the smallest value, 2.",
        "Step 4: C = 2 ÷ 2 = 1.",
        "Step 5: H = 8 ÷ 2 = 4.",
        "Step 6: Ratio = 1 : 4.",
        "Step 7: Empirical formula = CH₄."
      ],
      ans: "CH₄.",
      why: "The simplest whole-number ratio of C:H is 1:4."
    },
    {
      q: "A compound contains 14 g nitrogen and 16 g oxygen. Find its empirical formula. N = 14, O = 16.",
      steps: [
        "Step 1: Moles of N = 14 ÷ 14 = 1 mol.",
        "Step 2: Moles of O = 16 ÷ 16 = 1 mol.",
        "Step 3: Divide by the smallest value, 1.",
        "Step 4: Ratio N:O = 1:1.",
        "Step 5: Empirical formula = NO."
      ],
      ans: "NO.",
      why: "The simplest mole ratio is one nitrogen atom to one oxygen atom."
    }
  ],

  [
    {
      q: "A compound contains 4 g hydrogen and 32 g oxygen. Find its empirical formula.",
      hint: "First convert each mass into moles.",
      steps: [
        "Step 1: H moles = 4 ÷ 1 = 4 mol.",
        "Step 2: O moles = 32 ÷ 16 = 2 mol.",
        "Step 3: Divide both by the smallest value, 2.",
        "Step 4: H = 4 ÷ 2 = 2.",
        "Step 5: O = 2 ÷ 2 = 1.",
        "Step 6: Empirical formula = H₂O."
      ],
      ans: "H₂O.",
      why: "The simplest whole-number ratio of H:O is 2:1."
    }
  ]
);

add(
  "chemistry",
  "moles_quantitative_chemistry",
  "Molecular Formula",
  `<h2>Molecular Formula</h2>

  <p>The <strong>molecular formula</strong> shows the actual number of atoms of each element in one molecule.</p>

  <p>The molecular formula is a whole-number multiple of the empirical formula.</p>

  <h3>Method</h3>

  <ol>
    <li>Find the empirical formula.</li>
    <li>Calculate its empirical formula mass.</li>
    <li>Use:</li>
  </ol>

  <p><strong>Multiplier = molecular mass ÷ empirical formula mass</strong></p>

  <p>Multiply every subscript in the empirical formula by the multiplier.</p>

  <h3>Example</h3>

  <p>Empirical formula = CH₂.</p>

  <p>Empirical formula mass = 12 + 2 = 14.</p>

  <p>Molecular mass = 28.</p>

  <p>Multiplier = 28 ÷ 14 = 2.</p>

  <p>Molecular formula = C₂H₄.</p>`,

  [
    {
      q: "The empirical formula of a compound is CH₂ and its molecular mass is 28. Find the molecular formula. C = 12, H = 1.",
      steps: [
        "Step 1: Empirical formula mass = 12 + (2 × 1) = 14.",
        "Step 2: Multiplier = molecular mass ÷ empirical formula mass.",
        "Step 3: Multiplier = 28 ÷ 14 = 2.",
        "Step 4: Multiply the subscripts in CH₂ by 2.",
        "Step 5: Molecular formula = C₂H₄."
      ],
      ans: "C₂H₄.",
      why: "The molecular formula is twice the empirical formula."
    },
    {
      q: "The empirical formula is NO₂ and the molecular mass is 92. Find the molecular formula. N = 14, O = 16.",
      steps: [
        "Step 1: Empirical formula mass = 14 + (2 × 16) = 46.",
        "Step 2: Multiplier = 92 ÷ 46 = 2.",
        "Step 3: Multiply N₁O₂ by 2.",
        "Step 4: Molecular formula = N₂O₄."
      ],
      ans: "N₂O₄.",
      why: "The molecular mass is twice the empirical formula mass."
    },
    {
      q: "The empirical formula is CH and the molecular mass is 78. Find the molecular formula. C = 12, H = 1.",
      steps: [
        "Step 1: Empirical formula mass = 12 + 1 = 13.",
        "Step 2: Multiplier = 78 ÷ 13.",
        "Step 3: Multiplier = 6.",
        "Step 4: Multiply CH by 6.",
        "Step 5: Molecular formula = C₆H₆."
      ],
      ans: "C₆H₆.",
      why: "Six empirical formula units make one molecule with molecular mass 78."
    }
  ],

  [
    {
      q: "The empirical formula is H₂O and the molecular mass is 18. What is the molecular formula?",
      hint: "Compare the molecular mass with the empirical formula mass.",
      steps: [
        "Step 1: Empirical formula mass = 18.",
        "Step 2: Multiplier = 18 ÷ 18 = 1.",
        "Step 3: Multiply H₂O by 1.",
        "Step 4: Molecular formula = H₂O."
      ],
      ans: "H₂O.",
      why: "The molecular formula is already in its simplest ratio."
    }
  ]
);

add(
  "chemistry",
  "moles_quantitative_chemistry",
  "Percentage Composition",
  `<h2>Percentage Composition</h2>

  <p><strong>Percentage composition</strong> gives the percentage by mass of each element in a compound.</p>

  <p>Use:</p>

  <p><strong>% of element = (mass of element in one mole of compound ÷ molar mass of compound) × 100</strong></p>

  <h3>Example: Water</h3>

  <p>H₂O has molar mass 18.</p>

  <p>Mass of hydrogen = 2.</p>

  <p>%H = (2 ÷ 18) × 100</p>

  <p>%H = 11.1%</p>

  <p>Mass of oxygen = 16.</p>

  <p>%O = (16 ÷ 18) × 100</p>

  <p>%O = 88.9%</p>`,

  [
    {
      q: "Calculate the percentage of hydrogen in H₂O. H = 1, O = 16.",
      steps: [
        "Step 1: Molar mass of H₂O = (2 × 1) + 16 = 18.",
        "Step 2: Mass of hydrogen = 2.",
        "Step 3: %H = (2 ÷ 18) × 100.",
        "Step 4: %H = 11.1% approximately."
      ],
      ans: "11.1% approximately.",
      why: "Hydrogen contributes 2 g to every 18 g of water."
    },
    {
      q: "Calculate the percentage of oxygen in H₂O. H = 1, O = 16.",
      steps: [
        "Step 1: Molar mass = 18.",
        "Step 2: Mass of oxygen = 16.",
        "Step 3: %O = (16 ÷ 18) × 100.",
        "Step 4: %O = 88.9% approximately."
      ],
      ans: "88.9% approximately.",
      why: "Oxygen contributes 16 g to every 18 g of water."
    },
    {
      q: "Calculate the percentage of carbon in CO₂. C = 12, O = 16.",
      steps: [
        "Step 1: Molar mass of CO₂ = 12 + (2 × 16) = 44.",
        "Step 2: Mass of carbon = 12.",
        "Step 3: %C = (12 ÷ 44) × 100.",
        "Step 4: %C = 27.3% approximately."
      ],
      ans: "27.3% approximately.",
      why: "Carbon contributes 12 g to every 44 g of carbon dioxide."
    }
  ],

  [
    {
      q: "Calculate the percentage of oxygen in CO₂.",
      hint: "There are two oxygen atoms, each with relative atomic mass 16.",
      steps: [
        "Step 1: Molar mass of CO₂ = 44.",
        "Step 2: Oxygen mass = 2 × 16 = 32.",
        "Step 3: %O = (32 ÷ 44) × 100.",
        "Step 4: %O = 72.7% approximately."
      ],
      ans: "72.7% approximately.",
      why: "Oxygen contributes 32 g of the total 44 g molar mass."
    }
  ]
);

add(
  "chemistry",
  "moles_quantitative_chemistry",
  "Limiting Reactant",
  `<h2>Limiting Reactant</h2>

  <p>The <strong>limiting reactant</strong> is the reactant that is completely used up first in a chemical reaction.</p>

  <p>It determines the maximum amount of product that can be formed.</p>

  <h3>Example</h3>

  <p>2H₂ + O₂ → 2H₂O</p>

  <p>Suppose there are:</p>

  <ul>
    <li>3 mol H₂</li>
    <li>2 mol O₂</li>
  </ul>

  <p>The equation requires 2 mol H₂ for every 1 mol O₂.</p>

  <p>3 mol H₂ requires only 1.5 mol O₂.</p>

  <p>Since 2 mol O₂ are available, hydrogen runs out first.</p>

  <p>Therefore, <strong>H₂ is the limiting reactant</strong>.</p>`,

  [
    {
      q: "What is a limiting reactant?",
      steps: [
        "Step 1: Reactants combine in a fixed mole ratio.",
        "Step 2: One reactant may be completely consumed before another.",
        "Step 3: The reactant consumed first limits the amount of product formed."
      ],
      ans: "The limiting reactant is the reactant that is completely used up first and limits the amount of product formed.",
      why: "Once the limiting reactant is exhausted, the reaction cannot continue."
    },
    {
      q: "In 2H₂ + O₂ → 2H₂O, 3 mol H₂ are mixed with 2 mol O₂. Which reactant is limiting?",
      steps: [
        "Step 1: The equation requires 2 mol H₂ for every 1 mol O₂.",
        "Step 2: 3 mol H₂ require 3 ÷ 2 = 1.5 mol O₂.",
        "Step 3: 2 mol O₂ are available.",
        "Step 4: Oxygen is therefore in excess.",
        "Step 5: Hydrogen is completely used first.",
        "Step 6: H₂ is the limiting reactant."
      ],
      ans: "H₂.",
      why: "The available hydrogen is insufficient to react with all the available oxygen."
    },
    {
      q: "In N₂ + 3H₂ → 2NH₃, 2 mol N₂ are mixed with 5 mol H₂. Which reactant is limiting?",
      steps: [
        "Step 1: 1 mol N₂ requires 3 mol H₂.",
        "Step 2: 2 mol N₂ require 2 × 3 = 6 mol H₂.",
        "Step 3: Only 5 mol H₂ are available.",
        "Step 4: Hydrogen is therefore used up first.",
        "Step 5: H₂ is the limiting reactant."
      ],
      ans: "H₂.",
      why: "Six moles of hydrogen would be required to react completely with 2 moles of nitrogen, but only five are available."
    }
  ],

  [
    {
      q: "In 2Mg + O₂ → 2MgO, 4 mol Mg are mixed with 3 mol O₂. Which reactant is limiting?",
      hint: "Determine how much oxygen is required for 4 mol Mg.",
      steps: [
        "Step 1: 2 mol Mg require 1 mol O₂.",
        "Step 2: 4 mol Mg require 2 mol O₂.",
        "Step 3: 3 mol O₂ are available.",
        "Step 4: Oxygen is in excess.",
        "Step 5: Mg is used up first."
      ],
      ans: "Mg.",
      why: "The available oxygen is more than enough to react with all the magnesium."
    }
  ]
);

add(
  "chemistry",
  "moles_quantitative_chemistry",
  "Gas Volumes at Room Conditions",
  `<h2>Gas Volumes at Room Conditions</h2>

  <p>At room temperature and pressure, one mole of a gas occupies approximately <strong>24 dm³</strong>.</p>

  <p>Therefore:</p>

  <p><strong>Volume = moles × 24 dm³</strong></p>

  <p>And:</p>

  <p><strong>Moles = volume ÷ 24 dm³</strong></p>

  <h3>Unit conversion</h3>

  <p>1 dm³ = 1000 cm³.</p>

  <p>Therefore:</p>

  <p><strong>24 dm³ = 24,000 cm³</strong></p>`,

  [
    {
      q: "Calculate the volume occupied by 2 mol of a gas at room temperature and pressure.",
      steps: [
        "Step 1: Use V = n × 24.",
        "Step 2: n = 2 mol.",
        "Step 3: V = 2 × 24.",
        "Step 4: V = 48 dm³."
      ],
      ans: "48 dm³.",
      why: "One mole occupies approximately 24 dm³ at room temperature and pressure."
    },
    {
      q: "Calculate the volume occupied by 0.5 mol of a gas at room temperature and pressure.",
      steps: [
        "Step 1: V = n × 24.",
        "Step 2: V = 0.5 × 24.",
        "Step 3: V = 12 dm³."
      ],
      ans: "12 dm³.",
      why: "Half a mole occupies half the volume of one mole."
    },
    {
      q: "Calculate the number of moles in 72 dm³ of a gas at room temperature and pressure.",
      steps: [
        "Step 1: Use n = V ÷ 24.",
        "Step 2: n = 72 ÷ 24.",
        "Step 3: n = 3 mol."
      ],
      ans: "3 mol.",
      why: "72 dm³ contains three times the volume occupied by one mole."
    }
  ],

  [
    {
      q: "Convert 12 dm³ into cm³.",
      hint: "1 dm³ = 1000 cm³.",
      steps: [
        "Step 1: 1 dm³ = 1000 cm³.",
        "Step 2: 12 dm³ = 12 × 1000 cm³.",
        "Step 3: 12 dm³ = 12,000 cm³."
      ],
      ans: "12,000 cm³.",
      why: "Each cubic decimetre contains 1000 cubic centimetres."
    }
  ]
);

add(
  "chemistry",
  "moles_quantitative_chemistry",
  "Gas Volume Calculations",
  `<h2>Gas Volume Calculations</h2>

  <p>The volume of a gas can be connected to a chemical equation using mole ratios.</p>

  <p>At the same temperature and pressure, gas volumes react in the same ratios as their mole coefficients.</p>

  <h3>Example</h3>

  <p>N₂ + 3H₂ → 2NH₃</p>

  <p>The volume ratio is:</p>

  <p><strong>N₂ : H₂ : NH₃ = 1 : 3 : 2</strong></p>

  <p>If 10 dm³ of nitrogen reacts completely:</p>

  <p>Hydrogen required = 10 × 3 = 30 dm³.</p>

  <p>Ammonia produced = 10 × 2 = 20 dm³.</p>`,

  [
    {
      q: "In N₂ + 3H₂ → 2NH₃, what volume of H₂ reacts with 10 dm³ of N₂ under the same conditions?",
      steps: [
        "Step 1: N₂ : H₂ = 1 : 3.",
        "Step 2: 1 volume of N₂ requires 3 volumes of H₂.",
        "Step 3: 10 dm³ N₂ requires 10 × 3 dm³ H₂.",
        "Step 4: H₂ required = 30 dm³."
      ],
      ans: "30 dm³ H₂.",
      why: "Gas volumes at the same temperature and pressure follow the coefficients of the balanced equation."
    },
    {
      q: "In N₂ + 3H₂ → 2NH₃, what volume of NH₃ is produced from 10 dm³ of N₂ under the same conditions?",
      steps: [
        "Step 1: N₂ : NH₃ = 1 : 2.",
        "Step 2: 1 volume N₂ produces 2 volumes NH₃.",
        "Step 3: 10 dm³ N₂ produces 10 × 2 dm³ NH₃.",
        "Step 4: NH₃ produced = 20 dm³."
      ],
      ans: "20 dm³ NH₃.",
      why: "The equation gives a 1:2 volume ratio between nitrogen and ammonia."
    },
    {
      q: "In 2H₂ + O₂ → 2H₂O(g), what volume of oxygen reacts with 40 dm³ hydrogen under the same conditions?",
      steps: [
        "Step 1: H₂ : O₂ = 2 : 1.",
        "Step 2: 2 volumes H₂ require 1 volume O₂.",
        "Step 3: 40 dm³ H₂ requires 40 ÷ 2 dm³ O₂.",
        "Step 4: O₂ required = 20 dm³."
      ],
      ans: "20 dm³ O₂.",
      why: "The gas-volume ratio follows the balanced equation coefficients."
    }
  ],

  [
    {
      q: "In CH₄ + 2O₂ → CO₂ + 2H₂O(g), what volume of oxygen is required to burn 5 dm³ of methane completely?",
      hint: "The ratio CH₄ : O₂ is 1 : 2.",
      steps: [
        "Step 1: 1 volume CH₄ requires 2 volumes O₂.",
        "Step 2: 5 dm³ CH₄ requires 5 × 2 dm³ O₂.",
        "Step 3: O₂ required = 10 dm³."
      ],
      ans: "10 dm³ O₂.",
      why: "The balanced equation gives a 1:2 gas-volume ratio."
    }
  ]
);

add(
  "chemistry",
  "moles_quantitative_chemistry",
  "Percentage Yield",
  `<h2>Percentage Yield</h2>

  <p>The <strong>theoretical yield</strong> is the maximum amount of product that should be produced according to calculation.</p>

  <p>The <strong>actual yield</strong> is the amount of product obtained experimentally.</p>

  <p>Percentage yield is calculated using:</p>

  <p><strong>% yield = (actual yield ÷ theoretical yield) × 100</strong></p>

  <h3>Example</h3>

  <p>The theoretical yield is 10 g and the actual yield is 8 g.</p>

  <p>% yield = (8 ÷ 10) × 100</p>

  <p>% yield = 80%</p>

  <p>The actual yield is usually lower than the theoretical yield because reactions may not go to completion and some product may be lost.</p>`,

  [
    {
      q: "Calculate the percentage yield when the theoretical yield is 10 g and the actual yield is 8 g.",
      steps: [
        "Step 1: Use % yield = (actual ÷ theoretical) × 100.",
        "Step 2: % yield = (8 ÷ 10) × 100.",
        "Step 3: % yield = 80%."
      ],
      ans: "80%.",
      why: "The actual yield is 80% of the theoretical maximum."
    },
    {
      q: "A reaction has a theoretical yield of 25 g and an actual yield of 20 g. Calculate the percentage yield.",
      steps: [
        "Step 1: % yield = (actual ÷ theoretical) × 100.",
        "Step 2: % yield = (20 ÷ 25) × 100.",
        "Step 3: % yield = 0.8 × 100.",
        "Step 4: % yield = 80%."
      ],
      ans: "80%.",
      why: "The actual yield is four-fifths of the theoretical yield."
    },
    {
      q: "A reaction has a theoretical yield of 50 g and an actual yield of 35 g. Calculate the percentage yield.",
      steps: [
        "Step 1: % yield = (35 ÷ 50) × 100.",
        "Step 2: 35 ÷ 50 = 0.70.",
        "Step 3: 0.70 × 100 = 70%."
      ],
      ans: "70%.",
      why: "The actual yield is 70% of the calculated theoretical yield."
    }
  ],

  [
    {
      q: "The theoretical yield of a reaction is 40 g and the percentage yield is 75%. Calculate the actual yield.",
      hint: "Rearrange % yield = (actual ÷ theoretical) × 100.",
      steps: [
        "Step 1: 75 = (actual ÷ 40) × 100.",
        "Step 2: 75 ÷ 100 = actual ÷ 40.",
        "Step 3: 0.75 = actual ÷ 40.",
        "Step 4: actual = 0.75 × 40.",
        "Step 5: actual = 30 g."
      ],
      ans: "30 g.",
      why: "A 75% yield means the actual product is 75% of the theoretical amount."
    }
  ]
);
// ============================================================
// BATCH 11 — CHEMICAL REACTIONS
// Chapter: chemical_reactions
// One concept per screen
// No multiple-choice questions
// ============================================================


// ============================================================
// 1. CHEMICAL REACTIONS
// ============================================================

add(
  "chemistry",
  "chemical_reactions",
  "Chemical Reactions",
  `<h2>Chemical Reactions</h2>
  <p>A chemical reaction is a process in which one or more substances change to form new substances with different properties.</p>

  <h3>Reactants and products</h3>
  <p>The substances present before a chemical reaction are called <strong>reactants</strong>.</p>
  <p>The new substances formed are called <strong>products</strong>.</p>

  <p>For example:</p>
  <p><strong>Magnesium + Oxygen → Magnesium oxide</strong></p>
  <p>Magnesium and oxygen are the reactants. Magnesium oxide is the product.</p>

  <h3>What happens during a reaction?</h3>
  <p>Atoms are rearranged. The atoms themselves are not destroyed or created.</p>`,
  [
    {
      q: "What is a chemical reaction?",
      steps: [
        "Step 1: A chemical reaction involves substances changing.",
        "Step 2: New substances are formed.",
        "Step 3: The new substances have different properties from the original substances."
      ],
      ans: "A chemical reaction is a process in which substances change to form new substances with different properties.",
      why: "The formation of new substances distinguishes a chemical reaction from a physical change."
    },
    {
      q: "Identify the reactants and product in: magnesium + oxygen → magnesium oxide.",
      steps: [
        "Step 1: Look at the substances before the arrow.",
        "Step 2: Magnesium and oxygen are before the arrow, so they are the reactants.",
        "Step 3: Magnesium oxide is after the arrow, so it is the product."
      ],
      ans: "Reactants: magnesium and oxygen. Product: magnesium oxide.",
      why: "Reactants are changed during the reaction, while products are formed."
    },
    {
      q: "What happens to atoms during a chemical reaction?",
      steps: [
        "Step 1: Atoms in the reactants are present before the reaction.",
        "Step 2: The atoms become rearranged into new combinations.",
        "Step 3: The atoms are therefore conserved."
      ],
      ans: "Atoms are rearranged into new combinations; they are not created or destroyed.",
      why: "Chemical reactions involve rearrangement of atoms."
    }
  ],
  [
    {
      q: "A student reacts iron with sulphur to form iron(II) sulphide. Identify the reactants and product.",
      hint: "Reactants are the substances present before the arrow.",
      steps: [
        "Step 1: Iron and sulphur are used at the beginning.",
        "Step 2: Therefore they are the reactants.",
        "Step 3: Iron(II) sulphide is formed."
      ],
      ans: "Reactants: iron and sulphur. Product: iron(II) sulphide.",
      why: "The starting substances are reactants and the newly formed substance is the product."
    }
  ]
);


// ============================================================
// 2. REACTANTS
// ============================================================

add(
  "chemistry",
  "chemical_reactions",
  "Reactants",
  `<h2>Reactants</h2>
  <p>Reactants are the substances that take part in a chemical reaction and are changed during the reaction.</p>

  <p>In a chemical equation, reactants are written on the <strong>left-hand side</strong> of the arrow.</p>

  <p>Example:</p>
  <p><strong>2Mg + O<sub>2</sub> → 2MgO</strong></p>

  <p>Magnesium and oxygen are the reactants.</p>

  <h3>Remember</h3>
  <p><strong>Left of the arrow = reactants.</strong></p>`,
  [
    {
      q: "What are reactants?",
      steps: [
        "Step 1: Identify the substances present before a reaction occurs.",
        "Step 2: These substances take part in the reaction.",
        "Step 3: They are called reactants."
      ],
      ans: "Reactants are substances that take part in and are changed during a chemical reaction.",
      why: "Reactants provide the atoms that are rearranged to form products."
    },
    {
      q: "Identify the reactants in: CaCO₃ → CaO + CO₂.",
      steps: [
        "Step 1: Look at the left-hand side of the arrow.",
        "Step 2: CaCO₃ is on the left.",
        "Step 3: Therefore CaCO₃ is the reactant."
      ],
      ans: "Calcium carbonate (CaCO₃).",
      why: "The substance on the left of the reaction arrow is the reactant."
    },
    {
      q: "Identify all reactants in: 2H₂ + O₂ → 2H₂O.",
      steps: [
        "Step 1: Look to the left of the arrow.",
        "Step 2: H₂ and O₂ are written there.",
        "Step 3: Both are therefore reactants."
      ],
      ans: "Hydrogen (H₂) and oxygen (O₂).",
      why: "Both substances participate in forming water."
    }
  ],
  [
    {
      q: "In Zn + 2HCl → ZnCl₂ + H₂, identify the reactants.",
      hint: "Look at the left side of the arrow.",
      steps: [
        "Step 1: The left side contains Zn and 2HCl.",
        "Step 2: These are the substances that react."
      ],
      ans: "Zinc and hydrochloric acid.",
      why: "Reactants are written before the reaction arrow."
    }
  ]
);


// ============================================================
// 3. PRODUCTS
// ============================================================

add(
  "chemistry",
  "chemical_reactions",
  "Products",
  `<h2>Products</h2>
  <p>Products are the new substances formed during a chemical reaction.</p>

  <p>In a chemical equation, products are written on the <strong>right-hand side</strong> of the arrow.</p>

  <p>Example:</p>
  <p><strong>2H₂ + O₂ → 2H₂O</strong></p>

  <p>Water is the product.</p>

  <h3>Remember</h3>
  <p><strong>Right of the arrow = products.</strong></p>`,
  [
    {
      q: "What are products?",
      steps: [
        "Step 1: A chemical reaction produces new substances.",
        "Step 2: The new substances formed are called products."
      ],
      ans: "Products are the new substances formed during a chemical reaction.",
      why: "They are the substances produced after the reactants have changed."
    },
    {
      q: "Identify the product in: 2Mg + O₂ → 2MgO.",
      steps: [
        "Step 1: Look at the right-hand side of the arrow.",
        "Step 2: MgO is on the right.",
        "Step 3: Therefore magnesium oxide is the product."
      ],
      ans: "Magnesium oxide (MgO).",
      why: "The product is written after the reaction arrow."
    },
    {
      q: "Identify the product in: CaCO₃ → CaO + CO₂.",
      steps: [
        "Step 1: Look to the right of the arrow.",
        "Step 2: CaO and CO₂ are on the right.",
        "Step 3: Both are products."
      ],
      ans: "Calcium oxide (CaO) and carbon dioxide (CO₂).",
      why: "A reaction can form more than one product."
    }
  ],
  [
    {
      q: "In Fe + S → FeS, identify the product.",
      hint: "Look to the right of the arrow.",
      steps: [
        "Step 1: FeS is written after the arrow.",
        "Step 2: Therefore it is the substance formed."
      ],
      ans: "Iron(II) sulphide (FeS).",
      why: "Products are formed during the reaction and appear on the right."
    }
  ]
);


// ============================================================
// 4. SIGNS OF CHEMICAL REACTION
// ============================================================

add(
  "chemistry",
  "chemical_reactions",
  "Signs of Chemical Reaction",
  `<h2>Signs of a Chemical Reaction</h2>
  <p>A chemical reaction may be identified by observable changes.</p>

  <h3>Common signs</h3>
  <ul>
    <li>Formation of a new colour</li>
    <li>Production of a gas</li>
    <li>Formation of a precipitate</li>
    <li>Change in temperature</li>
    <li>Production of light</li>
    <li>Production of sound</li>
    <li>A new smell may be produced</li>
  </ul>

  <p>A precipitate is an insoluble solid formed when two solutions react.</p>`,
  [
    {
      q: "State three signs that may indicate that a chemical reaction has occurred.",
      steps: [
        "Step 1: Consider observable changes during a reaction.",
        "Step 2: Examples include gas production, colour change and temperature change.",
        "Step 3: A precipitate may also form."
      ],
      ans: "Any three: gas production, colour change, temperature change, precipitate formation, light production or sound production.",
      why: "Chemical reactions often produce observable changes because new substances are formed."
    },
    {
      q: "What is a precipitate?",
      steps: [
        "Step 1: Two solutions may react when mixed.",
        "Step 2: An insoluble solid may form.",
        "Step 3: This solid is called a precipitate."
      ],
      ans: "A precipitate is an insoluble solid formed during a chemical reaction in solution.",
      why: "The formation of an insoluble solid is evidence that a new substance has formed."
    },
    {
      q: "Why can a temperature change indicate a chemical reaction?",
      steps: [
        "Step 1: Chemical reactions involve energy changes.",
        "Step 2: Energy may be released or absorbed.",
        "Step 3: This can cause the temperature of the surroundings to change."
      ],
      ans: "Because chemical reactions can release or absorb energy, causing a temperature change.",
      why: "Energy changes accompany many chemical reactions."
    }
  ],
  [
    {
      q: "A colourless solution produces bubbles when another solution is added. What evidence suggests that a chemical reaction has occurred?",
      hint: "Look at what is being produced.",
      steps: [
        "Step 1: Bubbles indicate that a gas is being produced.",
        "Step 2: Gas production is an observable sign of a chemical reaction."
      ],
      ans: "The production of gas, observed as bubbles, suggests that a chemical reaction has occurred.",
      why: "A gas may be a new product formed during the reaction."
    }
  ]
);


// ============================================================
// 5. CONSERVATION OF MASS
// ============================================================

add(
  "chemistry",
  "chemical_reactions",
  "Conservation of Mass",
  `<h2>Conservation of Mass</h2>
  <p>The law of conservation of mass states that mass is neither created nor destroyed during a chemical reaction.</p>

  <p>Therefore:</p>
  <p><strong>Total mass of reactants = Total mass of products</strong></p>

  <h3>Example</h3>
  <p>If 10 g of substance A reacts with 6 g of substance B:</p>
  <p>Mass of reactants = 10 + 6 = 16 g</p>
  <p>Therefore the total mass of products must be <strong>16 g</strong>.</p>

  <p>If a reaction appears to lose mass, a gas may have escaped from an open system.</p>`,
  [
    {
      q: "State the law of conservation of mass.",
      steps: [
        "Step 1: Consider the total mass before a chemical reaction.",
        "Step 2: Compare it with the total mass after the reaction.",
        "Step 3: They are equal in a closed system."
      ],
      ans: "Mass is neither created nor destroyed during a chemical reaction.",
      why: "The atoms present before the reaction are rearranged rather than created or destroyed."
    },
    {
      q: "10 g of calcium carbonate decomposes to form 5.6 g of calcium oxide and carbon dioxide. Calculate the mass of carbon dioxide.",
      steps: [
        "Step 1: Total mass of reactants = 10 g.",
        "Step 2: Total mass of products must also be 10 g.",
        "Step 3: Mass of carbon dioxide = 10 − 5.6.",
        "Step 4: Mass of carbon dioxide = 4.4 g."
      ],
      ans: "4.4 g",
      why: "The total mass of products must equal the total mass of reactants."
    },
    {
      q: "12 g of magnesium reacts with oxygen to form 20 g of magnesium oxide. Calculate the mass of oxygen that reacted.",
      steps: [
        "Step 1: Mass of reactants = mass of magnesium + mass of oxygen.",
        "Step 2: Total mass of reactants must equal 20 g.",
        "Step 3: Mass of oxygen = 20 − 12.",
        "Step 4: Mass of oxygen = 8 g."
      ],
      ans: "8 g",
      why: "The mass of the product equals the total mass of the reactants."
    }
  ],
  [
    {
      q: "A reaction has 25 g of reactants and produces 18 g of one product. What is the mass of the other product?",
      hint: "Use total reactant mass = total product mass.",
      steps: [
        "Step 1: Total product mass must be 25 g.",
        "Step 2: One product has a mass of 18 g.",
        "Step 3: Other product = 25 − 18.",
        "Step 4: Other product = 7 g."
      ],
      ans: "7 g",
      why: "Mass is conserved during the reaction."
    }
  ]
);


// ============================================================
// 6. CHEMICAL EQUATIONS
// ============================================================

add(
  "chemistry",
  "chemical_reactions",
  "Chemical Equations",
  `<h2>Chemical Equations</h2>
  <p>A chemical equation represents a chemical reaction using chemical formulae and symbols.</p>

  <p>Example:</p>
  <p><strong>2Mg + O₂ → 2MgO</strong></p>

  <p>The plus sign separates different substances.</p>
  <p>The arrow means “reacts to form” or “produces”.</p>

  <h3>Equation structure</h3>
  <p><strong>Reactants → Products</strong></p>

  <p>A chemical equation should represent the substances involved and the correct proportions in which they react.</p>`,
  [
    {
      q: "What is a chemical equation?",
      steps: [
        "Step 1: A chemical reaction can be represented using symbols and formulae.",
        "Step 2: The reactants are written on the left.",
        "Step 3: The products are written on the right."
      ],
      ans: "A chemical equation is a symbolic representation of a chemical reaction using chemical formulae and symbols.",
      why: "Chemical equations provide a concise way of representing chemical reactions."
    },
    {
      q: "What does the arrow in a chemical equation mean?",
      steps: [
        "Step 1: Look at the direction of the reaction.",
        "Step 2: Reactants are placed before the arrow.",
        "Step 3: Products are placed after the arrow."
      ],
      ans: "It means 'reacts to form' or 'produces'.",
      why: "The arrow connects the reactants to the products."
    },
    {
      q: "Write the word equation for magnesium reacting with oxygen to form magnesium oxide.",
      steps: [
        "Step 1: Identify the reactants: magnesium and oxygen.",
        "Step 2: Identify the product: magnesium oxide.",
        "Step 3: Arrange them as reactants → product."
      ],
      ans: "Magnesium + oxygen → magnesium oxide",
      why: "A word equation names the substances instead of using chemical formulae."
    }
  ],
  [
    {
      q: "In the equation H₂ + Cl₂ → 2HCl, identify the reactants and products.",
      hint: "Use the position relative to the arrow.",
      steps: [
        "Step 1: H₂ and Cl₂ are on the left.",
        "Step 2: 2HCl is on the right.",
        "Step 3: Therefore H₂ and Cl₂ are reactants and HCl is the product."
      ],
      ans: "Reactants: H₂ and Cl₂. Product: HCl.",
      why: "Reactants are on the left and products are on the right."
    }
  ]
);


// ============================================================
// 7. WRITING CHEMICAL EQUATIONS
// ============================================================

add(
  "chemistry",
  "chemical_reactions",
  "Writing Chemical Equations",
  `<h2>Writing Chemical Equations</h2>
  <p>To write a chemical equation from a word equation:</p>

  <ol>
    <li>Identify the reactants.</li>
    <li>Identify the products.</li>
    <li>Write the correct chemical formula for each substance.</li>
    <li>Use an arrow between reactants and products.</li>
    <li>Balance the equation.</li>
  </ol>

  <h3>Example</h3>
  <p>Hydrogen reacts with oxygen to form water.</p>

  <p>Formulae:</p>
  <p>H₂ + O₂ → H₂O</p>

  <p>This equation is not balanced yet.</p>`,
  [
    {
      q: "Write the chemical equation for magnesium reacting with oxygen to form magnesium oxide before balancing.",
      steps: [
        "Step 1: Magnesium has the formula Mg.",
        "Step 2: Oxygen gas has the formula O₂.",
        "Step 3: Magnesium oxide has the formula MgO.",
        "Step 4: Write the reactants on the left and product on the right."
      ],
      ans: "Mg + O₂ → MgO",
      why: "The correct chemical formulae must be used before balancing."
    },
    {
      q: "Write the chemical equation for hydrogen reacting with chlorine to form hydrogen chloride before balancing.",
      steps: [
        "Step 1: Hydrogen gas is H₂.",
        "Step 2: Chlorine gas is Cl₂.",
        "Step 3: Hydrogen chloride is HCl.",
        "Step 4: Arrange them as reactants → product."
      ],
      ans: "H₂ + Cl₂ → HCl",
      why: "The formulae represent the substances taking part in the reaction."
    },
    {
      q: "Write the chemical equation for calcium carbonate decomposing into calcium oxide and carbon dioxide.",
      steps: [
        "Step 1: Calcium carbonate is CaCO₃.",
        "Step 2: Calcium oxide is CaO.",
        "Step 3: Carbon dioxide is CO₂.",
        "Step 4: Write the reactant first and products after the arrow."
      ],
      ans: "CaCO₃ → CaO + CO₂",
      why: "The equation represents one compound breaking down into two products."
    }
  ],
  [
    {
      q: "Write the unbalanced equation for zinc reacting with hydrochloric acid to form zinc chloride and hydrogen.",
      hint: "Use Zn, HCl, ZnCl₂ and H₂.",
      steps: [
        "Step 1: Zinc = Zn.",
        "Step 2: Hydrochloric acid = HCl.",
        "Step 3: Zinc chloride = ZnCl₂.",
        "Step 4: Hydrogen gas = H₂.",
        "Step 5: Arrange the substances."
      ],
      ans: "Zn + HCl → ZnCl₂ + H₂",
      why: "The correct formulae must be written before balancing."
    }
  ]
);


// ============================================================
// 8. STATE SYMBOLS
// ============================================================

add(
  "chemistry",
  "chemical_reactions",
  "State Symbols",
  `<h2>State Symbols</h2>
  <p>State symbols show the physical state of each substance in a chemical equation.</p>

  <ul>
    <li><strong>(s)</strong> = solid</li>
    <li><strong>(l)</strong> = liquid</li>
    <li><strong>(g)</strong> = gas</li>
    <li><strong>(aq)</strong> = aqueous, dissolved in water</li>
  </ul>

  <h3>Example</h3>
  <p><strong>Mg(s) + 2HCl(aq) → MgCl₂(aq) + H₂(g)</strong></p>

  <p>The symbols provide additional information about the physical states of the substances.</p>`,
  [
    {
      q: "What does (s) mean in a chemical equation?",
      steps: [
        "Step 1: Identify the state symbol.",
        "Step 2: (s) represents a solid."
      ],
      ans: "Solid.",
      why: "(s) is the standard state symbol for a solid."
    },
    {
      q: "What does (aq) mean?",
      steps: [
        "Step 1: Recognise that aq means aqueous.",
        "Step 2: Aqueous means dissolved in water."
      ],
      ans: "A substance dissolved in water.",
      why: "The symbol (aq) indicates an aqueous solution."
    },
    {
      q: "Identify the physical state of each substance in: Mg(s) + 2HCl(aq) → MgCl₂(aq) + H₂(g).",
      steps: [
        "Step 1: Mg(s) is a solid.",
        "Step 2: HCl(aq) is aqueous.",
        "Step 3: MgCl₂(aq) is aqueous.",
        "Step 4: H₂(g) is a gas."
      ],
      ans: "Mg = solid; HCl = aqueous; MgCl₂ = aqueous; H₂ = gas.",
      why: "Each state symbol describes the physical state of the substance."
    }
  ],
  [
    {
      q: "Write the correct state symbol for oxygen gas.",
      hint: "Oxygen under ordinary conditions is a gas.",
      steps: [
        "Step 1: Oxygen exists as a gas under ordinary conditions.",
        "Step 2: The state symbol for gas is (g)."
      ],
      ans: "(g)",
      why: "(g) represents the gaseous state."
    }
  ]
);


// ============================================================
// 9. BALANCING CHEMICAL EQUATIONS
// ============================================================

add(
  "chemistry",
  "chemical_reactions",
  "Balancing Chemical Equations",
  `<h2>Balancing Chemical Equations</h2>
  <p>A chemical equation is balanced when the number of atoms of each element is the same on both sides.</p>

  <p>Only the <strong>coefficients</strong> in front of formulae may be changed.</p>

  <p>You must not change the small numbers inside chemical formulae.</p>

  <h3>Example</h3>
  <p>H₂ + O₂ → H₂O</p>

  <p>There are 2 oxygen atoms on the left but only 1 on the right.</p>

  <p>Putting 2 before H₂O gives:</p>

  <p><strong>H₂ + O₂ → 2H₂O</strong></p>

  <p>Now hydrogen is unbalanced, so put 2 before H₂:</p>

  <p><strong>2H₂ + O₂ → 2H₂O</strong></p>`,
  [
    {
      q: "What does it mean for a chemical equation to be balanced?",
      steps: [
        "Step 1: Count the atoms of each element on the reactant side.",
        "Step 2: Count the atoms of each element on the product side.",
        "Step 3: The numbers must be equal for every element."
      ],
      ans: "A chemical equation is balanced when the number of atoms of every element is equal on both sides.",
      why: "Atoms are conserved during a chemical reaction."
    },
    {
      q: "What should be changed when balancing an equation?",
      steps: [
        "Step 1: Keep the chemical formulae unchanged.",
        "Step 2: Add numbers in front of formulae.",
        "Step 3: These numbers are called coefficients."
      ],
      ans: "Only the coefficients in front of chemical formulae should be changed.",
      why: "Changing subscripts would change the substances themselves."
    },
    {
      q: "Why must the small numbers inside formulae not be changed when balancing?",
      steps: [
        "Step 1: The small numbers are subscripts.",
        "Step 2: They define the composition of a substance.",
        "Step 3: Changing them would create a different substance."
      ],
      ans: "Because changing subscripts changes the chemical formula and therefore changes the substance.",
      why: "Balancing changes the number of particles, not the identity of the substances."
    }
  ],
  [
    {
      q: "Balance: H₂ + O₂ → H₂O.",
      hint: "First balance oxygen, then hydrogen.",
      steps: [
        "Step 1: There are 2 oxygen atoms in O₂ but 1 in H₂O.",
        "Step 2: Put 2 before H₂O: H₂ + O₂ → 2H₂O.",
        "Step 3: There are now 4 hydrogen atoms on the right.",
        "Step 4: Put 2 before H₂.",
        "Step 5: Final equation: 2H₂ + O₂ → 2H₂O."
      ],
      ans: "2H₂ + O₂ → 2H₂O",
      why: "Both hydrogen and oxygen now have equal numbers of atoms on both sides."
    }
  ]
);


// ============================================================
// 10. SIMPLE EQUATIONS
// ============================================================

add(
  "chemistry",
  "chemical_reactions",
  "Balancing Simple Equations",
  `<h2>Balancing Simple Equations</h2>
  <p>Simple equations can often be balanced by counting atoms and adjusting coefficients one element at a time.</p>

  <h3>Example 1</h3>
  <p>Mg + O₂ → MgO</p>
  <p>Put 2 before MgO:</p>
  <p>Mg + O₂ → 2MgO</p>
  <p>Now put 2 before Mg:</p>
  <p><strong>2Mg + O₂ → 2MgO</strong></p>

  <h3>Example 2</h3>
  <p>H₂ + Cl₂ → HCl</p>
  <p><strong>H₂ + Cl₂ → 2HCl</strong></p>`,
  [
    {
      q: "Balance: Mg + O₂ → MgO.",
      steps: [
        "Step 1: Oxygen has 2 atoms on the left and 1 on the right.",
        "Step 2: Put 2 before MgO.",
        "Step 3: Magnesium now has 2 atoms on the right.",
        "Step 4: Put 2 before Mg.",
        "Step 5: Check both elements."
      ],
      ans: "2Mg + O₂ → 2MgO",
      why: "There are 2 magnesium atoms and 2 oxygen atoms on both sides."
    },
    {
      q: "Balance: H₂ + Cl₂ → HCl.",
      steps: [
        "Step 1: There are 2 hydrogen atoms on the left.",
        "Step 2: There are 2 chlorine atoms on the left.",
        "Step 3: Put 2 before HCl.",
        "Step 4: The equation becomes H₂ + Cl₂ → 2HCl."
      ],
      ans: "H₂ + Cl₂ → 2HCl",
      why: "The coefficient 2 gives two hydrogen atoms and two chlorine atoms in the products."
    },
    {
      q: "Balance: Na + Cl₂ → NaCl.",
      steps: [
        "Step 1: Chlorine has 2 atoms on the left.",
        "Step 2: Put 2 before NaCl.",
        "Step 3: There are now 2 sodium atoms on the right.",
        "Step 4: Put 2 before Na."
      ],
      ans: "2Na + Cl₂ → 2NaCl",
      why: "Both sodium and chlorine atoms are equal on both sides."
    }
  ],
  [
    {
      q: "Balance: Ca + O₂ → CaO.",
      hint: "Oxygen occurs as O₂, so balance oxygen first.",
      steps: [
        "Step 1: O₂ contains 2 oxygen atoms.",
        "Step 2: Put 2 before CaO.",
        "Step 3: This gives 2 calcium atoms on the right.",
        "Step 4: Put 2 before Ca."
      ],
      ans: "2Ca + O₂ → 2CaO",
      why: "There are two calcium atoms and two oxygen atoms on both sides."
    }
  ]
);


// ============================================================
// 11. BALANCING MORE COMPLEX EQUATIONS
// ============================================================

add(
  "chemistry",
  "chemical_reactions",
  "Balancing More Complex Equations",
  `<h2>Balancing More Complex Equations</h2>
  <p>More complex equations contain several different elements or compounds. Balance one element at a time and check the entire equation at the end.</p>

  <h3>Example</h3>
  <p>Fe + O₂ → Fe₂O₃</p>

  <p>Use coefficients to obtain equal numbers of iron and oxygen atoms:</p>

  <p><strong>4Fe + 3O₂ → 2Fe₂O₃</strong></p>

  <p>Check:</p>
  <ul>
    <li>Iron: 4 on each side</li>
    <li>Oxygen: 6 on each side</li>
  </ul>`,
  [
    {
      q: "Balance: Fe + O₂ → Fe₂O₃.",
      steps: [
        "Step 1: Fe₂O₃ contains 2 Fe atoms and 3 O atoms.",
        "Step 2: Use 2Fe₂O₃ to give 4 Fe atoms and 6 O atoms.",
        "Step 3: Put 4 before Fe.",
        "Step 4: Put 3 before O₂ to give 6 oxygen atoms.",
        "Step 5: Check both elements."
      ],
      ans: "4Fe + 3O₂ → 2Fe₂O₃",
      why: "There are 4 iron atoms and 6 oxygen atoms on each side."
    },
    {
      q: "Balance: Al + O₂ → Al₂O₃.",
      steps: [
        "Step 1: Use 2Al₂O₃ to give 4 aluminium atoms and 6 oxygen atoms.",
        "Step 2: Put 4 before Al.",
        "Step 3: Put 3 before O₂.",
        "Step 4: Check aluminium and oxygen."
      ],
      ans: "4Al + 3O₂ → 2Al₂O₃",
      why: "Both elements have equal numbers of atoms on both sides."
    },
    {
      q: "Balance: CH₄ + O₂ → CO₂ + H₂O.",
      steps: [
        "Step 1: Carbon is already balanced with 1 C on each side.",
        "Step 2: CH₄ contains 4 hydrogen atoms, so put 2 before H₂O.",
        "Step 3: Products now contain 4 oxygen atoms.",
        "Step 4: Put 2 before O₂.",
        "Step 5: Check all elements."
      ],
      ans: "CH₄ + 2O₂ → CO₂ + 2H₂O",
      why: "There is 1 carbon, 4 hydrogen and 4 oxygen atoms on each side."
    }
  ],
  [
    {
      q: "Balance: N₂ + H₂ → NH₃.",
      hint: "Balance nitrogen first, then hydrogen.",
      steps: [
        "Step 1: N₂ contains 2 nitrogen atoms.",
        "Step 2: Put 2 before NH₃.",
        "Step 3: There are now 6 hydrogen atoms on the right.",
        "Step 4: Put 3 before H₂.",
        "Step 5: Check nitrogen and hydrogen."
      ],
      ans: "N₂ + 3H₂ → 2NH₃",
      why: "There are 2 nitrogen atoms and 6 hydrogen atoms on both sides."
    }
  ]
);


// ============================================================
// 12. COMBINATION REACTIONS
// ============================================================

add(
  "chemistry",
  "chemical_reactions",
  "Combination Reactions",
  `<h2>Combination Reactions</h2>
  <p>A combination reaction is a reaction in which two or more substances combine to form a single product.</p>

  <p>General pattern:</p>
  <p><strong>A + B → AB</strong></p>

  <h3>Example</h3>
  <p><strong>2Mg + O₂ → 2MgO</strong></p>

  <p>Magnesium and oxygen combine to form one product, magnesium oxide.</p>`,
  [
    {
      q: "What is a combination reaction?",
      steps: [
        "Step 1: Identify the number of reactants.",
        "Step 2: Two or more substances react together.",
        "Step 3: They form one product."
      ],
      ans: "A reaction in which two or more substances combine to form one product.",
      why: "The defining feature is the formation of a single product from multiple reactants."
    },
    {
      q: "Classify: 2Mg + O₂ → 2MgO.",
      steps: [
        "Step 1: There are two reactants: Mg and O₂.",
        "Step 2: There is one product: MgO.",
        "Step 3: Therefore it is a combination reaction."
      ],
      ans: "Combination reaction.",
      why: "Two reactants combine to form one product."
    },
    {
      q: "Write a balanced equation for iron reacting with sulphur to form iron(II) sulphide.",
      steps: [
        "Step 1: Iron = Fe.",
        "Step 2: Sulphur = S.",
        "Step 3: Iron(II) sulphide = FeS.",
        "Step 4: Write Fe + S → FeS.",
        "Step 5: The atoms are already balanced."
      ],
      ans: "Fe + S → FeS",
      why: "Iron and sulphur combine to form one product."
    }
  ],
  [
    {
      q: "Is CaO + H₂O → Ca(OH)₂ a combination reaction?",
      hint: "Count the reactants and products.",
      steps: [
        "Step 1: CaO and H₂O are two reactants.",
        "Step 2: Ca(OH)₂ is one product.",
        "Step 3: Therefore the reaction is a combination reaction."
      ],
      ans: "Yes, it is a combination reaction.",
      why: "Two substances combine to form a single product."
    }
  ]
);


// ============================================================
// 13. DECOMPOSITION REACTIONS
// ============================================================

add(
  "chemistry",
  "chemical_reactions",
  "Decomposition Reactions",
  `<h2>Decomposition Reactions</h2>
  <p>A decomposition reaction occurs when one compound breaks down into two or more simpler substances.</p>

  <p>General pattern:</p>
  <p><strong>AB → A + B</strong></p>

  <h3>Example</h3>
  <p><strong>CaCO₃ → CaO + CO₂</strong></p>

  <p>One compound produces two products.</p>`,
  [
    {
      q: "What is a decomposition reaction?",
      steps: [
        "Step 1: Start with one compound.",
        "Step 2: The compound breaks down.",
        "Step 3: Two or more simpler substances are formed."
      ],
      ans: "A reaction in which one compound breaks down into two or more simpler substances.",
      why: "The reactant is decomposed into simpler products."
    },
    {
      q: "Classify: CaCO₃ → CaO + CO₂.",
      steps: [
        "Step 1: There is one reactant, CaCO₃.",
        "Step 2: There are two products, CaO and CO₂.",
        "Step 3: Therefore it is decomposition."
      ],
      ans: "Decomposition reaction.",
      why: "One compound breaks down into two products."
    },
    {
      q: "Write the products formed when copper(II) carbonate decomposes: CuCO₃ → ?",
      steps: [
        "Step 1: A metal carbonate decomposes to form the metal oxide and carbon dioxide.",
        "Step 2: Copper(II) carbonate forms copper(II) oxide.",
        "Step 3: Carbon dioxide is also produced."
      ],
      ans: "CuCO₃ → CuO + CO₂",
      why: "Metal carbonates commonly decompose on heating to form the metal oxide and carbon dioxide."
    }
  ],
  [
    {
      q: "Classify: 2KClO₃ → 2KCl + 3O₂.",
      hint: "Look at the number of reactants and products.",
      steps: [
        "Step 1: There is one reactant, KClO₃.",
        "Step 2: Two products are formed.",
        "Step 3: Therefore it is decomposition."
      ],
      ans: "Decomposition reaction.",
      why: "One compound breaks down into simpler substances."
    }
  ]
);


// ============================================================
// 14. DISPLACEMENT REACTIONS
// ============================================================

add(
  "chemistry",
  "chemical_reactions",
  "Displacement Reactions",
  `<h2>Displacement Reactions</h2>
  <p>A displacement reaction occurs when a more reactive element displaces a less reactive element from its compound.</p>

  <h3>Example</h3>
  <p><strong>Zn + CuSO₄ → ZnSO₄ + Cu</strong></p>

  <p>Zinc is more reactive than copper, so zinc displaces copper from copper(II) sulphate.</p>

  <p>The reaction can occur because zinc is higher than copper in the reactivity series.</p>`,
  [
    {
      q: "What is a displacement reaction?",
      steps: [
        "Step 1: An element reacts with a compound.",
        "Step 2: The more reactive element replaces a less reactive element.",
        "Step 3: A new compound and displaced element are formed."
      ],
      ans: "A reaction in which a more reactive element displaces a less reactive element from its compound.",
      why: "The relative reactivity of the elements determines whether displacement occurs."
    },
    {
      q: "Explain why zinc displaces copper from copper(II) sulphate.",
      steps: [
        "Step 1: Zinc is higher than copper in the reactivity series.",
        "Step 2: Therefore zinc is more reactive than copper.",
        "Step 3: Zinc can displace copper from CuSO₄."
      ],
      ans: "Zinc is more reactive than copper, so it displaces copper from copper(II) sulphate.",
      why: "A more reactive metal can displace a less reactive metal from its compound."
    },
    {
      q: "Complete and balance: Zn + CuSO₄ → ?",
      steps: [
        "Step 1: Zinc displaces copper.",
        "Step 2: The products are ZnSO₄ and Cu.",
        "Step 3: Write the equation.",
        "Step 4: Check the atoms."
      ],
      ans: "Zn + CuSO₄ → ZnSO₄ + Cu",
      why: "Zinc replaces copper while the sulphate group remains together."
    }
  ],
  [
    {
      q: "Will copper displace zinc from zinc sulphate? Explain.",
      hint: "Compare copper and zinc in the reactivity series.",
      steps: [
        "Step 1: Zinc is more reactive than copper.",
        "Step 2: Copper is less reactive than zinc.",
        "Step 3: A less reactive metal cannot displace a more reactive metal."
      ],
      ans: "No. Copper cannot displace zinc from zinc sulphate because copper is less reactive than zinc.",
      why: "Displacement requires the free element to be more reactive than the element it replaces."
    }
  ]
);


// ============================================================
// 15. NEUTRALISATION REACTIONS
// ============================================================

add(
  "chemistry",
  "chemical_reactions",
  "Neutralisation Reactions",
  `<h2>Neutralisation Reactions</h2>
  <p>Neutralisation is a reaction between an acid and a base or alkali to form a salt and water.</p>

  <p>General pattern:</p>
  <p><strong>Acid + Base → Salt + Water</strong></p>

  <h3>Example</h3>
  <p><strong>HCl + NaOH → NaCl + H₂O</strong></p>

  <p>Hydrochloric acid reacts with sodium hydroxide to form sodium chloride and water.</p>`,
  [
    {
      q: "What is neutralisation?",
      steps: [
        "Step 1: An acid reacts with a base or alkali.",
        "Step 2: The reaction forms a salt.",
        "Step 3: Water is also formed."
      ],
      ans: "Neutralisation is a reaction between an acid and a base or alkali that produces a salt and water.",
      why: "The acidic and basic properties are neutralised during the reaction."
    },
    {
      q: "Complete: HCl + NaOH → ?",
      steps: [
        "Step 1: HCl is hydrochloric acid.",
        "Step 2: NaOH is sodium hydroxide.",
        "Step 3: The salt formed is sodium chloride, NaCl.",
        "Step 4: Water, H₂O, is also formed."
      ],
      ans: "HCl + NaOH → NaCl + H₂O",
      why: "Hydrochloric acid and sodium hydroxide undergo neutralisation."
    },
    {
      q: "Balance: H₂SO₄ + NaOH → Na₂SO₄ + H₂O.",
      steps: [
        "Step 1: Na₂SO₄ requires 2 sodium atoms.",
        "Step 2: Put 2 before NaOH.",
        "Step 3: There are now 2 OH groups, forming 2H₂O.",
        "Step 4: Check hydrogen and oxygen."
      ],
      ans: "H₂SO₄ + 2NaOH → Na₂SO₄ + 2H₂O",
      why: "The atoms of every element are equal on both sides."
    }
  ],
  [
    {
      q: "What type of reaction occurs between hydrochloric acid and sodium hydroxide?",
      hint: "An acid reacts with an alkali.",
      steps: [
        "Step 1: Hydrochloric acid is an acid.",
        "Step 2: Sodium hydroxide is an alkali.",
        "Step 3: Acid + alkali gives salt + water."
      ],
      ans: "Neutralisation reaction.",
      why: "An acid reacting with an alkali to form salt and water is neutralisation."
    }
  ]
);


// ============================================================
// 16. COMBUSTION REACTIONS
// ============================================================

add(
  "chemistry",
  "chemical_reactions",
  "Combustion Reactions",
  `<h2>Combustion Reactions</h2>
  <p>Combustion is a chemical reaction in which a substance burns in oxygen and releases energy, usually as heat and often as light.</p>

  <h3>Complete combustion of a hydrocarbon</h3>
  <p>A hydrocarbon contains carbon and hydrogen.</p>

  <p>Complete combustion produces:</p>
  <p><strong>Carbon dioxide + water</strong></p>

  <h3>Example</h3>
  <p><strong>CH₄ + 2O₂ → CO₂ + 2H₂O</strong></p>`,
  [
    {
      q: "What is combustion?",
      steps: [
        "Step 1: A substance reacts with oxygen.",
        "Step 2: Energy is released.",
        "Step 3: This process is called combustion."
      ],
      ans: "Combustion is a reaction in which a substance burns in oxygen and releases energy.",
      why: "Burning is a chemical reaction involving oxygen and energy release."
    },
    {
      q: "What are the products of complete combustion of a hydrocarbon?",
      steps: [
        "Step 1: A hydrocarbon contains carbon and hydrogen.",
        "Step 2: In complete combustion, carbon forms carbon dioxide.",
        "Step 3: Hydrogen forms water."
      ],
      ans: "Carbon dioxide and water.",
      why: "With sufficient oxygen, carbon is fully oxidised to CO₂ and hydrogen forms H₂O."
    },
    {
      q: "Balance: CH₄ + O₂ → CO₂ + H₂O.",
      steps: [
        "Step 1: Carbon is already balanced.",
        "Step 2: There are 4 hydrogen atoms in CH₄, so put 2 before H₂O.",
        "Step 3: Products now contain 4 oxygen atoms.",
        "Step 4: Put 2 before O₂."
      ],
      ans: "CH₄ + 2O₂ → CO₂ + 2H₂O",
      why: "The balanced equation has equal numbers of C, H and O atoms on both sides."
    }
  ],
  [
    {
      q: "What two substances are needed for combustion to occur?",
      hint: "Think about what is required for burning.",
      steps: [
        "Step 1: Combustion is burning.",
        "Step 2: Burning requires a substance that can burn.",
        "Step 3: It also requires oxygen."
      ],
      ans: "A combustible substance and oxygen.",
      why: "Oxygen supports combustion and reacts with the substance being burned."
    }
  ]
);
// ============================================================
// BATCH 12 — ACIDS, BASES AND SALTS
// Chapter: acids_bases_salts
// One concept per screen
// No multiple-choice questions
// ============================================================


// ============================================================
// 1. PROPERTIES OF ACIDS
// ============================================================

add(
  "chemistry",
  "acids_bases_salts",
  "Properties of Acids",
  `<h2>Properties of Acids</h2>
  <p>Acids are substances that produce hydrogen ions, H<sup>+</sup>, when dissolved in water.</p>

  <h3>Common properties</h3>
  <ul>
    <li>They have pH values below 7.</li>
    <li>They turn blue litmus paper red.</li>
    <li>They react with some metals to produce hydrogen gas.</li>
    <li>They react with carbonates to produce carbon dioxide.</li>
    <li>They react with bases and alkalis to form salts and water.</li>
  </ul>

  <p>Examples include hydrochloric acid (HCl), sulphuric(VI) acid (H<sub>2</sub>SO<sub>4</sub>) and ethanoic acid (CH<sub>3</sub>COOH).</p>`,
  [
    {
      q: "State three properties of acids.",
      steps: [
        "Step 1: Acids have pH values below 7.",
        "Step 2: They turn blue litmus red.",
        "Step 3: They react with suitable metals, carbonates and bases."
      ],
      ans: "Any three: pH below 7, turn blue litmus red, react with metals, react with carbonates, or react with bases.",
      why: "These are characteristic properties of acidic substances."
    },
    {
      q: "What ion is responsible for the acidic nature of an aqueous acid?",
      steps: [
        "Step 1: An acid dissolves in water.",
        "Step 2: It produces hydrogen ions.",
        "Step 3: The hydrogen ion is H⁺."
      ],
      ans: "Hydrogen ion, H⁺.",
      why: "The presence of hydrogen ions gives aqueous acids their acidic properties."
    },
    {
      q: "What happens to blue litmus paper in an acidic solution?",
      steps: [
        "Step 1: Place blue litmus paper in the acid.",
        "Step 2: Acidic conditions affect the indicator.",
        "Step 3: Blue litmus changes to red."
      ],
      ans: "Blue litmus turns red.",
      why: "Litmus is an indicator that changes colour according to whether a solution is acidic or basic."
    }
  ],
  [
    {
      q: "A solution has a pH of 3. Is it acidic or basic?",
      hint: "Compare its pH with 7.",
      steps: [
        "Step 1: Neutral solutions have pH 7.",
        "Step 2: A pH below 7 is acidic.",
        "Step 3: Therefore pH 3 is acidic."
      ],
      ans: "Acidic.",
      why: "A pH value below 7 indicates an acidic solution."
    }
  ]
);


// ============================================================
// 2. REACTIONS OF ACIDS WITH METALS
// ============================================================

add(
  "chemistry",
  "acids_bases_salts",
  "Reactions of Acids with Metals",
  `<h2>Reactions of Acids with Metals</h2>
  <p>Dilute acids react with suitable metals to form a <strong>salt and hydrogen gas</strong>.</p>

  <p><strong>Acid + Metal → Salt + Hydrogen</strong></p>

  <h3>Example</h3>
  <p>Magnesium reacts with hydrochloric acid:</p>
  <p><strong>Mg + 2HCl → MgCl<sub>2</sub> + H<sub>2</sub></strong></p>

  <p>Fizzing occurs because hydrogen gas is produced.</p>`,
  [
    {
      q: "What are the products when a suitable metal reacts with a dilute acid?",
      steps: [
        "Step 1: Identify the reaction pattern.",
        "Step 2: The acid reacts with the metal.",
        "Step 3: A salt and hydrogen gas are formed."
      ],
      ans: "A salt and hydrogen gas.",
      why: "This is the characteristic reaction of suitable metals with dilute acids."
    },
    {
      q: "Write the balanced equation for magnesium reacting with hydrochloric acid.",
      steps: [
        "Step 1: Magnesium = Mg.",
        "Step 2: Hydrochloric acid = HCl.",
        "Step 3: Magnesium chloride = MgCl₂.",
        "Step 4: Hydrogen = H₂.",
        "Step 5: Balance the chlorine and hydrogen atoms."
      ],
      ans: "Mg + 2HCl → MgCl₂ + H₂",
      why: "Two HCl molecules provide two chlorine atoms for MgCl₂ and two hydrogen atoms for H₂."
    },
    {
      q: "What gas is produced when zinc reacts with dilute sulphuric(VI) acid?",
      steps: [
        "Step 1: Zinc reacts with dilute sulphuric(VI) acid.",
        "Step 2: The general reaction is acid + metal → salt + hydrogen.",
        "Step 3: Therefore the gas is hydrogen."
      ],
      ans: "Hydrogen gas.",
      why: "Suitable metals reacting with dilute acids produce hydrogen gas."
    }
  ],
  [
    {
      q: "How can the gas produced when magnesium reacts with dilute hydrochloric acid be identified?",
      hint: "Use the standard test for hydrogen.",
      steps: [
        "Step 1: Collect the gas.",
        "Step 2: Bring a lighted splint to the gas.",
        "Step 3: Hydrogen burns with a characteristic 'pop' sound."
      ],
      ans: "Using a lighted splint; hydrogen burns with a 'pop' sound.",
      why: "The pop test is the standard laboratory test for hydrogen."
    }
  ]
);


// ============================================================
// 3. REACTIONS OF ACIDS WITH CARBONATES
// ============================================================

add(
  "chemistry",
  "acids_bases_salts",
  "Reactions of Acids with Carbonates",
  `<h2>Reactions of Acids with Carbonates</h2>
  <p>Acids react with carbonates to form a <strong>salt, water and carbon dioxide</strong>.</p>

  <p><strong>Acid + Carbonate → Salt + Water + Carbon dioxide</strong></p>

  <h3>Example</h3>
  <p>Hydrochloric acid reacts with calcium carbonate:</p>
  <p><strong>2HCl + CaCO<sub>3</sub> → CaCl<sub>2</sub> + H<sub>2</sub>O + CO<sub>2</sub></strong></p>`,
  [
    {
      q: "What are the products of the reaction between an acid and a carbonate?",
      steps: [
        "Step 1: An acid reacts with a carbonate.",
        "Step 2: The products are a salt, water and carbon dioxide."
      ],
      ans: "A salt, water and carbon dioxide.",
      why: "Carbonates release carbon dioxide when they react with acids."
    },
    {
      q: "Write the balanced equation for calcium carbonate reacting with hydrochloric acid.",
      steps: [
        "Step 1: Calcium carbonate = CaCO₃.",
        "Step 2: Hydrochloric acid = HCl.",
        "Step 3: Products are calcium chloride, water and carbon dioxide.",
        "Step 4: Balance the equation."
      ],
      ans: "CaCO₃ + 2HCl → CaCl₂ + H₂O + CO₂",
      why: "The atoms of Ca, C, O, H and Cl are equal on both sides."
    },
    {
      q: "How can carbon dioxide produced in this reaction be tested?",
      steps: [
        "Step 1: Pass the gas into limewater.",
        "Step 2: Observe the limewater.",
        "Step 3: Carbon dioxide turns limewater milky."
      ],
      ans: "Pass the gas through limewater; the limewater turns milky.",
      why: "Carbon dioxide reacts with calcium hydroxide in limewater to form insoluble calcium carbonate."
    }
  ],
  [
    {
      q: "A carbonate reacts with hydrochloric acid and produces fizzing. What gas causes the fizzing?",
      hint: "Think about the products of acid + carbonate.",
      steps: [
        "Step 1: Acid + carbonate produces salt, water and carbon dioxide.",
        "Step 2: Carbon dioxide is gaseous.",
        "Step 3: The gas escaping causes the fizzing."
      ],
      ans: "Carbon dioxide.",
      why: "Carbon dioxide gas is released during the reaction."
    }
  ]
);


// ============================================================
// 4. REACTIONS OF ACIDS WITH HYDROGEN CARBONATES
// ============================================================

add(
  "chemistry",
  "acids_bases_salts",
  "Reactions of Acids with Hydrogen Carbonates",
  `<h2>Reactions of Acids with Hydrogen Carbonates</h2>
  <p>Acids also react with hydrogen carbonates to produce a <strong>salt, water and carbon dioxide</strong>.</p>

  <p><strong>Acid + Hydrogen carbonate → Salt + Water + Carbon dioxide</strong></p>

  <h3>Example</h3>
  <p>Sodium hydrogen carbonate reacts with hydrochloric acid:</p>
  <p><strong>NaHCO<sub>3</sub> + HCl → NaCl + H<sub>2</sub>O + CO<sub>2</sub></strong></p>`,
  [
    {
      q: "What products are formed when an acid reacts with a hydrogen carbonate?",
      steps: [
        "Step 1: Identify the reaction as acid + hydrogen carbonate.",
        "Step 2: The hydrogen carbonate releases carbon dioxide.",
        "Step 3: The products are salt, water and carbon dioxide."
      ],
      ans: "A salt, water and carbon dioxide.",
      why: "Hydrogen carbonates react with acids in the same characteristic pattern as carbonates."
    },
    {
      q: "Write the equation for sodium hydrogen carbonate reacting with hydrochloric acid.",
      steps: [
        "Step 1: Sodium hydrogen carbonate = NaHCO₃.",
        "Step 2: Hydrochloric acid = HCl.",
        "Step 3: Sodium chloride = NaCl.",
        "Step 4: The other products are water and carbon dioxide."
      ],
      ans: "NaHCO₃ + HCl → NaCl + H₂O + CO₂",
      why: "The equation represents the reaction of a hydrogen carbonate with an acid."
    },
    {
      q: "What observation occurs when sodium hydrogen carbonate reacts with hydrochloric acid?",
      steps: [
        "Step 1: The reaction produces carbon dioxide.",
        "Step 2: Carbon dioxide escapes as bubbles.",
        "Step 3: Therefore effervescence is observed."
      ],
      ans: "Effervescence or fizzing occurs because carbon dioxide gas is produced.",
      why: "The escaping gas produces visible bubbles."
    }
  ],
  [
    {
      q: "How would you distinguish the gas produced from hydrogen?",
      hint: "Use limewater.",
      steps: [
        "Step 1: Pass the gas into limewater.",
        "Step 2: Carbon dioxide turns limewater milky.",
        "Step 3: Hydrogen does not turn limewater milky."
      ],
      ans: "Carbon dioxide turns limewater milky, while hydrogen does not.",
      why: "The limewater test distinguishes carbon dioxide from hydrogen."
    }
  ]
);


// ============================================================
// 5. REACTIONS OF ACIDS WITH METAL OXIDES
// ============================================================

add(
  "chemistry",
  "acids_bases_salts",
  "Reactions of Acids with Metal Oxides",
  `<h2>Reactions of Acids with Metal Oxides</h2>
  <p>Acids react with metal oxides to form a <strong>salt and water</strong>.</p>

  <p><strong>Acid + Metal oxide → Salt + Water</strong></p>

  <h3>Example</h3>
  <p>Copper(II) oxide reacts with sulphuric(VI) acid:</p>
  <p><strong>CuO + H<sub>2</sub>SO<sub>4</sub> → CuSO<sub>4</sub> + H<sub>2</sub>O</strong></p>`,
  [
    {
      q: "What products are formed when an acid reacts with a metal oxide?",
      steps: [
        "Step 1: Identify the reaction as acid + metal oxide.",
        "Step 2: The products are a salt and water."
      ],
      ans: "A salt and water.",
      why: "Metal oxides neutralise acids to form salts and water."
    },
    {
      q: "Write the equation for copper(II) oxide reacting with sulphuric(VI) acid.",
      steps: [
        "Step 1: Copper(II) oxide = CuO.",
        "Step 2: Sulphuric(VI) acid = H₂SO₄.",
        "Step 3: Copper(II) sulphate = CuSO₄.",
        "Step 4: Water is also formed."
      ],
      ans: "CuO + H₂SO₄ → CuSO₄ + H₂O",
      why: "The reaction is an acid-metal oxide neutralisation."
    },
    {
      q: "Why does copper(II) oxide react with an acid even though it is not an alkali?",
      steps: [
        "Step 1: Copper(II) oxide is a basic metal oxide.",
        "Step 2: Basic oxides react with acids.",
        "Step 3: The products are a salt and water."
      ],
      ans: "Because copper(II) oxide is a basic oxide and reacts with acids to form a salt and water.",
      why: "Basic metal oxides can neutralise acids."
    }
  ],
  [
    {
      q: "What type of reaction occurs between CuO and H₂SO₄?",
      hint: "Identify what an acid reacts with.",
      steps: [
        "Step 1: H₂SO₄ is an acid.",
        "Step 2: CuO is a metal oxide.",
        "Step 3: Acid + metal oxide gives salt + water."
      ],
      ans: "Neutralisation reaction.",
      why: "The basic metal oxide neutralises the acid."
    }
  ]
);


// ============================================================
// 6. BASES
// ============================================================

add(
  "chemistry",
  "acids_bases_salts",
  "Bases",
  `<h2>Bases</h2>
  <p>A base is a substance that reacts with an acid to form a salt and water.</p>

  <p>Many metal oxides and metal hydroxides are bases.</p>

  <p>Examples include:</p>
  <ul>
    <li>CuO — copper(II) oxide</li>
    <li>MgO — magnesium oxide</li>
    <li>Cu(OH)<sub>2</sub> — copper(II) hydroxide</li>
  </ul>

  <p>Some bases are soluble in water. These soluble bases are called <strong>alkalis</strong>.</p>`,
  [
    {
      q: "What is a base?",
      steps: [
        "Step 1: A base reacts with an acid.",
        "Step 2: The reaction forms a salt and water.",
        "Step 3: Therefore a base can neutralise an acid."
      ],
      ans: "A base is a substance that reacts with an acid to form a salt and water.",
      why: "The ability to neutralise acids is a defining chemical property of bases."
    },
    {
      q: "Give two examples of bases.",
      steps: [
        "Step 1: Metal oxides and hydroxides can be bases.",
        "Step 2: Examples include CuO and MgO."
      ],
      ans: "Copper(II) oxide and magnesium oxide.",
      why: "Both are basic metal oxides."
    },
    {
      q: "What is the difference between a base and an alkali?",
      steps: [
        "Step 1: A base can neutralise an acid.",
        "Step 2: An alkali is a base that dissolves in water.",
        "Step 3: Therefore not every base is necessarily an alkali."
      ],
      ans: "An alkali is a base that is soluble in water.",
      why: "Solubility in water distinguishes alkalis from insoluble bases."
    }
  ],
  [
    {
      q: "Is copper(II) oxide an alkali?",
      hint: "Consider whether it dissolves in water.",
      steps: [
        "Step 1: CuO is a base.",
        "Step 2: It is not soluble in water.",
        "Step 3: Therefore it is not an alkali."
      ],
      ans: "No. Copper(II) oxide is a base but not an alkali.",
      why: "Alkalis are water-soluble bases."
    }
  ]
);


// ============================================================
// 7. ALKALIS
// ============================================================

add(
  "chemistry",
  "acids_bases_salts",
  "Alkalis",
  `<h2>Alkalis</h2>
  <p>An alkali is a base that dissolves in water and produces hydroxide ions, OH<sup>−</sup>.</p>

  <p>Examples include:</p>
  <ul>
    <li>Sodium hydroxide, NaOH</li>
    <li>Potassium hydroxide, KOH</li>
    <li>Calcium hydroxide, Ca(OH)<sub>2</sub></li>
    <li>Aqueous ammonia</li>
  </ul>

  <p>Alkalis have pH values above 7.</p>`,
  [
    {
      q: "What is an alkali?",
      steps: [
        "Step 1: Start with the definition of a base.",
        "Step 2: Consider its solubility in water.",
        "Step 3: A soluble base is called an alkali."
      ],
      ans: "An alkali is a base that dissolves in water.",
      why: "Soluble bases form alkaline solutions."
    },
    {
      q: "What ion is associated with alkaline solutions?",
      steps: [
        "Step 1: Alkalis dissolve in water.",
        "Step 2: They produce hydroxide ions.",
        "Step 3: Hydroxide ions are OH⁻."
      ],
      ans: "Hydroxide ions, OH⁻.",
      why: "Hydroxide ions are responsible for alkaline properties."
    },
    {
      q: "Is sodium hydroxide an alkali?",
      steps: [
        "Step 1: Sodium hydroxide is NaOH.",
        "Step 2: NaOH dissolves in water.",
        "Step 3: Therefore it is a soluble base."
      ],
      ans: "Yes. Sodium hydroxide is an alkali.",
      why: "NaOH dissolves in water and produces hydroxide ions."
    }
  ],
  [
    {
      q: "A solution has a pH of 11. Is it likely to be an alkali?",
      hint: "Compare the pH with 7.",
      steps: [
        "Step 1: pH 7 is neutral.",
        "Step 2: Values above 7 are alkaline.",
        "Step 3: pH 11 is therefore alkaline."
      ],
      ans: "Yes, it is alkaline.",
      why: "Alkaline solutions have pH values above 7."
    }
  ]
);


// ============================================================
// 8. LITMUS
// ============================================================

add(
  "chemistry",
  "acids_bases_salts",
  "Litmus",
  `<h2>Litmus</h2>
  <p>Litmus is an acid-base indicator used to distinguish acidic solutions from alkaline solutions.</p>

  <h3>Colour changes</h3>
  <ul>
    <li>Acid: blue litmus turns red.</li>
    <li>Alkali: red litmus turns blue.</li>
    <li>Neutral solution: no change to either litmus colour.</li>
  </ul>`,
  [
    {
      q: "What happens to blue litmus in an acid?",
      steps: [
        "Step 1: Blue litmus is placed in the acidic solution.",
        "Step 2: Acidic conditions change its colour.",
        "Step 3: It turns red."
      ],
      ans: "Blue litmus turns red.",
      why: "This is the characteristic litmus response to an acid."
    },
    {
      q: "What happens to red litmus in an alkali?",
      steps: [
        "Step 1: Red litmus is placed in the alkaline solution.",
        "Step 2: The alkaline conditions change its colour.",
        "Step 3: It turns blue."
      ],
      ans: "Red litmus turns blue.",
      why: "This is the characteristic litmus response to an alkali."
    },
    {
      q: "What happens to litmus in a neutral solution?",
      steps: [
        "Step 1: A neutral solution does not have acidic or alkaline properties.",
        "Step 2: Litmus therefore does not undergo the acid or alkali colour change."
      ],
      ans: "There is no colour change.",
      why: "Litmus changes colour in acidic or alkaline conditions."
    }
  ],
  [
    {
      q: "A solution turns red litmus blue. What does this tell you?",
      hint: "Think about what causes red litmus to turn blue.",
      steps: [
        "Step 1: Red litmus turns blue in an alkaline solution.",
        "Step 2: Therefore the solution is alkaline."
      ],
      ans: "The solution is alkaline.",
      why: "Alkaline solutions turn red litmus blue."
    }
  ]
);


// ============================================================
// 9. UNIVERSAL INDICATOR
// ============================================================

add(
  "chemistry",
  "acids_bases_salts",
  "Universal Indicator",
  `<h2>Universal Indicator</h2>
  <p>Universal indicator is a mixture of indicators that produces different colours over a wide range of pH values.</p>

  <h3>Approximate colour range</h3>
  <ul>
    <li>Strongly acidic: red</li>
    <li>Weakly acidic: orange/yellow</li>
    <li>Neutral: green</li>
    <li>Weakly alkaline: blue</li>
    <li>Strongly alkaline: purple</li>
  </ul>

  <p>The colour is compared with a pH chart to estimate the pH.</p>`,
  [
    {
      q: "What is universal indicator used for?",
      steps: [
        "Step 1: Universal indicator changes colour in different solutions.",
        "Step 2: Its colour is compared with a pH chart.",
        "Step 3: This gives an estimate of pH."
      ],
      ans: "It is used to estimate the pH and acidity or alkalinity of a solution.",
      why: "Universal indicator gives different colours across the pH scale."
    },
    {
      q: "What colour does universal indicator usually show in a neutral solution?",
      steps: [
        "Step 1: Neutral corresponds to pH 7.",
        "Step 2: Universal indicator is green around pH 7."
      ],
      ans: "Green.",
      why: "Green corresponds approximately to neutral pH 7."
    },
    {
      q: "A solution turns universal indicator purple. What does this suggest?",
      steps: [
        "Step 1: Purple occurs at the alkaline end of the universal indicator scale.",
        "Step 2: Therefore the solution is strongly alkaline."
      ],
      ans: "The solution is strongly alkaline.",
      why: "Purple corresponds to a high pH."
    }
  ],
  [
    {
      q: "Universal indicator turns orange in a solution. Is the solution acidic or alkaline?",
      hint: "Orange occurs below pH 7.",
      steps: [
        "Step 1: Orange is found on the acidic side of the indicator scale.",
        "Step 2: Therefore the solution is acidic."
      ],
      ans: "Acidic.",
      why: "Orange indicates an acidic pH."
    }
  ]
);


// ============================================================
// 10. pH SCALE
// ============================================================

add(
  "chemistry",
  "acids_bases_salts",
  "pH Scale",
  `<h2>pH Scale</h2>
  <p>The pH scale is used to describe how acidic or alkaline an aqueous solution is.</p>

  <p>The commonly used scale runs from about <strong>0 to 14</strong>.</p>

  <ul>
    <li>pH below 7 = acidic</li>
    <li>pH 7 = neutral</li>
    <li>pH above 7 = alkaline</li>
  </ul>

  <p>The lower the pH, the more acidic the solution generally is.</p>
  <p>The higher the pH, the more alkaline the solution generally is.</p>`,
  [
    {
      q: "What does a pH of 7 indicate?",
      steps: [
        "Step 1: Locate 7 on the pH scale.",
        "Step 2: pH 7 represents the neutral point."
      ],
      ans: "A neutral solution.",
      why: "pH 7 is conventionally neutral at ordinary conditions."
    },
    {
      q: "Classify pH 2, pH 7 and pH 12.",
      steps: [
        "Step 1: Values below 7 are acidic.",
        "Step 2: 7 is neutral.",
        "Step 3: Values above 7 are alkaline."
      ],
      ans: "pH 2 = acidic; pH 7 = neutral; pH 12 = alkaline.",
      why: "The position of a pH value relative to 7 determines whether the solution is acidic, neutral or alkaline."
    },
    {
      q: "Which is more acidic: a solution of pH 2 or pH 5?",
      steps: [
        "Step 1: Both values are below 7.",
        "Step 2: Lower pH means greater acidity.",
        "Step 3: 2 is lower than 5."
      ],
      ans: "The pH 2 solution is more acidic.",
      why: "A lower pH indicates greater acidity."
    }
  ],
  [
    {
      q: "A solution has pH 9. Classify it.",
      hint: "Compare 9 with 7.",
      steps: [
        "Step 1: pH 7 is neutral.",
        "Step 2: pH 9 is above 7.",
        "Step 3: Therefore it is alkaline."
      ],
      ans: "Alkaline.",
      why: "A pH above 7 indicates an alkaline solution."
    }
  ]
);


// ============================================================
// 11. INTERPRETING pH
// ============================================================

add(
  "chemistry",
  "acids_bases_salts",
  "Interpreting pH",
  `<h2>Interpreting pH</h2>
  <p>The pH value allows solutions to be compared according to their acidity or alkalinity.</p>

  <h3>Examples</h3>
  <p>pH 2 is strongly acidic.</p>
  <p>pH 5 is weakly acidic.</p>
  <p>pH 7 is neutral.</p>
  <p>pH 9 is weakly alkaline.</p>
  <p>pH 13 is strongly alkaline.</p>

  <p>For the same type of aqueous solution, a decrease in pH indicates increasing acidity, while an increase indicates increasing alkalinity.</p>`,
  [
    {
      q: "Which solution is more acidic: pH 3 or pH 6?",
      steps: [
        "Step 1: Both solutions are acidic because both pH values are below 7.",
        "Step 2: Compare the values.",
        "Step 3: pH 3 is lower than pH 6."
      ],
      ans: "The pH 3 solution is more acidic.",
      why: "Lower pH indicates greater acidity."
    },
    {
      q: "Which solution is more alkaline: pH 8 or pH 12?",
      steps: [
        "Step 1: Both are above 7 and therefore alkaline.",
        "Step 2: Compare the values.",
        "Step 3: pH 12 is higher."
      ],
      ans: "The pH 12 solution is more alkaline.",
      why: "Higher pH indicates greater alkalinity."
    },
    {
      q: "Arrange these from most acidic to most alkaline: pH 11, pH 3, pH 7, pH 5.",
      steps: [
        "Step 1: The lowest pH is the most acidic.",
        "Step 2: Order the values from lowest to highest.",
        "Step 3: 3 < 5 < 7 < 11."
      ],
      ans: "pH 3, pH 5, pH 7, pH 11.",
      why: "Moving from low to high pH moves from acidic through neutral to alkaline."
    }
  ],
  [
    {
      q: "A solution changes from pH 4 to pH 2. Has its acidity increased or decreased?",
      hint: "Compare the two pH values.",
      steps: [
        "Step 1: The pH decreases from 4 to 2.",
        "Step 2: Lower pH means greater acidity."
      ],
      ans: "Its acidity has increased.",
      why: "A decrease in pH indicates increased acidity."
    }
  ]
);


// ============================================================
// 12. STRONG AND WEAK ACIDS
// ============================================================

add(
  "chemistry",
  "acids_bases_salts",
  "Strong and Weak Acids",
  `<h2>Strong and Weak Acids</h2>
  <p>A strong acid ionises extensively in water, producing a high concentration of hydrogen ions.</p>

  <p>A weak acid ionises only partially in water.</p>

  <h3>Examples</h3>
  <ul>
    <li>Hydrochloric acid — strong acid</li>
    <li>Sulphuric(VI) acid — strong acid</li>
    <li>Ethanoic acid — weak acid</li>
  </ul>

  <p>Strength is not the same as concentration. A dilute strong acid can have a lower concentration than a concentrated weak acid.</p>`,
  [
    {
      q: "What is a strong acid?",
      steps: [
        "Step 1: Consider what happens when the acid dissolves in water.",
        "Step 2: A strong acid ionises extensively.",
        "Step 3: This produces a high concentration of H⁺ ions."
      ],
      ans: "A strong acid is an acid that ionises extensively in water.",
      why: "Extensive ionisation produces many hydrogen ions in solution."
    },
    {
      q: "What is a weak acid?",
      steps: [
        "Step 1: A weak acid is dissolved in water.",
        "Step 2: Only part of its molecules ionise.",
        "Step 3: Therefore ionisation is incomplete."
      ],
      ans: "A weak acid is an acid that ionises only partially in water.",
      why: "Weak acids establish an equilibrium between ionised and unionised molecules."
    },
    {
      q: "Is ethanoic acid strong or weak?",
      steps: [
        "Step 1: Ethanoic acid is CH₃COOH.",
        "Step 2: It ionises only partially in water.",
        "Step 3: Therefore it is a weak acid."
      ],
      ans: "Weak acid.",
      why: "Ethanoic acid undergoes partial ionisation in water."
    }
  ],
  [
    {
      q: "Explain why a strong acid is not necessarily more concentrated than a weak acid.",
      hint: "Separate the ideas of strength and concentration.",
      steps: [
        "Step 1: Strength describes the extent of ionisation.",
        "Step 2: Concentration describes the amount of solute in a given volume.",
        "Step 3: Therefore they describe different properties."
      ],
      ans: "Strength describes ionisation, while concentration describes the amount of acid dissolved per unit volume.",
      why: "A dilute strong acid and a concentrated weak acid can exist."
    }
  ]
);


// ============================================================
// 13. STRONG AND WEAK BASES
// ============================================================

add(
  "chemistry",
  "acids_bases_salts",
  "Strong and Weak Bases",
  `<h2>Strong and Weak Bases</h2>
  <p>A strong base ionises extensively in water and produces a high concentration of hydroxide ions.</p>

  <p>A weak base reacts or ionises only partially in water.</p>

  <h3>Examples</h3>
  <ul>
    <li>Sodium hydroxide — strong base</li>
    <li>Potassium hydroxide — strong base</li>
    <li>Aqueous ammonia — weak base</li>
  </ul>`,
  [
    {
      q: "What is a strong base?",
      steps: [
        "Step 1: A strong base is placed in water.",
        "Step 2: It ionises extensively.",
        "Step 3: It produces a high concentration of OH⁻ ions."
      ],
      ans: "A base that ionises extensively in water and produces a high concentration of hydroxide ions.",
      why: "Extensive ionisation produces many hydroxide ions."
    },
    {
      q: "What is a weak base?",
      steps: [
        "Step 1: A weak base interacts with water.",
        "Step 2: Ionisation is only partial.",
        "Step 3: Therefore fewer hydroxide ions are produced than by a comparable strong base."
      ],
      ans: "A base that ionises only partially in water.",
      why: "Weak bases do not ionise completely in aqueous solution."
    },
    {
      q: "Is aqueous ammonia a strong or weak base?",
      steps: [
        "Step 1: Ammonia reacts partially with water.",
        "Step 2: It does not ionise completely.",
        "Step 3: Therefore it is a weak base."
      ],
      ans: "Weak base.",
      why: "Aqueous ammonia is only partially ionised in water."
    }
  ],
  [
    {
      q: "State the difference between a strong base and a weak base.",
      hint: "Compare their ionisation in water.",
      steps: [
        "Step 1: Strong bases ionise extensively.",
        "Step 2: Weak bases ionise partially.",
        "Step 3: Therefore the extent of ionisation distinguishes them."
      ],
      ans: "A strong base ionises extensively in water, while a weak base ionises only partially.",
      why: "The difference is based on the extent of ionisation."
    }
  ]
);


// ============================================================
// 14. NEUTRALISATION
// ============================================================

add(
  "chemistry",
  "acids_bases_salts",
  "Neutralisation",
  `<h2>Neutralisation</h2>
  <p>Neutralisation occurs when an acid reacts with a base or alkali to form a salt and water.</p>

  <p><strong>Acid + Base → Salt + Water</strong></p>

  <h3>Ionic idea</h3>
  <p>In a simple strong acid–strong alkali reaction:</p>
  <p><strong>H<sup>+</sup>(aq) + OH<sup>−</sup>(aq) → H<sub>2</sub>O(l)</strong></p>

  <p>The hydrogen ions from the acid combine with hydroxide ions from the alkali to form water.</p>`,
  [
    {
      q: "Define neutralisation.",
      steps: [
        "Step 1: An acid reacts with a base or alkali.",
        "Step 2: A salt is formed.",
        "Step 3: Water is also formed."
      ],
      ans: "Neutralisation is the reaction of an acid with a base or alkali to form salt and water.",
      why: "The acidic and alkaline properties are neutralised."
    },
    {
      q: "Write the ionic equation for neutralisation between a strong acid and a strong alkali.",
      steps: [
        "Step 1: Acids provide H⁺ ions.",
        "Step 2: Alkalis provide OH⁻ ions.",
        "Step 3: These ions combine to form water."
      ],
      ans: "H⁺(aq) + OH⁻(aq) → H₂O(l)",
      why: "This represents the essential chemical change in strong acid–strong alkali neutralisation."
    },
    {
      q: "Write the balanced equation for nitric acid reacting with sodium hydroxide.",
      steps: [
        "Step 1: Nitric acid = HNO₃.",
        "Step 2: Sodium hydroxide = NaOH.",
        "Step 3: The salt is sodium nitrate, NaNO₃.",
        "Step 4: Water is formed.",
        "Step 5: The equation is already balanced."
      ],
      ans: "HNO₃ + NaOH → NaNO₃ + H₂O",
      why: "The acid and alkali react in a 1:1 ratio."
    }
  ],
  [
    {
      q: "What ions react directly during neutralisation?",
      hint: "Think about the ions supplied by acids and alkalis.",
      steps: [
        "Step 1: Acids supply H⁺.",
        "Step 2: Alkalis supply OH⁻.",
        "Step 3: H⁺ combines with OH⁻."
      ],
      ans: "H⁺ and OH⁻ ions.",
      why: "These ions combine to form water."
    }
  ]
);


// ============================================================
// 15. SOLUBLE SALTS
// ============================================================

add(
  "chemistry",
  "acids_bases_salts",
  "Soluble Salts",
  `<h2>Soluble Salts</h2>
  <p>A soluble salt is a salt that dissolves in water to form an aqueous solution.</p>

  <p>Examples include sodium chloride, potassium nitrate and copper(II) sulphate.</p>

  <p>Soluble salts can be prepared using suitable reactions followed by crystallisation or evaporation of water.</p>`,
  [
    {
      q: "What is a soluble salt?",
      steps: [
        "Step 1: Consider what happens when the salt is added to water.",
        "Step 2: If it dissolves, it forms an aqueous solution.",
        "Step 3: Such a salt is called soluble."
      ],
      ans: "A salt that dissolves in water.",
      why: "Solubility refers to the ability of a substance to dissolve in a solvent."
    },
    {
      q: "Give two examples of soluble salts.",
      steps: [
        "Step 1: Sodium chloride dissolves in water.",
        "Step 2: Copper(II) sulphate also dissolves in water."
      ],
      ans: "Sodium chloride and copper(II) sulphate.",
      why: "Both form aqueous solutions when dissolved in water."
    },
    {
      q: "Why can a soluble salt be obtained by crystallisation?",
      steps: [
        "Step 1: Dissolve the salt in water.",
        "Step 2: Concentrate the solution by removing some water.",
        "Step 3: On cooling, crystals of the salt can form."
      ],
      ans: "Because the salt can dissolve in water and crystallise as the solution becomes concentrated and cools.",
      why: "Crystallisation separates a dissolved solid from its solution."
    }
  ],
  [
    {
      q: "Is sodium chloride soluble in water?",
      hint: "Consider ordinary table salt.",
      steps: [
        "Step 1: Sodium chloride is common table salt.",
        "Step 2: It dissolves in water.",
        "Step 3: Therefore it is soluble."
      ],
      ans: "Yes.",
      why: "Sodium chloride dissolves in water to form an aqueous solution."
    }
  ]
);


// ============================================================
// 16. INSOLUBLE SALTS
// ============================================================

add(
  "chemistry",
  "acids_bases_salts",
  "Insoluble Salts",
  `<h2>Insoluble Salts</h2>
  <p>An insoluble salt does not dissolve appreciably in water.</p>

  <p>Insoluble salts can often be prepared by mixing two soluble solutions so that an insoluble product forms as a <strong>precipitate</strong>.</p>

  <h3>Example</h3>
  <p>Lead(II) nitrate reacts with sodium chloride:</p>

  <p><strong>Pb(NO<sub>3</sub>)<sub>2</sub>(aq) + 2NaCl(aq) → PbCl<sub>2</sub>(s) + 2NaNO<sub>3</sub>(aq)</strong></p>

  <p>Lead(II) chloride is the insoluble precipitate.</p>`,
  [
    {
      q: "What is an insoluble salt?",
      steps: [
        "Step 1: Add the salt to water.",
        "Step 2: If it does not dissolve appreciably, it is insoluble.",
        "Step 3: Therefore its solid remains present."
      ],
      ans: "A salt that does not dissolve appreciably in water.",
      why: "Its low solubility means that much of the salt remains as a solid."
    },
    {
      q: "What is a precipitate?",
      steps: [
        "Step 1: Two aqueous solutions are mixed.",
        "Step 2: A new insoluble substance may form.",
        "Step 3: The insoluble solid is called a precipitate."
      ],
      ans: "An insoluble solid formed during a reaction in solution.",
      why: "The product comes out of solution as a solid."
    },
    {
      q: "Identify the precipitate in: Pb(NO₃)₂(aq) + 2NaCl(aq) → PbCl₂(s) + 2NaNO₃(aq).",
      steps: [
        "Step 1: Look for the product marked (s).",
        "Step 2: PbCl₂ is marked (s).",
        "Step 3: Therefore PbCl₂ is the precipitate."
      ],
      ans: "Lead(II) chloride, PbCl₂.",
      why: "The solid product is the insoluble precipitate."
    }
  ],
  [
    {
      q: "What method is used to separate an insoluble salt formed as a precipitate from the solution?",
      hint: "The solid must be separated from a liquid.",
      steps: [
        "Step 1: The insoluble salt is a solid.",
        "Step 2: The remaining solution is liquid.",
        "Step 3: Filtration separates the solid from the liquid."
      ],
      ans: "Filtration.",
      why: "Filtration separates an insoluble solid from a liquid."
    }
  ]
);


// ============================================================
// 17. PREPARATION OF SOLUBLE SALTS USING AN ACID AND METAL
// ============================================================

add(
  "chemistry",
  "acids_bases_salts",
  "Preparing Soluble Salts from Acids and Metals",
  `<h2>Preparing Soluble Salts from Acids and Metals</h2>
  <p>A soluble salt can be prepared by reacting a suitable acid with an excess of a reactive metal.</p>

  <h3>General method</h3>
  <ol>
    <li>Place the dilute acid in a suitable container.</li>
    <li>Add the metal gradually.</li>
    <li>Continue until no more metal reacts.</li>
    <li>Filter off excess metal.</li>
    <li>Concentrate the solution.</li>
    <li>Cool to allow crystals to form.</li>
    <li>Filter and dry the crystals.</li>
  </ol>

  <h3>Example</h3>
  <p>Mg + 2HCl → MgCl₂ + H₂</p>`,
  [
    {
      q: "Why is excess metal added when preparing a soluble salt using an acid and metal?",
      steps: [
        "Step 1: The aim is to ensure that all the acid reacts.",
        "Step 2: Adding excess metal ensures that acid is not left unreacted.",
        "Step 3: The excess metal can be removed by filtration."
      ],
      ans: "To ensure that all the acid reacts; the excess metal can then be removed by filtration.",
      why: "This prevents excess acid from remaining in the salt solution."
    },
    {
      q: "What method is used to remove excess metal after the reaction?",
      steps: [
        "Step 1: The metal is insoluble and remains solid.",
        "Step 2: The salt is dissolved in the solution.",
        "Step 3: Filtration removes the excess solid metal."
      ],
      ans: "Filtration.",
      why: "Filtration separates the unreacted solid metal from the salt solution."
    },
    {
      q: "Why is the salt solution concentrated before crystallisation?",
      steps: [
        "Step 1: A dilute solution contains a large amount of water.",
        "Step 2: Some water is evaporated.",
        "Step 3: The solution becomes more concentrated.",
        "Step 4: Crystals can then form more readily on cooling."
      ],
      ans: "To increase the concentration of the dissolved salt so that crystals can form on cooling.",
      why: "Crystallisation requires a sufficiently concentrated solution."
    }
  ],
  [
    {
      q: "Outline the main steps for preparing magnesium chloride crystals from magnesium and dilute hydrochloric acid.",
      hint: "Think reaction → filtration → concentration → crystallisation.",
      steps: [
        "Step 1: Add excess magnesium to dilute hydrochloric acid.",
        "Step 2: Allow the reaction to finish.",
        "Step 3: Filter off excess magnesium.",
        "Step 4: Concentrate the filtrate.",
        "Step 5: Cool to form crystals.",
        "Step 6: Filter and dry the crystals."
      ],
      ans: "React excess magnesium with dilute HCl, filter excess magnesium, concentrate the solution, cool to crystallise, then filter and dry the crystals.",
      why: "These steps produce relatively pure magnesium chloride crystals."
    }
  ]
);


// ============================================================
// 18. PREPARATION OF SOLUBLE SALTS USING AN INSOLUBLE BASE
// ============================================================

add(
  "chemistry",
  "acids_bases_salts",
  "Preparing Soluble Salts from Insoluble Bases",
  `<h2>Preparing Soluble Salts from Insoluble Bases</h2>
  <p>An insoluble metal oxide or hydroxide can react with an acid to prepare a soluble salt.</p>

  <h3>Example</h3>
  <p>To prepare copper(II) sulphate:</p>
  <p><strong>CuO + H₂SO₄ → CuSO₄ + H₂O</strong></p>

  <h3>Method</h3>
  <ol>
    <li>Warm dilute acid gently.</li>
    <li>Add the insoluble base in small portions.</li>
    <li>Continue until no more base reacts.</li>
    <li>Filter off excess base.</li>
    <li>Concentrate the solution.</li>
    <li>Cool to form crystals.</li>
    <li>Filter and dry the crystals.</li>
  </ol>`,
  [
    {
      q: "Why is an insoluble base added in excess?",
      steps: [
        "Step 1: The aim is to use up all the acid.",
        "Step 2: Excess insoluble base remains as a solid.",
        "Step 3: The excess can be removed by filtration."
      ],
      ans: "To ensure that all the acid reacts; the excess insoluble base can then be filtered off.",
      why: "This prevents excess acid from contaminating the salt solution."
    },
    {
      q: "Write the equation for preparing copper(II) sulphate from copper(II) oxide and sulphuric(VI) acid.",
      steps: [
        "Step 1: CuO is copper(II) oxide.",
        "Step 2: H₂SO₄ is sulphuric(VI) acid.",
        "Step 3: The salt formed is CuSO₄.",
        "Step 4: Water is also formed."
      ],
      ans: "CuO + H₂SO₄ → CuSO₄ + H₂O",
      why: "The basic copper(II) oxide neutralises sulphuric(VI) acid."
    },
    {
      q: "Why is filtration necessary after adding excess copper(II) oxide?",
      steps: [
        "Step 1: Copper(II) oxide is insoluble.",
        "Step 2: Any excess remains as a solid.",
        "Step 3: Filtration removes the solid from the copper(II) sulphate solution."
      ],
      ans: "To remove excess insoluble copper(II) oxide from the salt solution.",
      why: "Filtration separates the unreacted solid from the soluble salt solution."
    }
  ],
  [
    {
      q: "Which type of salt can be prepared using an insoluble metal oxide and an acid?",
      hint: "Consider whether the resulting salt can remain in solution.",
      steps: [
        "Step 1: The acid reacts with the insoluble base.",
        "Step 2: A salt and water are formed.",
        "Step 3: If the salt is soluble, it remains in solution."
      ],
      ans: "A soluble salt.",
      why: "The soluble salt remains dissolved after the insoluble base is removed."
    }
  ]
);


// ============================================================
// 19. PREPARATION OF SOLUBLE SALTS USING AN ACID AND CARBONATE
// ============================================================

add(
  "chemistry",
  "acids_bases_salts",
  "Preparing Soluble Salts from Acids and Carbonates",
  `<h2>Preparing Soluble Salts from Acids and Carbonates</h2>
  <p>Soluble salts can be prepared by reacting an acid with a suitable carbonate.</p>

  <p><strong>Acid + Carbonate → Salt + Water + Carbon dioxide</strong></p>

  <h3>Example</h3>
  <p>Calcium carbonate reacts with nitric acid:</p>
  <p><strong>CaCO₃ + 2HNO₃ → Ca(NO₃)₂ + H₂O + CO₂</strong></p>

  <p>An excess of the carbonate is used so that all the acid reacts. The excess solid is then filtered off.</p>`,
  [
    {
      q: "Why is an excess carbonate used when preparing a soluble salt?",
      steps: [
        "Step 1: The carbonate is added to the acid.",
        "Step 2: Excess carbonate ensures that all the acid reacts.",
        "Step 3: The remaining solid carbonate can be removed by filtration."
      ],
      ans: "To ensure that all the acid reacts; excess carbonate can then be filtered off.",
      why: "This prevents unreacted acid from remaining in the salt solution."
    },
    {
      q: "Write the equation for calcium carbonate reacting with nitric acid.",
      steps: [
        "Step 1: Calcium carbonate = CaCO₃.",
        "Step 2: Nitric acid = HNO₃.",
        "Step 3: Calcium nitrate = Ca(NO₃)₂.",
        "Step 4: Water and carbon dioxide are also formed.",
        "Step 5: Balance the equation."
      ],
      ans: "CaCO₃ + 2HNO₃ → Ca(NO₃)₂ + H₂O + CO₂",
      why: "Two nitric acid molecules are needed to provide the two nitrate ions in calcium nitrate."
    },
    {
      q: "How do you know that the reaction between an acid and carbonate has finished?",
      steps: [
        "Step 1: Carbonate reacts with acid and produces carbon dioxide.",
        "Step 2: While acid remains, added carbonate continues to fizz.",
        "Step 3: When no more fizzing occurs after adding carbonate, the acid has been used up."
      ],
      ans: "Fizzing stops when no more acid remains to react.",
      why: "The absence of further carbon dioxide production indicates that the acid has been consumed."
    }
  ],
  [
    {
      q: "What gas must be removed or allowed to escape during this salt preparation?",
      hint: "Acid + carbonate produces three products.",
      steps: [
        "Step 1: Acid + carbonate produces salt, water and carbon dioxide.",
        "Step 2: Carbon dioxide is a gas.",
        "Step 3: It escapes from the reaction mixture."
      ],
      ans: "Carbon dioxide.",
      why: "Carbon dioxide is produced during the reaction."
    }
  ]
);


// ============================================================
// 20. TITRATION
// ============================================================

add(
  "chemistry",
  "acids_bases_salts",
  "Titration",
  `<h2>Titration</h2>
  <p>Titration is a laboratory method used to determine the volume of one solution required to react completely with a measured volume of another solution.</p>

  <h3>Main apparatus</h3>
  <ul>
    <li>Burette</li>
    <li>Pipette</li>
    <li>Conical flask</li>
    <li>Indicator</li>
  </ul>

  <h3>Basic procedure</h3>
  <ol>
    <li>Use a pipette to transfer a known volume of one solution into a conical flask.</li>
    <li>Add a suitable indicator.</li>
    <li>Fill the burette with the other solution.</li>
    <li>Record the initial burette reading.</li>
    <li>Add the solution from the burette while swirling the flask.</li>
    <li>Stop at the end point indicated by the indicator colour change.</li>
    <li>Record the final burette reading.</li>
    <li>Calculate the titre.</li>
  </ol>

  <p><strong>Titre = final burette reading − initial burette reading</strong></p>`,
  [
    {
      q: "What is titration used for?",
      steps: [
        "Step 1: A known volume of one solution is measured.",
        "Step 2: Another solution is added until the reaction is complete.",
        "Step 3: The volume required is measured."
      ],
      ans: "Titration is used to determine the volume of one solution required to react completely with a known volume of another solution.",
      why: "The measured volume can be used to calculate unknown quantities or concentrations."
    },
    {
      q: "A burette reading is 0.20 cm³ initially and 24.60 cm³ finally. Calculate the titre.",
      steps: [
        "Step 1: Use titre = final reading − initial reading.",
        "Step 2: Titre = 24.60 − 0.20.",
        "Step 3: Titre = 24.40 cm³."
      ],
      ans: "24.40 cm³",
      why: "The titre is the volume delivered from the burette."
    },
    {
      q: "Why is an indicator used during titration?",
      steps: [
        "Step 1: The reaction reaches an end point.",
        "Step 2: The indicator changes colour near the end point.",
        "Step 3: This allows the experimenter to know when to stop adding the burette solution."
      ],
      ans: "To show the end point of the reaction by a colour change.",
      why: "The indicator provides a visible signal that the required reaction point has been reached."
    }
  ],
  [
    {
      q: "A burette has an initial reading of 1.10 cm³ and a final reading of 25.35 cm³. Calculate the titre.",
      hint: "Titre = final reading − initial reading.",
      steps: [
        "Step 1: Final reading = 25.35 cm³.",
        "Step 2: Initial reading = 1.10 cm³.",
        "Step 3: Titre = 25.35 − 1.10.",
        "Step 4: Titre = 24.25 cm³."
      ],
      ans: "24.25 cm³",
      why: "The titre is the volume of solution delivered from the burette."
    }
  ]
);
// ============================================================
// BATCH 13 — ENERGY AND RATE OF REACTION
// Chapter: energy_rate_reaction
// One concept per screen
// No multiple-choice questions
// ============================================================


// ============================================================
// 1. EXOTHERMIC REACTIONS
// ============================================================

add(
  "chemistry",
  "energy_rate_reaction",
  "Exothermic Reactions",
  `<h2>Exothermic Reactions</h2>
  <p>An exothermic reaction is a chemical reaction that releases energy to the surroundings, usually as heat.</p>

  <p>Because heat is released, the temperature of the surroundings usually increases.</p>

  <h3>Examples</h3>
  <ul>
    <li>Combustion of fuels</li>
    <li>Neutralisation of an acid by an alkali</li>
    <li>Many oxidation reactions</li>
  </ul>

  <p>For an exothermic reaction:</p>
  <p><strong>Energy released to surroundings &gt; energy absorbed from surroundings</strong></p>`,
  [
    {
      q: "What is an exothermic reaction?",
      steps: [
        "Step 1: Consider the energy change during the reaction.",
        "Step 2: Energy is transferred from the reacting system to the surroundings.",
        "Step 3: Therefore the reaction releases energy."
      ],
      ans: "An exothermic reaction is a reaction that releases energy to the surroundings.",
      why: "The surroundings receive energy from the reacting substances."
    },
    {
      q: "What happens to the temperature of the surroundings during an exothermic reaction?",
      steps: [
        "Step 1: An exothermic reaction releases energy.",
        "Step 2: Some of this energy is transferred as heat.",
        "Step 3: The surroundings therefore become warmer."
      ],
      ans: "The temperature of the surroundings increases.",
      why: "Heat is transferred from the reaction to the surroundings."
    },
    {
      q: "Give two examples of exothermic reactions.",
      steps: [
        "Step 1: Combustion releases energy.",
        "Step 2: Acid-alkali neutralisation also releases energy."
      ],
      ans: "Combustion and acid-alkali neutralisation.",
      why: "Both processes release energy to their surroundings."
    }
  ],
  [
    {
      q: "A reaction causes the temperature of the surrounding solution to rise from 22°C to 31°C. Is the reaction likely to be exothermic or endothermic?",
      hint: "Look at whether heat has entered or left the surroundings.",
      steps: [
        "Step 1: The temperature increased.",
        "Step 2: This means heat was transferred to the surroundings.",
        "Step 3: A reaction that releases heat is exothermic."
      ],
      ans: "Exothermic.",
      why: "The rise in surrounding temperature indicates that energy was released."
    }
  ]
);


// ============================================================
// 2. ENDOTHERMIC REACTIONS
// ============================================================

add(
  "chemistry",
  "energy_rate_reaction",
  "Endothermic Reactions",
  `<h2>Endothermic Reactions</h2>
  <p>An endothermic reaction is a chemical reaction that absorbs energy from the surroundings.</p>

  <p>The absorbed energy is often transferred as heat, causing the surroundings to become cooler.</p>

  <h3>Examples</h3>
  <ul>
    <li>Thermal decomposition of calcium carbonate</li>
    <li>Some reactions between salts and water</li>
    <li>Photosynthesis</li>
  </ul>

  <p>For an endothermic reaction, energy is transferred from the surroundings into the reacting system.</p>`,
  [
    {
      q: "What is an endothermic reaction?",
      steps: [
        "Step 1: Consider the direction of energy transfer.",
        "Step 2: Energy is absorbed by the reacting system.",
        "Step 3: Therefore the reaction is endothermic."
      ],
      ans: "An endothermic reaction is a reaction that absorbs energy from the surroundings.",
      why: "Energy must enter the reacting system for the reaction to occur."
    },
    {
      q: "What usually happens to the temperature of the surroundings during an endothermic reaction?",
      steps: [
        "Step 1: The reaction absorbs energy from the surroundings.",
        "Step 2: The surroundings lose thermal energy.",
        "Step 3: Their temperature usually decreases."
      ],
      ans: "The temperature of the surroundings decreases.",
      why: "Heat is transferred from the surroundings into the reaction."
    },
    {
      q: "Is thermal decomposition of calcium carbonate endothermic or exothermic?",
      steps: [
        "Step 1: Calcium carbonate requires heating to decompose.",
        "Step 2: Energy must be supplied to the reaction.",
        "Step 3: Therefore the decomposition is endothermic."
      ],
      ans: "Endothermic.",
      why: "Energy is absorbed during the thermal decomposition."
    }
  ],
  [
    {
      q: "A reaction causes the temperature of the surrounding water to fall from 25°C to 18°C. What type of reaction is this?",
      hint: "The surroundings have lost heat.",
      steps: [
        "Step 1: The temperature decreased.",
        "Step 2: Heat has been removed from the surroundings.",
        "Step 3: The reaction absorbed that energy."
      ],
      ans: "Endothermic.",
      why: "An endothermic reaction absorbs energy from the surroundings."
    }
  ]
);


// ============================================================
// 3. ENERGY PROFILE DIAGRAMS
// ============================================================

add(
  "chemistry",
  "energy_rate_reaction",
  "Energy Profile Diagrams",
  `<h2>Energy Profile Diagrams</h2>
  <p>An energy profile diagram shows how the energy of a reaction changes from reactants to products.</p>

  <h3>Important features</h3>
  <ul>
    <li>Reactant energy</li>
    <li>Product energy</li>
    <li>Activation energy</li>
    <li>Overall energy change</li>
  </ul>

  <p>In an exothermic reaction, the products are at a lower energy level than the reactants.</p>

  <p>In an endothermic reaction, the products are at a higher energy level than the reactants.</p>`,
  [
    {
      q: "What does an energy profile diagram show?",
      steps: [
        "Step 1: The diagram represents energy during a reaction.",
        "Step 2: It shows the energy level of reactants and products.",
        "Step 3: It also shows the energy barrier between them."
      ],
      ans: "It shows the energy changes that occur as reactants are converted into products.",
      why: "The diagram allows the energy change and activation energy to be identified."
    },
    {
      q: "Where are the products located relative to the reactants in an exothermic energy profile?",
      steps: [
        "Step 1: An exothermic reaction releases energy.",
        "Step 2: The products therefore contain less chemical energy than the reactants.",
        "Step 3: Products are drawn at a lower energy level."
      ],
      ans: "The products are at a lower energy level than the reactants.",
      why: "Energy has been released during the reaction."
    },
    {
      q: "Where are the products located relative to the reactants in an endothermic energy profile?",
      steps: [
        "Step 1: An endothermic reaction absorbs energy.",
        "Step 2: The products therefore have more chemical energy than the reactants.",
        "Step 3: Products are drawn at a higher energy level."
      ],
      ans: "The products are at a higher energy level than the reactants.",
      why: "Energy has been absorbed by the reaction."
    }
  ],
  [
    {
      q: "On an energy profile, the products are 40 kJ lower than the reactants. What type of reaction is represented?",
      hint: "Products are at a lower energy level.",
      steps: [
        "Step 1: Compare product energy with reactant energy.",
        "Step 2: Products are lower by 40 kJ.",
        "Step 3: Energy has been released."
      ],
      ans: "Exothermic reaction.",
      why: "Products having lower energy than reactants indicates an overall release of energy."
    }
  ]
);


// ============================================================
// 4. ACTIVATION ENERGY
// ============================================================

add(
  "chemistry",
  "energy_rate_reaction",
  "Activation Energy",
  `<h2>Activation Energy</h2>
  <p>Activation energy is the minimum energy that reacting particles must have for a successful chemical reaction to occur.</p>

  <p>Particles must collide with enough energy to overcome the energy barrier before new bonds can form and old bonds can break.</p>

  <h3>Important idea</h3>
  <p>A reaction can release energy overall and still require activation energy to start.</p>

  <p>For example, a fuel releases energy when it burns, but it normally requires a spark or flame to initiate combustion.</p>`,
  [
    {
      q: "What is activation energy?",
      steps: [
        "Step 1: Reacting particles must collide.",
        "Step 2: The collision must have enough energy.",
        "Step 3: The minimum required energy is called activation energy."
      ],
      ans: "Activation energy is the minimum energy required for reacting particles to undergo a successful reaction.",
      why: "Particles need sufficient energy to overcome the energy barrier to reaction."
    },
    {
      q: "Why does a fuel require a spark before it burns?",
      steps: [
        "Step 1: Combustion requires activation energy.",
        "Step 2: The spark supplies enough energy to start the reaction.",
        "Step 3: Once started, the combustion can release energy."
      ],
      ans: "The spark supplies the activation energy needed to start combustion.",
      why: "The reaction cannot begin effectively until particles have enough energy to overcome the activation barrier."
    },
    {
      q: "Does an exothermic reaction require activation energy?",
      steps: [
        "Step 1: Exothermic describes the overall energy change.",
        "Step 2: Activation energy describes the energy barrier that must be overcome.",
        "Step 3: Therefore an exothermic reaction can still require activation energy."
      ],
      ans: "Yes. An exothermic reaction can still require activation energy.",
      why: "Overall energy release and activation energy describe different parts of the reaction."
    }
  ],
  [
    {
      q: "A reaction has an activation energy of 80 kJ mol⁻¹. What does this value mean?",
      hint: "Activation energy is the minimum energy needed for successful reaction.",
      steps: [
        "Step 1: Identify the value: 80 kJ mol⁻¹.",
        "Step 2: It represents the minimum energy barrier for the reacting particles.",
        "Step 3: Particles must have sufficient energy to overcome it."
      ],
      ans: "The reacting particles require at least 80 kJ mol⁻¹ of energy to overcome the activation barrier.",
      why: "Activation energy is the minimum energy required for successful reaction."
    }
  ]
);


// ============================================================
// 5. SPECIFIC HEAT CAPACITY
// ============================================================

add(
  "chemistry",
  "energy_rate_reaction",
  "Specific Heat Capacity",
  `<h2>Specific Heat Capacity</h2>
  <p>Specific heat capacity is the amount of heat energy required to raise the temperature of 1 kg of a substance by 1°C.</p>

  <p>The symbol for specific heat capacity is <strong>c</strong>.</p>

  <p>The relationship is:</p>

  <p><strong>Q = mcΔT</strong></p>

  <ul>
    <li>Q = heat energy in joules (J)</li>
    <li>m = mass in kilograms (kg)</li>
    <li>c = specific heat capacity in J kg⁻¹ °C⁻¹</li>
    <li>ΔT = temperature change in °C</li>
  </ul>`,
  [
    {
      q: "Define specific heat capacity.",
      steps: [
        "Step 1: Consider a mass of 1 kg.",
        "Step 2: Consider increasing its temperature by 1°C.",
        "Step 3: The heat required is its specific heat capacity."
      ],
      ans: "The amount of heat energy required to raise the temperature of 1 kg of a substance by 1°C.",
      why: "Specific heat capacity measures how much thermal energy a substance requires for a given temperature rise."
    },
    {
      q: "State the formula used to calculate heat energy from specific heat capacity.",
      steps: [
        "Step 1: Identify the quantities involved: mass, specific heat capacity and temperature change.",
        "Step 2: Combine them using the heat equation."
      ],
      ans: "Q = mcΔT",
      why: "The heat energy depends on mass, specific heat capacity and temperature change."
    },
    {
      q: "What unit is commonly used for specific heat capacity?",
      steps: [
        "Step 1: Heat energy is measured in joules.",
        "Step 2: Mass is measured in kilograms.",
        "Step 3: Temperature change is measured in degrees Celsius."
      ],
      ans: "J kg⁻¹ °C⁻¹",
      why: "The unit represents joules required per kilogram per degree Celsius."
    }
  ],
  [
    {
      q: "Calculate the heat required to raise the temperature of 2 kg of water by 5°C if c = 4200 J kg⁻¹ °C⁻¹.",
      hint: "Use Q = mcΔT.",
      steps: [
        "Step 1: m = 2 kg.",
        "Step 2: c = 4200 J kg⁻¹ °C⁻¹.",
        "Step 3: ΔT = 5°C.",
        "Step 4: Q = mcΔT.",
        "Step 5: Q = 2 × 4200 × 5.",
        "Step 6: Q = 42,000 J."
      ],
      ans: "42,000 J",
      why: "The heat energy is found by multiplying mass, specific heat capacity and temperature change."
    }
  ]
);


// ============================================================
// 6. HEAT ENERGY CALCULATIONS
// ============================================================

add(
  "chemistry",
  "energy_rate_reaction",
  "Heat Energy Calculations",
  `<h2>Heat Energy Calculations</h2>
  <p>Heat energy calculations use the relationship:</p>

  <p><strong>Q = mcΔT</strong></p>

  <p>Always check that the mass is in kilograms when using the SI form of the formula.</p>

  <h3>Rearranging the formula</h3>
  <p><strong>Q = mcΔT</strong></p>
  <p><strong>m = Q ÷ (cΔT)</strong></p>
  <p><strong>c = Q ÷ (mΔT)</strong></p>
  <p><strong>ΔT = Q ÷ (mc)</strong></p>`,
  [
    {
      q: "Calculate the heat required to raise 0.5 kg of water from 20°C to 60°C. Take c = 4200 J kg⁻¹ °C⁻¹.",
      steps: [
        "Step 1: m = 0.5 kg.",
        "Step 2: Temperature change = 60 − 20 = 40°C.",
        "Step 3: c = 4200 J kg⁻¹ °C⁻¹.",
        "Step 4: Q = mcΔT.",
        "Step 5: Q = 0.5 × 4200 × 40.",
        "Step 6: Q = 84,000 J."
      ],
      ans: "84,000 J",
      why: "The temperature change is 40°C, so Q = 0.5 × 4200 × 40."
    },
    {
      q: "A substance absorbs 18,000 J of heat. Its mass is 2 kg and its temperature rises by 10°C. Calculate its specific heat capacity.",
      steps: [
        "Step 1: Q = 18,000 J.",
        "Step 2: m = 2 kg.",
        "Step 3: ΔT = 10°C.",
        "Step 4: c = Q ÷ (mΔT).",
        "Step 5: c = 18,000 ÷ (2 × 10).",
        "Step 6: c = 900 J kg⁻¹ °C⁻¹."
      ],
      ans: "900 J kg⁻¹ °C⁻¹",
      why: "Specific heat capacity is calculated by dividing heat energy by mass and temperature change."
    },
    {
      q: "A 1 kg substance has a specific heat capacity of 500 J kg⁻¹ °C⁻¹ and absorbs 10,000 J. Calculate its temperature rise.",
      steps: [
        "Step 1: Q = 10,000 J.",
        "Step 2: m = 1 kg.",
        "Step 3: c = 500 J kg⁻¹ °C⁻¹.",
        "Step 4: ΔT = Q ÷ (mc).",
        "Step 5: ΔT = 10,000 ÷ (1 × 500).",
        "Step 6: ΔT = 20°C."
      ],
      ans: "20°C",
      why: "The temperature rise depends on the energy supplied, mass and specific heat capacity."
    }
  ],
  [
    {
      q: "A 0.2 kg sample is heated from 25°C to 75°C. If c = 1000 J kg⁻¹ °C⁻¹, calculate the heat absorbed.",
      hint: "First calculate ΔT.",
      steps: [
        "Step 1: ΔT = 75 − 25 = 50°C.",
        "Step 2: Q = mcΔT.",
        "Step 3: Q = 0.2 × 1000 × 50.",
        "Step 4: Q = 10,000 J."
      ],
      ans: "10,000 J",
      why: "The temperature change is 50°C and Q = mcΔT."
    }
  ]
);


// ============================================================
// 7. LATENT HEAT OF FUSION
// ============================================================

add(
  "chemistry",
  "energy_rate_reaction",
  "Latent Heat of Fusion",
  `<h2>Latent Heat of Fusion</h2>
  <p>Latent heat of fusion is the energy required to change 1 kg of a substance from solid to liquid at its melting point without changing its temperature.</p>

  <p>The relationship is:</p>
  <p><strong>Q = mL<sub>f</sub></strong></p>

  <ul>
    <li>Q = heat energy in joules</li>
    <li>m = mass in kilograms</li>
    <li>L<sub>f</sub> = specific latent heat of fusion in J kg⁻¹</li>
  </ul>

  <p>During melting, energy is used to overcome attractive forces between particles rather than increasing temperature.</p>`,
  [
    {
      q: "What is specific latent heat of fusion?",
      steps: [
        "Step 1: Consider a solid at its melting point.",
        "Step 2: Energy is supplied without raising its temperature.",
        "Step 3: The solid changes to liquid."
      ],
      ans: "The energy required to change 1 kg of a substance from solid to liquid at its melting point without a temperature change.",
      why: "The energy is used for the change of state rather than increasing temperature."
    },
    {
      q: "State the formula for latent heat of fusion.",
      steps: [
        "Step 1: Heat energy depends on mass.",
        "Step 2: It also depends on the specific latent heat.",
        "Step 3: Multiply the two quantities."
      ],
      ans: "Q = mL_f",
      why: "The total latent heat is proportional to the mass undergoing the change of state."
    },
    {
      q: "Why does the temperature remain constant while a pure substance melts?",
      steps: [
        "Step 1: Heat is continuously supplied.",
        "Step 2: The energy is used to overcome attractive forces between particles.",
        "Step 3: Therefore the average kinetic energy does not increase."
      ],
      ans: "The supplied energy is used to overcome forces between particles rather than increasing their average kinetic energy.",
      why: "Temperature measures average kinetic energy, while the supplied energy during melting mainly changes potential energy."
    }
  ],
  [
    {
      q: "Calculate the energy required to melt 2 kg of a substance with a specific latent heat of fusion of 300,000 J kg⁻¹.",
      hint: "Use Q = mL_f.",
      steps: [
        "Step 1: m = 2 kg.",
        "Step 2: L_f = 300,000 J kg⁻¹.",
        "Step 3: Q = mL_f.",
        "Step 4: Q = 2 × 300,000.",
        "Step 5: Q = 600,000 J."
      ],
      ans: "600,000 J",
      why: "The latent heat is proportional to the mass being melted."
    }
  ]
);


// ============================================================
// 8. LATENT HEAT OF VAPORISATION
// ============================================================

add(
  "chemistry",
  "energy_rate_reaction",
  "Latent Heat of Vaporisation",
  `<h2>Latent Heat of Vaporisation</h2>
  <p>Specific latent heat of vaporisation is the energy required to change 1 kg of a liquid into gas at its boiling point without changing its temperature.</p>

  <p>The relationship is:</p>
  <p><strong>Q = mL<sub>v</sub></strong></p>

  <ul>
    <li>Q = heat energy in joules</li>
    <li>m = mass in kilograms</li>
    <li>L<sub>v</sub> = specific latent heat of vaporisation in J kg⁻¹</li>
  </ul>

  <p>During boiling, energy is used to separate particles from the liquid.</p>`,
  [
    {
      q: "What is specific latent heat of vaporisation?",
      steps: [
        "Step 1: Consider a liquid at its boiling point.",
        "Step 2: Energy is supplied without increasing temperature.",
        "Step 3: The liquid changes into gas."
      ],
      ans: "The energy required to change 1 kg of a liquid into gas at its boiling point without a temperature change.",
      why: "The energy supplied is used for the change of state."
    },
    {
      q: "State the formula for latent heat of vaporisation.",
      steps: [
        "Step 1: Identify the mass.",
        "Step 2: Identify the specific latent heat of vaporisation.",
        "Step 3: Multiply them."
      ],
      ans: "Q = mL_v",
      why: "The total latent heat depends on the mass and the specific latent heat."
    },
    {
      q: "Why does the temperature of boiling water remain constant while it is boiling?",
      steps: [
        "Step 1: Heat continues to enter the water.",
        "Step 2: The energy is used to separate liquid particles.",
        "Step 3: Therefore the temperature does not increase while the liquid is changing to gas."
      ],
      ans: "The supplied energy is used to overcome attractive forces between particles and change the state rather than raise the temperature.",
      why: "The energy during boiling mainly changes the physical state."
    }
  ],
  [
    {
      q: "Calculate the energy required to vaporise 0.5 kg of a liquid with L_v = 2,000,000 J kg⁻¹.",
      hint: "Use Q = mL_v.",
      steps: [
        "Step 1: m = 0.5 kg.",
        "Step 2: L_v = 2,000,000 J kg⁻¹.",
        "Step 3: Q = 0.5 × 2,000,000.",
        "Step 4: Q = 1,000,000 J."
      ],
      ans: "1,000,000 J",
      why: "The required energy is the mass multiplied by the specific latent heat of vaporisation."
    }
  ]
);


// ============================================================
// 9. MEANING OF RATE OF REACTION
// ============================================================

add(
  "chemistry",
  "energy_rate_reaction",
  "Rate of Reaction",
  `<h2>Rate of Reaction</h2>
  <p>The rate of a chemical reaction describes how quickly reactants are used up or products are formed.</p>

  <p>A reaction that happens quickly has a high rate. A reaction that happens slowly has a low rate.</p>

  <h3>Simple expression</h3>
  <p><strong>Rate = change in amount ÷ time taken</strong></p>

  <p>The amount may be measured using mass, volume, concentration or another suitable quantity.</p>`,
  [
    {
      q: "What is meant by the rate of a chemical reaction?",
      steps: [
        "Step 1: Consider how quickly a reaction occurs.",
        "Step 2: Measure how much reactant is used or product is formed.",
        "Step 3: Relate this change to the time taken."
      ],
      ans: "The rate of reaction is the speed at which reactants are used up or products are formed.",
      why: "Rate measures the change in a chemical system over time."
    },
    {
      q: "What does a high rate of reaction mean?",
      steps: [
        "Step 1: Rate describes how quickly a reaction occurs.",
        "Step 2: A high rate means a large change occurs in a short time."
      ],
      ans: "The reaction occurs quickly.",
      why: "A high rate means reactants are consumed or products are formed rapidly."
    },
    {
      q: "A reaction produces 40 cm³ of gas in 20 seconds. Calculate the average rate of gas production.",
      steps: [
        "Step 1: Use rate = volume ÷ time.",
        "Step 2: Volume = 40 cm³.",
        "Step 3: Time = 20 s.",
        "Step 4: Rate = 40 ÷ 20.",
        "Step 5: Rate = 2 cm³/s."
      ],
      ans: "2 cm³/s",
      why: "The average rate is the gas volume produced divided by the time taken."
    }
  ],
  [
    {
      q: "A reaction produces 60 cm³ of gas in 30 seconds. Calculate the average rate.",
      hint: "Rate = volume ÷ time.",
      steps: [
        "Step 1: Volume = 60 cm³.",
        "Step 2: Time = 30 s.",
        "Step 3: Rate = 60 ÷ 30.",
        "Step 4: Rate = 2 cm³/s."
      ],
      ans: "2 cm³/s",
      why: "Average rate is calculated by dividing the change in volume by time."
    }
  ]
);


// ============================================================
// 10. EFFECT OF TEMPERATURE ON RATE
// ============================================================

add(
  "chemistry",
  "energy_rate_reaction",
  "Effect of Temperature on Rate",
  `<h2>Effect of Temperature on Rate of Reaction</h2>
  <p>Increasing temperature generally increases the rate of a chemical reaction.</p>

  <h3>Why?</h3>
  <ul>
    <li>Particles gain kinetic energy.</li>
    <li>They move faster.</li>
    <li>Collisions occur more frequently.</li>
    <li>A greater proportion of collisions have enough energy to overcome activation energy.</li>
  </ul>

  <p>Therefore the number of successful collisions per second increases.</p>`,
  [
    {
      q: "What happens to the rate of most chemical reactions when temperature is increased?",
      steps: [
        "Step 1: Increasing temperature gives particles more kinetic energy.",
        "Step 2: Particles move faster and collide more frequently.",
        "Step 3: More collisions have enough energy to react."
      ],
      ans: "The rate generally increases.",
      why: "There are more frequent successful collisions when temperature is increased."
    },
    {
      q: "Why does increasing temperature increase the rate of reaction?",
      steps: [
        "Step 1: Particles gain kinetic energy.",
        "Step 2: They collide more frequently.",
        "Step 3: A larger proportion of collisions exceed the activation energy.",
        "Step 4: More successful collisions occur per second."
      ],
      ans: "Particles move faster, collide more often, and a greater proportion of collisions have enough energy to overcome the activation energy.",
      why: "The collision frequency and number of successful collisions both increase."
    },
    {
      q: "Why does a reaction usually become slower when temperature is decreased?",
      steps: [
        "Step 1: Particles lose kinetic energy.",
        "Step 2: They move more slowly.",
        "Step 3: Collisions become less frequent and fewer have enough energy to react."
      ],
      ans: "The rate decreases because particles move more slowly and fewer successful collisions occur.",
      why: "Lower temperature reduces the frequency and effectiveness of collisions."
    }
  ],
  [
    {
      q: "Two identical reactions are carried out at 20°C and 40°C. Which is likely to finish first?",
      hint: "Compare the temperatures.",
      steps: [
        "Step 1: 40°C is higher than 20°C.",
        "Step 2: Higher temperature generally gives particles more kinetic energy.",
        "Step 3: The reaction at 40°C is therefore faster."
      ],
      ans: "The reaction at 40°C.",
      why: "Increasing temperature generally increases the rate of reaction."
    }
  ]
);


// ============================================================
// 11. EFFECT OF CONCENTRATION ON RATE
// ============================================================

add(
  "chemistry",
  "energy_rate_reaction",
  "Effect of Concentration on Rate",
  `<h2>Effect of Concentration on Rate of Reaction</h2>
  <p>For reactions involving solutions, increasing the concentration of a reactant generally increases the rate of reaction.</p>

  <h3>Why?</h3>
  <p>A concentrated solution contains more reacting particles in a given volume.</p>

  <p>Therefore particles collide more frequently, producing more successful collisions per unit time.</p>`,
  [
    {
      q: "What happens to the rate of reaction when the concentration of a reactant solution is increased?",
      steps: [
        "Step 1: A higher concentration means more particles are present in a given volume.",
        "Step 2: More particles produce more frequent collisions.",
        "Step 3: More successful collisions occur per second."
      ],
      ans: "The rate generally increases.",
      why: "Higher concentration increases the frequency of collisions between reacting particles."
    },
    {
      q: "Why does a concentrated acid usually react faster with a solid carbonate than a dilute acid under otherwise similar conditions?",
      steps: [
        "Step 1: The concentrated acid contains more acid particles per unit volume.",
        "Step 2: These particles collide with the carbonate surface more frequently.",
        "Step 3: More successful collisions occur per second."
      ],
      ans: "Because the concentrated acid contains more reacting particles per unit volume, increasing the frequency of successful collisions.",
      why: "Higher concentration increases collision frequency."
    },
    {
      q: "If the concentration of a reactant is reduced, what generally happens to the reaction rate?",
      steps: [
        "Step 1: Fewer reacting particles are present in the same volume.",
        "Step 2: Collisions occur less frequently.",
        "Step 3: The number of successful collisions per second decreases."
      ],
      ans: "The rate generally decreases.",
      why: "Lower concentration reduces collision frequency."
    }
  ],
  [
    {
      q: "Which is likely to react faster with the same mass of magnesium: 2.0 mol/dm³ hydrochloric acid or 0.5 mol/dm³ hydrochloric acid?",
      hint: "Compare the concentrations.",
      steps: [
        "Step 1: 2.0 mol/dm³ is more concentrated than 0.5 mol/dm³.",
        "Step 2: It contains more HCl particles per unit volume.",
        "Step 3: More frequent successful collisions occur."
      ],
      ans: "2.0 mol/dm³ hydrochloric acid.",
      why: "Higher concentration generally produces a faster reaction."
    }
  ]
);


// ============================================================
// 12. EFFECT OF SURFACE AREA ON RATE
// ============================================================

add(
  "chemistry",
  "energy_rate_reaction",
  "Effect of Surface Area on Rate",
  `<h2>Effect of Surface Area on Rate of Reaction</h2>
  <p>For a reaction involving a solid, increasing the surface area of the solid generally increases the rate of reaction.</p>

  <h3>Example</h3>
  <p>Powdered calcium carbonate reacts faster with acid than large pieces of calcium carbonate of the same total mass.</p>

  <h3>Why?</h3>
  <p>More particles of the solid are exposed to the other reactant, giving more collisions per second.</p>`,
  [
    {
      q: "What happens to the rate of reaction when the surface area of a solid reactant is increased?",
      steps: [
        "Step 1: More of the solid surface becomes exposed.",
        "Step 2: More reacting particles can collide with the other reactant.",
        "Step 3: More successful collisions occur per second."
      ],
      ans: "The rate generally increases.",
      why: "A larger surface area provides more sites for collisions."
    },
    {
      q: "Why does powdered calcium carbonate react faster with hydrochloric acid than large pieces of calcium carbonate?",
      steps: [
        "Step 1: Powder has a larger total surface area.",
        "Step 2: More calcium carbonate particles are exposed to the acid.",
        "Step 3: Collisions occur more frequently.",
        "Step 4: More successful collisions occur each second."
      ],
      ans: "The powder has a larger surface area, so collisions with acid occur more frequently.",
      why: "Greater surface area increases the number of available collision sites."
    },
    {
      q: "Why must the mass of solid be kept the same when comparing the effect of particle size on reaction rate?",
      steps: [
        "Step 1: The experiment should test only one variable.",
        "Step 2: Changing the mass would also change the amount of reactant.",
        "Step 3: Keeping mass constant makes particle size/surface area the main changing variable."
      ],
      ans: "To make surface area the main variable being investigated and ensure a fair comparison.",
      why: "A fair experiment changes one independent variable while keeping other important factors constant."
    }
  ],
  [
    {
      q: "Which reacts faster with acid under otherwise identical conditions: 10 g of powdered marble or 10 g of marble chips?",
      hint: "Compare their surface areas.",
      steps: [
        "Step 1: Both samples have the same mass.",
        "Step 2: Powdered marble has a larger total surface area.",
        "Step 3: More surface is exposed to the acid."
      ],
      ans: "The powdered marble.",
      why: "The larger surface area gives a higher frequency of successful collisions."
    }
  ]
);


// ============================================================
// 13. CATALYSTS
// ============================================================

add(
  "chemistry",
  "energy_rate_reaction",
  "Catalysts",
  `<h2>Catalysts</h2>
  <p>A catalyst is a substance that increases the rate of a chemical reaction without being permanently used up in the reaction.</p>

  <h3>How catalysts work</h3>
  <p>A catalyst provides an alternative reaction pathway with a lower activation energy.</p>

  <p>Because the activation energy is lower, more collisions have enough energy to result in a reaction.</p>

  <h3>Important</h3>
  <p>A catalyst does not change the overall chemical equation or the amount of products formed at equilibrium. It changes how quickly the reaction occurs.</p>`,
  [
    {
      q: "What is a catalyst?",
      steps: [
        "Step 1: A catalyst affects the rate of a reaction.",
        "Step 2: It increases the reaction rate.",
        "Step 3: It is not permanently consumed."
      ],
      ans: "A substance that increases the rate of a chemical reaction without being permanently used up.",
      why: "A catalyst participates in an alternative reaction pathway but is regenerated."
    },
    {
      q: "How does a catalyst increase the rate of reaction?",
      steps: [
        "Step 1: A catalyst provides an alternative reaction pathway.",
        "Step 2: This pathway has a lower activation energy.",
        "Step 3: More particles can therefore react successfully."
      ],
      ans: "It provides an alternative pathway with a lower activation energy.",
      why: "Lower activation energy means a greater proportion of collisions can result in reaction."
    },
    {
      q: "Does a catalyst become permanently used up?",
      steps: [
        "Step 1: A catalyst participates in the reaction pathway.",
        "Step 2: It is regenerated rather than permanently consumed.",
        "Step 3: Therefore it can continue to catalyse further reaction."
      ],
      ans: "No. A catalyst is not permanently used up.",
      why: "The catalyst is regenerated during the catalytic process."
    }
  ],
  [
    {
      q: "A reaction has an activation energy of 100 kJ mol⁻¹. A catalyst provides an alternative pathway requiring 60 kJ mol⁻¹. By how much has the activation energy been reduced?",
      hint: "Subtract the new activation energy from the original.",
      steps: [
        "Step 1: Original activation energy = 100 kJ mol⁻¹.",
        "Step 2: Catalysed activation energy = 60 kJ mol⁻¹.",
        "Step 3: Reduction = 100 − 60.",
        "Step 4: Reduction = 40 kJ mol⁻¹."
      ],
      ans: "40 kJ mol⁻¹",
      why: "The catalyst lowers the activation energy from 100 to 60 kJ mol⁻¹."
    }
  ]
);
