// BATCH 14 — METALS AND EXTRACTION
// Chapter ID: metals_extraction
// ============================================================


// ------------------------------------------------------------
// 1. PHYSICAL PROPERTIES OF METALS
// ------------------------------------------------------------

add(
  "chemistry",
  "metals_extraction",
  "Physical Properties of Metals",
  `<h2>Physical Properties of Metals</h2>

  <p>Metals have physical properties that distinguish them from many non-metals.</p>

  <ul>
    <li>Most metals are solid at room temperature.</li>
    <li>They usually have a shiny surface when freshly cut or polished.</li>
    <li>They are generally good conductors of heat and electricity.</li>
    <li>They are generally strong and hard.</li>
    <li>They can usually be shaped without breaking.</li>
  </ul>

  <p>Examples of metals include iron, copper, aluminium, zinc, silver and gold.</p>

  <h3>Examples</h3>

  <p><strong>Example 1:</strong> State two physical properties of copper.</p>
  <p>Copper is a good conductor of electricity and is malleable.</p>

  <p><strong>Example 2:</strong> Why is copper used for electrical wires?</p>
  <p>Because copper conducts electricity well and can be drawn into wires.</p>

  <p><strong>Example 3:</strong> Why can metals be used to make tools?</p>
  <p>Many metals are strong and hard, allowing them to withstand forces.</p>`,
  [
    {
      q: "State three physical properties of metals.",
      steps: [
        "Step 1: Recall the common physical properties of metals.",
        "Step 2: Select three properties.",
        "Step 3: Examples include good electrical conductivity, good thermal conductivity and malleability."
      ],
      ans: "Metals are generally good conductors of electricity, good conductors of heat and malleable.",
      why: "These are characteristic physical properties of many metals."
    },
    {
      q: "State two physical properties of aluminium.",
      steps: [
        "Step 1: Identify aluminium as a metal.",
        "Step 2: Apply the common physical properties of metals.",
        "Step 3: Aluminium is malleable and conducts electricity."
      ],
      ans: "Aluminium is malleable and conducts electricity.",
      why: "Aluminium has the characteristic physical properties of metals."
    },
    {
      q: "Why is copper suitable for making electrical wires?",
      steps: [
        "Step 1: Identify the property needed in an electrical wire.",
        "Step 2: The material must conduct electricity.",
        "Step 3: Copper is a good electrical conductor."
      ],
      ans: "Copper is suitable because it is a good conductor of electricity.",
      why: "Electrical wires need materials that allow electric current to pass easily."
    }
  ],
  [
    {
      q: "A student says that metals are all gases at room temperature. Is this correct?",
      hint: "Think about the physical state of common metals such as iron and copper.",
      steps: [
        "Step 1: Consider common metals at room temperature.",
        "Step 2: Iron and copper are solids.",
        "Step 3: Therefore the statement is incorrect."
      ],
      ans: "No. Most metals are solids at room temperature.",
      why: "Most metals exist as solids under ordinary room conditions."
    }
  ]
);


// ------------------------------------------------------------
// 2. ELECTRICAL CONDUCTIVITY
// ------------------------------------------------------------

add(
  "chemistry",
  "metals_extraction",
  "Electrical Conductivity",
  `<h2>Electrical Conductivity of Metals</h2>

  <p>Metals conduct electricity because they contain mobile electrons that can move through the metal.</p>

  <p>This makes metals useful for electrical cables, contacts and electrical components.</p>

  <h3>Examples</h3>

  <p><strong>Example 1:</strong> Copper is used for electrical cables because it conducts electricity well.</p>

  <p><strong>Example 2:</strong> Aluminium is also used in electrical transmission because it conducts electricity and has a relatively low density.</p>

  <p><strong>Example 3:</strong> A plastic coating is placed around a copper wire because plastic is an electrical insulator.</p>`,
  [
    {
      q: "Why do metals conduct electricity?",
      steps: [
        "Step 1: Metals contain electrons that are able to move through the metal.",
        "Step 2: Moving electrons carry electric charge.",
        "Step 3: Therefore metals can conduct electricity."
      ],
      ans: "Metals conduct electricity because they contain mobile electrons that can carry electric charge.",
      why: "The movement of charged electrons allows electric current to pass through a metal."
    },
    {
      q: "Why is copper commonly used for electrical wires?",
      steps: [
        "Step 1: Electrical wires need a good electrical conductor.",
        "Step 2: Copper conducts electricity well.",
        "Step 3: Copper can also be drawn into thin wires."
      ],
      ans: "Copper is used because it is a good electrical conductor and can be drawn into wires.",
      why: "Both conductivity and the ability to form wires make copper suitable."
    },
    {
      q: "Why is plastic used to cover electrical wires?",
      steps: [
        "Step 1: The metal inside the wire conducts electricity.",
        "Step 2: The outside covering should prevent current from reaching the user.",
        "Step 3: Plastic is an electrical insulator."
      ],
      ans: "Plastic is used because it is an electrical insulator.",
      why: "An insulating covering reduces the risk of electric shock."
    }
  ],
  [
    {
      q: "A metal wire is replaced with a plastic wire. What happens to electrical conduction?",
      hint: "Compare conductors with insulators.",
      steps: [
        "Step 1: Metals are good electrical conductors.",
        "Step 2: Plastic is generally an electrical insulator.",
        "Step 3: Therefore the plastic will not conduct electricity effectively."
      ],
      ans: "Electrical conduction would be greatly reduced because plastic is an insulator.",
      why: "Plastic does not have freely moving charge carriers like a metal."
    }
  ]
);


// ------------------------------------------------------------
// 3. MALLEABILITY
// ------------------------------------------------------------

add(
  "chemistry",
  "metals_extraction",
  "Malleability",
  `<h2>Malleability of Metals</h2>

  <p><strong>Malleability</strong> is the ability of a material to be hammered or pressed into sheets without breaking.</p>

  <p>Many metals are malleable.</p>

  <h3>Examples</h3>

  <p><strong>Example 1:</strong> Aluminium can be rolled into thin sheets.</p>

  <p><strong>Example 2:</strong> Gold can be beaten into extremely thin sheets.</p>

  <p><strong>Example 3:</strong> Aluminium foil is possible because aluminium is malleable.</p>`,
  [
    {
      q: "Define malleability.",
      steps: [
        "Step 1: Identify malleability as a physical property.",
        "Step 2: It describes the ability to be shaped by hammering or pressing.",
        "Step 3: The material forms sheets instead of breaking."
      ],
      ans: "Malleability is the ability of a material to be hammered or pressed into sheets without breaking.",
      why: "Metals can often be shaped into sheets because their particles can shift without the whole structure immediately breaking."
    },
    {
      q: "Why can aluminium be made into foil?",
      steps: [
        "Step 1: Aluminium is a metal.",
        "Step 2: Aluminium is malleable.",
        "Step 3: Therefore it can be rolled into thin sheets."
      ],
      ans: "Aluminium can be made into foil because it is malleable.",
      why: "Malleability allows aluminium to be shaped into thin sheets."
    },
    {
      q: "Distinguish between malleability and brittleness.",
      steps: [
        "Step 1: Malleability involves being shaped without breaking.",
        "Step 2: Brittleness involves breaking when force is applied.",
        "Step 3: Therefore the properties describe opposite behaviours."
      ],
      ans: "Malleability is the ability to be shaped into sheets without breaking, while brittleness is the tendency to break when force is applied.",
      why: "The two properties describe how materials respond to applied force."
    }
  ],
  [
    {
      q: "A metal is hammered into a sheet without cracking. Which property is demonstrated?",
      hint: "Think of the property that allows metals to form sheets.",
      steps: [
        "Step 1: The metal is being hammered.",
        "Step 2: It forms a sheet without breaking.",
        "Step 3: This is malleability."
      ],
      ans: "Malleability.",
      why: "Malleability is the ability to form sheets without breaking."
    }
  ]
);


// ------------------------------------------------------------
// 4. DUCTILITY
// ------------------------------------------------------------

add(
  "chemistry",
  "metals_extraction",
  "Ductility",
  `<h2>Ductility of Metals</h2>

  <p><strong>Ductility</strong> is the ability of a material to be drawn or stretched into wires without breaking.</p>

  <p>Many metals are ductile.</p>

  <h3>Examples</h3>

  <p><strong>Example 1:</strong> Copper can be drawn into electrical wires.</p>

  <p><strong>Example 2:</strong> Aluminium can be formed into wires.</p>

  <p><strong>Example 3:</strong> The ability to make wires from copper depends partly on its ductility.</p>`,
  [
    {
      q: "Define ductility.",
      steps: [
        "Step 1: Ductility is a physical property.",
        "Step 2: It describes the ability of a material to be drawn or stretched.",
        "Step 3: The material forms a wire without breaking."
      ],
      ans: "Ductility is the ability of a material to be drawn or stretched into wires without breaking.",
      why: "Ductile materials can undergo deformation while remaining intact."
    },
    {
      q: "Why is copper suitable for making wires?",
      steps: [
        "Step 1: Wires need to be formed into long thin shapes.",
        "Step 2: Copper is ductile.",
        "Step 3: Therefore copper can be drawn into wires."
      ],
      ans: "Copper is suitable because it is ductile and can be drawn into wires.",
      why: "Ductility allows a metal to be formed into long thin wires."
    },
    {
      q: "Distinguish between ductility and malleability.",
      steps: [
        "Step 1: Ductility concerns forming wires.",
        "Step 2: Malleability concerns forming sheets.",
        "Step 3: Therefore they describe different ways metals can be shaped."
      ],
      ans: "Ductility is the ability to form wires, while malleability is the ability to form sheets.",
      why: "Both involve shaping metals, but the final forms are different."
    }
  ],
  [
    {
      q: "A metal can be pulled into a long thin wire without breaking. What property does it show?",
      hint: "The answer involves forming wires.",
      steps: [
        "Step 1: The metal is being pulled into a wire.",
        "Step 2: It does not break.",
        "Step 3: This demonstrates ductility."
      ],
      ans: "Ductility.",
      why: "Ductility is the ability to be drawn into wires."
    }
  ]
);


// ------------------------------------------------------------
// 5. REACTIVITY SERIES
// ------------------------------------------------------------

add(
  "chemistry",
  "metals_extraction",
  "Reactivity Series",
  `<h2>Reactivity Series</h2>

  <p>The reactivity series arranges metals from more reactive to less reactive.</p>

  <p>A commonly used order is:</p>

  <p><strong>Potassium → Sodium → Calcium → Magnesium → Aluminium → Carbon → Zinc → Iron → Hydrogen → Copper → Silver → Gold</strong></p>

  <p>Carbon and hydrogen are included as reference points even though they are not metals.</p>

  <p>A metal higher in the series is generally more reactive than a metal below it.</p>

  <h3>Examples</h3>

  <p><strong>Example 1:</strong> Magnesium is more reactive than copper because magnesium is higher in the series.</p>

  <p><strong>Example 2:</strong> Zinc is more reactive than iron because zinc is above iron.</p>

  <p><strong>Example 3:</strong> Copper is less reactive than iron because copper is below iron.</p>`,
  [
    {
      q: "Which is more reactive, magnesium or copper?",
      steps: [
        "Step 1: Locate magnesium in the reactivity series.",
        "Step 2: Locate copper in the reactivity series.",
        "Step 3: Magnesium is above copper.",
        "Step 4: Therefore magnesium is more reactive."
      ],
      ans: "Magnesium is more reactive than copper.",
      why: "A metal higher in the reactivity series is generally more reactive."
    },
    {
      q: "Which is more reactive, zinc or iron?",
      steps: [
        "Step 1: Locate zinc in the series.",
        "Step 2: Locate iron in the series.",
        "Step 3: Zinc is above iron.",
        "Step 4: Therefore zinc is more reactive."
      ],
      ans: "Zinc is more reactive than iron.",
      why: "Zinc occurs above iron in the reactivity series."
    },
    {
      q: "Arrange magnesium, copper, zinc and iron from most reactive to least reactive.",
      steps: [
        "Step 1: Locate the four metals in the reactivity series.",
        "Step 2: Magnesium is highest among the four.",
        "Step 3: Zinc comes next, followed by iron.",
        "Step 4: Copper is lowest among the four."
      ],
      ans: "Magnesium > zinc > iron > copper.",
      why: "The order follows their positions in the reactivity series."
    }
  ],
  [
    {
      q: "A student places copper above zinc in the reactivity series. Is this correct?",
      hint: "Compare the positions of copper and zinc.",
      steps: [
        "Step 1: Zinc is above iron and hydrogen.",
        "Step 2: Copper is below hydrogen.",
        "Step 3: Therefore zinc is more reactive than copper."
      ],
      ans: "No. Zinc is more reactive than copper.",
      why: "Zinc is higher than copper in the reactivity series."
    }
  ]
);


// ------------------------------------------------------------
// 6. DISPLACEMENT REACTIONS
// ------------------------------------------------------------

add(
  "chemistry",
  "metals_extraction",
  "Displacement Reactions",
  `<h2>Displacement Reactions</h2>

  <p>A more reactive metal can displace a less reactive metal from a compound of that metal.</p>

  <p>For example:</p>

  <p><strong>Fe + CuSO₄ → FeSO₄ + Cu</strong></p>

  <p>Iron is more reactive than copper, so iron displaces copper from copper(II) sulphate.</p>

  <p>A less reactive metal cannot displace a more reactive metal from its compound.</p>

  <h3>Examples</h3>

  <p><strong>Example 1:</strong></p>
  <p>Zn + CuSO₄ → ZnSO₄ + Cu</p>

  <p><strong>Example 2:</strong></p>
  <p>Mg + CuSO₄ → MgSO₄ + Cu</p>

  <p><strong>Example 3:</strong></p>
  <p>Cu + ZnSO₄ → No reaction</p>`,
  [
    {
      q: "Will iron displace copper from copper(II) sulphate?",
      steps: [
        "Step 1: Compare iron and copper in the reactivity series.",
        "Step 2: Iron is above copper.",
        "Step 3: Therefore iron is more reactive.",
        "Step 4: Iron can displace copper."
      ],
      ans: "Yes. Fe + CuSO₄ → FeSO₄ + Cu.",
      why: "Iron is more reactive than copper."
    },
    {
      q: "Write the equation for the reaction between zinc and copper(II) sulphate.",
      steps: [
        "Step 1: Zinc is more reactive than copper.",
        "Step 2: Zinc displaces copper.",
        "Step 3: The products are zinc sulphate and copper.",
        "Step 4: Write the balanced equation."
      ],
      ans: "Zn + CuSO₄ → ZnSO₄ + Cu.",
      why: "Zinc is above copper in the reactivity series."
    },
    {
      q: "Will copper displace zinc from zinc sulphate?",
      steps: [
        "Step 1: Compare copper and zinc in the reactivity series.",
        "Step 2: Zinc is more reactive than copper.",
        "Step 3: Copper is therefore unable to displace zinc."
      ],
      ans: "No reaction.",
      why: "A less reactive metal cannot displace a more reactive metal from its compound."
    }
  ],
  [
    {
      q: "A student predicts that Cu + MgSO₄ → CuSO₄ + Mg. Is this correct?",
      hint: "Compare copper and magnesium in the reactivity series.",
      steps: [
        "Step 1: Magnesium is above copper in the reactivity series.",
        "Step 2: Magnesium is therefore more reactive.",
        "Step 3: Copper cannot displace magnesium."
      ],
      ans: "No. There is no reaction.",
      why: "Copper is less reactive than magnesium."
    }
  ]
);


// ------------------------------------------------------------
// 7. ORES
// ------------------------------------------------------------

add(
  "chemistry",
  "metals_extraction",
  "Ores",
  `<h2>Ores</h2>

  <p>An <strong>ore</strong> is a naturally occurring mineral or rock containing a metal or metal compound from which the metal can be extracted economically.</p>

  <p>Examples include:</p>

  <ul>
    <li>Hematite — an important ore of iron</li>
    <li>Bauxite — the main ore of aluminium</li>
  </ul>

  <p>The method used to extract a metal depends strongly on its position in the reactivity series.</p>

  <h3>Examples</h3>

  <p><strong>Example 1:</strong> Iron can be extracted from hematite.</p>

  <p><strong>Example 2:</strong> Aluminium is obtained from aluminium oxide derived from bauxite.</p>

  <p><strong>Example 3:</strong> Highly reactive metals require more powerful extraction methods than less reactive metals.</p>`,
  [
    {
      q: "What is an ore?",
      steps: [
        "Step 1: An ore occurs naturally in the Earth's crust.",
        "Step 2: It contains a metal or metal compound.",
        "Step 3: The metal can be extracted economically from the ore."
      ],
      ans: "An ore is a naturally occurring mineral or rock containing a metal or metal compound from which the metal can be extracted economically.",
      why: "Not every mineral containing a metal is considered an ore; economic extraction is important."
    },
    {
      q: "Name the main ore of aluminium.",
      steps: [
        "Step 1: Recall the common ores of important metals.",
        "Step 2: Aluminium is obtained from bauxite.",
        "Step 3: Therefore the main ore is bauxite."
      ],
      ans: "Bauxite.",
      why: "Bauxite is the main ore from which aluminium is obtained."
    },
    {
      q: "Name an important ore of iron.",
      steps: [
        "Step 1: Recall common iron ores.",
        "Step 2: Hematite contains iron(III) oxide.",
        "Step 3: Therefore hematite is an important iron ore."
      ],
      ans: "Hematite.",
      why: "Hematite is an important source of iron."
    }
  ],
  [
    {
      q: "A rock contains a small amount of copper, but extracting the copper costs more than the copper is worth. Is the rock necessarily an ore?",
      hint: "Consider the economic part of the definition.",
      steps: [
        "Step 1: An ore must contain a useful metal or metal compound.",
        "Step 2: The metal must also be economically extractable.",
        "Step 3: If extraction costs more than the value obtained, it does not satisfy the economic requirement."
      ],
      ans: "No. It would not normally be considered an ore because the metal cannot be extracted economically.",
      why: "Economic extraction is part of the definition of an ore."
    }
  ]
);


// ------------------------------------------------------------
// 8. REDUCTION
// ------------------------------------------------------------

add(
  "chemistry",
  "metals_extraction",
  "Reduction",
  `<h2>Reduction of Metal Compounds</h2>

  <p><strong>Reduction</strong> is the removal of oxygen from a substance, or the gain of electrons.</p>

  <p>During extraction, a metal compound can be reduced to form the metal.</p>

  <p>For example:</p>

  <p><strong>Fe₂O₃ + 3CO → 2Fe + 3CO₂</strong></p>

  <p>Iron(III) oxide loses oxygen and forms iron.</p>

  <h3>Examples</h3>

  <p><strong>Example 1:</strong> Fe₂O₃ → Fe is a reduction because oxygen is removed from the iron compound.</p>

  <p><strong>Example 2:</strong> CuO + H₂ → Cu + H₂O. Copper(II) oxide is reduced to copper.</p>

  <p><strong>Example 3:</strong> A metal oxide that loses oxygen has undergone reduction.</p>`,
  [
    {
      q: "What is reduction in terms of oxygen?",
      steps: [
        "Step 1: Look at the oxygen content of the substance.",
        "Step 2: If oxygen is removed, the substance is reduced.",
        "Step 3: Therefore reduction can be described as removal of oxygen."
      ],
      ans: "Reduction is the removal of oxygen from a substance.",
      why: "This is the oxygen-based definition commonly used when discussing extraction of metals."
    },
    {
      q: "Identify the substance being reduced in Fe₂O₃ + 3CO → 2Fe + 3CO₂.",
      steps: [
        "Step 1: Compare the reactant and product containing iron.",
        "Step 2: Fe₂O₃ changes into Fe.",
        "Step 3: Oxygen has been removed from the iron compound."
      ],
      ans: "Fe₂O₃, iron(III) oxide, is being reduced.",
      why: "Iron(III) oxide loses oxygen to form iron."
    },
    {
      q: "In CuO + H₂ → Cu + H₂O, which substance is reduced?",
      steps: [
        "Step 1: Identify the copper-containing reactant.",
        "Step 2: CuO changes into Cu.",
        "Step 3: Oxygen is removed from CuO."
      ],
      ans: "Copper(II) oxide, CuO, is reduced.",
      why: "CuO loses oxygen and forms copper."
    }
  ],
  [
    {
      q: "A student says oxidation is the removal of oxygen. Is this correct?",
      hint: "Recall the oxygen definitions of oxidation and reduction.",
      steps: [
        "Step 1: Oxidation involves gain of oxygen.",
        "Step 2: Reduction involves loss of oxygen.",
        "Step 3: Therefore the statement is incorrect."
      ],
      ans: "No. Removal of oxygen is reduction; gain of oxygen is oxidation.",
      why: "These are the oxygen-based definitions of reduction and oxidation."
    }
  ]
);


// ------------------------------------------------------------
// 9. EXTRACTION OF IRON
// ------------------------------------------------------------

add(
  "chemistry",
  "metals_extraction",
  "Extraction of Iron",
  `<h2>Extraction of Iron</h2>

  <p>Iron is extracted from iron ore such as hematite, Fe₂O₃, in a blast furnace.</p>

  <h3>Main raw materials</h3>

  <ul>
    <li>Hematite — source of iron(III) oxide</li>
    <li>Coke — provides carbon and produces carbon monoxide</li>
    <li>Limestone — helps remove impurities</li>
    <li>Hot air — supplies oxygen for combustion</li>
  </ul>

  <h3>Important reactions</h3>

  <p>Carbon burns:</p>

  <p><strong>C + O₂ → CO₂</strong></p>

  <p>Carbon dioxide reacts with more carbon:</p>

  <p><strong>CO₂ + C → 2CO</strong></p>

  <p>Carbon monoxide reduces iron(III) oxide:</p>

  <p><strong>Fe₂O₃ + 3CO → 2Fe + 3CO₂</strong></p>

  <p>Molten iron collects at the bottom of the furnace.</p>`,
  [
    {
      q: "Write the equation for the reduction of iron(III) oxide by carbon monoxide.",
      steps: [
        "Step 1: Write the reactants: Fe₂O₃ and CO.",
        "Step 2: The products are Fe and CO₂.",
        "Step 3: Balance iron: Fe₂O₃ gives 2Fe.",
        "Step 4: Balance carbon monoxide and carbon dioxide.",
        "Step 5: The balanced equation is Fe₂O₃ + 3CO → 2Fe + 3CO₂."
      ],
      ans: "Fe₂O₃ + 3CO → 2Fe + 3CO₂.",
      why: "Carbon monoxide removes oxygen from iron(III) oxide, reducing it to iron."
    },
    {
      q: "What is the role of carbon monoxide in the blast furnace?",
      steps: [
        "Step 1: Identify the compound that must be changed into iron.",
        "Step 2: Iron(III) oxide must lose oxygen.",
        "Step 3: Carbon monoxide removes oxygen from the oxide."
      ],
      ans: "Carbon monoxide acts as a reducing agent and reduces iron(III) oxide to iron.",
      why: "CO removes oxygen from Fe₂O₃."
    },
    {
      q: "What is the role of limestone in the extraction of iron?",
      steps: [
        "Step 1: Iron ore contains unwanted impurities such as silica.",
        "Step 2: Limestone decomposes to form calcium oxide.",
        "Step 3: Calcium oxide reacts with silica to form calcium silicate slag."
      ],
      ans: "Limestone helps remove impurities by forming slag with silica.",
      why: "The calcium oxide formed from limestone reacts with acidic silica impurity."
    }
  ],
  [
    {
      q: "A student writes Fe₂O₃ + CO → Fe + CO₂ as the balanced equation. What is wrong?",
      hint: "Count iron, carbon and oxygen atoms on both sides.",
      steps: [
        "Step 1: Fe₂O₃ contains two iron atoms.",
        "Step 2: Therefore two Fe atoms are needed on the product side.",
        "Step 3: Balancing carbon and oxygen then requires three CO and three CO₂."
      ],
      ans: "The balanced equation is Fe₂O₃ + 3CO → 2Fe + 3CO₂.",
      why: "The original equation does not conserve the number of atoms."
    }
  ]
);


// ------------------------------------------------------------
// 10. RUSTING
// ------------------------------------------------------------

add(
  "chemistry",
  "metals_extraction",
  "Rusting",
  `<h2>Rusting of Iron</h2>

  <p><strong>Rusting</strong> is the corrosion of iron in the presence of oxygen and water.</p>

  <p>The rust formed is hydrated iron(III) oxide.</p>

  <p>A simplified representation is:</p>

  <p><strong>4Fe + 3O₂ → 2Fe₂O₃</strong></p>

  <p>In real rust, water is also involved, so rust is commonly represented as hydrated iron(III) oxide.</p>

  <h3>Effects of rusting</h3>

  <ul>
    <li>Iron objects become weakened.</li>
    <li>Structures can lose strength.</li>
    <li>Machines and tools can be damaged.</li>
    <li>Money is spent replacing or repairing corroded materials.</li>
  </ul>`,
  [
    {
      q: "What is rusting?",
      steps: [
        "Step 1: Identify the metal involved.",
        "Step 2: Rusting specifically refers to corrosion of iron and steel.",
        "Step 3: It occurs when iron reacts in the presence of oxygen and water."
      ],
      ans: "Rusting is the corrosion of iron or steel in the presence of oxygen and water, producing hydrated iron(III) oxide.",
      why: "Both oxygen and water are required for ordinary rusting."
    },
    {
      q: "State the two main conditions required for rusting.",
      steps: [
        "Step 1: Iron must have access to oxygen.",
        "Step 2: Iron must also have access to water.",
        "Step 3: Therefore both oxygen and water are required."
      ],
      ans: "Oxygen and water.",
      why: "Rusting requires both oxygen and water."
    },
    {
      q: "State two effects of rusting.",
      steps: [
        "Step 1: Rust forms on iron surfaces.",
        "Step 2: Continued corrosion removes and weakens the metal.",
        "Step 3: Therefore iron structures can lose strength and become damaged."
      ],
      ans: "Rusting weakens iron structures and damages iron objects.",
      why: "Corrosion gradually changes and removes useful metal."
    }
  ],
  [
    {
      q: "Iron nails are stored completely dry in a sealed container containing no oxygen. Will ordinary rusting occur?",
      hint: "Rusting needs both water and oxygen.",
      steps: [
        "Step 1: Rusting requires water.",
        "Step 2: Rusting also requires oxygen.",
        "Step 3: The nails have neither available oxygen nor water.",
        "Step 4: Ordinary rusting will therefore not occur."
      ],
      ans: "No. Ordinary rusting will not occur because oxygen and water are absent.",
      why: "Both conditions are necessary for ordinary rusting."
    }
  ]
);


// ------------------------------------------------------------
// 11. CONDITIONS FOR RUSTING
// ------------------------------------------------------------

add(
  "chemistry",
  "metals_extraction",
  "Conditions for Rusting",
  `<h2>Conditions for Rusting</h2>

  <p>Rusting requires both <strong>water</strong> and <strong>oxygen</strong>.</p>

  <p>This can be demonstrated using iron nails under different conditions.</p>

  <h3>Experiment</h3>

  <p><strong>Tube A:</strong> Nail exposed to air and water → rust forms.</p>

  <p><strong>Tube B:</strong> Nail kept dry with a drying agent → little or no rust.</p>

  <p><strong>Tube C:</strong> Nail placed in boiled water covered with oil → little or no rust because oxygen is excluded.</p>

  <p>The experiment shows that both oxygen and water are needed for ordinary rusting.</p>`,
  [
    {
      q: "Why does a dry iron nail not rust readily?",
      steps: [
        "Step 1: Rusting requires oxygen and water.",
        "Step 2: A dry nail has little or no water available.",
        "Step 3: Therefore the rusting reaction is prevented or greatly reduced."
      ],
      ans: "A dry iron nail does not rust readily because water is absent.",
      why: "Water is one of the conditions required for rusting."
    },
    {
      q: "Why can boiled water covered with oil reduce rusting of an iron nail?",
      steps: [
        "Step 1: Boiling removes much of the dissolved oxygen from water.",
        "Step 2: The oil layer prevents oxygen from entering the water easily.",
        "Step 3: The nail therefore has very little oxygen available."
      ],
      ans: "It reduces rusting because the nail has little available oxygen.",
      why: "The experiment removes or excludes oxygen while water is still present."
    },
    {
      q: "An iron nail is placed in ordinary water exposed to air. Will it rust?",
      steps: [
        "Step 1: The nail has access to water.",
        "Step 2: It also has access to oxygen from the air.",
        "Step 3: Both conditions for rusting are present."
      ],
      ans: "Yes, the nail will rust.",
      why: "Both water and oxygen are available."
    }
  ],
  [
    {
      q: "A nail is placed in dry air. Why is rusting greatly reduced?",
      hint: "What substance is missing from dry air?",
      steps: [
        "Step 1: Dry air provides oxygen.",
        "Step 2: However, it contains very little water.",
        "Step 3: Without sufficient water, ordinary rusting is greatly reduced."
      ],
      ans: "Rusting is greatly reduced because there is insufficient water.",
      why: "Rusting requires both oxygen and water."
    }
  ]
);


// ------------------------------------------------------------
// 12. PREVENTION OF RUSTING
// ------------------------------------------------------------

add(
  "chemistry",
  "metals_extraction",
  "Prevention of Rusting",
  `<h2>Prevention of Rusting</h2>

  <p>Rusting can be prevented by stopping iron from coming into contact with water or oxygen.</p>

  <h3>Barrier methods</h3>

  <ul>
    <li>Painting</li>
    <li>Oiling</li>
    <li>Greasing</li>
    <li>Coating with plastic</li>
    <li>Galvanising with zinc</li>
  </ul>

  <p>These methods form a barrier between the iron and the substances needed for rusting.</p>

  <h3>Examples</h3>

  <p><strong>Example 1:</strong> Bicycle chains can be oiled to keep water and oxygen away.</p>

  <p><strong>Example 2:</strong> Iron gates can be painted.</p>

  <p><strong>Example 3:</strong> Iron sheets can be galvanised by coating them with zinc.</p>`,
  [
    {
      q: "How does painting prevent rusting?",
      steps: [
        "Step 1: Rusting requires contact with oxygen and water.",
        "Step 2: Paint forms a protective layer over the iron.",
        "Step 3: The layer prevents water and oxygen from reaching the iron."
      ],
      ans: "Painting forms a barrier that prevents water and oxygen from reaching the iron.",
      why: "Removing contact with the required conditions reduces rusting."
    },
    {
      q: "Why is grease applied to a bicycle chain?",
      steps: [
        "Step 1: A bicycle chain is made largely of iron or steel.",
        "Step 2: Iron and steel can rust when exposed to water and oxygen.",
        "Step 3: Grease forms a protective barrier."
      ],
      ans: "Grease prevents water and oxygen from reaching the metal surface.",
      why: "The grease acts as a barrier against the conditions needed for rusting."
    },
    {
      q: "What is galvanising?",
      steps: [
        "Step 1: Identify the metal used as the protective coating.",
        "Step 2: Iron or steel is coated with zinc.",
        "Step 3: This process is called galvanising."
      ],
      ans: "Galvanising is coating iron or steel with zinc to protect it from corrosion.",
      why: "The zinc coating separates the steel from the environment and also provides sacrificial protection."
    }
  ],
  [
    {
      q: "A painted iron gate develops rust after the paint is scratched away. Why?",
      hint: "Think about what the scratch exposes.",
      steps: [
        "Step 1: Paint normally acts as a barrier.",
        "Step 2: The scratch exposes the iron.",
        "Step 3: Water and oxygen can reach the exposed iron.",
        "Step 4: Rusting can therefore begin at the damaged area."
      ],
      ans: "The scratch exposes the iron to water and oxygen, allowing rusting to occur.",
      why: "The protective barrier has been broken."
    }
  ]
);


// ------------------------------------------------------------
// 13. ALLOYS
// ------------------------------------------------------------

add(
  "chemistry",
  "metals_extraction",
  "Alloys",
  `<h2>Alloys</h2>

  <p>An <strong>alloy</strong> is a mixture containing a metal and one or more other elements.</p>

  <p>Alloys are often made to obtain properties that are different from those of the pure metal.</p>

  <h3>Common alloys</h3>

  <ul>
    <li><strong>Steel:</strong> mainly iron with carbon.</li>
    <li><strong>Stainless steel:</strong> iron with carbon and other elements such as chromium.</li>
    <li><strong>Brass:</strong> copper and zinc.</li>
    <li><strong>Bronze:</strong> copper and tin.</li>
    <li><strong>Duralumin:</strong> an aluminium-based alloy containing other elements.</li>
  </ul>

  <p>Alloys are commonly harder or stronger than the pure metals from which they are made.</p>`,
  [
    {
      q: "What is an alloy?",
      steps: [
        "Step 1: Identify an alloy as a mixture.",
        "Step 2: It contains a metal and one or more other elements.",
        "Step 3: Therefore it is not usually a pure element."
      ],
      ans: "An alloy is a mixture containing a metal and one or more other elements.",
      why: "Alloys are produced by combining elements to obtain useful properties."
    },
    {
      q: "Name the elements that make up brass.",
      steps: [
        "Step 1: Recall the common composition of brass.",
        "Step 2: Brass contains copper.",
        "Step 3: Brass also contains zinc."
      ],
      ans: "Copper and zinc.",
      why: "Brass is an alloy of copper and zinc."
    },
    {
      q: "Name the main metals in bronze.",
      steps: [
        "Step 1: Recall the common composition of bronze.",
        "Step 2: Bronze contains copper.",
        "Step 3: Tin is added to copper to form bronze."
      ],
      ans: "Copper and tin.",
      why: "Bronze is mainly an alloy of copper and tin."
    }
  ],
  [
    {
      q: "Why are alloys often preferred to pure metals?",
      hint: "Think about how their properties can change.",
      steps: [
        "Step 1: Combining elements changes the structure of the material.",
        "Step 2: This can change properties such as strength and hardness.",
        "Step 3: Therefore an alloy can have properties more suitable for a particular use."
      ],
      ans: "Alloys are often preferred because they can have improved properties such as greater strength or hardness.",
      why: "Alloying is used to modify the properties of metals."
    }
  ]
);


// ------------------------------------------------------------
// 14. USES OF METALS
// ------------------------------------------------------------

add(
  "chemistry",
  "metals_extraction",
  "Uses of Metals",
  `<h2>Uses of Metals</h2>

  <p>The use of a metal depends on its physical and chemical properties.</p>

  <h3>Common examples</h3>

  <p><strong>Copper:</strong> electrical wires because it conducts electricity well and is ductile.</p>

  <p><strong>Aluminium:</strong> aircraft bodies, cooking utensils and electrical transmission because it is relatively light, conducts electricity and is resistant to corrosion.</p>

  <p><strong>Iron and steel:</strong> buildings, bridges, tools and machines because they are strong.</p>

  <p><strong>Zinc:</strong> galvanising iron and steel because it helps protect them from corrosion.</p>

  <p><strong>Gold:</strong> jewellery because it is attractive and relatively unreactive.</p>

  <p><strong>Silver:</strong> jewellery and electrical contacts because it has very high electrical conductivity.</p>`,
  [
    {
      q: "Why is copper used for electrical wiring?",
      steps: [
        "Step 1: Electrical wires need a good conductor.",
        "Step 2: Copper conducts electricity well.",
        "Step 3: Copper is also ductile and can be drawn into wires."
      ],
      ans: "Copper is used because it conducts electricity well and is ductile.",
      why: "Its conductivity allows current to flow and its ductility allows wires to be formed."
    },
    {
      q: "Why is aluminium useful for aircraft construction?",
      steps: [
        "Step 1: Aircraft construction benefits from materials with low density.",
        "Step 2: Aluminium is relatively light.",
        "Step 3: Aluminium also has useful strength and corrosion resistance."
      ],
      ans: "Aluminium is useful because it is relatively light and has useful strength and corrosion resistance.",
      why: "Low mass is especially valuable in aircraft construction."
    },
    {
      q: "Why is steel used to make bridges?",
      steps: [
        "Step 1: A bridge must support large loads.",
        "Step 2: Steel is strong and can be formed into structural shapes.",
        "Step 3: Therefore steel is suitable for bridges."
      ],
      ans: "Steel is used because it is strong and suitable for structural construction.",
      why: "Strong materials are required to support the loads acting on bridges."
    }
  ],
  [
    {
      q: "A manufacturer wants a material for electrical cables that can be drawn into thin wires and conducts electricity well. Which metal is suitable: copper or sulphur?",
      hint: "Compare their conductivity and ductility.",
      steps: [
        "Step 1: Electrical cables need good electrical conductivity.",
        "Step 2: They also need a material that can form wires.",
        "Step 3: Copper is a good conductor and is ductile.",
        "Step 4: Sulphur is a non-metal and is not suitable."
      ],
      ans: "Copper.",
      why: "Copper has the required electrical conductivity and ductility."
    }
  ]
);
// ============================================================
// BATCH 15 — ELECTROCHEMISTRY
// Chapter ID: electrochemistry
// ============================================================


// ------------------------------------------------------------
// 1. ELECTROLYTES
// ------------------------------------------------------------

add(
  "chemistry",
  "electrochemistry",
  "Electrolytes",
  `<h2>Electrolytes</h2>

  <p>An <strong>electrolyte</strong> is a substance that conducts electricity when molten or dissolved in water because it contains mobile ions.</p>

  <p>Examples include:</p>

  <ul>
    <li>Molten sodium chloride</li>
    <li>Sodium chloride solution</li>
    <li>Copper(II) sulphate solution</li>
    <li>Dilute hydrochloric acid</li>
  </ul>

  <p>Solid ionic compounds generally do not conduct electricity because their ions are fixed in a lattice.</p>

  <h3>Examples</h3>

  <p><strong>Example 1:</strong> Solid NaCl does not conduct electricity effectively because its ions cannot move freely.</p>

  <p><strong>Example 2:</strong> Molten NaCl conducts because its ions are free to move.</p>

  <p><strong>Example 3:</strong> NaCl solution conducts because Na⁺ and Cl⁻ ions move through the solution.</p>`,
  [
    {
      q: "What is an electrolyte?",
      steps: [
        "Step 1: An electrolyte contains charged particles that can move.",
        "Step 2: These particles are usually ions.",
        "Step 3: Their movement allows electric current to pass."
      ],
      ans: "An electrolyte is a substance that conducts electricity when molten or dissolved in water because it contains mobile ions.",
      why: "Electric current through an electrolyte is carried by moving ions."
    },
    {
      q: "Why does molten sodium chloride conduct electricity?",
      steps: [
        "Step 1: Sodium chloride contains Na⁺ and Cl⁻ ions.",
        "Step 2: In solid sodium chloride, the ions are fixed in position.",
        "Step 3: Melting allows the ions to move freely.",
        "Step 4: The moving ions carry electric charge."
      ],
      ans: "Molten sodium chloride conducts because its Na⁺ and Cl⁻ ions are free to move.",
      why: "Mobile ions are required for conduction through an electrolyte."
    },
    {
      q: "Why does solid sodium chloride not conduct electricity effectively?",
      steps: [
        "Step 1: Solid NaCl contains ions.",
        "Step 2: The ions are held in fixed positions in the lattice.",
        "Step 3: They cannot move freely through the solid.",
        "Step 4: Therefore they cannot carry current through the substance."
      ],
      ans: "Solid sodium chloride does not conduct effectively because its ions cannot move freely.",
      why: "The ions become mobile only when the substance is molten or dissolved."
    }
  ],
  [
    {
      q: "A student says that solid NaCl conducts electricity because it contains ions. Is the statement complete?",
      hint: "Ask whether the ions can move.",
      steps: [
        "Step 1: Solid NaCl contains ions.",
        "Step 2: The ions are fixed in the crystal lattice.",
        "Step 3: Therefore they cannot move freely."
      ],
      ans: "No. Solid NaCl contains ions, but the ions are not free to move.",
      why: "Electrical conduction requires mobile charged particles."
    }
  ]
);


// ------------------------------------------------------------
// 2. MEANING OF ELECTROLYSIS
// ------------------------------------------------------------

add(
  "chemistry",
  "electrochemistry",
  "Meaning of Electrolysis",
  `<h2>Meaning of Electrolysis</h2>

  <p><strong>Electrolysis</strong> is the chemical decomposition of an ionic compound in the molten state or in aqueous solution by passing an electric current through it.</p>

  <p>The substance being decomposed must contain mobile ions.</p>

  <p>During electrolysis:</p>

  <ul>
    <li>Positive ions move towards the negative electrode.</li>
    <li>Negative ions move towards the positive electrode.</li>
  </ul>

  <h3>Example</h3>

  <p>Molten sodium chloride can be decomposed into sodium and chlorine:</p>

  <p><strong>2NaCl(l) → 2Na(l) + Cl₂(g)</strong></p>`,
  [
    {
      q: "Define electrolysis.",
      steps: [
        "Step 1: Identify electrolysis as a chemical process.",
        "Step 2: An ionic substance is decomposed.",
        "Step 3: Electrical energy is supplied to cause the decomposition."
      ],
      ans: "Electrolysis is the chemical decomposition of an ionic compound in the molten state or aqueous solution by passing an electric current through it.",
      why: "Electrical energy drives a non-spontaneous chemical decomposition."
    },
    {
      q: "What happens to molten sodium chloride during electrolysis?",
      steps: [
        "Step 1: Molten NaCl contains mobile Na⁺ and Cl⁻ ions.",
        "Step 2: Na⁺ ions move towards the negative electrode.",
        "Step 3: Cl⁻ ions move towards the positive electrode.",
        "Step 4: Sodium and chlorine are formed."
      ],
      ans: "Molten sodium chloride decomposes to form sodium and chlorine.",
      why: "The electric current causes the ions to discharge at the electrodes."
    },
    {
      q: "Write the overall equation for electrolysis of molten sodium chloride.",
      steps: [
        "Step 1: Sodium chloride provides Na⁺ and Cl⁻ ions.",
        "Step 2: Two chloride ions form one Cl₂ molecule.",
        "Step 3: Two sodium ions form two sodium atoms.",
        "Step 4: Balance the equation."
      ],
      ans: "2NaCl(l) → 2Na(l) + Cl₂(g).",
      why: "The equation conserves sodium and chlorine atoms."
    }
  ],
  [
    {
      q: "Can electrolysis occur in a solid ionic compound under ordinary conditions?",
      hint: "Think about whether its ions can move.",
      steps: [
        "Step 1: Electrolysis requires mobile ions.",
        "Step 2: Ions in a solid ionic lattice are not free to move.",
        "Step 3: Therefore the solid cannot normally undergo electrolysis."
      ],
      ans: "No. The ionic compound must normally be molten or dissolved so that its ions can move.",
      why: "Mobile ions are required to carry the current."
    }
  ]
);


// ------------------------------------------------------------
// 3. ELECTRODES
// ------------------------------------------------------------

add(
  "chemistry",
  "electrochemistry",
  "Electrodes",
  `<h2>Electrodes</h2>

  <p><strong>Electrodes</strong> are conductors through which electric current enters or leaves an electrolyte.</p>

  <p>There are two electrodes in an electrolytic cell:</p>

  <ul>
    <li><strong>Cathode:</strong> negative electrode in electrolysis.</li>
    <li><strong>Anode:</strong> positive electrode in electrolysis.</li>
  </ul>

  <p>Positive ions move towards the cathode.</p>

  <p>Negative ions move towards the anode.</p>

  <h3>Example</h3>

  <p>During electrolysis of molten NaCl:</p>

  <p>Na⁺ → cathode</p>

  <p>Cl⁻ → anode</p>`,
  [
    {
      q: "What is an electrode?",
      steps: [
        "Step 1: An electrode is placed in contact with the electrolyte.",
        "Step 2: It provides a conducting path for electric current.",
        "Step 3: Therefore it allows current to enter or leave the electrolyte."
      ],
      ans: "An electrode is a conductor through which electric current enters or leaves an electrolyte.",
      why: "Electrodes connect the external circuit to the ions in the electrolyte."
    },
    {
      q: "Which electrode attracts positive ions during electrolysis?",
      steps: [
        "Step 1: Positive ions are cations.",
        "Step 2: Opposite charges attract.",
        "Step 3: Therefore positive ions move towards the negative electrode.",
        "Step 4: The negative electrode is the cathode."
      ],
      ans: "The cathode.",
      why: "Positive ions are attracted to the negative cathode."
    },
    {
      q: "Which electrode attracts negative ions?",
      steps: [
        "Step 1: Negative ions are anions.",
        "Step 2: Opposite charges attract.",
        "Step 3: Negative ions move towards the positive electrode.",
        "Step 4: The positive electrode is the anode."
      ],
      ans: "The anode.",
      why: "Negative ions are attracted to the positive anode."
    }
  ],
  [
    {
      q: "A student says Cl⁻ ions move to the cathode. Correct the statement.",
      hint: "Cl⁻ is negatively charged.",
      steps: [
        "Step 1: Cl⁻ has a negative charge.",
        "Step 2: It is attracted to the positive electrode.",
        "Step 3: The positive electrode is the anode."
      ],
      ans: "Cl⁻ ions move to the anode.",
      why: "Negative ions are attracted to the positive electrode."
    }
  ]
);


// ------------------------------------------------------------
// 4. ANODE
// ------------------------------------------------------------

add(
  "chemistry",
  "electrochemistry",
  "Anode",
  `<h2>Anode</h2>

  <p>The <strong>anode</strong> is the positive electrode during electrolysis.</p>

  <p>Negative ions, called anions, move towards the anode.</p>

  <p>At the anode, anions lose electrons. This is oxidation.</p>

  <p>A useful memory rule is:</p>

  <p><strong>AN OX</strong> → Anode = Oxidation.</p>

  <h3>Example</h3>

  <p>During electrolysis of molten sodium chloride:</p>

  <p><strong>2Cl⁻ → Cl₂ + 2e⁻</strong></p>

  <p>Chloride ions lose electrons at the anode.</p>`,
  [
    {
      q: "What is the charge of the anode during electrolysis?",
      steps: [
        "Step 1: Recall the electrodes in an electrolytic cell.",
        "Step 2: The cathode is negative.",
        "Step 3: Therefore the anode is positive."
      ],
      ans: "The anode is positive.",
      why: "In an electrolytic cell, the external power supply makes the anode positive."
    },
    {
      q: "What happens to chloride ions at the anode?",
      steps: [
        "Step 1: Chloride ions are negative ions.",
        "Step 2: They move towards the positive anode.",
        "Step 3: At the anode they lose electrons.",
        "Step 4: Two chloride ions form one chlorine molecule."
      ],
      ans: "Chloride ions lose electrons and form chlorine gas: 2Cl⁻ → Cl₂ + 2e⁻.",
      why: "Loss of electrons is oxidation, and oxidation occurs at the anode."
    },
    {
      q: "What type of process occurs at the anode?",
      steps: [
        "Step 1: Ions at the anode lose electrons.",
        "Step 2: Loss of electrons is oxidation.",
        "Step 3: Therefore oxidation occurs at the anode."
      ],
      ans: "Oxidation.",
      why: "The anode is the site of oxidation."
    }
  ],
  [
    {
      q: "At which electrode would Br⁻ ions be discharged during electrolysis?",
      hint: "Br⁻ is negatively charged.",
      steps: [
        "Step 1: Br⁻ is an anion.",
        "Step 2: Anions move towards the positive electrode.",
        "Step 3: The positive electrode is the anode."
      ],
      ans: "The anode.",
      why: "Negative ions are attracted to the positive anode."
    }
  ]
);


// ------------------------------------------------------------
// 5. CATHODE
// ------------------------------------------------------------

add(
  "chemistry",
  "electrochemistry",
  "Cathode",
  `<h2>Cathode</h2>

  <p>The <strong>cathode</strong> is the negative electrode during electrolysis.</p>

  <p>Positive ions, called cations, move towards the cathode.</p>

  <p>At the cathode, cations gain electrons. This is reduction.</p>

  <p>A useful memory rule is:</p>

  <p><strong>RED CAT</strong> → Reduction = Cathode.</p>

  <h3>Example</h3>

  <p>During electrolysis of molten sodium chloride:</p>

  <p><strong>Na⁺ + e⁻ → Na</strong></p>

  <p>Sodium ions gain electrons at the cathode.</p>`,
  [
    {
      q: "What is the charge of the cathode during electrolysis?",
      steps: [
        "Step 1: Recall the two electrodes.",
        "Step 2: The anode is positive.",
        "Step 3: Therefore the cathode is negative."
      ],
      ans: "The cathode is negative.",
      why: "The external power supply makes the cathode negative in an electrolytic cell."
    },
    {
      q: "What happens to sodium ions at the cathode?",
      steps: [
        "Step 1: Na⁺ is a positive ion.",
        "Step 2: It moves towards the negative cathode.",
        "Step 3: It gains one electron.",
        "Step 4: It forms a sodium atom."
      ],
      ans: "Na⁺ gains an electron: Na⁺ + e⁻ → Na.",
      why: "Gain of electrons is reduction, and reduction occurs at the cathode."
    },
    {
      q: "What type of process occurs at the cathode?",
      steps: [
        "Step 1: Positive ions gain electrons at the cathode.",
        "Step 2: Gain of electrons is reduction.",
        "Step 3: Therefore reduction occurs at the cathode."
      ],
      ans: "Reduction.",
      why: "The cathode is the site of reduction."
    }
  ],
  [
    {
      q: "A student says that positive ions move to the anode during electrolysis. Correct the statement.",
      hint: "Positive ions are attracted to which electrode?",
      steps: [
        "Step 1: Positive ions are attracted to negative charges.",
        "Step 2: The cathode is negative during electrolysis.",
        "Step 3: Therefore positive ions move to the cathode."
      ],
      ans: "Positive ions move to the cathode.",
      why: "Opposite charges attract."
    }
  ]
);


// ------------------------------------------------------------
// 6. ELECTROLYSIS OF MOLTEN COMPOUNDS
// ------------------------------------------------------------

add(
  "chemistry",
  "electrochemistry",
  "Electrolysis of Molten Compounds",
  `<h2>Electrolysis of Molten Compounds</h2>

  <p>When an ionic compound is molten, its ions are free to move and can be discharged at the electrodes.</p>

  <p>For molten sodium chloride:</p>

  <p><strong>At the cathode:</strong></p>
  <p>Na⁺ + e⁻ → Na</p>

  <p><strong>At the anode:</strong></p>
  <p>2Cl⁻ → Cl₂ + 2e⁻</p>

  <p><strong>Overall:</strong></p>
  <p>2NaCl(l) → 2Na(l) + Cl₂(g)</p>

  <p>The products are sodium metal and chlorine gas.</p>`,
  [
    {
      q: "What are the products of electrolysis of molten sodium chloride?",
      steps: [
        "Step 1: Molten NaCl contains Na⁺ and Cl⁻ ions.",
        "Step 2: Na⁺ is reduced at the cathode to form sodium.",
        "Step 3: Cl⁻ is oxidised at the anode to form chlorine.",
        "Step 4: Therefore the products are sodium and chlorine."
      ],
      ans: "Sodium and chlorine gas.",
      why: "Na⁺ forms sodium at the cathode while Cl⁻ forms chlorine at the anode."
    },
    {
      q: "Write the half-equation for sodium ions at the cathode.",
      steps: [
        "Step 1: Sodium ion has a +1 charge.",
        "Step 2: It must gain one electron to become neutral.",
        "Step 3: Write the half-equation."
      ],
      ans: "Na⁺ + e⁻ → Na.",
      why: "The sodium ion is reduced by gaining an electron."
    },
    {
      q: "Write the half-equation for chloride ions at the anode.",
      steps: [
        "Step 1: Chloride ions lose electrons at the anode.",
        "Step 2: Two chloride ions form one chlorine molecule.",
        "Step 3: Two electrons are released."
      ],
      ans: "2Cl⁻ → Cl₂ + 2e⁻.",
      why: "Chloride ions are oxidised to chlorine gas."
    }
  ],
  [
    {
      q: "Why is sodium not produced from solid sodium chloride during electrolysis?",
      hint: "Think about the movement of ions in solid NaCl.",
      steps: [
        "Step 1: Solid NaCl has ions fixed in a lattice.",
        "Step 2: The ions cannot move freely.",
        "Step 3: Therefore electrolysis cannot proceed normally."
      ],
      ans: "Because the ions in solid NaCl cannot move freely.",
      why: "The compound must be molten or dissolved for its ions to carry current."
    }
  ]
);


// ------------------------------------------------------------
// 7. ELECTROLYSIS OF AQUEOUS SOLUTIONS
// ------------------------------------------------------------

add(
  "chemistry",
  "electrochemistry",
  "Electrolysis of Aqueous Solutions",
  `<h2>Electrolysis of Aqueous Solutions</h2>

  <p>An aqueous electrolyte contains ions from the dissolved compound and ions from water.</p>

  <p>Therefore, more than one type of ion may compete for discharge at an electrode.</p>

  <p>For example, aqueous sodium chloride contains:</p>

  <ul>
    <li>Na⁺</li>
    <li>Cl⁻</li>
    <li>H⁺ from water</li>
    <li>OH⁻ from water</li>
  </ul>

  <p>The products depend on which ions are preferentially discharged at each electrode.</p>

  <h3>Important idea</h3>

  <p>Do not assume that the ions in the dissolved salt are automatically the products.</p>`,
  [
    {
      q: "Why is electrolysis of an aqueous solution different from electrolysis of a molten compound?",
      steps: [
        "Step 1: A molten compound mainly contains ions from the compound.",
        "Step 2: An aqueous solution contains ions from the compound and ions associated with water.",
        "Step 3: These ions can compete for discharge."
      ],
      ans: "An aqueous solution contains additional ions from water, so several ions may compete for discharge.",
      why: "The presence of water changes which species are available at the electrodes."
    },
    {
      q: "Name the four ions commonly considered when aqueous sodium chloride is electrolysed.",
      steps: [
        "Step 1: Sodium chloride supplies Na⁺ and Cl⁻.",
        "Step 2: Water supplies H⁺ and OH⁻ for the electrolysis analysis.",
        "Step 3: List all four ions."
      ],
      ans: "Na⁺, Cl⁻, H⁺ and OH⁻.",
      why: "These are the ions available for consideration in aqueous sodium chloride."
    },
    {
      q: "Why can water affect the products obtained during electrolysis of an aqueous solution?",
      steps: [
        "Step 1: Water provides additional ions.",
        "Step 2: These ions can move towards the electrodes.",
        "Step 3: They may be discharged instead of ions from the dissolved salt."
      ],
      ans: "Water provides additional ions that may compete for discharge at the electrodes.",
      why: "The final products depend on which ions are preferentially discharged."
    }
  ],
  [
    {
      q: "A student treats aqueous NaCl as though it contains only Na⁺ and Cl⁻. What important ions have been omitted?",
      hint: "Consider the water in the solution.",
      steps: [
        "Step 1: Aqueous NaCl contains Na⁺ and Cl⁻ from the salt.",
        "Step 2: Water also contributes H⁺ and OH⁻ to the electrolysis analysis.",
        "Step 3: Therefore two additional ions must be considered."
      ],
      ans: "H⁺ and OH⁻.",
      why: "Water introduces additional ionic species into an aqueous electrolyte."
    }
  ]
);


// ------------------------------------------------------------
// 8. ELECTROLYSIS OF COPPER(II) SULPHATE
// ------------------------------------------------------------

add(
  "chemistry",
  "electrochemistry",
  "Electrolysis of Copper(II) Sulphate",
  `<h2>Electrolysis of Copper(II) Sulphate</h2>

  <p>Aqueous copper(II) sulphate contains Cu²⁺ ions, SO₄²⁻ ions and ions from water.</p>

  <p>Using inert electrodes:</p>

  <p><strong>At the cathode:</strong></p>
  <p>Cu²⁺ + 2e⁻ → Cu</p>

  <p>Copper is deposited at the cathode.</p>

  <p><strong>At the anode:</strong></p>
  <p>Water is oxidised to produce oxygen:</p>

  <p><strong>4OH⁻ → O₂ + 2H₂O + 4e⁻</strong></p>

  <p>Therefore copper is deposited at the cathode and oxygen is produced at the anode when inert electrodes are used.</p>`,
  [
    {
      q: "Which substance is deposited at the cathode during electrolysis of aqueous copper(II) sulphate using inert electrodes?",
      steps: [
        "Step 1: Copper(II) sulphate provides Cu²⁺ ions.",
        "Step 2: Cu²⁺ ions move to the negative cathode.",
        "Step 3: Cu²⁺ gains two electrons.",
        "Step 4: Copper metal is deposited."
      ],
      ans: "Copper.",
      why: "Cu²⁺ ions are reduced to copper atoms at the cathode."
    },
    {
      q: "Write the cathode half-equation for aqueous copper(II) sulphate.",
      steps: [
        "Step 1: Copper(II) ion is Cu²⁺.",
        "Step 2: It needs two electrons to become neutral copper.",
        "Step 3: Write the balanced half-equation."
      ],
      ans: "Cu²⁺ + 2e⁻ → Cu.",
      why: "Copper(II) ions gain electrons and are reduced to copper."
    },
    {
      q: "What gas is produced at the anode when inert electrodes are used?",
      steps: [
        "Step 1: Sulphate ions are not preferentially discharged under these conditions.",
        "Step 2: Water/OH⁻ is oxidised at the anode.",
        "Step 3: Oxygen is formed."
      ],
      ans: "Oxygen gas.",
      why: "Oxidation of water produces oxygen at the inert anode."
    }
  ],
  [
    {
      q: "A student predicts that copper metal will form at the anode during electrolysis of aqueous CuSO₄ using inert electrodes. Correct the prediction.",
      hint: "Copper(II) ions are positive. Which electrode attracts them?",
      steps: [
        "Step 1: Cu²⁺ ions are positively charged.",
        "Step 2: They move towards the negative cathode.",
        "Step 3: They gain electrons there.",
        "Step 4: Copper is therefore deposited at the cathode."
      ],
      ans: "Copper is deposited at the cathode, not the anode.",
      why: "Cu²⁺ ions are reduced at the cathode."
    }
  ]
);


// ------------------------------------------------------------
// 9. ELECTROPLATING
// ------------------------------------------------------------

add(
  "chemistry",
  "electrochemistry",
  "Electroplating",
  `<h2>Electroplating</h2>

  <p><strong>Electroplating</strong> is the coating of one metal object with a thin layer of another metal using electrolysis.</p>

  <h3>Arrangement</h3>

  <ul>
    <li>The object to be coated is made the <strong>cathode</strong>.</li>
    <li>The coating metal is usually the <strong>anode</strong>.</li>
    <li>The electrolyte contains ions of the coating metal.</li>
  </ul>

  <p>For copper plating, Cu²⁺ ions gain electrons at the object:</p>

  <p><strong>Cu²⁺ + 2e⁻ → Cu</strong></p>

  <p>Copper is therefore deposited onto the cathode.</p>`,
  [
    {
      q: "What is electroplating?",
      steps: [
        "Step 1: Identify electroplating as an electrolysis process.",
        "Step 2: A layer of one metal is deposited onto another object.",
        "Step 3: The deposited metal forms a coating."
      ],
      ans: "Electroplating is coating one metal object with a thin layer of another metal using electrolysis.",
      why: "Electrolysis can be used to deposit metal ions onto an object's surface."
    },
    {
      q: "Which electrode is the object being plated?",
      steps: [
        "Step 1: Metal ions are positively charged.",
        "Step 2: Positive metal ions move towards the negative electrode.",
        "Step 3: Therefore the object must be connected to the negative electrode."
      ],
      ans: "The object being plated is the cathode.",
      why: "Positive metal ions are reduced and deposited at the negative cathode."
    },
    {
      q: "Write the half-equation for copper deposition during copper electroplating.",
      steps: [
        "Step 1: Copper ions are Cu²⁺.",
        "Step 2: Each Cu²⁺ ion needs two electrons.",
        "Step 3: Write the reduction equation."
      ],
      ans: "Cu²⁺ + 2e⁻ → Cu.",
      why: "Copper ions gain electrons and become copper metal."
    }
  ],
  [
    {
      q: "A student connects the object to be plated to the positive terminal. Will metal ions normally deposit on it?",
      hint: "The object being plated must attract positive metal ions.",
      steps: [
        "Step 1: Metal ions are positively charged.",
        "Step 2: They are attracted to the negative electrode.",
        "Step 3: The object being plated should therefore be the cathode."
      ],
      ans: "No. The object should normally be connected to the negative terminal so that it acts as the cathode.",
      why: "Positive metal ions are deposited at the negative cathode."
    }
  ]
);


// ------------------------------------------------------------
// 10. APPLICATIONS OF ELECTROLYSIS
// ------------------------------------------------------------

add(
  "chemistry",
  "electrochemistry",
  "Applications of Electrolysis",
  `<h2>Applications of Electrolysis</h2>

  <p>Electrolysis has several important applications.</p>

  <ul>
    <li>Extraction of very reactive metals.</li>
    <li>Electroplating objects.</li>
    <li>Purification of metals.</li>
    <li>Manufacture of useful chemicals.</li>
  </ul>

  <h3>Examples</h3>

  <p><strong>Extraction:</strong> Aluminium is extracted from molten aluminium oxide by electrolysis because aluminium is too reactive to be extracted by ordinary chemical reduction with carbon.</p>

  <p><strong>Electroplating:</strong> Objects can be coated with metals such as copper, nickel or chromium.</p>

  <p><strong>Purification:</strong> Electrolysis can be used to purify copper.</p>

  <p><strong>Chemical manufacture:</strong> Electrolysis of brine is used industrially to produce chlorine, hydrogen and sodium hydroxide.</p>`,
  [
    {
      q: "State two applications of electrolysis.",
      steps: [
        "Step 1: Recall the major uses of electrolysis.",
        "Step 2: Select any two distinct applications.",
        "Step 3: Examples include electroplating and extraction of reactive metals."
      ],
      ans: "Electrolysis is used for electroplating and extraction of reactive metals.",
      why: "Electrical energy can drive both metal deposition and decomposition of ionic compounds."
    },
    {
      q: "Why is electrolysis used to extract aluminium?",
      steps: [
        "Step 1: Aluminium is high in the reactivity series.",
        "Step 2: Its compounds are difficult to reduce using carbon.",
        "Step 3: Molten aluminium oxide can be decomposed by electrolysis.",
        "Step 4: Aluminium is produced at the cathode."
      ],
      ans: "Electrolysis is used because aluminium is highly reactive and cannot be extracted effectively by reducing its oxide with carbon.",
      why: "The high reactivity of aluminium makes electrolysis necessary for its extraction."
    },
    {
      q: "State two products obtained from electrolysis of brine.",
      steps: [
        "Step 1: Brine is concentrated aqueous sodium chloride.",
        "Step 2: Electrolysis produces chlorine at the anode.",
        "Step 3: Hydrogen is produced at the cathode.",
        "Step 4: Sodium hydroxide remains in the solution."
      ],
      ans: "Chlorine and hydrogen are produced, while sodium hydroxide is formed in the solution.",
      why: "Electrolysis of brine separates the components into useful industrial products."
    }
  ],
  [
    {
      q: "A student claims electrolysis is useful only for extracting metals. Give one other application.",
      hint: "Think about depositing a metal onto an object.",
      steps: [
        "Step 1: Electrolysis can cause metal ions to gain electrons.",
        "Step 2: The metal can be deposited onto an object.",
        "Step 3: This process is electroplating."
      ],
      ans: "Electroplating.",
      why: "Electrolysis is used to coat objects with a layer of another metal."
    }
  ]
);
// ============================================================
// BATCH 16 — ORGANIC CHEMISTRY FOUNDATIONS
// Chapter ID: organic_chemistry
// ============================================================


// ------------------------------------------------------------
// 1. INTRODUCTION TO ORGANIC CHEMISTRY
// ------------------------------------------------------------

add(
  "chemistry",
  "organic_chemistry",
  "Introduction to Organic Chemistry",
  `<h2>Introduction to Organic Chemistry</h2>

  <p><strong>Organic chemistry</strong> is the study of carbon compounds, especially compounds containing carbon and hydrogen.</p>

  <p>Examples of organic compounds include:</p>

  <ul>
    <li>Methane, CH₄</li>
    <li>Ethane, C₂H₆</li>
    <li>Ethanol, C₂H₅OH</li>
    <li>Ethanoic acid, CH₃COOH</li>
  </ul>

  <p>Carbon forms a very large number of compounds because carbon atoms can bond strongly to other carbon atoms and to many other elements.</p>

  <h3>Important distinction</h3>

  <p>Not every carbon-containing substance is normally classified as an organic compound. For example, carbon dioxide, CO₂, carbon monoxide, CO, and carbonates are generally treated as inorganic compounds in school chemistry.</p>

  <h3>Examples</h3>

  <p><strong>Example 1:</strong> CH₄ is an organic compound.</p>

  <p><strong>Example 2:</strong> C₂H₅OH is an organic compound.</p>

  <p><strong>Example 3:</strong> CO₂ contains carbon but is treated as an inorganic compound.</p>`,
  [
    {
      q: "What is organic chemistry?",
      steps: [
        "Step 1: Organic chemistry deals mainly with compounds of carbon.",
        "Step 2: Many of these compounds contain carbon and hydrogen.",
        "Step 3: Therefore organic chemistry is the study of carbon compounds, especially hydrocarbons and their derivatives."
      ],
      ans: "Organic chemistry is the study of carbon compounds, especially compounds containing carbon and hydrogen.",
      why: "Carbon forms an enormous number of compounds with hydrogen and other elements."
    },
    {
      q: "State two examples of organic compounds.",
      steps: [
        "Step 1: Identify compounds containing carbon and hydrogen.",
        "Step 2: Methane contains carbon and hydrogen.",
        "Step 3: Ethanol also contains carbon and hydrogen."
      ],
      ans: "Methane and ethanol.",
      why: "Both are carbon-containing organic compounds."
    },
    {
      q: "Is carbon dioxide an organic compound?",
      steps: [
        "Step 1: Carbon dioxide contains carbon.",
        "Step 2: However, not every carbon-containing compound is classified as organic.",
        "Step 3: CO₂ is treated as an inorganic carbon compound."
      ],
      ans: "No. Carbon dioxide is generally classified as an inorganic carbon compound.",
      why: "Certain simple carbon compounds, including CO₂, are treated as inorganic in school chemistry."
    }
  ],
  [
    {
      q: "A student says every compound containing carbon is organic. Is this correct?",
      hint: "Think about carbon dioxide.",
      steps: [
        "Step 1: CO₂ contains carbon.",
        "Step 2: CO₂ is normally classified as inorganic.",
        "Step 3: Therefore not every carbon-containing compound is organic."
      ],
      ans: "No. Some carbon-containing compounds, such as CO₂, are classified as inorganic.",
      why: "The presence of carbon alone does not make a compound organic."
    }
  ]
);


// ------------------------------------------------------------
// 2. TETRAVALENCY OF CARBON
// ------------------------------------------------------------

add(
  "chemistry",
  "organic_chemistry",
  "Tetravalency of Carbon",
  `<h2>Tetravalency of Carbon</h2>

  <p>Carbon has atomic number 6 and has four electrons in its outer shell.</p>

  <p>Carbon normally forms <strong>four covalent bonds</strong>. This property is called <strong>tetravalency</strong>.</p>

  <p>For example, methane has the formula CH₄.</p>

  <p>The carbon atom forms four single covalent bonds with four hydrogen atoms.</p>

  <h3>Methane</h3>

  <p>CH₄ contains:</p>

  <ul>
    <li>1 carbon atom</li>
    <li>4 hydrogen atoms</li>
    <li>4 C–H covalent bonds</li>
  </ul>

  <p>Carbon can also form bonds with other carbon atoms, allowing chains and rings to develop.</p>`,
  [
    {
      q: "What is meant by tetravalency of carbon?",
      steps: [
        "Step 1: Carbon has four electrons in its outer shell.",
        "Step 2: Carbon commonly forms four covalent bonds.",
        "Step 3: This ability is called tetravalency."
      ],
      ans: "Tetravalency is the ability of carbon to form four covalent bonds.",
      why: "Carbon's bonding capacity allows it to form many different compounds."
    },
    {
      q: "How many covalent bonds does carbon form in methane, CH₄?",
      steps: [
        "Step 1: Methane contains one carbon atom.",
        "Step 2: Its formula is CH₄.",
        "Step 3: Carbon bonds to four hydrogen atoms.",
        "Step 4: Therefore carbon forms four covalent bonds."
      ],
      ans: "Four covalent bonds.",
      why: "Carbon is tetravalent."
    },
    {
      q: "How many carbon atoms and hydrogen atoms are present in C₂H₆?",
      steps: [
        "Step 1: The subscript after C is 2.",
        "Step 2: Therefore there are 2 carbon atoms.",
        "Step 3: The subscript after H is 6.",
        "Step 4: Therefore there are 6 hydrogen atoms."
      ],
      ans: "2 carbon atoms and 6 hydrogen atoms.",
      why: "Subscripts in a chemical formula show the number of atoms of each element."
    }
  ],
  [
    {
      q: "A student says carbon forms only two covalent bonds. Is this correct?",
      hint: "Recall the meaning of tetravalency.",
      steps: [
        "Step 1: Carbon is tetravalent.",
        "Step 2: Tetravalent means it can form four covalent bonds.",
        "Step 3: Therefore the statement is incorrect."
      ],
      ans: "No. Carbon normally forms four covalent bonds.",
      why: "Carbon's tetravalency is one reason it forms many organic compounds."
    }
  ]
);


// ------------------------------------------------------------
// 3. CATENATION
// ------------------------------------------------------------

add(
  "chemistry",
  "organic_chemistry",
  "Catenation",
  `<h2>Catenation</h2>

  <p><strong>Catenation</strong> is the ability of an element to form covalent bonds with atoms of the same element, producing chains, branches or rings.</p>

  <p>Carbon shows extensive catenation.</p>

  <p>Carbon atoms can join together to form:</p>

  <ul>
    <li>Short chains</li>
    <li>Long chains</li>
    <li>Branched chains</li>
    <li>Rings</li>
  </ul>

  <h3>Examples</h3>

  <p>Methane: CH₄ → one carbon atom.</p>

  <p>Ethane: C₂H₆ → two carbon atoms joined together.</p>

  <p>Propane: C₃H₈ → three carbon atoms joined in a chain.</p>

  <p>Butane: C₄H₁₀ → four carbon atoms joined in a chain.</p>`,
  [
    {
      q: "What is catenation?",
      steps: [
        "Step 1: Identify bonding between atoms of the same element.",
        "Step 2: Carbon can bond strongly to other carbon atoms.",
        "Step 3: This allows chains, branches and rings to form."
      ],
      ans: "Catenation is the ability of an element to form covalent bonds with atoms of the same element, producing chains, branches or rings.",
      why: "Carbon-carbon bonding allows organic compounds to have many different structures."
    },
    {
      q: "Why can carbon form long chains?",
      steps: [
        "Step 1: Carbon atoms can form strong covalent bonds with other carbon atoms.",
        "Step 2: One carbon atom can bond to another carbon atom.",
        "Step 3: The process can continue repeatedly.",
        "Step 4: Long carbon chains can therefore form."
      ],
      ans: "Carbon forms long chains because carbon atoms can form strong covalent bonds with other carbon atoms.",
      why: "Carbon's ability to bond to itself is called catenation."
    },
    {
      q: "How many carbon atoms are joined together in propane, C₃H₈?",
      steps: [
        "Step 1: Read the subscript after C.",
        "Step 2: The subscript is 3.",
        "Step 3: Therefore propane contains three carbon atoms."
      ],
      ans: "Three carbon atoms.",
      why: "The formula C₃H₈ contains three carbon atoms."
    }
  ],
  [
    {
      q: "Which property of carbon allows carbon atoms to form carbon chains?",
      hint: "Think about carbon bonding to itself.",
      steps: [
        "Step 1: Carbon atoms can bond to other carbon atoms.",
        "Step 2: This produces chains and other structures.",
        "Step 3: This property is catenation."
      ],
      ans: "Catenation.",
      why: "Catenation is carbon's ability to bond to itself."
    }
  ]
);


// ------------------------------------------------------------
// 4. HYDROCARBONS
// ------------------------------------------------------------

add(
  "chemistry",
  "organic_chemistry",
  "Hydrocarbons",
  `<h2>Hydrocarbons</h2>

  <p>A <strong>hydrocarbon</strong> is an organic compound containing only carbon and hydrogen.</p>

  <p>Examples include:</p>

  <ul>
    <li>Methane, CH₄</li>
    <li>Ethane, C₂H₆</li>
    <li>Propane, C₃H₈</li>
    <li>Ethene, C₂H₄</li>
    <li>Ethyne, C₂H₂</li>
  </ul>

  <p>Hydrocarbons can be classified according to the types of carbon-carbon bonds they contain.</p>

  <ul>
    <li><strong>Alkanes:</strong> contain only carbon-carbon single bonds.</li>
    <li><strong>Alkenes:</strong> contain at least one carbon-carbon double bond.</li>
    <li><strong>Alkynes:</strong> contain at least one carbon-carbon triple bond.</li>
  </ul>`,
  [
    {
      q: "What is a hydrocarbon?",
      steps: [
        "Step 1: Identify the elements present.",
        "Step 2: A hydrocarbon contains carbon.",
        "Step 3: It also contains hydrogen.",
        "Step 4: No other elements are present in a hydrocarbon."
      ],
      ans: "A hydrocarbon is an organic compound containing only carbon and hydrogen.",
      why: "The name hydrocarbon reflects hydrogen and carbon."
    },
    {
      q: "Is ethanol, C₂H₅OH, a hydrocarbon?",
      steps: [
        "Step 1: Check the elements present.",
        "Step 2: Ethanol contains carbon and hydrogen.",
        "Step 3: It also contains oxygen.",
        "Step 4: Therefore it is not a hydrocarbon."
      ],
      ans: "No. Ethanol is not a hydrocarbon because it contains oxygen as well as carbon and hydrogen.",
      why: "Hydrocarbons contain only carbon and hydrogen."
    },
    {
      q: "Classify ethene, C₂H₄, as an alkane, alkene or alkyne.",
      steps: [
        "Step 1: Ethene contains a carbon-carbon double bond.",
        "Step 2: Compounds containing a C=C double bond are alkenes.",
        "Step 3: Therefore ethene is an alkene."
      ],
      ans: "Ethene is an alkene.",
      why: "Alkenes contain at least one carbon-carbon double bond."
    }
  ],
  [
    {
      q: "A compound contains carbon, hydrogen and chlorine. Is it a hydrocarbon?",
      hint: "Hydrocarbons contain how many elements?",
      steps: [
        "Step 1: A hydrocarbon contains only carbon and hydrogen.",
        "Step 2: The compound also contains chlorine.",
        "Step 3: Therefore it is not a hydrocarbon."
      ],
      ans: "No. It is not a hydrocarbon because it contains chlorine.",
      why: "A hydrocarbon must contain only carbon and hydrogen."
    }
  ]
);


// ------------------------------------------------------------
// 5. ALKANES
// ------------------------------------------------------------

add(
  "chemistry",
  "organic_chemistry",
  "Alkanes",
  `<h2>Alkanes</h2>

  <p><strong>Alkanes</strong> are saturated hydrocarbons containing only carbon-carbon single bonds.</p>

  <p>The general formula for open-chain alkanes is:</p>

  <p><strong>CₙH₂ₙ₊₂</strong></p>

  <h3>First members</h3>

  <ul>
    <li>Methane — CH₄</li>
    <li>Ethane — C₂H₆</li>
    <li>Propane — C₃H₈</li>
    <li>Butane — C₄H₁₀</li>
    <li>Pentane — C₅H₁₂</li>
  </ul>

  <h3>Example</h3>

  <p>For n = 4:</p>

  <p>H = 2(4) + 2 = 10</p>

  <p>Therefore the formula is C₄H₁₀.</p>`,
  [
    {
      q: "What is an alkane?",
      steps: [
        "Step 1: Identify the type of hydrocarbon.",
        "Step 2: Alkanes contain only carbon-carbon single bonds.",
        "Step 3: Therefore they are saturated hydrocarbons."
      ],
      ans: "An alkane is a saturated hydrocarbon containing only carbon-carbon single bonds.",
      why: "The absence of carbon-carbon multiple bonds makes an open-chain alkane saturated."
    },
    {
      q: "State the general formula of open-chain alkanes.",
      steps: [
        "Step 1: Recall the alkane general formula.",
        "Step 2: Substitute the number of carbon atoms with n.",
        "Step 3: The formula is CₙH₂ₙ₊₂."
      ],
      ans: "CₙH₂ₙ₊₂.",
      why: "This formula applies to open-chain saturated hydrocarbons."
    },
    {
      q: "Find the molecular formula of the alkane with 6 carbon atoms.",
      steps: [
        "Step 1: Use CₙH₂ₙ₊₂.",
        "Step 2: Substitute n = 6.",
        "Step 3: H = 2(6) + 2.",
        "Step 4: H = 12 + 2 = 14."
      ],
      ans: "C₆H₁₄.",
      why: "The alkane formula is CₙH₂ₙ₊₂."
    }
  ],
  [
    {
      q: "A student gives C₄H₈ as the formula of an open-chain alkane. Check the answer.",
      hint: "Use CₙH₂ₙ₊₂.",
      steps: [
        "Step 1: For n = 4, H = 2(4) + 2.",
        "Step 2: H = 8 + 2 = 10.",
        "Step 3: Therefore the alkane formula should contain 10 hydrogen atoms."
      ],
      ans: "The correct formula is C₄H₁₀.",
      why: "C₄H₈ does not satisfy the general formula for an open-chain alkane."
    }
  ]
);


// ------------------------------------------------------------
// 6. ALKENES
// ------------------------------------------------------------

add(
  "chemistry",
  "organic_chemistry",
  "Alkenes",
  `<h2>Alkenes</h2>

  <p><strong>Alkenes</strong> are unsaturated hydrocarbons containing at least one carbon-carbon double bond.</p>

  <p>The general formula for open-chain alkenes containing one double bond is:</p>

  <p><strong>CₙH₂ₙ</strong></p>

  <h3>Examples</h3>

  <ul>
    <li>Ethene — C₂H₄</li>
    <li>Propene — C₃H₆</li>
    <li>Butene — C₄H₈</li>
    <li>Pentene — C₅H₁₀</li>
  </ul>

  <p>The carbon-carbon double bond is responsible for many characteristic reactions of alkenes.</p>`,
  [
    {
      q: "What is an alkene?",
      steps: [
        "Step 1: Identify the type of hydrocarbon.",
        "Step 2: Alkenes contain a carbon-carbon double bond.",
        "Step 3: Therefore they are unsaturated hydrocarbons."
      ],
      ans: "An alkene is an unsaturated hydrocarbon containing at least one carbon-carbon double bond.",
      why: "The double bond means the carbon atoms do not contain the maximum possible number of hydrogen atoms."
    },
    {
      q: "State the general formula for open-chain alkenes with one double bond.",
      steps: [
        "Step 1: Recall the alkene general formula.",
        "Step 2: Express it using n carbon atoms.",
        "Step 3: The formula is CₙH₂ₙ."
      ],
      ans: "CₙH₂ₙ.",
      why: "This is the general formula for open-chain alkenes containing one double bond."
    },
    {
      q: "Find the molecular formula of an alkene containing 5 carbon atoms.",
      steps: [
        "Step 1: Use CₙH₂ₙ.",
        "Step 2: Substitute n = 5.",
        "Step 3: H = 2(5) = 10."
      ],
      ans: "C₅H₁₀.",
      why: "The formula CₙH₂ₙ gives C₅H₁₀ when n = 5."
    }
  ],
  [
    {
      q: "A compound has formula C₄H₈ and is an open-chain hydrocarbon with one double bond. Is it an alkene?",
      hint: "Compare its formula with CₙH₂ₙ.",
      steps: [
        "Step 1: For n = 4, CₙH₂ₙ gives C₄H₈.",
        "Step 2: The formula matches the general formula.",
        "Step 3: Therefore it can be an alkene."
      ],
      ans: "Yes. C₄H₈ matches the general formula of an open-chain alkene.",
      why: "The formula is consistent with an alkene containing one double bond."
    }
  ]
);


// ------------------------------------------------------------
// 7. ALKYNES
// ------------------------------------------------------------

add(
  "chemistry",
  "organic_chemistry",
  "Alkynes",
  `<h2>Alkynes</h2>

  <p><strong>Alkynes</strong> are unsaturated hydrocarbons containing at least one carbon-carbon triple bond.</p>

  <p>The general formula for open-chain alkynes containing one triple bond is:</p>

  <p><strong>CₙH₂ₙ₋₂</strong></p>

  <h3>Examples</h3>

  <ul>
    <li>Ethyne — C₂H₂</li>
    <li>Propyne — C₃H₄</li>
    <li>Butyne — C₄H₆</li>
    <li>Pentyne — C₅H₈</li>
  </ul>

  <p>The carbon-carbon triple bond is characteristic of alkynes.</p>`,
  [
    {
      q: "What is an alkyne?",
      steps: [
        "Step 1: Identify the type of hydrocarbon.",
        "Step 2: Alkynes contain a carbon-carbon triple bond.",
        "Step 3: Therefore they are unsaturated hydrocarbons."
      ],
      ans: "An alkyne is an unsaturated hydrocarbon containing at least one carbon-carbon triple bond.",
      why: "The triple bond is the defining structural feature of an alkyne."
    },
    {
      q: "State the general formula for an open-chain alkyne with one triple bond.",
      steps: [
        "Step 1: Recall the alkyne general formula.",
        "Step 2: Express it using n carbon atoms.",
        "Step 3: The formula is CₙH₂ₙ₋₂."
      ],
      ans: "CₙH₂ₙ₋₂.",
      why: "This is the general formula for an open-chain alkyne containing one triple bond."
    },
    {
      q: "Find the molecular formula of an alkyne containing 4 carbon atoms.",
      steps: [
        "Step 1: Use CₙH₂ₙ₋₂.",
        "Step 2: Substitute n = 4.",
        "Step 3: H = 2(4) − 2.",
        "Step 4: H = 8 − 2 = 6."
      ],
      ans: "C₄H₆.",
      why: "The formula CₙH₂ₙ₋₂ gives C₄H₆ when n = 4."
    }
  ],
  [
    {
      q: "A student gives C₃H₈ as the formula of an open-chain alkyne. Check the answer.",
      hint: "Use CₙH₂ₙ₋₂.",
      steps: [
        "Step 1: Substitute n = 3.",
        "Step 2: H = 2(3) − 2.",
        "Step 3: H = 6 − 2 = 4.",
        "Step 4: Therefore the alkyne should be C₃H₄."
      ],
      ans: "The correct formula is C₃H₄.",
      why: "C₃H₈ is an alkane formula, not an open-chain alkyne formula."
    }
  ]
);


// ------------------------------------------------------------
// 8. HOMOLOGOUS SERIES
// ------------------------------------------------------------

add(
  "chemistry",
  "organic_chemistry",
  "Homologous Series",
  `<h2>Homologous Series</h2>

  <p>A <strong>homologous series</strong> is a family of organic compounds with:</p>

  <ul>
    <li>The same functional group.</li>
    <li>The same general formula.</li>
    <li>Similar chemical properties.</li>
    <li>A gradual change in physical properties.</li>
    <li>Successive members differing by a <strong>CH₂</strong> unit.</li>
  </ul>

  <h3>Example: Alkanes</h3>

  <p>Methane: CH₄</p>

  <p>Ethane: C₂H₆</p>

  <p>Propane: C₃H₈</p>

  <p>Butane: C₄H₁₀</p>

  <p>Each successive member differs from the previous one by CH₂.</p>`,
  [
    {
      q: "What is a homologous series?",
      steps: [
        "Step 1: Identify it as a family of related organic compounds.",
        "Step 2: Members have the same general formula and functional group.",
        "Step 3: Successive members differ by CH₂."
      ],
      ans: "A homologous series is a family of organic compounds with the same functional group and general formula, where successive members differ by CH₂.",
      why: "These similarities produce related chemical properties within the series."
    },
    {
      q: "What is the difference between ethane, C₂H₆, and propane, C₃H₈?",
      steps: [
        "Step 1: Compare the carbon atoms: 3 − 2 = 1.",
        "Step 2: Compare the hydrogen atoms: 8 − 6 = 2.",
        "Step 3: The difference is CH₂."
      ],
      ans: "Propane differs from ethane by one CH₂ unit.",
      why: "Successive members of a homologous series differ by CH₂."
    },
    {
      q: "Are methane, ethane and propane members of the same homologous series?",
      steps: [
        "Step 1: Methane, ethane and propane are all alkanes.",
        "Step 2: They have the same general formula, CₙH₂ₙ₊₂.",
        "Step 3: Each successive member differs by CH₂."
      ],
      ans: "Yes. They are members of the alkane homologous series.",
      why: "They satisfy the defining characteristics of a homologous series."
    }
  ],
  [
    {
      q: "A student says ethene and ethane belong to the same homologous series because both contain carbon and hydrogen. Is this correct?",
      hint: "Check their bonding and general formulae.",
      steps: [
        "Step 1: Ethane is an alkane.",
        "Step 2: Ethene is an alkene.",
        "Step 3: They have different general formulae and different types of carbon-carbon bonds."
      ],
      ans: "No. Ethane belongs to the alkane series while ethene belongs to the alkene series.",
      why: "Members of a homologous series must share the same characteristic structural type and general formula."
    }
  ]
);


// ------------------------------------------------------------
// 9. GENERAL FORMULA OF ALKANES
// ------------------------------------------------------------

add(
  "chemistry",
  "organic_chemistry",
  "General Formula of Alkanes",
  `<h2>General Formula of Alkanes</h2>

  <p>The general formula of open-chain alkanes is:</p>

  <p><strong>CₙH₂ₙ₊₂</strong></p>

  <p>This formula allows the molecular formula of an alkane to be calculated when the number of carbon atoms is known.</p>

  <h3>Worked examples</h3>

  <p><strong>Example 1: n = 3</strong></p>

  <p>H = 2(3) + 2 = 8</p>

  <p>Formula = C₃H₈</p>

  <p><strong>Example 2: n = 7</strong></p>

  <p>H = 2(7) + 2 = 16</p>

  <p>Formula = C₇H₁₆</p>

  <p><strong>Example 3: n = 10</strong></p>

  <p>H = 2(10) + 2 = 22</p>

  <p>Formula = C₁₀H₂₂</p>`,
  [
    {
      q: "Find the formula of an alkane containing 8 carbon atoms.",
      steps: [
        "Step 1: Use CₙH₂ₙ₊₂.",
        "Step 2: Substitute n = 8.",
        "Step 3: H = 2(8) + 2.",
        "Step 4: H = 16 + 2 = 18."
      ],
      ans: "C₈H₁₈.",
      why: "The alkane general formula is CₙH₂ₙ₊₂."
    },
    {
      q: "Find the formula of an alkane containing 12 carbon atoms.",
      steps: [
        "Step 1: Use CₙH₂ₙ₊₂.",
        "Step 2: Substitute n = 12.",
        "Step 3: H = 2(12) + 2.",
        "Step 4: H = 24 + 2 = 26."
      ],
      ans: "C₁₂H₂₆.",
      why: "The formula follows the alkane general formula."
    },
    {
      q: "An alkane has the formula C₉Hₓ. Find x.",
      steps: [
        "Step 1: Use H = 2n + 2.",
        "Step 2: n = 9.",
        "Step 3: H = 2(9) + 2.",
        "Step 4: H = 18 + 2 = 20."
      ],
      ans: "x = 20, so the formula is C₉H₂₀.",
      why: "The number of hydrogen atoms in an open-chain alkane is 2n + 2."
    }
  ],
  [
    {
      q: "A learner writes C₇H₁₄ as the formula of an alkane. What is the correct formula?",
      hint: "Substitute n = 7 into CₙH₂ₙ₊₂.",
      steps: [
        "Step 1: H = 2(7) + 2.",
        "Step 2: H = 14 + 2.",
        "Step 3: H = 16."
      ],
      ans: "C₇H₁₆.",
      why: "C₇H₁₆ follows the general formula of an open-chain alkane."
    }
  ]
);


// ------------------------------------------------------------
// 10. GENERAL FORMULA OF ALKENES AND ALKYNES
// ------------------------------------------------------------

add(
  "chemistry",
  "organic_chemistry",
  "General Formulae of Alkenes and Alkynes",
  `<h2>General Formulae of Alkenes and Alkynes</h2>

  <p>For open-chain hydrocarbons containing one multiple bond:</p>

  <p><strong>Alkenes:</strong> CₙH₂ₙ</p>

  <p><strong>Alkynes:</strong> CₙH₂ₙ₋₂</p>

  <h3>Worked examples</h3>

  <p><strong>Example 1: Alkene with 6 carbon atoms</strong></p>

  <p>H = 2(6) = 12</p>

  <p>Formula = C₆H₁₂</p>

  <p><strong>Example 2: Alkyne with 5 carbon atoms</strong></p>

  <p>H = 2(5) − 2 = 8</p>

  <p>Formula = C₅H₈</p>

  <p><strong>Example 3: Alkene with 9 carbon atoms</strong></p>

  <p>H = 2(9) = 18</p>

  <p>Formula = C₉H₁₈</p>`,
  [
    {
      q: "Find the formula of an alkene containing 7 carbon atoms.",
      steps: [
        "Step 1: Use the alkene formula CₙH₂ₙ.",
        "Step 2: Substitute n = 7.",
        "Step 3: H = 2(7) = 14."
      ],
      ans: "C₇H₁₄.",
      why: "Open-chain alkenes with one double bond follow CₙH₂ₙ."
    },
    {
      q: "Find the formula of an alkyne containing 6 carbon atoms.",
      steps: [
        "Step 1: Use CₙH₂ₙ₋₂.",
        "Step 2: Substitute n = 6.",
        "Step 3: H = 2(6) − 2.",
        "Step 4: H = 12 − 2 = 10."
      ],
      ans: "C₆H₁₀.",
      why: "Open-chain alkynes with one triple bond follow CₙH₂ₙ₋₂."
    },
    {
      q: "An alkene has the formula C₈Hₓ. Find x.",
      steps: [
        "Step 1: Use H = 2n.",
        "Step 2: n = 8.",
        "Step 3: H = 2(8) = 16."
      ],
      ans: "x = 16, so the formula is C₈H₁₆.",
      why: "The general formula for an open-chain alkene is CₙH₂ₙ."
    }
  ],
  [
    {
      q: "A learner says C₅H₈ is an alkene. Check the formula.",
      hint: "For an open-chain alkene, use CₙH₂ₙ.",
      steps: [
        "Step 1: For n = 5, an alkene should have H = 2(5) = 10.",
        "Step 2: Therefore an alkene would be C₅H₁₀.",
        "Step 3: C₅H₈ instead matches the alkyne formula."
      ],
      ans: "C₅H₈ is not the formula of an open-chain alkene; it matches an alkyne.",
      why: "Alkenes follow CₙH₂ₙ, while alkynes follow CₙH₂ₙ₋₂."
    }
  ]
);
// ============================================================
// BATCH 17 — ORGANIC STRUCTURE
// Chapter: organic_chemistry
// ============================================================


// ============================================================
// 1. STRUCTURAL FORMULAE
// ============================================================

add(
  "chemistry",
  "organic_chemistry",
  "Structural Formulae",
  `<h2>Structural Formulae</h2>

  <p>A structural formula shows how atoms are connected to one another in an organic molecule.</p>

  <p>For example, ethane has the molecular formula <strong>C₂H₆</strong>.</p>

  <p>Its structural formula shows the carbon-carbon bond and the hydrogen atoms attached to each carbon:</p>

  <p><strong>CH₃–CH₃</strong></p>

  <p>Carbon forms four covalent bonds, so the total number of bonds around each carbon must be four.</p>

  <h3>Example 1: Ethane</h3>
  <p>Molecular formula: C₂H₆</p>
  <p>Structural formula: CH₃–CH₃</p>

  <h3>Example 2: Propane</h3>
  <p>Molecular formula: C₃H₈</p>
  <p>Structural formula: CH₃–CH₂–CH₃</p>

  <h3>Example 3: Propene</h3>
  <p>Molecular formula: C₃H₆</p>
  <p>Structural formula: CH₂=CH–CH₃</p>

  <p>The double bond in propene must be shown because it is part of the structure of the molecule.</p>`,
  [
    {
      q: "Write the structural formula of ethane, C₂H₆.",
      steps: [
        "Step 1: Ethane contains two carbon atoms.",
        "Step 2: The two carbon atoms are joined by a single bond.",
        "Step 3: Each carbon needs three hydrogen atoms to complete four bonds.",
        "Step 4: The structural formula is CH₃–CH₃."
      ],
      ans: "CH₃–CH₃",
      why: "Each carbon forms four covalent bonds, so the two carbon atoms each bond to three hydrogen atoms."
    },
    {
      q: "Write the structural formula of propane, C₃H₈.",
      steps: [
        "Step 1: Arrange the three carbon atoms in a chain.",
        "Step 2: Join them using single carbon-carbon bonds.",
        "Step 3: The two end carbons each have three hydrogen atoms.",
        "Step 4: The middle carbon has two hydrogen atoms.",
        "Step 5: The structural formula is CH₃–CH₂–CH₃."
      ],
      ans: "CH₃–CH₂–CH₃",
      why: "The middle carbon has two carbon bonds and therefore needs two hydrogen atoms, while each end carbon needs three."
    },
    {
      q: "Write the structural formula of propene, C₃H₆.",
      steps: [
        "Step 1: Propene contains three carbon atoms.",
        "Step 2: The suffix '-ene' indicates a carbon-carbon double bond.",
        "Step 3: Place the double bond between carbon 1 and carbon 2.",
        "Step 4: Complete the remaining carbon bonds with hydrogen.",
        "Step 5: The structural formula is CH₂=CH–CH₃."
      ],
      ans: "CH₂=CH–CH₃",
      why: "Propene contains one carbon-carbon double bond, which must appear in its structural formula."
    }
  ],
  [
    {
      q: "Write the structural formula of butane, C₄H₁₀.",
      hint: "Arrange four carbon atoms in a straight chain and complete each carbon's four bonds.",
      steps: [
        "Step 1: Arrange four carbon atoms in a chain.",
        "Step 2: Join adjacent carbon atoms with single bonds.",
        "Step 3: Complete the valencies with hydrogen atoms.",
        "Step 4: The structural formula is CH₃–CH₂–CH₂–CH₃."
      ],
      ans: "CH₃–CH₂–CH₂–CH₃",
      why: "Butane is a four-carbon alkane with only single carbon-carbon bonds."
    }
  ]
);


// ============================================================
// 2. CONDENSED STRUCTURAL FORMULAE
// ============================================================

add(
  "chemistry",
  "organic_chemistry",
  "Condensed Structural Formulae",
  `<h2>Condensed Structural Formulae</h2>

  <p>A condensed structural formula represents an organic molecule by grouping hydrogen atoms with the carbon atom to which they are attached.</p>

  <p>Instead of drawing every individual bond, groups such as <strong>CH₃</strong> and <strong>CH₂</strong> are written together.</p>

  <p>For example:</p>

  <p>Butane can be written as:</p>
  <p><strong>CH₃CH₂CH₂CH₃</strong></p>

  <p>Or with bond lines:</p>
  <p><strong>CH₃–CH₂–CH₂–CH₃</strong></p>

  <h3>Reading a condensed formula</h3>
  <p>CH₃CH₂CH₂CH₃ contains:</p>
  <ul>
    <li>4 carbon atoms</li>
    <li>10 hydrogen atoms</li>
  </ul>

  <p>The order of the groups shows how the carbon atoms are connected.</p>`,
  [
    {
      q: "Write the condensed structural formula of propane.",
      steps: [
        "Step 1: Propane contains three carbon atoms.",
        "Step 2: The first carbon is CH₃.",
        "Step 3: The middle carbon is CH₂.",
        "Step 4: The final carbon is CH₃.",
        "Step 5: Combine the groups: CH₃CH₂CH₃."
      ],
      ans: "CH₃CH₂CH₃",
      why: "The condensed formula groups the hydrogen atoms with each carbon while preserving the carbon chain."
    },
    {
      q: "How many carbon atoms are present in CH₃CH₂CH₂CH₂CH₃?",
      steps: [
        "Step 1: Count each carbon represented by CH₃ or CH₂.",
        "Step 2: There are five carbon groups.",
        "Step 3: Therefore, there are five carbon atoms."
      ],
      ans: "5 carbon atoms",
      why: "Each CH₃ or CH₂ group contains one carbon atom."
    },
    {
      q: "Write the condensed structural formula of pentane.",
      steps: [
        "Step 1: Pentane contains five carbon atoms.",
        "Step 2: The two terminal carbons are CH₃.",
        "Step 3: The three internal carbons are CH₂.",
        "Step 4: Combine them in order.",
        "Step 5: CH₃CH₂CH₂CH₂CH₃."
      ],
      ans: "CH₃CH₂CH₂CH₂CH₃",
      why: "Pentane is a straight-chain five-carbon alkane."
    }
  ],
  [
    {
      q: "Write the condensed structural formula for hexane.",
      hint: "Hexane contains six carbon atoms in a straight chain.",
      steps: [
        "Step 1: The first and last carbons are CH₃.",
        "Step 2: The four internal carbons are CH₂.",
        "Step 3: Write them in order.",
        "Step 4: CH₃CH₂CH₂CH₂CH₂CH₃."
      ],
      ans: "CH₃CH₂CH₂CH₂CH₂CH₃",
      why: "A straight-chain six-carbon alkane has two terminal CH₃ groups and four internal CH₂ groups."
    }
  ]
);


// ============================================================
// 3. NAMING STRAIGHT-CHAIN ALKANES
// ============================================================

add(
  "chemistry",
  "organic_chemistry",
  "Naming Straight-Chain Alkanes",
  `<h2>Naming Straight-Chain Alkanes</h2>

  <p>Straight-chain alkanes are named according to the number of carbon atoms in the longest continuous chain.</p>

  <p>The main carbon prefixes are:</p>

  <ul>
    <li>1 carbon → meth-</li>
    <li>2 carbons → eth-</li>
    <li>3 carbons → prop-</li>
    <li>4 carbons → but-</li>
    <li>5 carbons → pent-</li>
    <li>6 carbons → hex-</li>
    <li>7 carbons → hept-</li>
    <li>8 carbons → oct-</li>
    <li>9 carbons → non-</li>
    <li>10 carbons → dec-</li>
  </ul>

  <p>Alkanes end with <strong>-ane</strong>.</p>

  <h3>Examples</h3>
  <p>CH₄ → methane</p>
  <p>CH₃CH₃ → ethane</p>
  <p>CH₃CH₂CH₃ → propane</p>
  <p>CH₃CH₂CH₂CH₃ → butane</p>

  <p>For a straight-chain alkane, count the carbon atoms and select the corresponding prefix, then add <strong>-ane</strong>.</p>`,
  [
    {
      q: "Name CH₃CH₂CH₃.",
      steps: [
        "Step 1: Count the carbon atoms: 3.",
        "Step 2: The three-carbon prefix is prop-.",
        "Step 3: It is an alkane, so use the ending -ane.",
        "Step 4: The name is propane."
      ],
      ans: "Propane",
      why: "A straight-chain alkane containing three carbon atoms is propane."
    },
    {
      q: "Name CH₃CH₂CH₂CH₂CH₃.",
      steps: [
        "Step 1: Count the carbon atoms: 5.",
        "Step 2: The five-carbon prefix is pent-.",
        "Step 3: Add the alkane ending -ane.",
        "Step 4: The name is pentane."
      ],
      ans: "Pentane",
      why: "Pentane is the five-carbon straight-chain alkane."
    },
    {
      q: "Name CH₃CH₂CH₂CH₂CH₂CH₃.",
      steps: [
        "Step 1: Count the carbon atoms: 6.",
        "Step 2: The six-carbon prefix is hex-.",
        "Step 3: Add -ane.",
        "Step 4: The name is hexane."
      ],
      ans: "Hexane",
      why: "A six-carbon straight-chain alkane is hexane."
    }
  ],
  [
    {
      q: "Name CH₃CH₂CH₂CH₂CH₂CH₂CH₃.",
      hint: "Count the carbon atoms before choosing the prefix.",
      steps: [
        "Step 1: Count seven carbon atoms.",
        "Step 2: The prefix for seven carbons is hept-.",
        "Step 3: Add -ane.",
        "Step 4: The name is heptane."
      ],
      ans: "Heptane",
      why: "The molecule contains seven carbon atoms and only single carbon-carbon bonds."
    }
  ]
);


// ============================================================
// 4. NAMING BRANCHED-CHAIN ALKANES
// ============================================================

add(
  "chemistry",
  "organic_chemistry",
  "Naming Branched-Chain Alkanes",
  `<h2>Naming Branched-Chain Alkanes</h2>

  <p>A branched-chain alkane contains a carbon chain with one or more carbon groups attached to the main chain.</p>

  <h3>Step 1: Find the longest continuous carbon chain</h3>
  <p>This gives the parent alkane name.</p>

  <h3>Step 2: Number the chain</h3>
  <p>Number from the end that gives the substituent the lowest possible number.</p>

  <h3>Step 3: Identify the branch</h3>
  <p>A one-carbon branch is called <strong>methyl</strong>.</p>
  <p>A two-carbon branch is called <strong>ethyl</strong>.</p>

  <h3>Step 4: Give the branch its position</h3>
  <p>The number of the carbon carrying the branch is written before the branch name.</p>

  <h3>Example</h3>
  <p>CH₃–CH(CH₃)–CH₂–CH₃</p>

  <p>The longest chain has four carbons → butane.</p>
  <p>The methyl branch is on carbon 2.</p>
  <p>Name: <strong>2-methylbutane</strong>.</p>`,
  [
    {
      q: "Name CH₃–CH(CH₃)–CH₃.",
      steps: [
        "Step 1: Find the longest continuous carbon chain. It contains three carbons.",
        "Step 2: The parent name is propane.",
        "Step 3: There is a methyl branch.",
        "Step 4: The methyl branch is attached to carbon 2.",
        "Step 5: Combine the parts: 2-methylpropane."
      ],
      ans: "2-methylpropane",
      why: "The longest chain is three carbons and the methyl substituent is attached to carbon 2."
    },
    {
      q: "Name CH₃–CH(CH₃)–CH₂–CH₃.",
      steps: [
        "Step 1: The longest continuous chain contains four carbons.",
        "Step 2: The parent name is butane.",
        "Step 3: There is a methyl branch.",
        "Step 4: Numbering from the nearer end places the methyl group on carbon 2.",
        "Step 5: The name is 2-methylbutane."
      ],
      ans: "2-methylbutane",
      why: "The four-carbon parent chain is butane and the methyl substituent receives the lowest possible number, 2."
    },
    {
      q: "Name CH₃–CH₂–CH(CH₃)–CH₂–CH₃.",
      steps: [
        "Step 1: Find the longest chain: five carbon atoms.",
        "Step 2: The parent name is pentane.",
        "Step 3: There is a methyl substituent.",
        "Step 4: The substituent is on carbon 3.",
        "Step 5: The name is 3-methylpentane."
      ],
      ans: "3-methylpentane",
      why: "The longest chain has five carbons and the methyl group is attached to the third carbon."
    }
  ],
  [
    {
      q: "Name CH₃–CH(CH₃)–CH₂–CH₂–CH₃.",
      hint: "First identify the longest carbon chain before identifying the branch.",
      steps: [
        "Step 1: The longest chain contains five carbon atoms.",
        "Step 2: The parent name is pentane.",
        "Step 3: There is a methyl substituent.",
        "Step 4: Number from the nearer end so the substituent gets the lowest number.",
        "Step 5: The methyl group is on carbon 2.",
        "Step 6: The name is 2-methylpentane."
      ],
      ans: "2-methylpentane",
      why: "The longest chain is pentane and the methyl substituent is at carbon 2."
    }
  ]
);


// ============================================================
// 5. NAMING ALKENES
// ============================================================

add(
  "chemistry",
  "organic_chemistry",
  "Naming Alkenes",
  `<h2>Naming Alkenes</h2>

  <p>Alkenes contain at least one carbon-carbon double bond.</p>

  <p>They are named using the carbon chain containing the double bond and the ending <strong>-ene</strong>.</p>

  <h3>Rules</h3>

  <p><strong>Step 1:</strong> Find the longest carbon chain containing the double bond.</p>

  <p><strong>Step 2:</strong> Number the chain from the end nearest to the double bond.</p>

  <p><strong>Step 3:</strong> Identify the position of the double bond.</p>

  <p><strong>Step 4:</strong> Name the compound using the appropriate carbon prefix and <strong>-ene</strong>.</p>

  <h3>Examples</h3>

  <p>CH₂=CH₂ → ethene</p>

  <p>CH₂=CH–CH₃ → propene</p>

  <p>CH₂=CH–CH₂–CH₃ → but-1-ene</p>

  <p>CH₃–CH=CH–CH₃ → but-2-ene</p>

  <p>The position number tells us where the double bond begins.</p>`,
  [
    {
      q: "Name CH₂=CH₂.",
      steps: [
        "Step 1: Count the two carbon atoms.",
        "Step 2: The prefix is eth-.",
        "Step 3: The molecule contains a double bond.",
        "Step 4: Use the ending -ene.",
        "Step 5: The name is ethene."
      ],
      ans: "Ethene",
      why: "Ethene is the two-carbon alkene."
    },
    {
      q: "Name CH₂=CH–CH₂–CH₃.",
      steps: [
        "Step 1: The longest chain contains four carbons.",
        "Step 2: The parent name is butene.",
        "Step 3: Number from the end nearest the double bond.",
        "Step 4: The double bond begins at carbon 1.",
        "Step 5: The name is but-1-ene."
      ],
      ans: "But-1-ene",
      why: "The four-carbon chain is but- and the double bond starts at carbon 1."
    },
    {
      q: "Name CH₃–CH=CH–CH₃.",
      steps: [
        "Step 1: The longest chain contains four carbons.",
        "Step 2: The parent name is butene.",
        "Step 3: Numbering from either end places the double bond between carbon 2 and carbon 3.",
        "Step 4: The double bond therefore starts at carbon 2.",
        "Step 5: The name is but-2-ene."
      ],
      ans: "But-2-ene",
      why: "The double bond begins at carbon 2 in the four-carbon chain."
    }
  ],
  [
    {
      q: "Name CH₂=CH–CH₂–CH₂–CH₃.",
      hint: "Number from the end closest to the double bond.",
      steps: [
        "Step 1: The longest chain has five carbons.",
        "Step 2: The parent name is pentene.",
        "Step 3: The double bond begins at carbon 1.",
        "Step 4: The name is pent-1-ene."
      ],
      ans: "Pent-1-ene",
      why: "The five-carbon chain contains a double bond beginning at carbon 1."
    }
  ]
);


// ============================================================
// 6. NAMING ALKYNES
// ============================================================

add(
  "chemistry",
  "organic_chemistry",
  "Naming Alkynes",
  `<h2>Naming Alkynes</h2>

  <p>Alkynes contain at least one carbon-carbon triple bond.</p>

  <p>The suffix used for alkynes is <strong>-yne</strong>.</p>

  <h3>Rules</h3>

  <p><strong>Step 1:</strong> Find the longest carbon chain containing the triple bond.</p>

  <p><strong>Step 2:</strong> Number the chain from the end nearest to the triple bond.</p>

  <p><strong>Step 3:</strong> Identify the position where the triple bond begins.</p>

  <p><strong>Step 4:</strong> Use the carbon prefix and the ending <strong>-yne</strong>.</p>

  <h3>Examples</h3>

  <p>HC≡CH → ethyne</p>

  <p>CH≡C–CH₃ → propyne</p>

  <p>CH≡C–CH₂–CH₃ → but-1-yne</p>

  <p>CH₃–C≡C–CH₃ → but-2-yne</p>`,
  [
    {
      q: "Name HC≡CH.",
      steps: [
        "Step 1: Count the carbon atoms: 2.",
        "Step 2: The prefix is eth-.",
        "Step 3: The molecule contains a triple bond.",
        "Step 4: Use the ending -yne.",
        "Step 5: The name is ethyne."
      ],
      ans: "Ethyne",
      why: "Ethyne is the two-carbon alkyne."
    },
    {
      q: "Name HC≡C–CH₃.",
      steps: [
        "Step 1: The chain contains three carbon atoms.",
        "Step 2: The prefix is prop-.",
        "Step 3: There is a triple bond.",
        "Step 4: Use the ending -yne.",
        "Step 5: The name is propyne."
      ],
      ans: "Propyne",
      why: "A three-carbon molecule containing a triple bond is propyne."
    },
    {
      q: "Name CH₃–C≡C–CH₃.",
      steps: [
        "Step 1: The longest chain contains four carbon atoms.",
        "Step 2: The parent name is butyne.",
        "Step 3: Number the chain from either end.",
        "Step 4: The triple bond begins at carbon 2.",
        "Step 5: The name is but-2-yne."
      ],
      ans: "But-2-yne",
      why: "The four-carbon chain has a triple bond beginning at carbon 2."
    }
  ],
  [
    {
      q: "Name HC≡C–CH₂–CH₂–CH₃.",
      hint: "Count the longest chain and number from the end nearest the triple bond.",
      steps: [
        "Step 1: The longest chain contains five carbon atoms.",
        "Step 2: The parent name is pent-yne.",
        "Step 3: The triple bond begins at carbon 1.",
        "Step 4: The name is pent-1-yne."
      ],
      ans: "Pent-1-yne",
      why: "The five-carbon chain has a triple bond beginning at carbon 1."
    }
  ]
);


// ============================================================
// 7. STRUCTURAL ISOMERISM
// ============================================================

add(
  "chemistry",
  "organic_chemistry",
  "Structural Isomerism",
  `<h2>Structural Isomerism</h2>

  <p>Structural isomers are compounds that have the <strong>same molecular formula</strong> but different arrangements of atoms.</p>

  <h3>Example: C₄H₁₀</h3>

  <p>C₄H₁₀ can form two different structures:</p>

  <p><strong>CH₃–CH₂–CH₂–CH₃</strong></p>
  <p>Butane</p>

  <p>and</p>

  <p><strong>CH₃–CH(CH₃)–CH₃</strong></p>
  <p>2-methylpropane</p>

  <p>Both have the molecular formula C₄H₁₀, but their atoms are connected differently.</p>

  <h3>Important rule</h3>

  <p>When looking for structural isomers, keep the molecular formula unchanged but rearrange the carbon skeleton.</p>

  <h3>C₅H₁₂</h3>

  <p>Pentane has three structural isomers:</p>

  <p>1. Pentane</p>
  <p>2. 2-methylbutane</p>
  <p>3. 2,2-dimethylpropane</p>`,
  [
    {
      q: "What is meant by structural isomerism?",
      steps: [
        "Step 1: Structural isomers have the same molecular formula.",
        "Step 2: Their atoms are connected in different arrangements.",
        "Step 3: Therefore, structural isomerism is the existence of compounds with the same molecular formula but different structural arrangements."
      ],
      ans: "Structural isomerism is the existence of compounds with the same molecular formula but different structural arrangements.",
      why: "The molecular formula remains the same, while the connectivity of the atoms changes."
    },
    {
      q: "Write the two structural isomers of C₄H₁₀.",
      steps: [
        "Step 1: Draw the straight four-carbon chain: CH₃–CH₂–CH₂–CH₃.",
        "Step 2: This is butane.",
        "Step 3: Rearrange the carbon skeleton to form a three-carbon main chain with a methyl branch.",
        "Step 4: The second structure is CH₃–CH(CH₃)–CH₃.",
        "Step 5: This is 2-methylpropane."
      ],
      ans: "Butane and 2-methylpropane",
      why: "Both structures contain four carbon atoms and ten hydrogen atoms, but their carbon atoms are connected differently."
    },
    {
      q: "How many structural isomers does C₅H₁₂ have?",
      steps: [
        "Step 1: Draw the straight chain: pentane.",
        "Step 2: Rearrange the chain to form 2-methylbutane.",
        "Step 3: Rearrange it further to form 2,2-dimethylpropane.",
        "Step 4: No other distinct carbon skeletons are possible.",
        "Step 5: Therefore, C₅H₁₂ has three structural isomers."
      ],
      ans: "3",
      why: "Pentane has three distinct possible carbon skeletons."
    }
  ],
  [
    {
      q: "Are CH₃CH₂CH₂CH₃ and CH₃CH(CH₃)CH₃ structural isomers?",
      hint: "Compare both their molecular formulae and their atom arrangements.",
      steps: [
        "Step 1: Both compounds have four carbon atoms and ten hydrogen atoms.",
        "Step 2: Their molecular formula is therefore C₄H₁₀.",
        "Step 3: Their carbon arrangements are different.",
        "Step 4: Therefore, they are structural isomers."
      ],
      ans: "Yes",
      why: "They have the same molecular formula but different carbon skeletons."
    }
  ]
);


// ============================================================
// 8. GEOMETRIC ISOMERISM
// ============================================================

add(
  "chemistry",
  "organic_chemistry",
  "Geometric Isomerism",
  `<h2>Geometric Isomerism</h2>

  <p>Geometric isomerism occurs when compounds have the same molecular formula and connectivity but different spatial arrangements around a carbon-carbon double bond.</p>

  <p>A carbon-carbon double bond does not allow free rotation in the same way as a single bond.</p>

  <h3>Example: But-2-ene</h3>

  <p>But-2-ene can exist in two arrangements:</p>

  <p><strong>cis-but-2-ene</strong> — similar groups are on the same side of the double bond.</p>

  <p><strong>trans-but-2-ene</strong> — similar groups are on opposite sides of the double bond.</p>

  <h3>Why does this happen?</h3>

  <p>The carbon-carbon double bond restricts rotation. Therefore, the groups attached to the double-bonded carbons can remain in different fixed arrangements.</p>

  <p>Geometric isomerism is therefore different from structural isomerism:</p>

  <ul>
    <li><strong>Structural isomers:</strong> atoms are connected differently.</li>
    <li><strong>Geometric isomers:</strong> atoms are connected in the same order but arranged differently in space.</li>
  </ul>`,
  [
    {
      q: "What is geometric isomerism?",
      steps: [
        "Step 1: Geometric isomers have the same molecular formula.",
        "Step 2: They have the same order of connectivity.",
        "Step 3: Their groups have different spatial arrangements around a double bond.",
        "Step 4: Therefore, geometric isomerism results from different spatial arrangements around a restricted carbon-carbon double bond."
      ],
      ans: "Geometric isomerism is the existence of compounds with the same connectivity but different spatial arrangements around a carbon-carbon double bond.",
      why: "The double bond restricts rotation, allowing different fixed arrangements."
    },
    {
      q: "What is the difference between cis-but-2-ene and trans-but-2-ene?",
      steps: [
        "Step 1: Both compounds have the same molecular formula, C₄H₈.",
        "Step 2: Both have the same carbon-carbon connectivity.",
        "Step 3: In cis-but-2-ene, the similar groups are on the same side of the double bond.",
        "Step 4: In trans-but-2-ene, the similar groups are on opposite sides."
      ],
      ans: "Cis has similar groups on the same side; trans has similar groups on opposite sides.",
      why: "The two forms differ only in the spatial arrangement around the carbon-carbon double bond."
    },
    {
      q: "Why can but-2-ene show geometric isomerism?",
      steps: [
        "Step 1: But-2-ene contains a carbon-carbon double bond.",
        "Step 2: Rotation around the double bond is restricted.",
        "Step 3: Each double-bonded carbon has two different groups attached to it.",
        "Step 4: The groups can therefore occupy different fixed spatial arrangements.",
        "Step 5: But-2-ene can therefore exist as cis and trans forms."
      ],
      ans: "Because rotation around its C=C bond is restricted and each double-bonded carbon has two different groups attached.",
      why: "Both conditions are needed for the common cis-trans form of geometric isomerism."
    }
  ],
  [
    {
      q: "Is butane capable of cis-trans geometric isomerism?",
      hint: "Check whether butane contains a carbon-carbon double bond.",
      steps: [
        "Step 1: Butane contains only carbon-carbon single bonds.",
        "Step 2: Single bonds allow rotation.",
        "Step 3: Butane therefore does not have the required restricted C=C bond for cis-trans isomerism.",
        "Step 4: Therefore, butane does not show cis-trans geometric isomerism."
      ],
      ans: "No",
      why: "Butane has only single carbon-carbon bonds and therefore does not have the restricted double bond required for cis-trans isomerism."
    }
  ]
);
