// ============================================================
// 1. ALCOHOLS
// ============================================================

add(
  "chemistry",
  "organic_chemistry",
  "Alcohols",
  `<h2>Alcohols</h2>

  <p>Alcohols are organic compounds containing the <strong>hydroxyl functional group, –OH</strong>, attached to a carbon atom.</p>

  <p>The –OH group is called the <strong>hydroxyl group</strong>.</p>

  <h3>General structure</h3>

  <p>For a simple alcohol:</p>

  <p><strong>R–OH</strong></p>

  <p>R represents the carbon-containing part of the molecule.</p>

  <h3>Examples</h3>

  <p>Methanol: CH₃OH</p>
  <p>Ethanol: CH₃CH₂OH</p>
  <p>Propanol: CH₃CH₂CH₂OH</p>

  <p>The presence of the –OH group distinguishes alcohols from hydrocarbons such as alkanes.</p>`,
  [
    {
      q: "What functional group is present in alcohols?",
      steps: [
        "Step 1: Identify the characteristic group of alcohols.",
        "Step 2: The group contains oxygen and hydrogen.",
        "Step 3: It is written as –OH.",
        "Step 4: Therefore, the functional group is the hydroxyl group."
      ],
      ans: "Hydroxyl group, –OH",
      why: "Alcohols are characterised by the presence of a hydroxyl group attached to carbon."
    },
    {
      q: "Is CH₃CH₂OH an alcohol?",
      steps: [
        "Step 1: Look at the structure.",
        "Step 2: It contains an –OH group.",
        "Step 3: The –OH group is attached to a carbon-containing chain.",
        "Step 4: Therefore, CH₃CH₂OH is an alcohol."
      ],
      ans: "Yes",
      why: "CH₃CH₂OH contains the hydroxyl functional group and is ethanol."
    },
    {
      q: "Identify the functional group in CH₃CH₂CH₂OH.",
      steps: [
        "Step 1: Examine the formula.",
        "Step 2: Locate the oxygen and hydrogen joined together.",
        "Step 3: The group is –OH.",
        "Step 4: Therefore, the functional group is hydroxyl."
      ],
      ans: "–OH, the hydroxyl group",
      why: "The –OH group is the characteristic functional group of alcohols."
    }
  ],
  [
    {
      q: "Write the structural formula of propanol.",
      hint: "Propanol has three carbon atoms and contains the –OH group.",
      steps: [
        "Step 1: Arrange three carbon atoms in a chain.",
        "Step 2: Attach the hydroxyl group to the carbon chain.",
        "Step 3: Complete the remaining valencies with hydrogen.",
        "Step 4: The structural formula is CH₃CH₂CH₂OH."
      ],
      ans: "CH₃CH₂CH₂OH",
      why: "Propanol is a three-carbon alcohol containing the –OH functional group."
    }
  ]
);


// ============================================================
// 2. ETHANOL
// ============================================================

add(
  "chemistry",
  "organic_chemistry",
  "Ethanol",
  `<h2>Ethanol</h2>

  <p>Ethanol is a two-carbon alcohol.</p>

  <p>Its molecular formula is:</p>

  <p><strong>C₂H₆O</strong></p>

  <p>It is commonly written as:</p>

  <p><strong>C₂H₅OH</strong></p>

  <p>Its structural formula is:</p>

  <p><strong>CH₃CH₂OH</strong></p>

  <h3>Structure</h3>

  <p>Ethanol contains:</p>

  <ul>
    <li>2 carbon atoms</li>
    <li>6 hydrogen atoms</li>
    <li>1 oxygen atom</li>
    <li>1 hydroxyl group, –OH</li>
  </ul>

  <p>The two-carbon chain gives the prefix <strong>eth-</strong>, while the –OH functional group identifies it as an alcohol.</p>`,
  [
    {
      q: "What is the molecular formula of ethanol?",
      steps: [
        "Step 1: Ethanol is a two-carbon alcohol.",
        "Step 2: Its formula can be written as C₂H₅OH.",
        "Step 3: Count the hydrogen atoms: 5 + 1 = 6.",
        "Step 4: Therefore, the molecular formula is C₂H₆O."
      ],
      ans: "C₂H₆O",
      why: "Ethanol contains two carbon atoms, six hydrogen atoms and one oxygen atom."
    },
    {
      q: "Write the structural formula of ethanol.",
      steps: [
        "Step 1: Ethanol contains two carbon atoms.",
        "Step 2: Join them using a carbon-carbon single bond.",
        "Step 3: Attach the hydroxyl group to the second carbon.",
        "Step 4: Complete the valencies with hydrogen.",
        "Step 5: The structural formula is CH₃CH₂OH."
      ],
      ans: "CH₃CH₂OH",
      why: "Ethanol is the two-carbon alcohol containing the –OH group."
    },
    {
      q: "Calculate the relative molecular mass of ethanol, C₂H₆O. Use C = 12, H = 1 and O = 16.",
      steps: [
        "Step 1: Carbon contribution = 2 × 12 = 24.",
        "Step 2: Hydrogen contribution = 6 × 1 = 6.",
        "Step 3: Oxygen contribution = 1 × 16 = 16.",
        "Step 4: Add the contributions: 24 + 6 + 16 = 46."
      ],
      ans: "46",
      why: "The relative molecular mass is obtained by adding the relative atomic masses of all atoms in the molecule."
    }
  ],
  [
    {
      q: "How many oxygen atoms are present in one molecule of ethanol?",
      hint: "Look at the formula C₂H₅OH.",
      steps: [
        "Step 1: Examine C₂H₅OH.",
        "Step 2: There is one O symbol.",
        "Step 3: Therefore, one molecule of ethanol contains one oxygen atom."
      ],
      ans: "1 oxygen atom",
      why: "The formula C₂H₅OH contains one oxygen atom."
    }
  ]
);


// ============================================================
// 3. PROPERTIES OF ETHANOL
// ============================================================

add(
  "chemistry",
  "organic_chemistry",
  "Properties of Ethanol",
  `<h2>Properties of Ethanol</h2>

  <p>Ethanol is a colourless, volatile liquid with a characteristic smell.</p>

  <h3>Physical properties</h3>

  <ul>
    <li>It is a colourless liquid.</li>
    <li>It is volatile.</li>
    <li>It is miscible with water.</li>
    <li>It is flammable.</li>
    <li>It is a good solvent for many substances.</li>
  </ul>

  <h3>Combustion</h3>

  <p>Ethanol burns in oxygen to produce carbon dioxide and water.</p>

  <p><strong>C₂H₅OH + 3O₂ → 2CO₂ + 3H₂O</strong></p>

  <p>This is a combustion reaction.</p>

  <h3>Solubility</h3>

  <p>Ethanol mixes readily with water because of interactions involving its hydroxyl group.</p>`,
  [
    {
      q: "State two physical properties of ethanol.",
      steps: [
        "Step 1: Recall the observable properties of ethanol.",
        "Step 2: Ethanol is a colourless liquid.",
        "Step 3: It is also volatile and miscible with water.",
        "Step 4: Any two of these are acceptable."
      ],
      ans: "For example: ethanol is a colourless liquid and is volatile.",
      why: "These are physical properties because they can be observed without changing ethanol into another substance."
    },
    {
      q: "What happens when ethanol burns completely in oxygen?",
      steps: [
        "Step 1: Complete combustion requires oxygen.",
        "Step 2: Ethanol contains carbon and hydrogen.",
        "Step 3: Carbon forms carbon dioxide.",
        "Step 4: Hydrogen forms water.",
        "Step 5: Therefore, complete combustion produces carbon dioxide and water."
      ],
      ans: "Carbon dioxide and water are formed.",
      why: "Complete combustion of an organic compound containing carbon and hydrogen produces carbon dioxide and water."
    },
    {
      q: "Balance the equation: C₂H₅OH + O₂ → CO₂ + H₂O.",
      steps: [
        "Step 1: There are 2 carbon atoms, so place 2 before CO₂.",
        "Step 2: There are 6 hydrogen atoms, so place 3 before H₂O.",
        "Step 3: The products now contain 4 + 3 = 7 oxygen atoms.",
        "Step 4: Ethanol already contains 1 oxygen atom, so oxygen gas must supply 6 more oxygen atoms.",
        "Step 5: Six oxygen atoms require 3O₂.",
        "Step 6: The balanced equation is C₂H₅OH + 3O₂ → 2CO₂ + 3H₂O."
      ],
      ans: "C₂H₅OH + 3O₂ → 2CO₂ + 3H₂O",
      why: "The balanced equation has equal numbers of carbon, hydrogen and oxygen atoms on both sides."
    }
  ],
  [
    {
      q: "Why is ethanol described as flammable?",
      hint: "Think about what happens when ethanol reacts with oxygen and is ignited.",
      steps: [
        "Step 1: Ethanol reacts readily with oxygen when ignited.",
        "Step 2: The reaction releases energy as heat and light.",
        "Step 3: Therefore, ethanol can burn."
      ],
      ans: "Because ethanol burns readily in oxygen when ignited.",
      why: "A flammable substance can undergo combustion readily."
    }
  ]
);


// ============================================================
// 4. FERMENTATION
// ============================================================

add(
  "chemistry",
  "organic_chemistry",
  "Fermentation",
  `<h2>Fermentation</h2>

  <p>Fermentation is the process in which sugars are converted into ethanol and carbon dioxide by microorganisms such as yeast, usually in the absence of oxygen.</p>

  <h3>Word equation</h3>

  <p><strong>Glucose → ethanol + carbon dioxide</strong></p>

  <h3>Symbol equation</h3>

  <p><strong>C₆H₁₂O₆ → 2C₂H₅OH + 2CO₂</strong></p>

  <h3>Conditions</h3>

  <ul>
    <li>Yeast is required.</li>
    <li>A suitable temperature is required.</li>
    <li>Oxygen is excluded or kept very low.</li>
    <li>A sugar such as glucose is required.</li>
  </ul>

  <p>Fermentation is different from combustion. Fermentation produces ethanol, while complete combustion of ethanol produces carbon dioxide and water.</p>`,
  [
    {
      q: "What is fermentation?",
      steps: [
        "Step 1: Identify the starting substance: sugar such as glucose.",
        "Step 2: Yeast acts on the sugar.",
        "Step 3: The process occurs under conditions where oxygen is absent or very limited.",
        "Step 4: Ethanol and carbon dioxide are produced."
      ],
      ans: "Fermentation is the conversion of sugar into ethanol and carbon dioxide by yeast in the absence or near absence of oxygen.",
      why: "Yeast carries out the biochemical conversion of sugar into ethanol and carbon dioxide."
    },
    {
      q: "Write the word equation for fermentation of glucose.",
      steps: [
        "Step 1: Identify the reactant: glucose.",
        "Step 2: Identify the products: ethanol and carbon dioxide.",
        "Step 3: Write them in reaction order."
      ],
      ans: "Glucose → ethanol + carbon dioxide",
      why: "These are the reactant and products of alcoholic fermentation."
    },
    {
      q: "Balance the fermentation equation: C₆H₁₂O₆ → C₂H₅OH + CO₂.",
      steps: [
        "Step 1: There are 6 carbon atoms in glucose.",
        "Step 2: Place 2 before ethanol, giving 4 carbon atoms.",
        "Step 3: The remaining 2 carbon atoms form 2CO₂.",
        "Step 4: Check hydrogen: 2 × 6 = 12 hydrogen atoms.",
        "Step 5: Check oxygen: 2 oxygen atoms in ethanol plus 4 in carbon dioxide gives 6.",
        "Step 6: The balanced equation is C₆H₁₂O₆ → 2C₂H₅OH + 2CO₂."
      ],
      ans: "C₆H₁₂O₆ → 2C₂H₅OH + 2CO₂",
      why: "The same number of carbon, hydrogen and oxygen atoms occurs on both sides."
    }
  ],
  [
    {
      q: "Why is oxygen kept out during fermentation?",
      hint: "Consider what happens to glucose when yeast has oxygen available.",
      steps: [
        "Step 1: Fermentation is an anaerobic process.",
        "Step 2: Anaerobic means occurring without oxygen.",
        "Step 3: Keeping oxygen low allows yeast to convert glucose into ethanol and carbon dioxide."
      ],
      ans: "Because fermentation is an anaerobic process and requires little or no oxygen.",
      why: "The desired conversion of glucose to ethanol occurs under anaerobic conditions."
    }
  ]
);


// ============================================================
// 5. OXIDATION OF ETHANOL
// ============================================================

add(
  "chemistry",
  "organic_chemistry",
  "Oxidation of Ethanol",
  `<h2>Oxidation of Ethanol</h2>

  <p>Ethanol can be oxidised to form <strong>ethanoic acid</strong>.</p>

  <p>This can occur when ethanol is exposed to oxygen in the presence of suitable microorganisms, or when an oxidising agent is used in the laboratory.</p>

  <h3>Overall change</h3>

  <p><strong>Ethanol → ethanoic acid</strong></p>

  <p>In the presence of oxygen:</p>

  <p><strong>C₂H₅OH + O₂ → CH₃COOH + H₂O</strong></p>

  <h3>Observation</h3>

  <p>The reaction changes the alcohol into a carboxylic acid.</p>

  <p>Oxidation therefore provides an important link between alcohols and carboxylic acids.</p>`,
  [
    {
      q: "What product is formed when ethanol is oxidised completely?",
      steps: [
        "Step 1: Identify the starting alcohol: ethanol.",
        "Step 2: Oxidation changes ethanol into a carboxylic acid.",
        "Step 3: The carboxylic acid formed is ethanoic acid."
      ],
      ans: "Ethanoic acid",
      why: "Ethanol is oxidised to ethanoic acid."
    },
    {
      q: "Write the equation for oxidation of ethanol by oxygen.",
      steps: [
        "Step 1: Write ethanol as C₂H₅OH.",
        "Step 2: Add oxygen as the oxidising reactant.",
        "Step 3: The acid formed is CH₃COOH.",
        "Step 4: Water is also formed.",
        "Step 5: Balance the equation: C₂H₅OH + O₂ → CH₃COOH + H₂O."
      ],
      ans: "C₂H₅OH + O₂ → CH₃COOH + H₂O",
      why: "Ethanol is oxidised to ethanoic acid while oxygen is reduced to form water."
    },
    {
      q: "Name the type of organic compound formed when ethanol is oxidised to CH₃COOH.",
      steps: [
        "Step 1: Identify CH₃COOH.",
        "Step 2: It contains the –COOH functional group.",
        "Step 3: The –COOH group is characteristic of carboxylic acids.",
        "Step 4: Therefore, the product is a carboxylic acid."
      ],
      ans: "Carboxylic acid",
      why: "CH₃COOH contains the carboxyl functional group."
    }
  ],
  [
    {
      q: "What organic acid is produced from ethanol by oxidation?",
      hint: "It is the two-carbon carboxylic acid.",
      steps: [
        "Step 1: Ethanol contains two carbon atoms.",
        "Step 2: Oxidation forms the corresponding two-carbon carboxylic acid.",
        "Step 3: The product is ethanoic acid."
      ],
      ans: "Ethanoic acid",
      why: "Oxidation of ethanol produces ethanoic acid."
    }
  ]
);


// ============================================================
// 6. CARBOXYLIC ACIDS
// ============================================================

add(
  "chemistry",
  "organic_chemistry",
  "Carboxylic Acids",
  `<h2>Carboxylic Acids</h2>

  <p>Carboxylic acids are organic compounds containing the <strong>carboxyl functional group, –COOH</strong>.</p>

  <p>The carboxyl group contains both:</p>

  <ul>
    <li>a carbonyl component, C=O</li>
    <li>a hydroxyl component, –OH</li>
  </ul>

  <h3>General structure</h3>

  <p><strong>R–COOH</strong></p>

  <p>R represents the carbon-containing part of the molecule.</p>

  <h3>Examples</h3>

  <p>Methanoic acid: HCOOH</p>

  <p>Ethanoic acid: CH₃COOH</p>

  <p>Propanoic acid: CH₃CH₂COOH</p>

  <p>Carboxylic acids are acidic because they can release hydrogen ions from the carboxyl group.</p>`,
  [
    {
      q: "What functional group is present in carboxylic acids?",
      steps: [
        "Step 1: Identify the characteristic functional group.",
        "Step 2: It is written as –COOH.",
        "Step 3: This is called the carboxyl group."
      ],
      ans: "Carboxyl group, –COOH",
      why: "The carboxyl group is the characteristic functional group of carboxylic acids."
    },
    {
      q: "Identify the carboxylic acid functional group in CH₃COOH.",
      steps: [
        "Step 1: Examine the formula CH₃COOH.",
        "Step 2: The final part is COOH.",
        "Step 3: COOH represents the carboxyl group."
      ],
      ans: "–COOH",
      why: "The –COOH group identifies a compound as a carboxylic acid."
    },
    {
      q: "Name HCOOH.",
      steps: [
        "Step 1: Count the carbon atoms: 1.",
        "Step 2: The one-carbon prefix is meth-.",
        "Step 3: It is a carboxylic acid, so the name ends in -oic acid.",
        "Step 4: The name is methanoic acid."
      ],
      ans: "Methanoic acid",
      why: "Methanoic acid is the one-carbon carboxylic acid."
    }
  ],
  [
    {
      q: "Write the general formula for a carboxylic acid.",
      hint: "Use R for the carbon-containing part of the molecule.",
      steps: [
        "Step 1: Identify the characteristic carboxyl group.",
        "Step 2: Attach it to the carbon-containing group R.",
        "Step 3: The general structure is R–COOH."
      ],
      ans: "R–COOH",
      why: "All carboxylic acids contain the –COOH functional group."
    }
  ]
);


// ============================================================
// 7. ETHANOIC ACID
// ============================================================

add(
  "chemistry",
  "organic_chemistry",
  "Ethanoic Acid",
  `<h2>Ethanoic Acid</h2>

  <p>Ethanoic acid is a two-carbon carboxylic acid.</p>

  <p>Its molecular formula is:</p>

  <p><strong>C₂H₄O₂</strong></p>

  <p>Its structural formula is:</p>

  <p><strong>CH₃COOH</strong></p>

  <p>It contains the carboxyl group, –COOH.</p>

  <h3>Properties</h3>

  <ul>
    <li>It is a colourless liquid in pure form.</li>
    <li>It has a characteristic sharp smell.</li>
    <li>It is soluble in water.</li>
    <li>It is an acid.</li>
  </ul>

  <p>Dilute ethanoic acid is present in vinegar.</p>`,
  [
    {
      q: "Write the structural formula of ethanoic acid.",
      steps: [
        "Step 1: Ethanoic acid contains two carbon atoms.",
        "Step 2: The carboxyl group is –COOH.",
        "Step 3: Attach the carboxyl group to the first carbon.",
        "Step 4: The remaining carbon is CH₃.",
        "Step 5: The structural formula is CH₃COOH."
      ],
      ans: "CH₃COOH",
      why: "Ethanoic acid is the two-carbon carboxylic acid containing the –COOH group."
    },
    {
      q: "Calculate the relative molecular mass of ethanoic acid, C₂H₄O₂. Use C = 12, H = 1 and O = 16.",
      steps: [
        "Step 1: Carbon contribution = 2 × 12 = 24.",
        "Step 2: Hydrogen contribution = 4 × 1 = 4.",
        "Step 3: Oxygen contribution = 2 × 16 = 32.",
        "Step 4: Add: 24 + 4 + 32 = 60."
      ],
      ans: "60",
      why: "The relative molecular mass is the sum of the relative atomic masses of all atoms in C₂H₄O₂."
    },
    {
      q: "Where is dilute ethanoic acid commonly found?",
      steps: [
        "Step 1: Identify a common household source of dilute ethanoic acid.",
        "Step 2: Vinegar contains dilute ethanoic acid.",
        "Step 3: Therefore, dilute ethanoic acid is commonly found in vinegar."
      ],
      ans: "Vinegar",
      why: "Vinegar is a dilute solution of ethanoic acid in water."
    }
  ],
  [
    {
      q: "How many carbon atoms are present in one molecule of ethanoic acid?",
      hint: "Use the molecular formula C₂H₄O₂.",
      steps: [
        "Step 1: Look at the subscript after C.",
        "Step 2: The subscript is 2.",
        "Step 3: Therefore, one molecule contains two carbon atoms."
      ],
      ans: "2 carbon atoms",
      why: "The molecular formula C₂H₄O₂ contains two carbon atoms."
    }
  ]
);


// ============================================================
// 8. REACTIONS OF ETHANOIC ACID
// ============================================================

add(
  "chemistry",
  "organic_chemistry",
  "Reactions of Ethanoic Acid",
  `<h2>Reactions of Ethanoic Acid</h2>

  <p>Ethanoic acid shows the typical reactions of an acid.</p>

  <h3>1. Reaction with reactive metals</h3>

  <p>Ethanoic acid reacts with some reactive metals to produce a salt and hydrogen gas.</p>

  <p>For example:</p>

  <p><strong>2CH₃COOH + Mg → (CH₃COO)₂Mg + H₂</strong></p>

  <h3>2. Reaction with carbonates</h3>

  <p>Ethanoic acid reacts with carbonates to produce a salt, water and carbon dioxide.</p>

  <p>For example:</p>

  <p><strong>2CH₃COOH + Na₂CO₃ → 2CH₃COONa + H₂O + CO₂</strong></p>

  <h3>3. Reaction with alkalis</h3>

  <p>Ethanoic acid reacts with an alkali in a neutralisation reaction.</p>

  <p>For example:</p>

  <p><strong>CH₃COOH + NaOH → CH₃COONa + H₂O</strong></p>

  <p>The salt formed with sodium hydroxide is sodium ethanoate.</p>`,
  [
    {
      q: "What products are formed when ethanoic acid reacts with magnesium?",
      steps: [
        "Step 1: Ethanoic acid is an acid.",
        "Step 2: Acids react with reactive metals.",
        "Step 3: The products are a salt and hydrogen gas.",
        "Step 4: With magnesium, the salt is magnesium ethanoate."
      ],
      ans: "Magnesium ethanoate and hydrogen gas",
      why: "Acid-metal reactions produce a salt and hydrogen gas."
    },
    {
      q: "Complete and balance: CH₃COOH + NaOH →",
      steps: [
        "Step 1: Ethanoic acid reacts with sodium hydroxide.",
        "Step 2: This is a neutralisation reaction.",
        "Step 3: The salt formed is sodium ethanoate, CH₃COONa.",
        "Step 4: Water is also formed.",
        "Step 5: The balanced equation is CH₃COOH + NaOH → CH₃COONa + H₂O."
      ],
      ans: "CH₃COOH + NaOH → CH₃COONa + H₂O",
      why: "An acid reacts with an alkali to form a salt and water."
    },
    {
      q: "What gas is produced when ethanoic acid reacts with sodium carbonate?",
      steps: [
        "Step 1: Ethanoic acid is an acid.",
        "Step 2: Acids react with carbonates.",
        "Step 3: Acid-carbonate reactions produce a salt, water and carbon dioxide.",
        "Step 4: Therefore, the gas produced is carbon dioxide."
      ],
      ans: "Carbon dioxide",
      why: "Carbon dioxide is the characteristic gas produced when an acid reacts with a carbonate."
    }
  ],
  [
    {
      q: "Balance the equation: CH₃COOH + Na₂CO₃ → CH₃COONa + H₂O + CO₂.",
      hint: "Balance the sodium atoms first.",
      steps: [
        "Step 1: Na₂CO₃ contains two sodium atoms.",
        "Step 2: Place 2 before CH₃COONa.",
        "Step 3: This requires 2 molecules of CH₃COOH to supply two ethanoate groups.",
        "Step 4: Check carbon, hydrogen and oxygen atoms.",
        "Step 5: The balanced equation is 2CH₃COOH + Na₂CO₃ → 2CH₃COONa + H₂O + CO₂."
      ],
      ans: "2CH₃COOH + Na₂CO₃ → 2CH₃COONa + H₂O + CO₂",
      why: "The coefficients make the number of every type of atom equal on both sides."
    }
  ]
);
