// ------------------------------------------------------------
// 3. USES OF OXYGEN
// ------------------------------------------------------------

add(
  "chemistry",
  "air_water_environment",
  "Uses of Oxygen",
  `<h2>Uses of Oxygen</h2>

  <p>Oxygen is important because it supports combustion and respiration.</p>

  <h3>Main uses</h3>

  <ul>
    <li>Respiration in hospitals.</li>
    <li>Welding and cutting metals.</li>
    <li>Steel manufacture.</li>
    <li>Supporting combustion in industrial processes.</li>
    <li>Life-support systems in aircraft and spacecraft.</li>
  </ul>

  <h3>Medical oxygen</h3>
  <p>Patients who cannot obtain enough oxygen from normal air may be supplied with oxygen.</p>

  <h3>Welding</h3>
  <p>Oxygen is used with suitable fuel gases to produce a very hot flame for cutting and welding metals.</p>`,

  [
    {
      q: "Why is oxygen used in hospitals?",
      steps: [
        "Step 1: Human cells require oxygen for aerobic respiration.",
        "Step 2: Some patients cannot obtain enough oxygen through normal breathing.",
        "Step 3: Oxygen can therefore be supplied to them."
      ],
      ans: "Oxygen is supplied to patients who need additional oxygen for respiration.",
      why: "Oxygen is required for aerobic respiration."
    },
    {
      q: "Why is oxygen useful in welding?",
      steps: [
        "Step 1: Oxygen supports combustion.",
        "Step 2: A fuel burning in oxygen can produce a very hot flame.",
        "Step 3: The hot flame can melt or cut metals."
      ],
      ans: "It supports combustion and helps produce a very hot flame.",
      why: "The high-temperature flame is useful for cutting and welding metals."
    },
    {
      q: "State two uses of oxygen.",
      steps: [
        "Step 1: Oxygen is required for respiration.",
        "Step 2: Oxygen also supports combustion.",
        "Step 3: Therefore, examples include medical respiration and welding."
      ],
      ans: "Medical respiration and welding/cutting metals.",
      why: "Both uses depend on oxygen's ability to support respiration or combustion."
    }
  ],

  [
    {
      q: "Why would oxygen be useful for a patient having difficulty obtaining enough oxygen from air?",
      hint: "Think about the role of oxygen in respiration.",
      steps: [
        "Step 1: Cells require oxygen for aerobic respiration.",
        "Step 2: Supplying oxygen increases the amount available for respiration.",
        "Step 3: Therefore, oxygen can support the patient's respiratory needs."
      ],
      ans: "Because oxygen is required for aerobic respiration.",
      why: "Cells need oxygen to release energy efficiently through aerobic respiration."
    }
  ]
);


// ------------------------------------------------------------
// 4. PROPERTIES OF WATER
// ------------------------------------------------------------

add(
  "chemistry",
  "air_water_environment",
  "Properties of Water",
  `<h2>Properties of Water</h2>

  <p>Pure water is a colourless, odourless and tasteless liquid at room temperature.</p>

  <ul>
    <li>It freezes at 0°C under standard atmospheric pressure.</li>
    <li>It boils at 100°C under standard atmospheric pressure.</li>
    <li>It is a good solvent for many substances.</li>
    <li>It is essential for living organisms.</li>
  </ul>

  <h3>Water as a compound</h3>
  <p>Water is a compound because hydrogen and oxygen are chemically bonded in a fixed ratio.</p>

  <p><strong>Formula: H₂O</strong></p>`,

  [
    {
      q: "What is the chemical formula of water?",
      steps: [
        "Step 1: Water contains hydrogen and oxygen.",
        "Step 2: Two hydrogen atoms combine with one oxygen atom.",
        "Step 3: Therefore, the formula is H₂O."
      ],
      ans: "H₂O",
      why: "Each water molecule contains two hydrogen atoms and one oxygen atom."
    },
    {
      q: "At what temperature does pure water boil at standard atmospheric pressure?",
      steps: [
        "Step 1: Recall the standard boiling point of water.",
        "Step 2: Pure water boils at 100°C at standard atmospheric pressure."
      ],
      ans: "100°C",
      why: "100°C is the standard boiling point of pure water at normal atmospheric pressure."
    },
    {
      q: "At what temperature does pure water freeze at standard atmospheric pressure?",
      steps: [
        "Step 1: Recall the standard freezing point of water.",
        "Step 2: Pure water freezes at 0°C."
      ],
      ans: "0°C",
      why: "0°C is the standard freezing point of pure water."
    }
  ],

  [
    {
      q: "A learner says water is a mixture because it contains hydrogen and oxygen. Correct the statement.",
      hint: "Ask whether hydrogen and oxygen are chemically bonded.",
      steps: [
        "Step 1: Hydrogen and oxygen are chemically bonded in water.",
        "Step 2: They occur in a fixed ratio of 2:1.",
        "Step 3: Therefore, water is a compound."
      ],
      ans: "Water is a compound because hydrogen and oxygen are chemically bonded in a fixed ratio.",
      why: "Compounds contain elements chemically combined in definite proportions."
    }
  ]
);


// ------------------------------------------------------------
// 5. WATER AS A SOLVENT
// ------------------------------------------------------------

add(
  "chemistry",
  "air_water_environment",
  "Water as a Solvent",
  `<h2>Water as a Solvent</h2>

  <p>A <strong>solvent</strong> is a substance that dissolves a solute to form a solution.</p>

  <p>Water dissolves many ionic and polar substances and is therefore often called a good solvent.</p>

  <h3>Examples</h3>

  <p>When sodium chloride dissolves in water:</p>

  <p><strong>NaCl(s) → Na⁺(aq) + Cl⁻(aq)</strong></p>

  <p>Water is important in living organisms because many substances are transported in aqueous solution.</p>`,

  [
    {
      q: "What is a solvent?",
      steps: [
        "Step 1: A solution contains a solvent and one or more solutes.",
        "Step 2: The solvent is the substance that dissolves the solute.",
        "Step 3: Therefore, a solvent is the substance that dissolves a solute."
      ],
      ans: "A solvent is a substance that dissolves a solute to form a solution.",
      why: "The solvent provides the medium in which the solute dissolves."
    },
    {
      q: "What happens when sodium chloride dissolves in water?",
      steps: [
        "Step 1: Sodium chloride contains Na⁺ and Cl⁻ ions.",
        "Step 2: Water separates and surrounds the ions.",
        "Step 3: The ions become dispersed in the water."
      ],
      ans: "NaCl dissolves to form hydrated Na⁺ and Cl⁻ ions in solution.",
      why: "Water can separate ionic particles and keep them dispersed in solution."
    },
    {
      q: "Why is water important for transporting dissolved substances in living organisms?",
      steps: [
        "Step 1: Water dissolves many substances.",
        "Step 2: Dissolved substances can move with the water.",
        "Step 3: Therefore, water can transport substances through organisms."
      ],
      ans: "Because water dissolves many substances, allowing them to be transported in solution.",
      why: "Dissolved particles can move through aqueous fluids."
    }
  ],

  [
    {
      q: "Salt disappears when added to water. Has the salt necessarily been destroyed?",
      hint: "Think about what dissolving means.",
      steps: [
        "Step 1: Salt particles become separated and dispersed in water.",
        "Step 2: The particles are still present in the solution.",
        "Step 3: Therefore, the salt has dissolved rather than been destroyed."
      ],
      ans: "No. The salt has dissolved and its particles remain in the solution.",
      why: "Dissolving is a physical process; the substance remains present in the solution."
    }
  ]
);


// ------------------------------------------------------------
// 6. HARD WATER
// ------------------------------------------------------------

add(
  "chemistry",
  "air_water_environment",
  "Hard Water",
  `<h2>Hard Water</h2>

  <p>Hard water contains dissolved calcium and magnesium ions.</p>

  <p>These ions react with soap to form an insoluble substance called <strong>scum</strong>.</p>

  <h3>Effects of hard water</h3>

  <ul>
    <li>Soap does not lather easily.</li>
    <li>Scum is formed.</li>
    <li>More soap is required for washing.</li>
    <li>Some types of hard water can form scale in pipes and boilers.</li>
  </ul>

  <h3>Important distinction</h3>
  <p>Hard water is not necessarily unsafe to drink. The main problem considered here is its behaviour with soap and heating systems.</p>`,

  [
    {
      q: "What makes water hard?",
      steps: [
        "Step 1: Hard water contains dissolved mineral ions.",
        "Step 2: The important ions are mainly calcium and magnesium ions.",
        "Step 3: Therefore, dissolved calcium and magnesium ions cause hardness."
      ],
      ans: "Dissolved calcium and magnesium ions.",
      why: "These ions cause the characteristic reactions of hard water."
    },
    {
      q: "Why does hard water form scum with soap?",
      steps: [
        "Step 1: Hard water contains Ca²⁺ and/or Mg²⁺ ions.",
        "Step 2: These ions react with soap anions.",
        "Step 3: An insoluble substance called scum is formed."
      ],
      ans: "Calcium and magnesium ions react with soap to form insoluble scum.",
      why: "The insoluble calcium or magnesium soap removes soap from solution."
    },
    {
      q: "Why is more soap needed when washing with hard water?",
      steps: [
        "Step 1: Some soap reacts with calcium and magnesium ions.",
        "Step 2: This produces scum instead of useful lather.",
        "Step 3: More soap is therefore needed to produce sufficient lather."
      ],
      ans: "More soap is needed because some soap is used up forming scum.",
      why: "The calcium and magnesium ions reduce the amount of soap available to form lather."
    }
  ],

  [
    {
      q: "A learner adds soap to hard water and obtains little lather. What is the likely reason?",
      hint: "Think about calcium and magnesium ions.",
      steps: [
        "Step 1: Hard water contains calcium and magnesium ions.",
        "Step 2: These ions react with soap.",
        "Step 3: The reaction forms scum and reduces lather."
      ],
      ans: "Calcium and magnesium ions react with the soap to form scum.",
      why: "This is the characteristic behaviour of hard water."
    }
  ]
);


// ------------------------------------------------------------
// 7. SOFT WATER
// ------------------------------------------------------------

add(
  "chemistry",
  "air_water_environment",
  "Soft Water",
  `<h2>Soft Water</h2>

  <p>Soft water contains very small amounts of calcium and magnesium ions compared with hard water.</p>

  <h3>Behaviour with soap</h3>

  <p>Soft water reacts less with soap, so soap produces lather readily.</p>

  <h3>Comparison</h3>

  <p><strong>Soft water → easy lathering → little or no scum.</strong></p>

  <p><strong>Hard water → poor lathering → scum formation.</strong></p>`,

  [
    {
      q: "What is soft water?",
      steps: [
        "Step 1: Compare its calcium and magnesium ion content with hard water.",
        "Step 2: Soft water contains little calcium and magnesium ions.",
        "Step 3: Therefore, it lathers easily with soap."
      ],
      ans: "Water containing little calcium and magnesium ions that lathers easily with soap.",
      why: "The low concentration of hardness-causing ions means little soap is lost as scum."
    },
    {
      q: "What happens when soap is added to soft water?",
      steps: [
        "Step 1: Soft water has little calcium and magnesium.",
        "Step 2: Little soap is converted into insoluble scum.",
        "Step 3: Therefore, soap forms lather easily."
      ],
      ans: "Soap lathers easily.",
      why: "There are few calcium and magnesium ions to react with the soap."
    },
    {
      q: "Which type of water is generally preferred for washing with soap: hard or soft?",
      steps: [
        "Step 1: Washing requires soap to produce lather.",
        "Step 2: Soft water allows soap to lather readily.",
        "Step 3: Therefore, soft water is preferred."
      ],
      ans: "Soft water.",
      why: "Soft water allows soap to form lather without significant scum formation."
    }
  ],

  [
    {
      q: "Water produces abundant lather with only a small amount of soap. Is it likely to be hard or soft?",
      hint: "Hard water wastes some soap as scum.",
      steps: [
        "Step 1: Hard water reacts with soap and forms scum.",
        "Step 2: Soft water allows soap to lather easily.",
        "Step 3: Therefore, the water is likely soft."
      ],
      ans: "Soft water.",
      why: "Easy lathering with little soap indicates low hardness."
    }
  ]
);


// ------------------------------------------------------------
// 8. WATER PURIFICATION
// ------------------------------------------------------------

add(
  "chemistry",
  "air_water_environment",
  "Water Purification",
  `<h2>Water Purification</h2>

  <p>Water purification removes unwanted substances and harmful microorganisms so that water becomes suitable for its intended use.</p>

  <h3>Common purification processes</h3>

  <ul>
    <li><strong>Filtration:</strong> removes insoluble solid particles.</li>
    <li><strong>Boiling:</strong> kills many microorganisms.</li>
    <li><strong>Chlorination:</strong> uses chlorine to disinfect water.</li>
    <li><strong>Distillation:</strong> separates water from many dissolved substances by evaporation followed by condensation.</li>
  </ul>

  <p>The purification method depends on the type of impurity present.</p>`,

  [
    {
      q: "What is the purpose of filtration during water purification?",
      steps: [
        "Step 1: Identify the type of impurity filtration removes.",
        "Step 2: Filtration separates insoluble solid particles from a liquid.",
        "Step 3: Therefore, filtration removes suspended insoluble particles."
      ],
      ans: "To remove insoluble solid particles from water.",
      why: "The filter traps solid particles while water passes through."
    },
    {
      q: "Why is water boiled during purification?",
      steps: [
        "Step 1: Contaminated water may contain harmful microorganisms.",
        "Step 2: Heating water to boiling temperature kills many microorganisms.",
        "Step 3: Therefore, boiling helps make water safer."
      ],
      ans: "Boiling kills many harmful microorganisms.",
      why: "High temperature damages and kills many microorganisms."
    },
    {
      q: "What is the main purpose of chlorination?",
      steps: [
        "Step 1: Chlorine is added to water in controlled amounts.",
        "Step 2: Chlorine acts as a disinfectant.",
        "Step 3: It destroys or inactivates many microorganisms."
      ],
      ans: "To disinfect water by killing or inactivating microorganisms.",
      why: "Chlorine is an effective water disinfectant."
    }
  ],

  [
    {
      q: "A water sample contains mud particles. Which purification process should be used first?",
      hint: "Think about separating insoluble solids from a liquid.",
      steps: [
        "Step 1: Mud is an insoluble solid.",
        "Step 2: Filtration separates insoluble solids from liquids.",
        "Step 3: Therefore, filtration is appropriate."
      ],
      ans: "Filtration.",
      why: "Filtration removes suspended insoluble particles such as mud."
    }
  ]
);


// ------------------------------------------------------------
// 9. CARBON MONOXIDE AS AN AIR POLLUTANT
// ------------------------------------------------------------

add(
  "chemistry",
  "air_water_environment",
  "Carbon Monoxide as an Air Pollutant",
  `<h2>Carbon Monoxide as an Air Pollutant</h2>

  <p>Carbon monoxide, CO, is a poisonous gas produced mainly by incomplete combustion of carbon-containing fuels.</p>

  <p>For example:</p>

  <p><strong>2C + O₂ → 2CO</strong></p>

  <h3>Why CO is dangerous</h3>

  <p>Carbon monoxide combines strongly with haemoglobin in blood. This reduces the ability of blood to transport oxygen around the body.</p>

  <h3>Sources</h3>

  <ul>
    <li>Incomplete combustion in vehicle engines.</li>
    <li>Burning charcoal in poorly ventilated rooms.</li>
    <li>Faulty fuel-burning appliances.</li>
  </ul>`,

  [
    {
      q: "How is carbon monoxide formed?",
      steps: [
        "Step 1: Carbon-containing fuels require oxygen for combustion.",
        "Step 2: If the oxygen supply is insufficient, combustion may be incomplete.",
        "Step 3: Incomplete combustion can produce carbon monoxide."
      ],
      ans: "Carbon monoxide is formed mainly during incomplete combustion of carbon-containing fuels.",
      why: "Insufficient oxygen prevents complete conversion of carbon to carbon dioxide."
    },
    {
      q: "Write an equation showing formation of carbon monoxide from carbon.",
      steps: [
        "Step 1: The reactants are carbon and oxygen.",
        "Step 2: Limited oxygen produces carbon monoxide.",
        "Step 3: Balance the equation: 2C + O₂ → 2CO."
      ],
      ans: "2C + O₂ → 2CO",
      why: "Two carbon atoms combine with one oxygen molecule to produce two carbon monoxide molecules."
    },
    {
      q: "Why is carbon monoxide poisonous?",
      steps: [
        "Step 1: Carbon monoxide enters the bloodstream through the lungs.",
        "Step 2: It binds strongly to haemoglobin.",
        "Step 3: This reduces the blood's ability to transport oxygen."
      ],
      ans: "It binds strongly to haemoglobin and reduces oxygen transport in the blood.",
      why: "Reduced oxygen transport can deprive body tissues of oxygen."
    }
  ],

  [
    {
      q: "Why is burning charcoal inside a poorly ventilated room dangerous?",
      hint: "Consider incomplete combustion and the gas produced.",
      steps: [
        "Step 1: Charcoal contains carbon.",
        "Step 2: Limited oxygen can cause incomplete combustion.",
        "Step 3: Carbon monoxide can therefore accumulate in the room."
      ],
      ans: "It can cause poisonous carbon monoxide to accumulate.",
      why: "Poor ventilation limits oxygen and prevents CO from being safely dispersed."
    }
  ]
);


// ------------------------------------------------------------
// 10. SULPHUR DIOXIDE AS AN AIR POLLUTANT
// ------------------------------------------------------------

add(
  "chemistry",
  "air_water_environment",
  "Sulphur Dioxide as an Air Pollutant",
  `<h2>Sulphur Dioxide as an Air Pollutant</h2>

  <p>Sulphur dioxide, SO₂, is produced when sulphur-containing fuels are burned.</p>

  <p>A simplified equation is:</p>

  <p><strong>S + O₂ → SO₂</strong></p>

  <h3>Effects</h3>

  <ul>
    <li>Irritates the respiratory system.</li>
    <li>Contributes to acid rain.</li>
    <li>Can damage vegetation.</li>
    <li>Can contribute to corrosion of materials.</li>
  </ul>

  <p>SO₂ can react with water in the atmosphere to form acidic substances.</p>`,

  [
    {
      q: "How is sulphur dioxide formed during combustion?",
      steps: [
        "Step 1: Sulphur-containing material is burned.",
        "Step 2: Sulphur reacts with oxygen.",
        "Step 3: Sulphur dioxide is produced."
      ],
      ans: "Sulphur dioxide is formed when sulphur-containing substances burn in oxygen.",
      why: "Sulphur combines with oxygen during combustion."
    },
    {
      q: "Write the equation for combustion of sulphur in oxygen.",
      steps: [
        "Step 1: Sulphur is the reactant.",
        "Step 2: Oxygen is the other reactant.",
        "Step 3: The product is sulphur dioxide."
      ],
      ans: "S + O₂ → SO₂",
      why: "One sulphur atom combines with one oxygen molecule to form sulphur dioxide."
    },
    {
      q: "State two environmental effects of sulphur dioxide.",
      steps: [
        "Step 1: SO₂ can react with atmospheric water.",
        "Step 2: This contributes to acidic precipitation.",
        "Step 3: SO₂ can also damage vegetation and materials."
      ],
      ans: "It contributes to acid rain and can damage vegetation or materials.",
      why: "Sulphur dioxide is an acidic air pollutant."
    }
  ],

  [
    {
      q: "A factory burns sulphur-containing fuel and releases SO₂. Name one environmental problem that may result.",
      hint: "Think about acidic precipitation.",
      steps: [
        "Step 1: SO₂ enters the atmosphere.",
        "Step 2: It can participate in reactions that produce acidic substances.",
        "Step 3: These contribute to acid rain."
      ],
      ans: "Acid rain.",
      why: "Sulphur dioxide is an important contributor to acid rain."
    }
  ]
);


// ------------------------------------------------------------
// 11. NITROGEN OXIDES AS AIR POLLUTANTS
