// ------------------------------------------------------------
// 1. TEST FOR AMMONIUM IONS
// ------------------------------------------------------------

add(
  "chemistry",
  "qualitative_analysis",
  "Test for Ammonium Ions",
  `<h2>Test for Ammonium Ions</h2>

  <p>Ammonium ions are represented by <strong>NH₄⁺</strong>.</p>

  <p>They can be identified by adding a suitable alkali, such as sodium hydroxide solution, and warming the mixture.</p>

  <h3>Test</h3>
  <ol>
    <li>Add sodium hydroxide solution to the sample.</li>
    <li>Warm the mixture gently.</li>
    <li>Test any gas produced with damp red litmus paper.</li>
  </ol>

  <h3>Positive result</h3>
  <p>A pungent-smelling gas is produced which turns damp red litmus paper blue.</p>

  <p>The gas is <strong>ammonia, NH₃</strong>.</p>

  <p><strong>NH₄⁺ + OH⁻ → NH₃ + H₂O</strong></p>`,

  [
    {
      q: "Which ion is being tested for when ammonia gas is produced after warming a sample with sodium hydroxide?",
      steps: [
        "Step 1: Ammonia is NH₃.",
        "Step 2: Ammonia can be produced from ammonium ions when an alkali is added.",
        "Step 3: Therefore, the ion being tested is NH₄⁺."
      ],
      ans: "Ammonium ion, NH₄⁺.",
      why: "Ammonium ions react with hydroxide ions to release ammonia gas."
    },
    {
      q: "What happens to damp red litmus paper in the presence of ammonia gas?",
      steps: [
        "Step 1: Ammonia dissolves in the moisture on the litmus paper.",
        "Step 2: The resulting solution is alkaline.",
        "Step 3: Alkaline substances turn red litmus blue."
      ],
      ans: "Damp red litmus paper turns blue.",
      why: "Ammonia produces an alkaline solution in water."
    },
    {
      q: "Write the ionic equation for the reaction between ammonium ions and hydroxide ions.",
      steps: [
        "Step 1: The reactants are NH₄⁺ and OH⁻.",
        "Step 2: Ammonium ions react with hydroxide ions.",
        "Step 3: The products are ammonia and water."
      ],
      ans: "NH₄⁺ + OH⁻ → NH₃ + H₂O",
      why: "The reaction releases ammonia gas from ammonium ions."
    }
  ],

  [
    {
      q: "A sample gives off ammonia when warmed with sodium hydroxide. What ion is present?",
      hint: "The gas is produced from ammonium ions.",
      steps: [
        "Step 1: Identify the gas as ammonia.",
        "Step 2: Ammonia is released from ammonium ions in this test.",
        "Step 3: Therefore, the sample contains NH₄⁺."
      ],
      ans: "Ammonium ions, NH₄⁺.",
      why: "The sodium hydroxide test is a standard test for ammonium ions."
    }
  ]
);


