add(
  "chemistry",
  "qualitative_analysis",
  "Test for Copper(II) Ions",
  `<h2>Test for Copper(II) Ions</h2>

  <p>Copper(II) ions are represented by <strong>Cu²⁺</strong>.</p>

  <h3>Test using sodium hydroxide</h3>

  <p>Add sodium hydroxide solution to the sample.</p>

  <h3>Positive result</h3>

  <p>A <strong>blue precipitate</strong> of copper(II) hydroxide forms.</p>

  <p><strong>Cu²⁺ + 2OH⁻ → Cu(OH)₂(s)</strong></p>

  <p>The precipitate is insoluble in excess sodium hydroxide under the usual school laboratory test.</p>`,

  [
    {
      q: "What colour precipitate is produced when sodium hydroxide is added to a solution containing Cu²⁺ ions?",
      steps: [
        "Step 1: Cu²⁺ reacts with OH⁻ ions.",
        "Step 2: Copper(II) hydroxide is formed.",
        "Step 3: Copper(II) hydroxide is blue."
      ],
      ans: "A blue precipitate.",
      why: "Cu²⁺ forms blue copper(II) hydroxide with hydroxide ions."
    },
    {
      q: "Write the ionic equation for the test for Cu²⁺ ions.",
      steps: [
        "Step 1: Identify the ions reacting: Cu²⁺ and OH⁻.",
        "Step 2: Two hydroxide ions are required to balance the +2 charge.",
        "Step 3: The solid product is Cu(OH)₂."
      ],
      ans: "Cu²⁺ + 2OH⁻ → Cu(OH)₂(s)",
      why: "The charges and atoms are balanced in the precipitation reaction."
    },
    {
      q: "What observation indicates the presence of copper(II) ions?",
      steps: [
        "Step 1: Add sodium hydroxide solution.",
        "Step 2: Observe whether a precipitate forms.",
        "Step 3: A blue precipitate indicates Cu²⁺."
      ],
      ans: "A blue precipitate forms.",
      why: "Copper(II) hydroxide has a characteristic blue colour."
    }
  ],

  [
    {
      q: "A colourless solution produces a blue precipitate when sodium hydroxide is added. Which common ion could be present?",
      hint: "Think of the metal ion that forms blue copper(II) hydroxide.",
      steps: [
        "Step 1: A blue precipitate is observed.",
        "Step 2: Cu²⁺ reacts with OH⁻ to form blue Cu(OH)₂.",
        "Step 3: Therefore, Cu²⁺ may be present."
      ],
      ans: "Copper(II) ions, Cu²⁺.",
      why: "Copper(II) hydroxide is a blue precipitate."
    }
  ]
);


