add(
  "chemistry",
  "electrochemistry",
  "Chemical Cell Voltage",
  `<h2>Chemical Cell Voltage</h2>

  <p>The <strong>voltage</strong> or <strong>potential difference</strong> of a cell is the electrical energy supplied per unit charge.</p>

  <p>It is measured in <strong>volts (V)</strong>.</p>

  <p>The voltage produced by a chemical cell depends on the materials used as the electrodes and the electrolyte.</p>

  <h3>Connecting Cells in Series</h3>

  <p>When cells are connected in series in the same direction, their voltages add.</p>

  <p>For example:</p>

  <p><strong>1.5 V + 1.5 V = 3.0 V</strong></p>

  <h3>Connecting Cells in Opposition</h3>

  <p>If cells are connected in opposite directions, their voltages oppose each other.</p>

  <p>For example:</p>

  <p><strong>3.0 V − 1.5 V = 1.5 V</strong></p>`,
  [
    {
      q: "What is the unit used to measure the voltage of a chemical cell?",
      steps: [
        "Step 1: Voltage is a measure of potential difference.",
        "Step 2: Potential difference is measured in volts.",
        "Step 3: Therefore, the unit is V."
      ],
      ans: "Volt (V).",
      why: "The volt is the SI unit for potential difference."
    },
    {
      q: "Two identical cells each produce 1.5 V. They are connected in series in the same direction. Calculate the total voltage.",
      steps: [
        "Step 1: Voltage of first cell = 1.5 V.",
        "Step 2: Voltage of second cell = 1.5 V.",
        "Step 3: Cells are connected in series in the same direction.",
        "Step 4: Add their voltages: 1.5 + 1.5 = 3.0 V."
      ],
      ans: "3.0 V.",
      why: "The voltages of cells connected in series in the same direction add together."
    },
    {
      q: "Three cells each produce 2 V and are connected in series in the same direction. What is the total voltage?",
      steps: [
        "Step 1: Each cell produces 2 V.",
        "Step 2: There are 3 cells.",
        "Step 3: Total voltage = 2 + 2 + 2.",
        "Step 4: Total voltage = 6 V."
      ],
      ans: "6 V.",
      why: "The voltages of series-connected cells add together."
    }
  ],
  [
    {
      q: "A circuit requires 6 V. You have four identical cells, each rated at 1.5 V. How should they be connected to obtain 6 V?",
      hint: "Add the voltages of cells connected in series.",
      steps: [
        "Step 1: Each cell produces 1.5 V.",
        "Step 2: Four cells are available.",
        "Step 3: Total voltage = 1.5 × 4.",
        "Step 4: Total voltage = 6 V.",
        "Step 5: Therefore, connect the four cells in series in the same direction."
      ],
      ans: "Connect all four cells in series in the same direction.",
      why: "Four 1.5 V cells produce 6 V when their voltages are added in series."
    }
  ]
);

add(
  "chemistry",
  "electrochemistry",
  "Batteries",
  `<h2>Batteries</h2>

  <p>A <strong>battery</strong> is an arrangement of one or more electrochemical cells used to provide electrical energy.</p>

  <h3>Primary Batteries</h3>

  <p>Primary batteries are designed for use until the chemical reactants are substantially consumed. They are generally not intended to be recharged.</p>

  <h3>Secondary Batteries</h3>

  <p>Secondary batteries can be recharged by passing an electric current through them in the appropriate direction.</p>

  <p>Charging drives chemical changes that restore the chemical substances needed for the cell to operate again.</p>

  <h3>Series Connection</h3>

  <p>Cells connected in series increase the total voltage.</p>

  <h3>Parallel Connection</h3>

  <p>Cells connected in parallel can provide the same voltage as one cell while allowing the arrangement to supply current for a longer period, depending on the cells and load.</p>

  <p>Batteries should be handled and disposed of safely because some contain hazardous substances.</p>`,
  [
    {
      q: "What is a battery?",
      steps: [
        "Step 1: An electrochemical cell produces electrical energy from chemical reactions.",
        "Step 2: A battery consists of one or more electrochemical cells arranged to supply electrical energy.",
        "Step 3: Therefore, a battery is an arrangement of electrochemical cells."
      ],
      ans: "A battery is an arrangement of one or more electrochemical cells used to provide electrical energy.",
      why: "A battery uses electrochemical cells as its source of electrical energy."
    },
    {
      q: "What is the difference between a primary battery and a secondary battery?",
      steps: [
        "Step 1: Consider whether the battery can be restored by charging.",
        "Step 2: Primary batteries are generally not designed to be recharged.",
        "Step 3: Secondary batteries can be recharged."
      ],
      ans: "A primary battery is generally not rechargeable, while a secondary battery can be recharged.",
      why: "Charging a secondary battery reverses or restores the chemical changes that occur during discharge."
    },
    {
      q: "Four identical 1.5 V cells are connected in series. Calculate the total voltage.",
      steps: [
        "Step 1: Voltage of one cell = 1.5 V.",
        "Step 2: Number of cells = 4.",
        "Step 3: Total voltage = 1.5 × 4.",
        "Step 4: Total voltage = 6 V."
      ],
      ans: "6 V.",
      why: "Cells connected in series have their voltages added."
    }
  ],
  [
    {
      q: "A student connects three 1.5 V cells in series but one cell is connected in the opposite direction. What is the resulting voltage if the opposing cell subtracts from the other two?",
      hint: "Add the two cells in the same direction, then subtract the opposing cell.",
      steps: [
        "Step 1: Two cells in the same direction give 1.5 + 1.5 = 3.0 V.",
        "Step 2: The opposing cell contributes −1.5 V.",
        "Step 3: Resulting voltage = 3.0 − 1.5.",
        "Step 4: Resulting voltage = 1.5 V."
      ],
      ans: "1.5 V.",
      why: "The voltage of the oppositely connected cell opposes the voltage of the other two cells."
    }
  ]
);
add(
  "chemistry",
  "electrochemistry",
  "Strong Electrolytes",
  `<h2>Strong Electrolytes</h2>

  <p>A <strong>strong electrolyte</strong> is a substance that completely dissociates or ionises into ions when dissolved in water.</p>

  <p>Because many ions are present and are free to move through the solution, a strong electrolyte conducts electricity well.</p>

  <h3>Examples</h3>

  <ul>
    <li>Hydrochloric acid, HCl</li>
    <li>Nitric acid, HNO₃</li>
    <li>Sodium hydroxide, NaOH</li>
    <li>Sodium chloride, NaCl</li>
  </ul>

  <h3>Example</h3>

  <p>When sodium chloride dissolves:</p>

  <p><strong>NaCl(aq) → Na⁺(aq) + Cl⁻(aq)</strong></p>

  <p>The sodium chloride produces mobile ions throughout the solution.</p>`,
  [
    {
      q: "What is a strong electrolyte?",
      steps: [
        "Step 1: A strong electrolyte is dissolved in water.",
        "Step 2: It completely dissociates or ionises into ions.",
        "Step 3: The ions are free to move through the solution.",
        "Step 4: The mobile ions allow the solution to conduct electricity well."
      ],
      ans: "A strong electrolyte is a substance that completely dissociates or ionises into ions in water and conducts electricity well.",
      why: "The large concentration of mobile ions allows electrical charge to move through the solution."
    },
    {
      q: "Write the ionic equation for sodium chloride dissolving in water.",
      steps: [
        "Step 1: Identify the ions in sodium chloride.",
        "Step 2: Sodium chloride contains Na⁺ and Cl⁻ ions.",
        "Step 3: Dissolving separates the ions.",
        "Step 4: Write the equation as NaCl(aq) → Na⁺(aq) + Cl⁻(aq)."
      ],
      ans: "NaCl(aq) → Na⁺(aq) + Cl⁻(aq).",
      why: "Sodium chloride separates into sodium ions and chloride ions in aqueous solution."
    },
    {
      q: "Why does a strong electrolyte conduct electricity well?",
      steps: [
        "Step 1: The substance produces many ions in solution.",
        "Step 2: The ions are free to move.",
        "Step 3: Moving charged particles carry electrical charge."
      ],
      ans: "Because it produces a high concentration of mobile ions that carry electrical charge.",
      why: "Electrical conduction in an electrolyte solution occurs through the movement of ions."
    }
  ],
  [
    {
      q: "A solution contains a substance that completely dissociates into ions and conducts electricity strongly. How would you classify the substance?",
      hint: "Think about the extent of ion formation.",
      steps: [
        "Step 1: The substance completely dissociates into ions.",
        "Step 2: The solution therefore contains many mobile ions.",
        "Step 3: This is characteristic of a strong electrolyte."
      ],
      ans: "It is a strong electrolyte.",
      why: "Complete ionisation or dissociation produces many mobile ions and strong electrical conductivity."
    }
  ]
);

add(
  "chemistry",
  "electrochemistry",
  "Weak Electrolytes",
  `<h2>Weak Electrolytes</h2>

  <p>A <strong>weak electrolyte</strong> is a substance that only partially ionises or dissociates into ions when dissolved in water.</p>

  <p>The solution therefore contains both ions and un-ionised or undissociated particles.</p>

  <p>Because there are fewer mobile ions than in a strong electrolyte solution of comparable concentration, a weak electrolyte conducts electricity less strongly.</p>

  <h3>Example</h3>

  <p>Ethanoic acid is a weak electrolyte:</p>

  <p><strong>CH₃COOH(aq) ⇌ H⁺(aq) + CH₃COO⁻(aq)</strong></p>

  <p>The reversible arrow shows that only part of the ethanoic acid ionises.</p>

  <h3>Important distinction</h3>

  <p>Weak does not mean that the solution contains no ions. It means that ionisation is incomplete.</p>`,
  [
    {
      q: "What is a weak electrolyte?",
      steps: [
        "Step 1: A weak electrolyte is dissolved in water.",
        "Step 2: Only part of the substance ionises or dissociates.",
        "Step 3: Both ions and un-ionised particles remain in the solution."
      ],
      ans: "A weak electrolyte is a substance that only partially ionises or dissociates into ions in water.",
      why: "Incomplete ionisation means fewer mobile ions are present compared with a strong electrolyte of similar concentration."
    },
    {
      q: "Why does a weak electrolyte conduct electricity less strongly than a strong electrolyte of similar concentration?",
      steps: [
        "Step 1: A weak electrolyte only partially ionises.",
        "Step 2: Therefore, fewer mobile ions are produced.",
        "Step 3: Fewer mobile ions carry less electrical charge through the solution."
      ],
      ans: "Because it produces fewer mobile ions in solution.",
      why: "Electrical conductivity depends on the availability and movement of charged particles."
    },
    {
      q: "Write the ionisation equation for ethanoic acid in water.",
      steps: [
        "Step 1: Ethanoic acid has the formula CH₃COOH.",
        "Step 2: It forms hydrogen ions and ethanoate ions.",
        "Step 3: Because it is a weak electrolyte, use a reversible arrow.",
        "Step 4: Write CH₃COOH(aq) ⇌ H⁺(aq) + CH₃COO⁻(aq)."
      ],
      ans: "CH₃COOH(aq) ⇌ H⁺(aq) + CH₃COO⁻(aq).",
      why: "Only some ethanoic acid molecules ionise, so the process is represented as reversible."
    }
  ],
  [
    {
      q: "A student says, 'A weak electrolyte does not contain ions.' Is the statement correct?",
      hint: "Weak means partial ionisation, not zero ionisation.",
      steps: [
        "Step 1: A weak electrolyte partially ionises in water.",
        "Step 2: Partial ionisation produces some ions.",
        "Step 3: Therefore, ions are present even though many particles remain un-ionised."
      ],
      ans: "No. A weak electrolyte contains ions, but only a fraction of its particles ionise.",
      why: "Weak electrolytes produce fewer ions because their ionisation is incomplete."
    }
  ]
);

add(
  "chemistry",
  "electrochemistry",
  "Non-electrolytes",
  `<h2>Non-electrolytes</h2>

  <p>A <strong>non-electrolyte</strong> is a substance that does not produce ions in solution and therefore does not conduct electricity through its aqueous solution.</p>

  <h3>Example</h3>

  <p>Sugar dissolves in water but remains mainly as neutral sugar molecules.</p>

  <p><strong>C₁₂H₂₂O₁₁(s) → C₁₂H₂₂O₁₁(aq)</strong></p>

  <p>The sugar molecules do not separate into ions.</p>

  <p>Therefore, there are no mobile ions available to carry electrical charge through the solution.</p>

  <h3>Comparison</h3>

  <ul>
    <li><strong>Strong electrolyte:</strong> completely ionises or dissociates.</li>
    <li><strong>Weak electrolyte:</strong> partially ionises or dissociates.</li>
    <li><strong>Non-electrolyte:</strong> does not produce ions in solution.</li>
  </ul>`,
  [
    {
      q: "What is a non-electrolyte?",
      steps: [
        "Step 1: A non-electrolyte dissolves without producing mobile ions.",
        "Step 2: Without mobile ions, electrical charge cannot be carried through the solution by ions.",
        "Step 3: Therefore, its aqueous solution does not conduct electricity."
      ],
      ans: "A non-electrolyte is a substance that does not produce ions in solution and therefore does not conduct electricity through its aqueous solution.",
      why: "There are no mobile ions available to carry electrical charge."
    },
    {
      q: "Why does a sugar solution not conduct electricity like a sodium chloride solution?",
      steps: [
        "Step 1: Sugar dissolves as neutral molecules.",
        "Step 2: It does not produce ions in the solution.",
        "Step 3: Sodium chloride produces Na⁺ and Cl⁻ ions.",
        "Step 4: The sodium chloride ions can move and carry electrical charge."
      ],
      ans: "Sugar remains as neutral molecules and produces no mobile ions, while sodium chloride produces mobile ions.",
      why: "Electrical conduction in aqueous electrolyte solutions depends on the movement of ions."
    },
    {
      q: "Classify sodium chloride solution, ethanoic acid solution and sugar solution as strong electrolyte, weak electrolyte or non-electrolyte.",
      steps: [
        "Step 1: Sodium chloride produces ions in solution and is treated as a strong electrolyte.",
        "Step 2: Ethanoic acid only partially ionises, so it is a weak electrolyte.",
        "Step 3: Sugar does not produce ions, so it is a non-electrolyte."
      ],
      ans: "Sodium chloride solution — strong electrolyte; ethanoic acid solution — weak electrolyte; sugar solution — non-electrolyte.",
      why: "The classification depends on how extensively the substance produces mobile ions in solution."
    }
  ],
  [
    {
      q: "Three solutions are tested for electrical conductivity. Solution A conducts strongly, Solution B conducts weakly and Solution C does not conduct. Classify each solution.",
      hint: "Match conductivity with the amount of mobile ions produced.",
      steps: [
        "Step 1: Strong conductivity indicates many mobile ions.",
        "Step 2: Weak conductivity indicates fewer mobile ions.",
        "Step 3: No conductivity indicates no significant mobile ions.",
        "Step 4: Therefore, A is a strong electrolyte, B is a weak electrolyte and C is a non-electrolyte."
      ],
      ans: "A — strong electrolyte; B — weak electrolyte; C — non-electrolyte.",
      why: "The three categories differ according to the extent to which mobile ions are produced in solution."
    }
  ]
);
add(
  "chemistry",
  "metals",
  "Bauxite",
  `<h2>Bauxite</h2>

  <p><strong>Bauxite</strong> is the main ore from which aluminium is extracted.</p>

  <p>It contains aluminium compounds together with impurities such as iron(III) oxide, silicon compounds and other materials.</p>

  <p>Because aluminium is very reactive, it is not extracted from its ore by simple reduction with carbon.</p>

  <h3>Extraction of Aluminium</h3>

  <p>The extraction of aluminium involves:</p>

  <ol>
    <li>Obtaining bauxite.</li>
    <li>Purifying the bauxite to obtain aluminium oxide.</li>
    <li>Electrolysing molten aluminium oxide to produce aluminium.</li>
  </ol>

  <p>The purified aluminium oxide is commonly called <strong>alumina</strong>.</p>`,
  [
    {
      q: "What is bauxite?",
      steps: [
        "Step 1: Aluminium occurs naturally combined with other elements.",
        "Step 2: The main ore containing aluminium compounds is bauxite.",
        "Step 3: Therefore, bauxite is the main ore used to obtain aluminium."
      ],
      ans: "Bauxite is the main ore from which aluminium is extracted.",
      why: "Bauxite contains aluminium compounds that can be processed to obtain aluminium oxide."
    },
    {
      q: "Why is aluminium not extracted from its ore by heating it with carbon?",
      steps: [
        "Step 1: Aluminium is a very reactive metal.",
        "Step 2: Aluminium has a stronger attraction to oxygen than carbon can overcome under ordinary extraction conditions.",
        "Step 3: Therefore, carbon cannot effectively reduce aluminium oxide to aluminium.",
        "Step 4: Aluminium is instead extracted by electrolysis."
      ],
      ans: "Because aluminium is more reactive than carbon, its oxide cannot be effectively reduced by carbon.",
      why: "The high reactivity of aluminium makes electrolysis necessary for its extraction."
    },
    {
      q: "State the main ore used in the extraction of aluminium.",
      steps: [
        "Step 1: Identify the principal naturally occurring aluminium ore.",
        "Step 2: The ore is bauxite."
      ],
      ans: "Bauxite.",
      why: "Bauxite is the principal ore used as the source of aluminium."
    }
  ],
  [
    {
      q: "An ore contains aluminium compounds mixed with several impurities. What is the first major processing step before aluminium can be extracted by electrolysis?",
      hint: "The aluminium compound must first be separated from the impurities.",
      steps: [
        "Step 1: The ore is bauxite.",
        "Step 2: Bauxite contains aluminium compounds and impurities.",
        "Step 3: The ore must therefore be purified.",
        "Step 4: Purification produces aluminium oxide suitable for the extraction process."
      ],
      ans: "Purify the bauxite to obtain aluminium oxide.",
      why: "Impurities must be removed before aluminium oxide is subjected to electrolysis."
    }
  ]
);

add(
  "chemistry",
  "metals",
  "Purification of Bauxite",
  `<h2>Purification of Bauxite</h2>

  <p>Bauxite contains aluminium compounds mixed with impurities. The aluminium compound must therefore be separated from the unwanted materials.</p>

  <p>The purified product is <strong>aluminium oxide, Al₂O₃</strong>, also called <strong>alumina</strong>.</p>

  <h3>Why Purification Is Necessary</h3>

  <p>Impurities can interfere with the extraction process and increase the amount of material that must be processed.</p>

  <p>Purification produces aluminium oxide that can be used in the electrolytic extraction stage.</p>

  <h3>Extraction Sequence</h3>

  <p><strong>Bauxite → Purification → Aluminium oxide → Electrolysis → Aluminium</strong></p>`,
  [
    {
      q: "What is the main product obtained when bauxite is purified for aluminium extraction?",
      steps: [
        "Step 1: Bauxite contains aluminium compounds and impurities.",
        "Step 2: The unwanted impurities are removed.",
        "Step 3: The aluminium-containing material is processed to obtain aluminium oxide."
      ],
      ans: "Aluminium oxide, Al₂O₃, also called alumina.",
      why: "Aluminium oxide is the compound used in the electrolytic extraction of aluminium."
    },
    {
      q: "Why must bauxite be purified before electrolysis?",
      steps: [
        "Step 1: Raw bauxite contains impurities.",
        "Step 2: The desired aluminium compound is aluminium oxide.",
        "Step 3: Removing impurities gives a more suitable material for the electrolytic process."
      ],
      ans: "To remove impurities and obtain aluminium oxide suitable for electrolysis.",
      why: "The extraction stage requires aluminium oxide rather than untreated ore containing unwanted materials."
    },
    {
      q: "Write the chemical formula of aluminium oxide.",
      steps: [
        "Step 1: Aluminium forms Al³⁺ ions.",
        "Step 2: Oxygen forms O²⁻ ions.",
        "Step 3: The charges must balance.",
        "Step 4: Two Al³⁺ ions give +6 and three O²⁻ ions give −6.",
        "Step 5: Therefore, the formula is Al₂O₃."
      ],
      ans: "Al₂O₃.",
      why: "Two aluminium ions and three oxide ions give an overall neutral compound."
    }
  ],
  [
    {
      q: "A sample of bauxite contains aluminium oxide and unwanted impurities. What should happen to the impurities before electrolysis?",
      hint: "Think about what purification means.",
      steps: [
        "Step 1: Identify the desired substance: aluminium oxide.",
        "Step 2: The remaining substances are impurities.",
        "Step 3: Purification removes the unwanted substances.",
        "Step 4: The aluminium oxide is then used in the extraction stage."
      ],
      ans: "The impurities should be removed, leaving purified aluminium oxide.",
      why: "Purification separates the aluminium-containing material from unwanted substances."
    }
  ]
);

add(
  "chemistry",
  "metals",
  "Electrolysis of Aluminium Oxide",
  `<h2>Electrolysis of Aluminium Oxide</h2>

  <p>Aluminium is extracted from aluminium oxide by <strong>electrolysis</strong>.</p>

  <p>Aluminium oxide has a very high melting point. In the industrial process, it is dissolved in molten <strong>cryolite</strong> to lower the operating temperature and improve the conductivity of the electrolyte.</p>

  <h3>At the Cathode</h3>

  <p>Aluminium ions move towards the negative cathode and gain electrons.</p>

  <p><strong>Al³⁺ + 3e⁻ → Al</strong></p>

  <p>Aluminium metal is therefore formed at the cathode.</p>

  <h3>At the Anode</h3>

  <p>Oxide ions move towards the positive anode and lose electrons.</p>

  <p><strong>2O²⁻ → O₂ + 4e⁻</strong></p>

  <p>The oxygen produced reacts with the carbon anodes, causing them to be gradually consumed.</p>

  <h3>Important Points</h3>

  <ul>
    <li>Aluminium ions are reduced at the cathode.</li>
    <li>Oxide ions are oxidised at the anode.</li>
    <li>Aluminium forms at the cathode.</li>
    <li>Carbon anodes are gradually consumed.</li>
  </ul>`,
  [
    {
      q: "Why is aluminium extracted by electrolysis rather than reduction with carbon?",
      steps: [
        "Step 1: Aluminium is very reactive.",
        "Step 2: Aluminium oxide is too stable to be effectively reduced by carbon.",
        "Step 3: Electrolysis supplies electrical energy to reduce aluminium ions.",
        "Step 4: Aluminium metal is therefore obtained at the cathode."
      ],
      ans: "Because aluminium is very reactive and its oxide cannot be effectively reduced by carbon, so aluminium oxide is electrolysed.",
      why: "Electrolysis provides the energy needed to reduce Al³⁺ ions to aluminium metal."
    },
    {
      q: "Write the half-equation for the formation of aluminium at the cathode.",
      steps: [
        "Step 1: Aluminium ions are Al³⁺.",
        "Step 2: The cathode is where reduction occurs.",
        "Step 3: Reduction involves gaining electrons.",
        "Step 4: Each Al³⁺ ion requires three electrons.",
        "Step 5: Therefore, Al³⁺ + 3e⁻ → Al."
      ],
      ans: "Al³⁺ + 3e⁻ → Al.",
      why: "Aluminium ions gain three electrons to become neutral aluminium atoms."
    },
    {
      q: "What happens to oxide ions at the anode during the electrolysis of aluminium oxide?",
      steps: [
        "Step 1: Oxide ions are O²⁻.",
        "Step 2: The anode is where oxidation occurs.",
        "Step 3: Oxide ions lose electrons.",
        "Step 4: The oxide ions form oxygen."
      ],
      ans: "Oxide ions are oxidised and form oxygen at the anode.",
      why: "Oxide ions lose electrons at the positive anode."
    }
  ],
  [
    {
      q: "During aluminium extraction, a student writes the cathode reaction as Al³⁺ → Al + 3e⁻. What is wrong with this equation?",
      hint: "Reduction at the cathode involves gaining electrons, not losing them.",
      steps: [
        "Step 1: The cathode is the site of reduction.",
        "Step 2: Reduction means gain of electrons.",
        "Step 3: Al³⁺ must gain three electrons.",
        "Step 4: The correct equation is Al³⁺ + 3e⁻ → Al."
      ],
      ans: "The electrons are on the wrong side. The correct half-equation is Al³⁺ + 3e⁻ → Al.",
      why: "Aluminium ions are reduced at the cathode by gaining three electrons."
    },
    {
      q: "Why do the carbon anodes used in aluminium extraction gradually become smaller?",
      hint: "Consider what happens to oxide ions at the anode.",
      steps: [
        "Step 1: Oxide ions are discharged at the anode.",
        "Step 2: Oxygen is produced.",
        "Step 3: The oxygen reacts with the carbon anode.",
        "Step 4: Carbon is converted into carbon oxides and the anode is gradually consumed."
      ],
      ans: "The oxygen produced at the anode reacts with the carbon anode, consuming the carbon.",
      why: "The carbon anodes are oxidised by the oxygen formed during electrolysis."
    }
  ]
);
add(
  "chemistry",
  "non_metals",
  "Preparation of Hydrogen",
  `<h2>Preparation of Hydrogen</h2>

  <p>Hydrogen gas can be prepared in the laboratory by reacting a suitable metal with a dilute acid.</p>

  <p>A common method uses <strong>zinc</strong> and <strong>dilute hydrochloric acid</strong>.</p>

  <p><strong>Zn + 2HCl → ZnCl₂ + H₂</strong></p>

  <h3>What Happens</h3>

  <ol>
    <li>Zinc reacts with dilute hydrochloric acid.</li>
    <li>Zinc chloride is formed.</li>
    <li>Hydrogen gas is released.</li>
  </ol>

  <p>The hydrogen can be collected and tested using a suitable test.</p>

  <h3>Important Safety Point</h3>

  <p>Hydrogen is highly flammable. It must be kept away from naked flames except when carrying out the controlled test for the gas.</p>`,
  [
    {
      q: "Name one metal that can be used to prepare hydrogen gas from a dilute acid.",
      steps: [
        "Step 1: A reactive metal can react with a dilute acid to release hydrogen.",
        "Step 2: Zinc is a suitable metal for this laboratory preparation.",
        "Step 3: Therefore, zinc can be used."
      ],
      ans: "Zinc.",
      why: "Zinc reacts with dilute acids to produce hydrogen gas."
    },
    {
      q: "Write the balanced equation for the reaction between zinc and dilute hydrochloric acid.",
      steps: [
        "Step 1: Write the reactants: Zn + HCl.",
        "Step 2: The products are zinc chloride and hydrogen: ZnCl₂ + H₂.",
        "Step 3: Zinc is already balanced.",
        "Step 4: ZnCl₂ requires two chlorine atoms, so use 2HCl.",
        "Step 5: The two hydrogen atoms then form H₂."
      ],
      ans: "Zn + 2HCl → ZnCl₂ + H₂.",
      why: "The equation has equal numbers of zinc, hydrogen and chlorine atoms on both sides."
    },
    {
      q: "What gas is produced when zinc reacts with dilute hydrochloric acid?",
      steps: [
        "Step 1: Zinc reacts with dilute hydrochloric acid.",
        "Step 2: The products include zinc chloride and a gas.",
        "Step 3: The gas is hydrogen."
      ],
      ans: "Hydrogen gas.",
      why: "The hydrogen ions from the acid are reduced to hydrogen gas."
    }
  ],
  [
    {
      q: "A student wants to prepare hydrogen using zinc and hydrochloric acid. Why should the acid be dilute rather than concentrated?",
      hint: "Think about controlling the reaction and the safety of handling hydrogen.",
      steps: [
        "Step 1: The reaction produces flammable hydrogen gas.",
        "Step 2: A controlled reaction is preferred in laboratory preparation.",
        "Step 3: Dilute acid provides a suitable reaction rate and safer conditions than using a highly concentrated acid."
      ],
      ans: "Dilute acid allows the hydrogen-producing reaction to be carried out under more controlled and safer conditions.",
      why: "Laboratory gas preparation should be controlled, particularly because hydrogen is highly flammable."
    }
  ]
);

add(
  "chemistry",
  "non_metals",
  "Properties of Hydrogen",
  `<h2>Properties of Hydrogen</h2>

  <p>Hydrogen is a non-metal and the lightest element.</p>

  <h3>Physical Properties</h3>

  <ul>
    <li>It is a colourless gas.</li>
    <li>It is odourless.</li>
    <li>It is very light.</li>
    <li>It is only slightly soluble in water.</li>
  </ul>

  <h3>Chemical Properties</h3>

  <p>Hydrogen is <strong>flammable</strong> and burns in oxygen to form water.</p>

  <p><strong>2H₂ + O₂ → 2H₂O</strong></p>

  <p>Hydrogen can also act as a reducing agent in some reactions because it can remove oxygen from certain metal oxides.</p>

  <p>For example:</p>

  <p><strong>CuO + H₂ → Cu + H₂O</strong></p>`,
  [
    {
      q: "State three physical properties of hydrogen gas.",
      steps: [
        "Step 1: Identify its appearance.",
        "Step 2: Identify its smell.",
        "Step 3: Consider its density and solubility."
      ],
      ans: "Hydrogen is colourless, odourless, very light and only slightly soluble in water.",
      why: "These are characteristic physical properties of hydrogen gas."
    },
    {
      q: "Write the balanced equation for the combustion of hydrogen in oxygen.",
      steps: [
        "Step 1: Write H₂ + O₂ → H₂O.",
        "Step 2: Balance hydrogen by placing 2 before H₂O.",
        "Step 3: There are now two oxygen atoms on the product side.",
        "Step 4: Place 2 before H₂.",
        "Step 5: The balanced equation is 2H₂ + O₂ → 2H₂O."
      ],
      ans: "2H₂ + O₂ → 2H₂O.",
      why: "Hydrogen reacts with oxygen to form water, and the equation is balanced with two hydrogen molecules and one oxygen molecule."
    },
    {
      q: "What happens when hydrogen is passed over heated copper(II) oxide?",
      steps: [
        "Step 1: Hydrogen reacts with copper(II) oxide.",
        "Step 2: Hydrogen removes oxygen from the copper(II) oxide.",
        "Step 3: Copper is produced.",
        "Step 4: Water is also formed."
      ],
      ans: "Copper and water are formed.",
      why: "Hydrogen acts as a reducing agent and removes oxygen from copper(II) oxide."
    }
  ],
  [
    {
      q: "A gas is colourless, odourless and highly flammable. Why can these observations alone not prove that the gas is hydrogen?",
      hint: "Think about identification versus general properties.",
      steps: [
        "Step 1: Several gases can be colourless and odourless.",
        "Step 2: A property shared by several gases cannot uniquely identify one gas.",
        "Step 3: Hydrogen therefore requires a specific chemical test."
      ],
      ans: "Because those properties are not unique to hydrogen; a specific test is needed to identify it.",
      why: "Identification of a gas should use a characteristic test rather than relying only on general physical properties."
    }
  ]
);

add(
  "chemistry",
  "non_metals",
  "Test for Hydrogen",
  `<h2>Test for Hydrogen</h2>

  <p>Hydrogen can be identified using a <strong>lighted splint test</strong>.</p>

  <h3>Procedure</h3>

  <ol>
    <li>Collect a small sample of the gas.</li>
    <li>Bring a lighted splint to the gas.</li>
    <li>Observe the sound and reaction.</li>
  </ol>

  <p>Hydrogen burns rapidly and produces a characteristic <strong>squeaky pop</strong>.</p>

  <p>The reaction is:</p>

  <p><strong>2H₂ + O₂ → 2H₂O</strong></p>

  <h3>Safety</h3>

  <p>Only a small sample should be tested under controlled laboratory conditions because hydrogen is highly flammable.</p>`,
  [
    {
      q: "What test is used to identify hydrogen gas?",
      steps: [
        "Step 1: Collect a small sample of the gas.",
        "Step 2: Bring a lighted splint to the sample.",
        "Step 3: Observe the reaction.",
        "Step 4: Hydrogen produces a characteristic squeaky pop."
      ],
      ans: "A lighted splint test; hydrogen produces a squeaky pop.",
      why: "The rapid combustion of hydrogen in oxygen produces the characteristic pop."
    },
    {
      q: "What causes the squeaky pop when hydrogen is tested?",
      steps: [
        "Step 1: Hydrogen is brought into contact with oxygen.",
        "Step 2: The hydrogen burns rapidly.",
        "Step 3: Water is formed.",
        "Step 4: The rapid combustion produces the characteristic sound."
      ],
      ans: "Rapid combustion of hydrogen with oxygen produces the squeaky pop.",
      why: "Hydrogen reacts rapidly with oxygen when ignited."
    },
    {
      q: "Write the balanced equation for the reaction responsible for the hydrogen test.",
      steps: [
        "Step 1: Hydrogen reacts with oxygen to form water.",
        "Step 2: Write H₂ + O₂ → H₂O.",
        "Step 3: Balance hydrogen using 2H₂ and 2H₂O.",
        "Step 4: One O₂ molecule then balances the oxygen atoms."
      ],
      ans: "2H₂ + O₂ → 2H₂O.",
      why: "The equation represents the combustion of hydrogen during the test."
    }
  ],
  [
    {
      q: "A gas gives no characteristic pop when a lighted splint is applied. Can it be identified as hydrogen?",
      hint: "Recall the positive observation for the hydrogen test.",
      steps: [
        "Step 1: Hydrogen should produce a characteristic squeaky pop.",
        "Step 2: The gas did not produce this observation.",
        "Step 3: Therefore, the test does not identify the gas as hydrogen."
      ],
      ans: "No. The absence of the characteristic squeaky pop means the test does not identify the gas as hydrogen.",
      why: "A positive hydrogen test requires the characteristic pop."
    }
  ]
);

add(
  "chemistry",
  "non_metals",
  "Uses of Hydrogen",
  `<h2>Uses of Hydrogen</h2>

  <p>Hydrogen has several important uses because of its chemical properties and its ability to release energy during combustion.</p>

  <h3>Major Uses</h3>

  <ul>
    <li><strong>Manufacture of ammonia:</strong> Hydrogen reacts with nitrogen in the Haber process.</li>
    <li><strong>Hydrogenation:</strong> Hydrogen is used to add hydrogen to unsaturated compounds in some industrial processes.</li>
    <li><strong>Fuel:</strong> Hydrogen can be used as a fuel because it releases energy when it reacts with oxygen.</li>
    <li><strong>Reduction:</strong> Hydrogen can reduce some metal oxides to metals.</li>
  </ul>

  <h3>Hydrogen in the Haber Process</h3>

  <p>Hydrogen reacts with nitrogen to produce ammonia:</p>

  <p><strong>N₂ + 3H₂ ⇌ 2NH₃</strong></p>

  <p>Ammonia is important in the manufacture of fertilisers and other chemicals.</p>`,
  [
    {
      q: "State two uses of hydrogen.",
      steps: [
        "Step 1: Hydrogen is used in industrial chemical reactions.",
        "Step 2: It is used to manufacture ammonia.",
        "Step 3: It can also be used as a fuel or reducing agent."
      ],
      ans: "Hydrogen is used in the manufacture of ammonia, as a fuel, in hydrogenation and as a reducing agent.",
      why: "Hydrogen's chemical properties make it useful in several industrial processes."
    },
    {
      q: "How is hydrogen used in the Haber process?",
      steps: [
        "Step 1: Nitrogen reacts with hydrogen.",
        "Step 2: The reaction is reversible.",
        "Step 3: Ammonia is formed.",
        "Step 4: The balanced equation is N₂ + 3H₂ ⇌ 2NH₃."
      ],
      ans: "Hydrogen reacts with nitrogen to produce ammonia.",
      why: "Hydrogen is one of the reactants required for industrial ammonia manufacture."
    },
    {
      q: "Why can hydrogen be used as a fuel?",
      steps: [
        "Step 1: Hydrogen is combustible.",
        "Step 2: It reacts with oxygen.",
        "Step 3: The reaction releases energy.",
        "Step 4: The main product is water."
      ],
      ans: "Because hydrogen reacts with oxygen and releases energy during combustion.",
      why: "The energy released during hydrogen combustion can be harnessed for useful purposes."
    }
  ],
  [
    {
      q: "Hydrogen is used to reduce copper(II) oxide. What two products are formed?",
      hint: "Hydrogen removes oxygen from the metal oxide.",
      steps: [
        "Step 1: Hydrogen reacts with copper(II) oxide.",
        "Step 2: Hydrogen removes oxygen from CuO.",
        "Step 3: The remaining metal is copper.",
        "Step 4: The removed oxygen combines with hydrogen to form water."
      ],
      ans: "Copper and water.",
      why: "Hydrogen reduces copper(II) oxide to copper while forming water."
    }
  ]
);
add(
  "chemistry",
  "organic_chemistry",
  "Addition Reactions",
  `<h2>Addition Reactions</h2>

  <p>Alkenes undergo addition reactions because they contain a carbon-carbon double bond.</p>

  <p>In an addition reaction, atoms or groups of atoms are added across the double bond, converting the alkene into a saturated compound.</p>

  <h3>Hydrogenation</h3>

  <p>Hydrogen can add across the double bond of an alkene in the presence of a nickel catalyst and heat.</p>

  <p><strong>Ethene + Hydrogen → Ethane</strong></p>

  <p>C₂H₄ + H₂ → C₂H₆</p>

  <p>The C=C double bond becomes a C-C single bond.</p>

  <h3>Addition of Bromine</h3>

  <p>Bromine also adds across the double bond.</p>

  <p><strong>Ethene + Bromine → 1,2-dibromoethane</strong></p>

  <p>C₂H₄ + Br₂ → C₂H₄Br₂</p>

  <p>This reaction is important because it provides a test for unsaturation.</p>`,
  [
    {
      q: "What happens to the carbon-carbon double bond when hydrogen is added to ethene?",
      steps: [
        "Step 1: Ethene contains a C=C double bond.",
        "Step 2: Hydrogen adds across the double bond.",
        "Step 3: The C=C double bond becomes a C-C single bond.",
        "Step 4: Ethene is converted into ethane."
      ],
      ans: "The C=C double bond becomes a C-C single bond and ethene is converted into ethane.",
      why: "Hydrogenation is an addition reaction in which hydrogen atoms add across the carbon-carbon double bond."
    },
    {
      q: "Write the balanced equation for the reaction between ethene and hydrogen.",
      steps: [
        "Step 1: Write the formula of ethene: C₂H₄.",
        "Step 2: Write the formula of hydrogen: H₂.",
        "Step 3: Addition across the double bond produces ethane, C₂H₆.",
        "Step 4: Check the atoms: 2 carbon atoms and 6 hydrogen atoms occur on both sides."
      ],
      ans: "C₂H₄ + H₂ → C₂H₆",
      why: "One molecule of hydrogen adds across the double bond of one molecule of ethene."
    },
    {
      q: "What product is formed when ethene reacts with bromine?",
      steps: [
        "Step 1: Ethene contains a C=C double bond.",
        "Step 2: Bromine adds across the double bond.",
        "Step 3: The product formed is 1,2-dibromoethane."
      ],
      ans: "1,2-dibromoethane, C₂H₄Br₂.",
      why: "Bromine undergoes an addition reaction with the carbon-carbon double bond."
    }
  ],
  [
    {
      q: "An alkene reacts with hydrogen in the presence of nickel and heat. What type of reaction has occurred?",
      hint: "Think about what happens when atoms are added across a double bond.",
      steps: [
        "Step 1: The reactant is an alkene containing a C=C bond.",
        "Step 2: Hydrogen is added across the double bond.",
        "Step 3: The double bond becomes a single bond.",
        "Step 4: Therefore, the reaction is an addition reaction."
      ],
      ans: "An addition reaction.",
      why: "Hydrogen is added across the carbon-carbon double bond of the alkene."
    },
    {
      q: "Complete the equation: C₂H₄ + Br₂ → ?",
      hint: "Bromine adds across the double bond of ethene.",
      steps: [
        "Step 1: Start with ethene, C₂H₄.",
        "Step 2: Add Br₂ across the C=C double bond.",
        "Step 3: The product contains two bromine atoms.",
        "Step 4: The product is C₂H₄Br₂."
      ],
      ans: "C₂H₄Br₂.",
      why: "Bromine adds across the double bond to form 1,2-dibromoethane."
    }
  ]
);
add(
  "chemistry",
  "organic_chemistry",
  "Ester Formation",
  `<h2>Ester Formation</h2>

  <p>Esters are organic compounds formed when an alcohol reacts with a carboxylic acid.</p>

  <p>The reaction is called <strong>esterification</strong>.</p>

  <p>A carboxylic acid reacts with an alcohol in the presence of a concentrated acid catalyst, commonly concentrated sulfuric acid, and on heating.</p>

  <p><strong>Ethanoic acid + Ethanol ⇌ Ethyl ethanoate + Water</strong></p>

  <p>CH₃COOH + C₂H₅OH ⇌ CH₃COOC₂H₅ + H₂O</p>

  <p>Esterification is a reversible reaction, so an equilibrium is established between the reactants and products.</p>`,
  [
    {
      q: "What type of reaction forms an ester from an alcohol and a carboxylic acid?",
      steps: [
        "Step 1: An alcohol is reacted with a carboxylic acid.",
        "Step 2: The reaction produces an ester and water.",
        "Step 3: This reaction is called esterification."
      ],
      ans: "Esterification.",
      why: "Esterification is the reaction between an alcohol and a carboxylic acid to form an ester and water."
    },
    {
      q: "Write the equation for the reaction between ethanol and ethanoic acid.",
      steps: [
        "Step 1: Write ethanol as C₂H₅OH.",
        "Step 2: Write ethanoic acid as CH₃COOH.",
        "Step 3: The ester formed is ethyl ethanoate, CH₃COOC₂H₅.",
        "Step 4: Water is also produced.",
        "Step 5: Use a reversible arrow because esterification is reversible."
      ],
      ans: "CH₃COOH + C₂H₅OH ⇌ CH₃COOC₂H₅ + H₂O",
      why: "Ethanoic acid reacts with ethanol to form ethyl ethanoate and water."
    },
    {
      q: "What catalyst is commonly used during esterification?",
      steps: [
        "Step 1: Esterification is normally carried out with an acid catalyst.",
        "Step 2: Concentrated sulfuric acid provides the required acidic conditions.",
        "Step 3: Therefore, concentrated sulfuric acid is commonly used."
      ],
      ans: "Concentrated sulfuric acid.",
      why: "Concentrated sulfuric acid acts as an acid catalyst in esterification."
    }
  ],
  [
    {
      q: "Ethanol reacts with propanoic acid. What type of compound is produced together with water?",
      hint: "An alcohol reacting with a carboxylic acid forms an ester.",
      steps: [
        "Step 1: Ethanol is an alcohol.",
        "Step 2: Propanoic acid is a carboxylic acid.",
        "Step 3: Alcohol + carboxylic acid produces an ester and water."
      ],
      ans: "An ester.",
      why: "Esterification produces an ester and water."
    },
    {
      q: "Why is a reversible arrow used in the equation for esterification?",
      hint: "Consider whether the products can react to reform the reactants.",
      steps: [
        "Step 1: Esterification produces an ester and water.",
        "Step 2: The products can react under suitable conditions to form the original reactants.",
        "Step 3: Therefore, the reaction is reversible."
      ],
      ans: "Because esterification is a reversible reaction.",
      why: "The ester and water can react to reform the alcohol and carboxylic acid."
    }
  ]
);
add(
  "chemistry",
  "organic_chemistry",
  "Addition Polymerisation",
  `<h2>Addition Polymerisation</h2>

  <p>Addition polymerisation is a reaction in which many small alkene molecules join together to form a large molecule called a polymer.</p>

  <p>The small molecules that join together are called <strong>monomers</strong>.</p>

  <p>During addition polymerisation, the carbon-carbon double bond in each alkene monomer opens and the monomers join to form a long chain.</p>

  <h3>Example: Ethene</h3>

  <p>Ethene molecules can join together to form poly(ethene).</p>

  <p><strong>nCH₂=CH₂ → [−CH₂−CH₂−]ₙ</strong></p>

  <p>Ethene is the monomer and poly(ethene) is the polymer.</p>

  <p>No small molecule such as water is eliminated during addition polymerisation.</p>`,
  [
    {
      q: "What is a monomer?",
      steps: [
        "Step 1: A polymer is a large molecule made from repeating smaller units.",
        "Step 2: The small molecules that join together are called monomers.",
        "Step 3: Therefore, a monomer is a small molecule that can join with other molecules to form a polymer."
      ],
      ans: "A monomer is a small molecule that joins with other molecules to form a polymer.",
      why: "Polymers are formed from repeating monomer units."
    },
    {
      q: "What monomer is used to make poly(ethene)?",
      steps: [
        "Step 1: Identify the repeating unit in poly(ethene): −CH₂−CH₂−.",
        "Step 2: This repeating unit comes from ethene.",
        "Step 3: Ethene contains the C=C double bond needed for addition polymerisation."
      ],
      ans: "Ethene, CH₂=CH₂.",
      why: "Ethene molecules undergo addition polymerisation to form poly(ethene)."
    },
    {
      q: "What happens to the double bond in an alkene during addition polymerisation?",
      steps: [
        "Step 1: The alkene monomer contains a C=C double bond.",
        "Step 2: The double bond opens during polymerisation.",
        "Step 3: The carbon atoms form new single bonds with neighbouring monomers.",
        "Step 4: A long polymer chain is produced."
      ],
      ans: "The C=C double bond opens and the monomers join through new C-C single bonds.",
      why: "Opening the double bond allows the alkene molecules to link into a long chain."
    }
  ],
  [
    {
      q: "Ethene is polymerised. What polymer is formed?",
      hint: "The polymer name is based on the monomer ethene.",
      steps: [
        "Step 1: The monomer is ethene.",
        "Step 2: Ethene undergoes addition polymerisation.",
        "Step 3: The polymer formed is poly(ethene)."
      ],
      ans: "Poly(ethene).",
      why: "Ethene molecules join together by addition polymerisation to form poly(ethene)."
    },
    {
      q: "Does addition polymerisation produce a small molecule such as water as a by-product?",
      hint: "Compare addition polymerisation with condensation polymerisation.",
      steps: [
        "Step 1: In addition polymerisation, alkene monomers join directly.",
        "Step 2: No small molecule is removed.",
        "Step 3: Therefore, water is not produced as a by-product."
      ],
      ans: "No. No small molecule is eliminated.",
      why: "Addition polymerisation joins the monomers without eliminating a small molecule."
    }
  ]
);
add(
  "chemistry",
  "organic_chemistry",
  "Crude Oil",
  `<h2>Crude Oil</h2>

  <p>Crude oil is a naturally occurring mixture of hydrocarbons found beneath the Earth's surface.</p>

  <p>It is formed from the remains of living organisms that were buried and subjected to heat and pressure over millions of years.</p>

  <p>Crude oil contains many different hydrocarbons with different molecular sizes and boiling points.</p>

  <h3>Why Crude Oil Is Separated</h3>

  <p>The different hydrocarbons in crude oil have different uses. They must therefore be separated into groups called <strong>fractions</strong>.</p>

  <p>The separation is carried out mainly by <strong>fractional distillation</strong>.</p>

  <h3>Important Point</h3>

  <p>Crude oil is a mixture, not a single compound. The hydrocarbons are separated physically according to differences in their boiling points.</p>`,
  [
    {
      q: "What is crude oil?",
      steps: [
        "Step 1: Crude oil occurs naturally beneath the Earth's surface.",
        "Step 2: It contains many different hydrocarbons.",
        "Step 3: Therefore, crude oil is a mixture of hydrocarbons."
      ],
      ans: "Crude oil is a naturally occurring mixture of hydrocarbons.",
      why: "Crude oil contains many different hydrocarbon molecules rather than one pure compound."
    },
    {
      q: "Why is crude oil described as a mixture?",
      steps: [
        "Step 1: A mixture contains two or more substances that are not chemically combined.",
        "Step 2: Crude oil contains many different hydrocarbons.",
        "Step 3: These hydrocarbons can be separated physically.",
        "Step 4: Therefore, crude oil is a mixture."
      ],
      ans: "Because it contains many different hydrocarbons that can be physically separated.",
      why: "The different hydrocarbons retain their individual properties and can be separated by fractional distillation."
    },
    {
      q: "Why is crude oil separated into fractions?",
      steps: [
        "Step 1: Crude oil contains many hydrocarbons.",
        "Step 2: Different hydrocarbons have different properties and uses.",
        "Step 3: Separating them produces groups of hydrocarbons with useful ranges of boiling points.",
        "Step 4: These groups are called fractions."
      ],
      ans: "It is separated so that useful groups of hydrocarbons with different boiling-point ranges can be obtained.",
      why: "Different fractions have different properties and therefore different applications."
    }
  ],
  [
    {
      q: "Is crude oil an element, compound or mixture?",
      hint: "Crude oil contains many different hydrocarbons.",
      steps: [
        "Step 1: An element contains one type of atom.",
        "Step 2: A compound contains chemically combined elements in fixed proportions.",
        "Step 3: Crude oil contains many different hydrocarbons.",
        "Step 4: Therefore, crude oil is a mixture."
      ],
      ans: "A mixture.",
      why: "Crude oil contains many different hydrocarbons."
    },
    {
      q: "What type of substances make up crude oil?",
      hint: "Think about the substances discussed in Organic Chemistry.",
      steps: [
        "Step 1: Crude oil contains compounds made only of carbon and hydrogen.",
        "Step 2: Such compounds are called hydrocarbons."
      ],
      ans: "Hydrocarbons.",
      why: "Crude oil consists mainly of hydrocarbons."
    }
  ]
);
add(
  "chemistry",
  "organic_chemistry",
  "Cracking",
  `<h2>Cracking</h2>

  <p>Cracking is the process of breaking down large, long-chain hydrocarbon molecules into smaller, more useful hydrocarbons.</p>

  <p>Large hydrocarbons from heavy crude-oil fractions can be cracked to produce smaller hydrocarbons.</p>

  <p>Cracking usually produces a mixture containing <strong>alkanes and alkenes</strong>.</p>

  <h3>Why Cracking Is Needed</h3>

  <p>There is often greater demand for smaller hydrocarbons such as petrol-range hydrocarbons and alkenes than for some heavier fractions.</p>

  <p>Cracking therefore converts less useful large hydrocarbons into more useful smaller molecules.</p>

  <h3>Example</h3>

  <p>Decane can be cracked to produce octane and ethene:</p>

  <p><strong>C₁₀H₂₂ → C₈H₁₈ + C₂H₄</strong></p>

  <p>The equation is balanced because there are 10 carbon atoms and 22 hydrogen atoms on both sides.</p>

  <h3>Conditions</h3>

  <p>Cracking requires high temperatures. A catalyst such as an aluminium oxide or zeolite catalyst may be used in catalytic cracking.</p>`,
  [
    {
      q: "What is cracking?",
      steps: [
        "Step 1: Large hydrocarbons are heated under suitable conditions.",
        "Step 2: Their long carbon chains are broken into smaller molecules.",
        "Step 3: The smaller products are more useful hydrocarbons."
      ],
      ans: "Cracking is the breaking down of large hydrocarbon molecules into smaller, more useful hydrocarbons.",
      why: "Cracking converts heavy, long-chain hydrocarbons into smaller molecules such as alkanes and alkenes."
    },
    {
      q: "What two types of hydrocarbons are commonly produced during cracking?",
      steps: [
        "Step 1: Cracking breaks large hydrocarbon molecules into smaller molecules.",
        "Step 2: The products commonly include saturated and unsaturated hydrocarbons.",
        "Step 3: Saturated hydrocarbons are alkanes and unsaturated hydrocarbons include alkenes."
      ],
      ans: "Alkanes and alkenes.",
      why: "Cracking commonly produces smaller alkanes together with alkenes."
    },
    {
      q: "Balance the cracking equation: C₁₀H₂₂ → C₈H₁₈ + C₂H₄.",
      steps: [
        "Step 1: Count carbon atoms on the right: 8 + 2 = 10.",
        "Step 2: Count hydrogen atoms on the right: 18 + 4 = 22.",
        "Step 3: The number of carbon and hydrogen atoms is already equal on both sides."
      ],
      ans: "C₁₀H₂₂ → C₈H₁₈ + C₂H₄",
      why: "The equation is already balanced with 10 carbon atoms and 22 hydrogen atoms on each side."
    }
  ],
  [
    {
      q: "Why is cracking carried out on some heavy fractions of crude oil?",
      hint: "Think about the demand for smaller hydrocarbons.",
      steps: [
        "Step 1: Heavy fractions contain large hydrocarbon molecules.",
        "Step 2: Some smaller hydrocarbons are in greater demand.",
        "Step 3: Cracking converts large molecules into smaller, more useful hydrocarbons."
      ],
      ans: "To convert large, less useful hydrocarbons into smaller, more useful hydrocarbons that are in greater demand.",
      why: "Cracking increases the supply of useful smaller hydrocarbons."
    },
    {
      q: "A large alkane is cracked and one of the products is ethene. Is ethene an alkane or an alkene?",
      hint: "Look at ethene's carbon-carbon bonding.",
      steps: [
        "Step 1: Ethene has the formula C₂H₄.",
        "Step 2: It contains a carbon-carbon double bond.",
        "Step 3: Hydrocarbons containing a C=C double bond are alkenes."
      ],
      ans: "Ethene is an alkene.",
      why: "Ethene contains a carbon-carbon double bond and therefore belongs to the alkene homologous series."
    }
  ]
);
add(
  "chemistry",
  "metals",
  "Chemical Properties of Metals",
  `<h2>Chemical Properties of Metals</h2>

  <p>Metals undergo chemical reactions with substances such as oxygen, water and acids. Their reactions depend on the position of the metal in the reactivity series.</p>

  <h3>Reaction with Oxygen</h3>

  <p>Many metals react with oxygen to form metal oxides.</p>

  <p><strong>2Mg + O₂ → 2MgO</strong></p>

  <p>Magnesium reacts with oxygen to form magnesium oxide.</p>

  <h3>Reaction with Water</h3>

  <p>Some metals react with water to form a metal hydroxide and hydrogen gas.</p>

  <p>For example:</p>

  <p><strong>2Na + 2H₂O → 2NaOH + H₂</strong></p>

  <p>More reactive metals generally react more readily with water.</p>

  <h3>Reaction with Dilute Acids</h3>

  <p>Metals above hydrogen in the reactivity series can react with dilute acids to produce a salt and hydrogen gas.</p>

  <p>For example:</p>

  <p><strong>Zn + 2HCl → ZnCl₂ + H₂</strong></p>

  <h3>Key Idea</h3>

  <p>The ease with which a metal reacts depends on its reactivity. A more reactive metal loses electrons more readily than a less reactive metal.</p>`,
  [
    {
      q: "What is formed when magnesium reacts with oxygen?",
      steps: [
        "Step 1: Magnesium reacts with oxygen.",
        "Step 2: Metals commonly form oxides when they react with oxygen.",
        "Step 3: Therefore, magnesium oxide is formed.",
        "Step 4: The balanced equation is 2Mg + O₂ → 2MgO."
      ],
      ans: "Magnesium oxide, MgO.",
      why: "Magnesium combines with oxygen to form the metal oxide magnesium oxide."
    },
    {
      q: "What products are formed when sodium reacts with water?",
      steps: [
        "Step 1: Sodium is a very reactive metal.",
        "Step 2: Sodium reacts with water.",
        "Step 3: The products are sodium hydroxide and hydrogen gas.",
        "Step 4: The balanced equation is 2Na + 2H₂O → 2NaOH + H₂."
      ],
      ans: "Sodium hydroxide and hydrogen gas.",
      why: "Reactive metals such as sodium react with water to form a metal hydroxide and hydrogen."
    },
    {
      q: "What products are formed when zinc reacts with dilute hydrochloric acid?",
      steps: [
        "Step 1: Zinc is above hydrogen in the reactivity series.",
        "Step 2: Zinc can therefore displace hydrogen from dilute hydrochloric acid.",
        "Step 3: Zinc chloride is formed as the salt.",
        "Step 4: Hydrogen gas is released.",
        "Step 5: The balanced equation is Zn + 2HCl → ZnCl₂ + H₂."
      ],
      ans: "Zinc chloride and hydrogen gas.",
      why: "Zinc reacts with dilute hydrochloric acid to form zinc chloride and hydrogen."
    }
  ],
  [
    {
      q: "A metal reacts vigorously with water and produces hydrogen gas. What does this suggest about its reactivity?",
      hint: "Compare its behaviour with metals that react slowly or not at all with water.",
      steps: [
        "Step 1: The metal reacts readily with water.",
        "Step 2: Vigorous reaction indicates that the metal readily undergoes chemical change.",
        "Step 3: Therefore, the metal is relatively reactive."
      ],
      ans: "It is a relatively reactive metal.",
      why: "A vigorous reaction with water indicates high chemical reactivity."
    },
    {
      q: "A metal reacts with dilute hydrochloric acid and produces hydrogen gas. What does this tell you about its position relative to hydrogen in the reactivity series?",
      hint: "A metal must be able to displace hydrogen from the acid.",
      steps: [
        "Step 1: The metal reacts with hydrochloric acid and releases hydrogen.",
        "Step 2: This means the metal displaces hydrogen from the acid.",
        "Step 3: Metals that displace hydrogen are above hydrogen in the reactivity series."
      ],
      ans: "The metal is above hydrogen in the reactivity series.",
      why: "Only metals more reactive than hydrogen can generally displace hydrogen from dilute acids."
    }
  ]
);
add(
  "chemistry",
  "metals",
  "Concentration of Ores",
  `<h2>Concentration of Ores</h2>

  <p>An ore contains a useful mineral together with unwanted materials called <strong>gangue</strong>.</p>

  <p>Before the metal is extracted, the ore is usually concentrated to increase the proportion of the useful mineral.</p>

  <p><strong>Concentration of an ore</strong> is the process of removing unwanted gangue from the ore.</p>

  <h3>Why Ores Are Concentrated</h3>

  <p>Concentrating the ore reduces the amount of unwanted material that must be processed during extraction.</p>

  <p>This makes the subsequent extraction process more efficient.</p>

  <h3>Methods</h3>

  <p>The method used depends on the physical and chemical properties of the ore and the gangue.</p>

  <p>Examples include:</p>

  <ul>
    <li>gravity separation;</li>
    <li>magnetic separation;</li>
    <li>froth flotation.</li>
  </ul>

  <p>For example, magnetic separation can be used when the desired mineral has magnetic properties that differ from the gangue.</p>`,
  [
    {
      q: "What is an ore?",
      steps: [
        "Step 1: An ore contains a naturally occurring mineral from which a metal can be obtained.",
        "Step 2: The useful mineral occurs together with unwanted materials.",
        "Step 3: Therefore, an ore is a naturally occurring material from which a metal can be extracted economically."
      ],
      ans: "An ore is a naturally occurring material containing a useful mineral from which a metal can be extracted economically.",
      why: "Ores contain minerals from which metals can be obtained."
    },
    {
      q: "What is gangue?",
      steps: [
        "Step 1: An ore contains the useful mineral together with unwanted materials.",
        "Step 2: These unwanted earthy or rocky materials are called gangue."
      ],
      ans: "Gangue is the unwanted earthy or rocky material associated with the useful mineral in an ore.",
      why: "Gangue has no useful value in the extraction of the desired metal and is removed during ore processing."
    },
    {
      q: "Why is an ore concentrated before the metal is extracted?",
      steps: [
        "Step 1: An ore contains useful mineral and unwanted gangue.",
        "Step 2: Concentration removes some of the gangue.",
        "Step 3: This increases the proportion of useful mineral.",
        "Step 4: Less unwanted material then has to be processed during extraction."
      ],
      ans: "To remove unwanted gangue and increase the proportion of the useful mineral before extraction.",
      why: "Concentration makes the subsequent extraction process more efficient."
    }
  ],
  [
    {
      q: "An ore contains a magnetic mineral mixed with non-magnetic gangue. Which separation method could be used?",
      hint: "Think about a method that separates substances according to magnetic properties.",
      steps: [
        "Step 1: The useful mineral is magnetic.",
        "Step 2: The gangue is non-magnetic.",
        "Step 3: A magnetic field can attract the magnetic material while leaving the non-magnetic material behind.",
        "Step 4: Therefore, magnetic separation can be used."
      ],
      ans: "Magnetic separation.",
      why: "Magnetic separation works when the useful mineral and gangue have different magnetic properties."
    },
    {
      q: "What happens to the proportion of useful mineral when gangue is removed from an ore?",
      hint: "Compare the amount of useful mineral with the total mass of the ore.",
      steps: [
        "Step 1: Gangue is unwanted material.",
        "Step 2: Removing gangue decreases the amount of unwanted material.",
        "Step 3: The useful mineral therefore makes up a greater proportion of the remaining material."
      ],
      ans: "The proportion of useful mineral increases.",
      why: "Removing gangue concentrates the useful mineral in the remaining material."
    }
  ]
);
add(
  "chemistry",
  "metals",
  "Extraction by Reduction",
  `<h2>Extraction by Reduction</h2>

  <p>Some metals are extracted from their ores by reducing their metal oxides.</p>

  <p><strong>Reduction</strong> is the removal of oxygen from a metal oxide, or the gain of electrons by the metal ion.</p>

  <h3>Reduction Using Carbon</h3>

  <p>Metals that are less reactive than carbon can often be extracted by heating their oxides with carbon.</p>

  <p>For example, zinc oxide can be reduced by carbon:</p>

  <p><strong>ZnO + C → Zn + CO</strong></p>

  <p>The carbon removes oxygen from zinc oxide, leaving zinc metal.</p>

  <h3>Reduction Using Carbon Monoxide</h3>

  <p>Carbon monoxide can also act as a reducing agent.</p>

  <p>For example:</p>

  <p><strong>Fe₂O₃ + 3CO → 2Fe + 3CO₂</strong></p>

  <p>Iron(III) oxide is reduced to iron while carbon monoxide is oxidised to carbon dioxide.</p>

  <h3>Choosing the Method</h3>

  <p>The extraction method depends on the reactivity of the metal.</p>

  <p>Very reactive metals, such as aluminium, cannot generally be extracted by carbon reduction and require electrolysis.</p>`,
  [
    {
      q: "What is reduction in the extraction of a metal from its oxide?",
      steps: [
        "Step 1: A metal oxide contains the metal chemically combined with oxygen.",
        "Step 2: During reduction, oxygen is removed from the oxide.",
        "Step 3: The metal is therefore obtained from its oxide."
      ],
      ans: "Reduction is the removal of oxygen from a metal oxide.",
      why: "Removing oxygen from a metal oxide produces the metal."
    },
    {
      q: "How can zinc be extracted from zinc oxide using carbon?",
      steps: [
        "Step 1: Zinc oxide is ZnO.",
        "Step 2: Carbon acts as the reducing agent.",
        "Step 3: Carbon removes oxygen from zinc oxide.",
        "Step 4: Zinc metal is produced.",
        "Step 5: The balanced equation is ZnO + C → Zn + CO."
      ],
      ans: "ZnO + C → Zn + CO",
      why: "Carbon removes oxygen from zinc oxide, reducing ZnO to zinc."
    },
    {
      q: "What happens to carbon monoxide when it reduces iron(III) oxide?",
      steps: [
        "Step 1: Carbon monoxide reacts with iron(III) oxide.",
        "Step 2: It removes oxygen from the iron oxide.",
        "Step 3: Carbon monoxide gains oxygen.",
        "Step 4: It is converted into carbon dioxide."
      ],
      ans: "Carbon monoxide is oxidised to carbon dioxide.",
      why: "CO removes oxygen from iron(III) oxide and therefore becomes CO₂."
    }
  ],
  [
    {
      q: "A metal oxide reacts with carbon and produces the metal. What role does carbon play?",
      hint: "Carbon removes oxygen from the metal oxide.",
      steps: [
        "Step 1: Carbon removes oxygen from the metal oxide.",
        "Step 2: Removing oxygen from an oxide is reduction.",
        "Step 3: Therefore, carbon acts as the reducing agent."
      ],
      ans: "Carbon acts as the reducing agent.",
      why: "The reducing agent removes oxygen from the metal oxide."
    },
    {
      q: "Why is aluminium not normally extracted by heating aluminium oxide with carbon?",
      hint: "Compare aluminium's position with carbon in the reactivity series.",
      steps: [
        "Step 1: Aluminium is more reactive than carbon.",
        "Step 2: Carbon cannot readily remove oxygen from aluminium oxide.",
        "Step 3: Therefore, carbon reduction is not suitable for extracting aluminium.",
        "Step 4: Aluminium oxide is instead extracted by electrolysis."
      ],
      ans: "Because aluminium is more reactive than carbon, carbon cannot effectively reduce aluminium oxide.",
      why: "Highly reactive metals such as aluminium require electrolysis rather than ordinary carbon reduction."
    }
  ]
);
add(
  "chemistry",
  "metals",
  "Extraction of Iron",
  `<h2>Extraction of Iron</h2>

  <p>Iron is extracted from iron ore in a <strong>blast furnace</strong>. The main ore used is haematite, which contains iron(III) oxide, Fe₂O₃.</p>

  <h3>Raw Materials</h3>

  <ul>
    <li><strong>Haematite</strong> — source of iron(III) oxide</li>
    <li><strong>Coke</strong> — provides heat and produces carbon monoxide</li>
    <li><strong>Limestone</strong> — removes impurities</li>
    <li><strong>Hot air</strong> — supplies oxygen for combustion</li>
  </ul>

  <h3>Formation of Carbon Monoxide</h3>

  <p>Coke burns in the hot air to produce carbon dioxide:</p>

  <p><strong>C + O₂ → CO₂</strong></p>

  <p>Carbon dioxide then reacts with more hot carbon:</p>

  <p><strong>CO₂ + C → 2CO</strong></p>

  <p>The carbon monoxide acts as the reducing agent.</p>

  <h3>Reduction of Iron(III) Oxide</h3>

  <p>Carbon monoxide removes oxygen from iron(III) oxide:</p>

  <p><strong>Fe₂O₃ + 3CO → 2Fe + 3CO₂</strong></p>

  <p>Molten iron collects at the bottom of the furnace.</p>

  <h3>Role of Limestone</h3>

  <p>Limestone decomposes when heated:</p>

  <p><strong>CaCO₃ → CaO + CO₂</strong></p>

  <p>Calcium oxide reacts with silica impurity to form slag:</p>

  <p><strong>CaO + SiO₂ → CaSiO₃</strong></p>

  <p>The slag is separated from the molten iron.</p>

  <h3>Key Sequence</h3>

  <p><strong>Haematite → reduction → molten iron → separation from slag</strong></p>`,
  [
    {
      q: "What is the main ore used to extract iron?",
      steps: [
        "Step 1: Iron is extracted from an iron-containing ore.",
        "Step 2: The main ore used in the blast furnace is haematite.",
        "Step 3: Haematite contains iron(III) oxide, Fe₂O₃."
      ],
      ans: "Haematite.",
      why: "Haematite is an important iron ore containing iron(III) oxide."
    },
    {
      q: "What is the role of carbon monoxide in the extraction of iron?",
      steps: [
        "Step 1: Iron ore contains iron(III) oxide.",
        "Step 2: Carbon monoxide reacts with iron(III) oxide.",
        "Step 3: Carbon monoxide removes oxygen from the iron oxide.",
        "Step 4: Iron is produced.",
        "Step 5: Fe₂O₃ + 3CO → 2Fe + 3CO₂."
      ],
      ans: "Carbon monoxide acts as a reducing agent and removes oxygen from iron(III) oxide.",
      why: "Carbon monoxide reduces iron(III) oxide to iron."
    },
    {
      q: "What is the purpose of limestone in the blast furnace?",
      steps: [
        "Step 1: Limestone decomposes to form calcium oxide.",
        "Step 2: Calcium oxide reacts with silica impurity.",
        "Step 3: Calcium silicate, called slag, is formed.",
        "Step 4: The slag can then be separated from the molten iron."
      ],
      ans: "Limestone removes silica impurities by forming slag.",
      why: "Limestone produces calcium oxide, which reacts with silica to form calcium silicate slag."
    }
  ],
  [
    {
      q: "A blast furnace produces iron and slag. What is the function of the slag?",
      hint: "Think about the impurities removed from the iron ore.",
      steps: [
        "Step 1: Iron ore contains impurities such as silica.",
        "Step 2: Calcium oxide from limestone reacts with silica.",
        "Step 3: Calcium silicate is formed.",
        "Step 4: This calcium silicate is slag and can be separated from the iron."
      ],
      ans: "Slag is formed by reacting with impurities such as silica, allowing those impurities to be separated from the iron.",
      why: "Slag carries unwanted impurities away from the iron during extraction."
    },
    {
      q: "Write the equation for the reduction of iron(III) oxide by carbon monoxide.",
      hint: "Iron(III) oxide is Fe₂O₃ and carbon monoxide is CO.",
      steps: [
        "Step 1: Write the reactants: Fe₂O₃ + CO.",
        "Step 2: Iron(III) oxide is reduced to iron.",
        "Step 3: Carbon monoxide is oxidised to carbon dioxide.",
        "Step 4: Balance the equation.",
        "Step 5: The balanced equation is Fe₂O₃ + 3CO → 2Fe + 3CO₂."
      ],
      ans: "Fe₂O₃ + 3CO → 2Fe + 3CO₂",
      why: "Carbon monoxide removes oxygen from iron(III) oxide to produce iron and carbon dioxide."
    }
  ]
);
add(
  "chemistry",
  "metals",
  "Rusting",
  `<h2>Rusting</h2>

  <p><strong>Rusting</strong> is the slow chemical reaction in which iron reacts with oxygen and water to form rust.</p>

  <p>Rust is mainly a hydrated form of iron(III) oxide.</p>

  <h3>Conditions Required for Rusting</h3>

  <p>Iron requires both <strong>oxygen</strong> and <strong>water</strong> for rusting to occur.</p>

  <p><strong>Iron + oxygen + water → rust</strong></p>

  <h3>What Happens During Rusting?</h3>

  <p>Iron atoms lose electrons during the process while oxygen is reduced. The resulting iron compounds eventually form hydrated iron(III) oxide, commonly called rust.</p>

  <h3>Effects of Rusting</h3>

  <p>Rusting gradually weakens iron and steel objects. It can cause:</p>

  <ul>
    <li>loss of strength;</li>
    <li>damage to structures;</li>
    <li>failure of machinery and equipment;</li>
    <li>economic losses through replacement and repair.</li>
  </ul>

  <h3>Key Idea</h3>

  <p>Rusting is a chemical change because new substances are formed and the process is not easily reversed by physical means.</p>`,
  [
    {
      q: "What is rusting?",
      steps: [
        "Step 1: Iron reacts slowly with substances in its surroundings.",
        "Step 2: Oxygen and water are required for the process.",
        "Step 3: A new substance called rust is formed."
      ],
      ans: "Rusting is the slow reaction of iron with oxygen and water to form rust.",
      why: "Rusting is a chemical reaction involving iron, oxygen and water."
    },
    {
      q: "What two substances are required for iron to rust?",
      steps: [
        "Step 1: Rusting requires oxygen.",
        "Step 2: Rusting also requires water.",
        "Step 3: Therefore, both oxygen and water must be available for normal rusting to occur."
      ],
      ans: "Oxygen and water.",
      why: "Both oxygen and water are necessary for ordinary rusting of iron."
    },
    {
      q: "Why is rusting classified as a chemical change?",
      steps: [
        "Step 1: Iron reacts with oxygen and water.",
        "Step 2: A new substance, rust, is formed.",
        "Step 3: Formation of a new substance indicates a chemical change."
      ],
      ans: "Because a new substance, rust, is formed.",
      why: "Chemical changes involve the formation of new substances."
    }
  ],
  [
    {
      q: "An iron nail is kept in completely dry air. Will it rust normally? Explain.",
      hint: "Rusting requires both oxygen and water.",
      steps: [
        "Step 1: Dry air contains oxygen but essentially no liquid water.",
        "Step 2: Rusting requires water as well as oxygen.",
        "Step 3: Therefore, the absence of water prevents normal rusting."
      ],
      ans: "No. It will not rust normally because water is required for rusting.",
      why: "Oxygen alone is not sufficient for ordinary rusting; water is also required."
    },
    {
      q: "Why can rusting cause an iron structure to become weaker?",
      hint: "Think about what happens to the original iron as rust forms.",
      steps: [
        "Step 1: Rusting converts iron into corrosion products.",
        "Step 2: The original metal is gradually lost.",
        "Step 3: Continued rusting reduces the effective amount and strength of the iron."
      ],
      ans: "Rusting gradually consumes and damages the iron, reducing its strength.",
      why: "Corrosion can reduce the amount and structural strength of iron."
    }
  ]
);
